INSERT INTO recipes (id, recipe_id, source_url, title, servings, cook_time, difficulty, tips, copyright, created_at, updated_at, raw_data) VALUES (342, '6891816', 'https://www.10000recipe.com/recipe/6891816', '마지막 한 젓가락까지 바삭하고 고소한 간장 멸치볶음(아이밑반찬,간단반찬)멸치볶음', '4인분', '10분 이내', '아무나', '["♡멸치를 약간 튀기듯이 하면 마지막 한젓가락까지 비린내없이 눅눅하지않고 바삭하게 드실수있어요 ♡불조절이 중요합니다 아니면 멸치가 엉겨붙어요"]'::jsonb, '미은미은', 2025-11-23 01:18:09.278521, 2025-11-23 01:47:19.573813, '{"tips": ["♡멸치를 약간 튀기듯이 하면 마지막 한젓가락까지 비린내없이 눅눅하지않고 바삭하게 드실수있어요 ♡불조절이 중요합니다 아니면 멸치가 엉겨붙어요"], "steps": ["잔멸치 국그릇1이예요 대량으로 구매를 해서 몇 그람 정도인지 몰라서 비커에 넣어 봤어요ㅋ 300cc네요", "멸치 비린내를 없애기 위해서 볶음팬에 아무것도 없이 멸치만 넣고 중간불에 볶아주세요", "멸치가 약간 노릇노릇하게 되었을때 오일을 3T 넣고 볶아주세요 저는 카놀라유를 사용했어요 약간의 기포가 생길때 불을 끄고", "맛술1T,간장1T를 넣고 골고루 섞어주세요", "올리고당 3T와 설탕 티스푼1T 넣고 약불에서 아주 잠깐만(3초~5초) 골고루 볶아주세요(달게 드시지 않으시면 설탕은 생략하셔도 됩니다)", "다시 불을 끄고 참기름1", "깨소금1T", "골고루 섞어주면 완성입니다"], "title": "마지막 한 젓가락까지 바삭하고 고소한 간장 멸치볶음(아이밑반찬,간단반찬)멸치볶음", "servings": "4인분", "cook_time": "10분 이내", "copyright": "미은미은", "recipe_id": "6891816", "step_tips": [null, null, null, null, null, null, null, null], "difficulty": "아무나", "source_url": "https://www.10000recipe.com/recipe/6891816", "ingredients": ["잔멸치 300cc 1국그릇", "오일 3스푼", "간장 1스푼", "맛술 1스푼", "올리고당 3스푼", "설탕 1티스푼", "참기름 1스푼", "깨소금 1스푼"], "ingredients_struct": [{"qty": "1국그릇", "desc": null, "name": "잔멸치 300cc"}, {"qty": "3스푼", "desc": null, "name": "오일"}, {"qty": "1스푼", "desc": null, "name": "간장"}, {"qty": "1스푼", "desc": null, "name": "맛술"}, {"qty": "3스푼", "desc": null, "name": "올리고당"}, {"qty": "1티스푼", "desc": null, "name": "설탕"}, {"qty": "1스푼", "desc": null, "name": "참기름"}, {"qty": "1스푼", "desc": null, "name": "깨소금"}]}'::jsonb);
INSERT INTO recipes (id, recipe_id, source_url, title, servings, cook_time, difficulty, tips, copyright, created_at, updated_at, raw_data) VALUES (276, '3568149', 'https://www.10000recipe.com/recipe/3568149', '고등어무조림', '2인분', '30분 이내', '초급', '[]'::jsonb, '풀향기', 2025-11-22 23:01:06.568718, 2025-11-23 01:23:39.922617, '{"tips": [], "steps": ["무와 대파는 흐르는 물에 씻은 후 무는 도톰하게 반달 썰어 주고 대파는 어슷 썰어 줍니다.", "고등어는 흐르는 물에 깨끗하게 씻어 줍니다.", "분량의 양념장 재료 진간장, 고추장, 고춧가루, 매실액, 맛술, 올리고당, 다진 마늘, 후춧가루를 넣어 고루 섞어서 양념장을 만들어 줍니다.", "냄비 바닥에 무를 깔고 씻어 놓은 고등어를 올린 후 대파를 얹어 주고 양념장을 끼얹어 준 다음 물을 부어 줍니다.", "가스 불에 올려 센 불에서 끓여 주다가 한소끔 끓으면 불을 줄이고 간이 고루 배도록 중간 중간 양념장을 끼얹어 주면서 조려 줍니다."], "title": "고등어무조림", "servings": "2인분", "cook_time": "30분 이내", "copyright": "풀향기", "recipe_id": "3568149", "step_tips": [null, null, null, null, null], "difficulty": "초급", "source_url": "https://www.10000recipe.com/recipe/3568149", "ingredients": ["고등어 1마리", "무 500g", "대파 1뿌리", "물 300ml", "진간장 4큰술", "고추장 2큰술", "고춧가루 1큰술", "매실액 2큰술", "맛술 2큰술", "올리고당 1큰술", "다진 마늘 1작은술", "후춧가루 약간"], "ingredients_struct": [{"qty": "1마리", "desc": null, "name": "고등어"}, {"qty": "500g", "desc": null, "name": "무"}, {"qty": "1뿌리", "desc": null, "name": "대파"}, {"qty": "300ml", "desc": null, "name": "물"}, {"qty": "4큰술", "desc": null, "name": "진간장"}, {"qty": "2큰술", "desc": null, "name": "고추장"}, {"qty": "1큰술", "desc": null, "name": "고춧가루"}, {"qty": "2큰술", "desc": null, "name": "매실액"}, {"qty": "2큰술", "desc": null, "name": "맛술"}, {"qty": "1큰술", "desc": null, "name": "올리고당"}, {"qty": "1작은술", "desc": null, "name": "다진 마늘"}, {"qty": "약간", "desc": null, "name": "후춧가루"}]}'::jsonb);
INSERT INTO recipes (id, recipe_id, source_url, title, servings, cook_time, difficulty, tips, copyright, created_at, updated_at, raw_data) VALUES (279, '6833097', 'https://www.10000recipe.com/recipe/6833097', '김치콩나물 국 얼큰하고 맛나게 끓이기!', '4인분', '30분 이내', '중급', '[]'::jsonb, '줌마요리', 2025-11-22 23:08:05.668430, 2025-11-23 01:23:39.980963, '{"tips": [], "steps": ["신김치를 먹기좋은 크기로 한공기 정도 썰어주세요,김치가 너무 시었을때는 씻어서 사용하시구 고추가루를 넣어 얼큰한 맛을 냅니다. ^^", "김치국물도 같이 넣어줘야 맛나요,", "콩나물도 깨끗이 씻어주구요,", "냄비에 물 1리터정도 넣고 국물 멸치를 5분 정도 끓이다가 멸치를 건지고 김치를 먼저 팔팔 끓입니다. 저는 중간멸치라서 김치랑 넣고 같이 끓여요^^", "김치가 팔팔 끓으면 불순물을 국자로 좀 떠주세요, 고추가루때문에 자꾸만 거품이 생기는데 서너번정도만 떠내 주면 되요^^", "김치를 5분 이상 팔팔 끓이고 콩나물을 넣고 또 끓입니다 .이때 물이 너무 적으면 더 넣어주시구요!", "어느정도 끓이다가 국간장도 한숟갈 넣어 끓입니다. 모자란 간은 소금으로 맞추세요^^", "고추가루도 한스푼 넣어주구요 마늘도 반숟갈, 파도 송송 썰어 넣어 우르르 끓입니다.", "사실 김치국이 얼큰하긴 한데 더 칼칼한 맛을 원하실땐 청양고추를 넣어주시면 되요^^", "얼큰하게 끓인 김치콩나물국 한그릇이 아침을 개운하게 만들어 주네요^^"], "title": "김치콩나물 국 얼큰하고 맛나게 끓이기!", "servings": "4인분", "cook_time": "30분 이내", "copyright": "줌마요리", "recipe_id": "6833097", "step_tips": [null, null, null, null, null, null, null, null, null, null], "difficulty": "중급", "source_url": "https://www.10000recipe.com/recipe/6833097", "ingredients": ["콩나물 2공기", "신김치 1공기", "파 1대", "국간장 1숟갈", "소금 약간", "고추가루 1숟갈", "청양고추 1개", "마늘 1/2스푼"], "ingredients_struct": [{"qty": "2공기", "desc": null, "name": "콩나물"}, {"qty": "1공기", "desc": null, "name": "신김치"}, {"qty": "1대", "desc": null, "name": "파"}, {"qty": "1숟갈", "desc": null, "name": "국간장"}, {"qty": "약간", "desc": null, "name": "소금"}, {"qty": "1숟갈", "desc": null, "name": "고추가루"}, {"qty": "1개", "desc": null, "name": "청양고추"}, {"qty": "1/2스푼", "desc": null, "name": "마늘"}]}'::jsonb);
INSERT INTO recipes (id, recipe_id, source_url, title, servings, cook_time, difficulty, tips, copyright, created_at, updated_at, raw_data) VALUES (331, '6882083', 'https://www.10000recipe.com/recipe/6882083', '내장까지 넣어 제대로 진한 전복죽 만들기', '3인분', '60분 이내', '초급', '[]'::jsonb, '초롱비', 2025-11-23 00:56:44.310119, 2025-11-23 01:38:37.192284, '{"tips": [], "steps": ["전복죽은 전복손질만하면 그리 어려운요리는 아니에요. 칫솔로 전복 배부분과 껍질은 문질러서 깨끗하게 씻구요", "전복 가쪽을 숟가락으로 살살 돌리면 가운데로 움찔하는데 그때 숟가락으로 긁어서 떼어냅니다", "내장과 살을 빨간선을따라 잘라서 분리.", "전복은 나중에 고명으로올릴 하나빼고 모두 다지기. 전복이 미끄러우니 손조심하세요.", "나머지 야채들도 곱게 다지기. 야채는 양파는 필수고 나머지는 집에있는 자투리야채들 활용하시면 되요.", "그리고 분리해두었던 전복내장은 믹서기에 물과함께 곱게 갈아냅니다. 죽끓일때 채에 걸러내는 방법도 있는데 믹서기로 갈아서 사용하는것이 더 완전하게 내장을 100% 사용할수가 있어서 전 믹서기에 갈아서 사용해요.", "팬에 참기름을 두르고 양파먼저 볶구요. 전 찬밥을 이용할꺼지만 쌀을 이용하신다면 30분이상 불려둔쌀을 함께 볶아주세요", "당근, 버섯, 전복넣고 볶기. 물을넣어 푹 끓일것임으로 볶는순서는 중요하지않아요", "전복내장 넣어주기", "물을 밥량 두배이상으로 넣어주고 (쌀사용시4배이상)", "밥도 풍덩 해줍니다. 물은 요리중 모자르다싶으면 중간중간 더 추가해주시면 되니 물량을 정확하게 맞추실필요는 없어요", "국간장 한스푼넣어 기본간 맞춰주구요. 나머지 모자른간은 다 끓인후에 취향에따라 소금으로 맞춰주시면 되요.", "보글보글 끓기 시작하면 한번씩 저어주면서 물이 다 졸아들고 밥알이 푹 퍼질때까지 끓여주면 끝", "통으로 넣었던 전복을 얇게썰어서 밥위에 올려주시면 더욱 맛있어보이는 세팅을 하실수가 있답니다. 전복손질과 끓이는시간이 걸려서그렇지 어렵지않은 요리에요.^^"], "title": "내장까지 넣어 제대로 진한 전복죽 만들기", "servings": "3인분", "cook_time": "60분 이내", "copyright": "초롱비", "recipe_id": "6882083", "step_tips": ["칫솔", "숟가락", "도마", null, null, "믹서기", "멀티팬", null, null, null, null, null, null, "국자"], "difficulty": "초급", "source_url": "https://www.10000recipe.com/recipe/6882083", "ingredients": ["전복 中 4마리", "밥 1.5공기", "양파 1/2개", "당근 1/3개", "양송이버섯 3개", "국간장 1T", "소금", "참기름", "물 3공기"], "ingredients_struct": [{"qty": "4마리", "desc": null, "name": "전복 中"}, {"qty": "1.5공기", "desc": null, "name": "밥"}, {"qty": "1/2개", "desc": null, "name": "양파"}, {"qty": "1/3개", "desc": null, "name": "당근"}, {"qty": "3개", "desc": null, "name": "양송이버섯"}, {"qty": "1T", "desc": null, "name": "국간장"}, {"qty": "", "desc": null, "name": "소금"}, {"qty": "", "desc": null, "name": "참기름"}, {"qty": "3공기", "desc": null, "name": "물"}]}'::jsonb);
INSERT INTO recipes (id, recipe_id, source_url, title, servings, cook_time, difficulty, tips, copyright, created_at, updated_at, raw_data) VALUES (332, '6883771', 'https://www.10000recipe.com/recipe/6883771', '돼지갈비찜 양념 황금레시피 갈비는 손으로 뜯어 먹어야 제맛!', '5인분', '2시간 이상', '초급', '["갈비는 바로 양념을 해서 만들어 먹는 것보다 한나절이나 전날 양념에 숙성시켜 놓으면 훨씬 맛이 좋다 갈비 양념은 약간 달달해야 맛있기에 황금레시피 양념 비율은 간장과 단맛을 내는 설탕이나 올리고당을 1:1에 가깝게 넣어 주면 된다 집에 있는 재료를 사용해서 매실청이나 올리고당, 설탕 등을 비율에 맞게 넣어 주고 과일을 많이 갈아 넣을 때는 설탕을 조금 덜 잡아 준다 고기를 너무 오래 삶는 것보다 적당히 살이 뼈에 붙어 있을 때가 가장 맛있는 듯~"]'::jsonb, '판교댁쏭아', 2025-11-23 00:58:20.981745, 2025-11-23 01:38:37.201512, '{"tips": ["갈비는 바로 양념을 해서 만들어 먹는 것보다 한나절이나 전날 양념에 숙성시켜 놓으면 훨씬 맛이 좋다 갈비 양념은 약간 달달해야 맛있기에 황금레시피 양념 비율은 간장과 단맛을 내는 설탕이나 올리고당을 1:1에 가깝게 넣어 주면 된다 집에 있는 재료를 사용해서 매실청이나 올리고당, 설탕 등을 비율에 맞게 넣어 주고 과일을 많이 갈아 넣을 때는 설탕을 조금 덜 잡아 준다 고기를 너무 오래 삶는 것보다 적당히 살이 뼈에 붙어 있을 때가 가장 맛있는 듯~"], "steps": ["레시피의 재료 양은 고기 2kg을 기준으로 작성되었고 나는 가족들이 많아서 5근 이상을 만들었다 핏물은 찬물에 담가서 빼주는데 3시간 이상 핏물을 빼주어야 한다 물은 30분에서 1시간에 한 번씩 갈아준다", "끓는 물에 갈비를 한번 끓여서 버려준 뒤 찬물로 깨끗하게 헹구어서 준비 이때 된장을 살짝 넣어 같이 끓여주어도 좋다", "양념장 만들기 배나 사과 같은 과일이 있으면 갈아서 넣어 주면 좋지만 간장과 설탕이나 올리고당을 비율에 잘 맞춰서 넣어 주기만 해도 아주 맛이 좋다", "양념을 고기에 섞어 바로 끓이기 보다는 양념이 갈비에 잘 베이도록 충분히 시간을 두는 게 좋다 고기도 훨씬 연해지고 맛도 있다", "전 날 밤에 고기를 재워두고 다음날 끓여주었다", "당근과 감자의 가장자리 모서리 부분을 살짝 깎아내면 모양이 훨씬 좋다", "조금 번거로워도 어른들 드실 음식엔 늘 이렇게 정성을 들여본다", "양념된 고기와 야채를 넣고 끓여주기", "잘 익을 때까지 푹 끓여주는데 가끔 감자가 빨리 익어서 부서질 때가 있는데 이럴 때는 감자를 먼저 꺼내 놓고 고기를 푹 익혀 준 뒤 마지막에 같이 넣어 섞어 주면 된다", "중간에 간을 보고 입맛에 맞게 간장이나 설탕을 추가해 주기~ 입맛이 각기 다르기 때문에 본인의 입에 맞는 간을 했을 때가 가장 맛있는 음식이 된다 하지만 황금 레시피 비율은 대부분 좋아하는 갈비찜 양념 맛이다~", "마지막에 대파와 청양고추도 송송 썰어서 올려주면 조금 더 개운한 맛이 난다"], "title": "돼지갈비찜 양념 황금레시피 갈비는 손으로 뜯어 먹어야 제맛!", "servings": "5인분", "cook_time": "2시간 이상", "copyright": "판교댁쏭아", "recipe_id": "6883771", "step_tips": [null, null, null, null, null, null, null, null, null, null, null], "difficulty": "초급", "source_url": "https://www.10000recipe.com/recipe/6883771", "ingredients": ["돼지갈비 2kg", "감자 2개", "당근 2개", "대파 약간", "양조간장 1.5컵", "설탕 이나 올리고당 1컵", "맛술 1/2컵", "다진 마늘 1/2컵", "후추 약간", "참기름 약간", "대파 잘게 다진 1개"], "ingredients_struct": [{"qty": "2kg", "desc": null, "name": "돼지갈비"}, {"qty": "2개", "desc": null, "name": "감자"}, {"qty": "2개", "desc": null, "name": "당근"}, {"qty": "약간", "desc": null, "name": "대파"}, {"qty": "1.5컵", "desc": null, "name": "양조간장"}, {"qty": "1컵", "desc": null, "name": "설탕 이나 올리고당"}, {"qty": "1/2컵", "desc": null, "name": "맛술"}, {"qty": "1/2컵", "desc": null, "name": "다진 마늘"}, {"qty": "약간", "desc": null, "name": "후추"}, {"qty": "약간", "desc": null, "name": "참기름"}, {"qty": "1개", "desc": null, "name": "대파 잘게 다진"}]}'::jsonb);
INSERT INTO recipes (id, recipe_id, source_url, title, servings, cook_time, difficulty, tips, copyright, created_at, updated_at, raw_data) VALUES (333, '6883937', 'https://www.10000recipe.com/recipe/6883937', '닭볶음탕 닭도리탕 황금레시피 짱짱맛 칼칼함이 남달라', '3인분', '60분 이내', '중급', '["닭도리탕 닭볶음탕 황금레시피 비율만 지키시면 완전 대박 ~!! 아주 맛있게 완성할 수가 있어요 칼칼하면서 매콤한 맛이 엄쥐척! 황금팁은 양념장 비율과 야채 넣고 1분 후에 불을 끄는 것이랍니다 반드시 1분 후 불을 꺼야 청양고추의 매콤한 맛과 대파의 살아있는 향 양파의 아삭함을 느낄 수가 있어요 야채의 재료가 살아있어야 맛있답니다 국물을 많이 있게 졸이면 칼칼한 국물도 같이 먹을 수 있는 국물닭도리탕 국물을 적게 있게 졸이면 양념이 아주 잘 밴 닭고기가 된답니다 둘다 매콤 칼칼해요! 블레스그레이스 블로그에 많이 놀러와주세요 https://blog.naver.com/blessgrace7"]'::jsonb, '블레스그레이스', 2025-11-23 01:00:30.635259, 2025-11-23 01:40:50.939223, '{"tips": ["닭도리탕 닭볶음탕 황금레시피 비율만 지키시면 완전 대박 ~!! 아주 맛있게 완성할 수가 있어요 칼칼하면서 매콤한 맛이 엄쥐척! 황금팁은 양념장 비율과 야채 넣고 1분 후에 불을 끄는 것이랍니다 반드시 1분 후 불을 꺼야 청양고추의 매콤한 맛과 대파의 살아있는 향 양파의 아삭함을 느낄 수가 있어요 야채의 재료가 살아있어야 맛있답니다 국물을 많이 있게 졸이면 칼칼한 국물도 같이 먹을 수 있는 국물닭도리탕 국물을 적게 있게 졸이면 양념이 아주 잘 밴 닭고기가 된답니다 둘다 매콤 칼칼해요! 블레스그레이스 블로그에 많이 놀러와주세요 https://blog.naver.com/blessgrace7"], "steps": ["블로그에서 핫한 반응을 일으켰던 닭볶음탕이니 믿고 따라해주세요!", "양파는 반을 자른 후 사각으로 썰어주세요", "고추장2큰술 고추가루7큰술 설탕2큰술 국간장5큰술 마늘1큰술 넣고 소주잔으로 물1컵 넣고 섞어 주세요", "닭은 끓는 물에 살짝 데쳐냅니다 끓기 시작하면 5분 정도 데친 후", "물을 버리고 찬물로 불순물을 씻어주세요", "데친 닭을 깊은 팬에 넣고 소주 1컵을 부어줍니다 닭 잡내를 잡아줍니다", "당근 감자를 넣어주고 중간에 양념장을 올린 후 물 800ml 넣어주세요 계랑컵이 없으면 재료 끄트머리 2/3 정도만 넣어주세요", "강불에서 팔팔 끓어오르면 양념장을 섞고 강불과 중불 사이에서 익히세요", "국물이 반으로 졸았을 때 감자와 닭이 익었는지 젓가락으로 찔러 확인하세요", "국물이 요 정도 있는 상태에서 대파 고추 양파를 넣습니다 국물 없게 조리는 건 비추구요 국물이 있게 졸여주세요", "대파 청양 고추 양파를 넣은 후 휘리릭 섞고 1분 후 불을 끕니다", "국물은 요 정도로 졸이면 돼요 아주 칼칼하기 때문에 국물이 있어야 밥도 비벼 먹고 맛있답니다", "국물을 매콤 칼칼하게 먹을 수 있어서 맛집 식당에서 맛보는듯한 닭볶음탕 레시피 완성! 양념장이 황금 비율이랍니다 비율은 모두 지켜주세요 여러번 해보고 터득한 황금비율이에요^^", "국물을 많이 있게 졸이면 매콤한 국물닭도리탕 백숙처럼 부드러운 닭고기에 국물을 얹어먹을 수 있는 스타일 (국물이 매콤 칼칼) 취향에 따라 졸여주세요"], "title": "닭볶음탕 닭도리탕 황금레시피 짱짱맛 칼칼함이 남달라", "servings": "3인분", "cook_time": "60분 이내", "copyright": "블레스그레이스", "recipe_id": "6883937", "step_tips": [null, null, null, null, null, null, null, null, null, null, null, null, null, null], "difficulty": "중급", "source_url": "https://www.10000recipe.com/recipe/6883937", "ingredients": ["닭 1마리", "당근 1/3개", "양파 1/2개", "감자 3개", "대파 초록색 부분 20센티 4개", "청양고추 4개", "고추장 2큰술", "고추가루 7큰술", "설탕 2큰술", "국간장 5큰술", "마늘 듬뿍 1큰술", "물 1소주잔"], "ingredients_struct": [{"qty": "1마리", "desc": null, "name": "닭"}, {"qty": "1/3개", "desc": null, "name": "당근"}, {"qty": "1/2개", "desc": null, "name": "양파"}, {"qty": "3개", "desc": null, "name": "감자"}, {"qty": "4개", "desc": null, "name": "대파 초록색 부분 20센티"}, {"qty": "4개", "desc": null, "name": "청양고추"}, {"qty": "2큰술", "desc": null, "name": "고추장"}, {"qty": "7큰술", "desc": null, "name": "고추가루"}, {"qty": "2큰술", "desc": null, "name": "설탕"}, {"qty": "5큰술", "desc": null, "name": "국간장"}, {"qty": "1큰술", "desc": null, "name": "마늘 듬뿍"}, {"qty": "1소주잔", "desc": null, "name": "물"}]}'::jsonb);
INSERT INTO recipes (id, recipe_id, source_url, title, servings, cook_time, difficulty, tips, copyright, created_at, updated_at, raw_data) VALUES (406, '6893285', 'https://www.10000recipe.com/recipe/6893285', '무생채 만드는 법, 절이지 않고 10분 만에 휘리릭 ~', '6인분 이상', '15분 이내', '초급', '[]'::jsonb, '뽕림이', 2025-11-23 01:48:29.615193, 2025-11-23 01:48:29.615193, '{"tips": [], "steps": ["먼저 무는 깨끗이 씻은 후 가늘게 채 썰어주세요. *최대한 가늘게 채 썰어주셔야 양념이 잘 배고요. 무 껍질은 벗기셔도 되고 안 벗기셔도 됩니다 :)", "고춧가루 2 큰 술을 넣고 바락바락 문질러 무를 빨갛게 물들여주세요.", "다진 마늘 1 큰 술, 설탕 1 큰 술, 오미자청(또는 매실청) 1 큰 술, 식초 2 큰 술을 넣어주시고요.", "이어서 액젓 2 큰 술, 소금 적당량을 넣고 조물조물 무쳐 맛을 봐주세요. 약간 싱거우시면 소금을 더 넣어주시고요. 새콤한 맛을 더 느끼고 싶으신 분들은 식초를 조금 더 넣어주세요 :) 마지막으로 통깨와 송송 썬 대파를 넣고 가볍게 섞어주기만 하면 무생채 만드는 법, 끝 ~♩"], "title": "무생채 만드는 법, 절이지 않고 10분 만에 휘리릭 ~", "servings": "6인분 이상", "cook_time": "15분 이내", "copyright": "뽕림이", "recipe_id": "6893285", "step_tips": [null, null, null, null], "difficulty": "초급", "source_url": "https://www.10000recipe.com/recipe/6893285", "ingredients": ["무 600g", "고춧가루 2큰술", "다진 마늘 1큰술", "설탕 1큰술", "오미자청 또는 매실청 1큰술", "식초 2큰술", "액젓 2큰술", "소금 적당량", "통깨 적당량", "송송 썬 대파 1종이컵"], "ingredients_struct": [{"qty": "600g", "desc": null, "name": "무"}, {"qty": "2큰술", "desc": null, "name": "고춧가루"}, {"qty": "1큰술", "desc": null, "name": "다진 마늘"}, {"qty": "1큰술", "desc": null, "name": "설탕"}, {"qty": "1큰술", "desc": null, "name": "오미자청 또는 매실청"}, {"qty": "2큰술", "desc": null, "name": "식초"}, {"qty": "2큰술", "desc": null, "name": "액젓"}, {"qty": "적당량", "desc": null, "name": "소금"}, {"qty": "적당량", "desc": null, "name": "통깨"}, {"qty": "1종이컵", "desc": null, "name": "송송 썬 대파"}]}'::jsonb);
INSERT INTO recipes (id, recipe_id, source_url, title, servings, cook_time, difficulty, tips, copyright, created_at, updated_at, raw_data) VALUES (277, '4164229', 'https://www.10000recipe.com/recipe/4164229', '꽃게탕/꽃게탕 끓이는법', NULL, NULL, '초급', '[]'::jsonb, '돌하우스', 2025-11-22 23:03:50.205881, 2025-11-23 01:23:39.968824, '{"tips": [], "steps": ["저는 손질되어있는 냉동 꽃게를 사용했습니다.", "사진정도 크기의 12토막을 깨끗이 씻어 준비하고...", "분량의 양파, 호박, 대파, 청고추를 사진처럼 썰어서 준비합니다.", "분량의 고추장, 집된장, 고춧가루, 소금, 국간장, 다진마늘을 잘 섞어서 양념장을 만들고...", "물1000ml를 끓인후에.. 준비해논 양념장을 풀어줍니다.", "그런다음, 준비해논 꽃게와...", "양파, 호박을 넣고 5분가량 끓여줍니다.", "끓이는 중간중간에 거품은 거둬 내고...", "마지막에 대파와 청고추를 넣고, 살짝 한번 더 끓여주면 완성입니다."], "title": "꽃게탕/꽃게탕 끓이는법", "servings": null, "cook_time": null, "copyright": "돌하우스", "recipe_id": "4164229", "step_tips": [null, null, null, null, null, null, null, null, null], "difficulty": "초급", "source_url": "https://www.10000recipe.com/recipe/4164229", "ingredients": ["꽃게 작은 사이즈 6마리", "양파(중) 1/2개", "호박 1/2개", "대파 1/2개", "청양고추 2개", "물 1000ml", "후춧가루 약간", "고추장 1스푼", "집된장 1스푼", "고춧가루 1.5스푼", "소금 1/3스푼", "국간장 1스푼", "다진마늘 1/2스푼"], "ingredients_struct": [{"qty": "6마리", "desc": null, "name": "꽃게 작은 사이즈"}, {"qty": "1/2개", "desc": null, "name": "양파(중)"}, {"qty": "1/2개", "desc": null, "name": "호박"}, {"qty": "1/2개", "desc": null, "name": "대파"}, {"qty": "2개", "desc": null, "name": "청양고추"}, {"qty": "1000ml", "desc": null, "name": "물"}, {"qty": "약간", "desc": null, "name": "후춧가루"}, {"qty": "1스푼", "desc": null, "name": "고추장"}, {"qty": "1스푼", "desc": null, "name": "집된장"}, {"qty": "1.5스푼", "desc": null, "name": "고춧가루"}, {"qty": "1/3스푼", "desc": null, "name": "소금"}, {"qty": "1스푼", "desc": null, "name": "국간장"}, {"qty": "1/2스푼", "desc": null, "name": "다진마늘"}]}'::jsonb);
INSERT INTO recipes (id, recipe_id, source_url, title, servings, cook_time, difficulty, tips, copyright, created_at, updated_at, raw_data) VALUES (285, '6838020', 'https://www.10000recipe.com/recipe/6838020', '메추리알장조림 초간단 레시피 소개해용^^', '3인분', '30분 이내', '아무나', '["준비한 메추리알 양에 맞게 나머지 재료들 양조절 해주시구요! 꽈리고추는 메추리알 넣고 졸일때 넣어주세요!!"]'::jsonb, '혁이어뭉', 2025-11-22 23:32:36.719332, 2025-11-23 01:23:39.987172, '{"tips": ["준비한 메추리알 양에 맞게 나머지 재료들 양조절 해주시구요! 꽈리고추는 메추리알 넣고 졸일때 넣어주세요!!"], "steps": ["재료준비! 저는 깐메추리알을 사용했어요~ 편한대로 준비해주세요^^", "깐메추리알은 흐르는 물에 헹궈서 물에 잠시 담궈두시구용~", "그다음, 준비한 냄비에 간장 1컵!", "물 3컵!!", "매실액 1/4컵 넣어주세요^^ 매실액은 없으면 생략해도 무방하답니다~", "설탕은 밥수저로 4스푼~ 혹시 단거 좋아하시는분들은 더 넣으셔도 됩니다용!", "저는 약간 매콤(?)하게 할려고 청양고추를 썼는데 꽈리고추 쓰실분들은 나중에 넣어주세요~ 너무 빨리넣음 흐물해져요^^;", "다진마늘도 1스푼 투하~!!!!! 통마늘도 가능~~", "다넣었음 간장을 센불에서 팔팔 끓여주세용!!", "한소끔 끓으면 중불로 줄인뒤 메추리알 넣고 색감이 예뻐지도록 졸여주면 끝이랍니다^^ 완전 간단하쥬?", "효자반찬 메추리알장조림 완성~♡"], "title": "메추리알장조림 초간단 레시피 소개해용^^", "servings": "3인분", "cook_time": "30분 이내", "copyright": "혁이어뭉", "recipe_id": "6838020", "step_tips": [null, null, null, null, null, null, null, null, null, null, null], "difficulty": "아무나", "source_url": "https://www.10000recipe.com/recipe/6838020", "ingredients": ["깐메추리알 1kg", "청양고추 3개", "간장 1컵", "물 3컵", "매실액 생략가능 1/4컵", "설탕 4스푼", "다진마늘 통마늘가능 1스푼"], "ingredients_struct": [{"qty": "1kg", "desc": null, "name": "깐메추리알"}, {"qty": "3개", "desc": null, "name": "청양고추"}, {"qty": "1컵", "desc": null, "name": "간장"}, {"qty": "3컵", "desc": null, "name": "물"}, {"qty": "1/4컵", "desc": null, "name": "매실액 생략가능"}, {"qty": "4스푼", "desc": null, "name": "설탕"}, {"qty": "1스푼", "desc": null, "name": "다진마늘 통마늘가능"}]}'::jsonb);
INSERT INTO recipes (id, recipe_id, source_url, title, servings, cook_time, difficulty, tips, copyright, created_at, updated_at, raw_data) VALUES (286, '6838792', 'https://www.10000recipe.com/recipe/6838792', '배추 5포기 김장김치 양념 만들기', '6인분 이상', '2시간 이상', '중급', '[]'::jsonb, '파송송요리탁', 2025-11-22 23:34:03.508880, 2025-11-23 01:23:39.993402, '{"tips": [], "steps": ["다진 마늘 종이컵으로 한컵반을 준비합니다.", "찹쌀 풀 종이컵으로 3컵 준비해주세요. *찹쌀 풀은 끓여서 차게 식혀주세요.", "황태는 1마리 반에 물 800~1000cc 정도를 넣고 처음에는 중간불에서 끓이기 시작해서 끓기 시작하면 약한 불로 줄여서 끓여주세요. 이렇게 끓여서 500cc 정도의 황태 육수를 만들어주세요.", "고춧가루 4컵(종이컵)을 준비합니다.", "다진 생강 1/3컵(종이컵)을 준비해주세요.", "멸치 액젓 2컵(종이컵) 준비합니다.", "그리고 새우젓 1컵(종이컵)을 준비해주세요.", "단맛을 내기 위해 배즙이나 꿀이 좋다고 해서 집에 있는 꿀 3 큰 술 넣어주었어요. *김치 속 양념은 잘 섞어주세요.", "갓 600g을 준비하고 3cm 길이로 잘라주세요.", "쪽파 40개 (320g)를 준비하고 3cm 길이로 썰어주세요.", "갓과 쪽파를 썰어서 함께 준비해주세요.", "무 2/3개를 채썰기 해주세요.", "생새우 300g를 준비하고 물에 가볍게 씻어서 소쿠리에 받쳐서 물기를 빼주세요.", "김장재료에 양념을 넣어서 잘 버무려주세요.", "배추 속잎이 위로 올라오도록 김치통에 담고 비닐팩 한 장을 위에 덮어주고 뚜껑을 닫아주세요."], "title": "배추 5포기 김장김치 양념 만들기", "servings": "6인분 이상", "cook_time": "2시간 이상", "copyright": "파송송요리탁", "recipe_id": "6838792", "step_tips": [null, null, null, null, null, null, null, null, null, null, null, null, null, null, null], "difficulty": "중급", "source_url": "https://www.10000recipe.com/recipe/6838792", "ingredients": ["절임 배추 10kg 5포기", "갓 600g", "쪽파 320g 40개", "무 700g 2/3개", "생새우 300g", "황태 육수 500cc", "고춧가루 320g 4컵", "다진마늘 1.5컵", "다진생강 1/3컵", "찹쌀풀 3컵", "새우젓 1컵", "멸치액젓 2컵", "꿀 3T"], "ingredients_struct": [{"qty": "5포기", "desc": null, "name": "절임 배추 10kg"}, {"qty": "600g", "desc": null, "name": "갓"}, {"qty": "40개", "desc": null, "name": "쪽파 320g"}, {"qty": "2/3개", "desc": null, "name": "무 700g"}, {"qty": "300g", "desc": null, "name": "생새우"}, {"qty": "500cc", "desc": null, "name": "황태 육수"}, {"qty": "4컵", "desc": null, "name": "고춧가루 320g"}, {"qty": "1.5컵", "desc": null, "name": "다진마늘"}, {"qty": "1/3컵", "desc": null, "name": "다진생강"}, {"qty": "3컵", "desc": null, "name": "찹쌀풀"}, {"qty": "1컵", "desc": null, "name": "새우젓"}, {"qty": "2컵", "desc": null, "name": "멸치액젓"}, {"qty": "3T", "desc": null, "name": "꿀"}]}'::jsonb);
INSERT INTO recipes (id, recipe_id, source_url, title, servings, cook_time, difficulty, tips, copyright, created_at, updated_at, raw_data) VALUES (302, '6859263', 'https://www.10000recipe.com/recipe/6859263', '매콤 된장찌개, 채소와 두부만 넣은 초간단 초스피드 된장찌개', '2인분', '15분 이내', '초급', '[]'::jsonb, '김쭈', 2025-11-23 00:03:09.451808, 2025-11-23 01:27:03.996748, '{"tips": [], "steps": ["물1.5종이컵에 된장,고추가루,다진마늘,설탕,간장을 한데넣고 한소끔 끓여줍니다.", "그사이 양파,버섯,애호박,청양고추,두부는 적당한 크기로 썰어줍니다.", "한소끔 끓은 된장물에 양파,버섯,애호박,청양고추,두부를 넣어 줍니다.", "애호박이 익을때까지 끓여주어 간을보아 부족한간은 소금으로 해주어 완성. 저는 부족한간이 없어 소금은 넣지 않았습니다."], "title": "매콤 된장찌개, 채소와 두부만 넣은 초간단 초스피드 된장찌개", "servings": "2인분", "cook_time": "15분 이내", "copyright": "김쭈", "recipe_id": "6859263", "step_tips": [null, null, null, null], "difficulty": "초급", "source_url": "https://www.10000recipe.com/recipe/6859263", "ingredients": ["느타리버섯 1줌", "양파 1/2개", "애호박 1/4개", "청양고추 2개", "두부 1/4모", "물 1.5종이컵", "된장 2T", "진간장 1T", "고추가루 1.5T", "다진마늘 0.5T", "설탕 0.5티스푼", "소금 간맞추기"], "ingredients_struct": [{"qty": "1줌", "desc": null, "name": "느타리버섯"}, {"qty": "1/2개", "desc": null, "name": "양파"}, {"qty": "1/4개", "desc": null, "name": "애호박"}, {"qty": "2개", "desc": null, "name": "청양고추"}, {"qty": "1/4모", "desc": null, "name": "두부"}, {"qty": "1.5종이컵", "desc": null, "name": "물"}, {"qty": "2T", "desc": null, "name": "된장"}, {"qty": "1T", "desc": null, "name": "진간장"}, {"qty": "1.5T", "desc": null, "name": "고추가루"}, {"qty": "0.5T", "desc": null, "name": "다진마늘"}, {"qty": "0.5티스푼", "desc": null, "name": "설탕"}, {"qty": "간맞추기", "desc": null, "name": "소금"}]}'::jsonb);
INSERT INTO recipes (id, recipe_id, source_url, title, servings, cook_time, difficulty, tips, copyright, created_at, updated_at, raw_data) VALUES (407, '6894096', 'https://www.10000recipe.com/recipe/6894096', '너무 간단한데 맛있어서 놀라는 백종원 분식점 떡볶이 황금 레시피', '2인분', '15분 이내', '아무나', '["평소 단맛을 싫어하시면 설탕을 약간 줄여주셔도 됩니다. 기호에 따라 어묵을 약간 넣어주셔도 되요"]'::jsonb, '뽀유TV', 2025-11-23 01:49:52.321002, 2025-11-23 01:49:52.321002, '{"tips": ["평소 단맛을 싫어하시면 설탕을 약간 줄여주셔도 됩니다. 기호에 따라 어묵을 약간 넣어주셔도 되요"], "steps": ["먼저 종이컵 기준 물 2컵에 떡볶이떡을 넣고 센불에서 팔팔 끓여 줍니다.", "물이 팔팔 끓으면 양념을 다 넣어준 뒤 잘 풀어주고 또 자글자글 끓여 줍니다.", "국물이 졸아들면 대파를 가위로 쫑쫑 썰어 넣어주시고 통깨 약간 뿌려 주시면 끝!", "너무 간단한데 맛있어서 놀라는 백종원 분식점 떡볶이 완성입니다!", "한개 먹어보니 어머머!정말 분식점에서 파는 떡볶이 맛이 나면서 넘 맛있어요. 너무 간단한데 맛있어서 놀랬어요^^"], "title": "너무 간단한데 맛있어서 놀라는 백종원 분식점 떡볶이 황금 레시피", "servings": "2인분", "cook_time": "15분 이내", "copyright": "뽀유TV", "recipe_id": "6894096", "step_tips": [null, null, null, null, null], "difficulty": "아무나", "source_url": "https://www.10000recipe.com/recipe/6894096", "ingredients": ["떡볶이떡 2컵", "물 2컵", "대파 1/2대", "통깨 약간", "고추장 2T", "고추가루 1.5T", "간장 2T", "설탕 3T"], "ingredients_struct": [{"qty": "2컵", "desc": null, "name": "떡볶이떡"}, {"qty": "2컵", "desc": null, "name": "물"}, {"qty": "1/2대", "desc": null, "name": "대파"}, {"qty": "약간", "desc": null, "name": "통깨"}, {"qty": "2T", "desc": null, "name": "고추장"}, {"qty": "1.5T", "desc": null, "name": "고추가루"}, {"qty": "2T", "desc": null, "name": "간장"}, {"qty": "3T", "desc": null, "name": "설탕"}]}'::jsonb);
INSERT INTO recipes (id, recipe_id, source_url, title, servings, cook_time, difficulty, tips, copyright, created_at, updated_at, raw_data) VALUES (408, '6895723', 'https://www.10000recipe.com/recipe/6895723', '생선 없이도 깊은 맛이 나는 ''백종원 무조림'' 레시피', '2인분', '30분 이내', '아무나', '[]'::jsonb, '뽀유TV', 2025-11-23 01:51:00.533147, 2025-11-23 01:51:00.533147, '{"tips": [], "steps": ["먼저 무를 반달모양으로 썰어 주시되 적당한 두께감으로 썰어주셔요", "대파도 송송송 썰어 준비합니다", "냄비에 썰어 놓은 무와 멸치1줌과 물을 넣어 줍니다.", "간장2/3컵, 고추가루4T, 설탕2T,다진마늘1T, 들기름1T, 대파, 생강을 넣고 센불에서 10분정도 끓여 줍니다.", "끓이면서 나오는 거품은 걷어내주셔야 깔끔한 맛이 납니다.", "어느 정도 익으면 양념이 잘 베이도록 가볍게 뒤적뒤적 해주시고 중불에서 잘 졸여주시면 끝!", "생선 없이도 깊은 맛이 나는 밥도둑 백종원 무조림 완성입니다. 뜨끈한 밥과 함께 먹어보니 무만 넣었는데도 기대이상으로 넘 맛있더라구요!밥 한공기 뚝딱 했답니다^^"], "title": "생선 없이도 깊은 맛이 나는 ''백종원 무조림'' 레시피", "servings": "2인분", "cook_time": "30분 이내", "copyright": "뽀유TV", "recipe_id": "6895723", "step_tips": [null, null, null, null, null, null, null], "difficulty": "아무나", "source_url": "https://www.10000recipe.com/recipe/6895723", "ingredients": ["작은 무 1/2개", "멸치 1줌", "대파 1대", "물 600ml", "간장 2/3종이컵", "고추가루 4T", "설탕 2T", "다진마늘 1T", "들기름 1T", "생강 약간"], "ingredients_struct": [{"qty": "1/2개", "desc": null, "name": "작은 무"}, {"qty": "1줌", "desc": null, "name": "멸치"}, {"qty": "1대", "desc": null, "name": "대파"}, {"qty": "600ml", "desc": null, "name": "물"}, {"qty": "2/3종이컵", "desc": null, "name": "간장"}, {"qty": "4T", "desc": null, "name": "고추가루"}, {"qty": "2T", "desc": null, "name": "설탕"}, {"qty": "1T", "desc": null, "name": "다진마늘"}, {"qty": "1T", "desc": null, "name": "들기름"}, {"qty": "약간", "desc": null, "name": "생강"}]}'::jsonb);
INSERT INTO recipes (id, recipe_id, source_url, title, servings, cook_time, difficulty, tips, copyright, created_at, updated_at, raw_data) VALUES (409, '6896908', 'https://www.10000recipe.com/recipe/6896908', '비빔국수 황금레시피', '2인분', '30분 이내', '아무나', '[]'::jsonb, 'ㄴ딸기바람', 2025-11-23 01:52:15.486376, 2025-11-23 01:52:15.486376, '{"tips": [], "steps": ["위에 적힌 양념장재료를 모두 넣어 만들어 주세요. 이 양념장은 정말로 황금레시피입니다. 맛 본 사람들 모두 살면서 먹어 본 비빔국수 중에서 단연 최고라고 해주었어요!!", "물에 소금을 약간 넣고 끓으면 면을 넣고 5분간 삶아주는 사이에 열무는 종종 썰고 깻잎도 썰어주세요. 없으시면 생략해도 되고 넣고싶으신 고명 올리시면 되겠죠?^^", "소금 약간 넣어 삶은 면을 건져서 얼음물에 탱탱한 면발을 헹궈줘요!", "물기 잠깐 빼는 사이에 집에서 만든 오쿠로 만든 수제 훈제계란을 반으로 딱! 없으시면 생략해도 되지만 계란을 올리면 데코가 살지요^^", "물기뺀 면을 그릇에 닮고 썰어둔 열무와 양념장을 올리고", "꺳잎과 삶을 달걀을 올리고 마지막으로 꺠를 뿌려주세요>___", "김도 잘라 올리고 깻잎과 계란 그리고 마지막으로 깨소금까지! 완성입니다^^"], "title": "비빔국수 황금레시피", "servings": "2인분", "cook_time": "30분 이내", "copyright": "ㄴ딸기바람", "recipe_id": "6896908", "step_tips": [null, null, null, null, null, null, null], "difficulty": "아무나", "source_url": "https://www.10000recipe.com/recipe/6896908", "ingredients": ["국수 2인분", "깻잎 2~3장", "열무 김치 있으면 적당량", "고추장 2T", "고춧가루 2T", "식초 4T", "설탕 3T", "다진마늘 1T", "간장 2T", "와사비 1t", "참기름 1.5T", "다진 고추 약간", "깨소금 약간"], "ingredients_struct": [{"qty": "2인분", "desc": null, "name": "국수"}, {"qty": "2~3장", "desc": null, "name": "깻잎"}, {"qty": "적당량", "desc": null, "name": "열무 김치 있으면"}, {"qty": "2T", "desc": null, "name": "고추장"}, {"qty": "2T", "desc": null, "name": "고춧가루"}, {"qty": "4T", "desc": null, "name": "식초"}, {"qty": "3T", "desc": null, "name": "설탕"}, {"qty": "1T", "desc": null, "name": "다진마늘"}, {"qty": "2T", "desc": null, "name": "간장"}, {"qty": "1t", "desc": null, "name": "와사비"}, {"qty": "1.5T", "desc": null, "name": "참기름"}, {"qty": "약간", "desc": null, "name": "다진 고추"}, {"qty": "약간", "desc": null, "name": "깨소금"}]}'::jsonb);
INSERT INTO recipes (id, recipe_id, source_url, title, servings, cook_time, difficulty, tips, copyright, created_at, updated_at, raw_data) VALUES (288, '6840027', 'https://www.10000recipe.com/recipe/6840027', '[연근조림] 아작 아작 달콤 짭쪼름한 연근 조림 만들기', '6인분 이상', '30분 이내', '아무나', '["*식초를 넣는 이유는 연근의 아린맛을 없애주려고 넣어요."]'::jsonb, '양싸', 2025-11-22 23:38:20.491322, 2025-11-23 01:27:03.847867, '{"tips": ["*식초를 넣는 이유는 연근의 아린맛을 없애주려고 넣어요."], "steps": ["감자 칼로 연근의 껍질을 벗겨주세요.", "그리고 적당한 두께로 잘라주세요. 자르시고 물에 한번 깨끗이 씻어주세요.", "냄비에 연근을 넣고 식초 3T를 넣어줍니다. 식초를 넣는 이유는 연근의 아린맛을 없애주려고 넣어요. 소금 1/2T도 넣고 연근이 반쯤 익을때까지 삶아줍니다.", "연근을 식초 넣고 한번 삶아주면 조릴 때 더 편하겠죠? 체에 받쳐 물만 버려주세요.", "물 600cc, 간장 20T, 설탕 15T, 물엿 10T, 깨를 넣고 양념장을 만들어주세요. 20큰술 이라니깐 많아 보이죠? 숟가락으로 넣다보면 안많아요!^^ *대용량 주의*", "냄비에 연근과 양념장을 넣고 센불에서 끓이시다가 어느 정도 물이 졸아 들면 중불로 바꾸시고 졸여주시면 됩니다.", "거의 다 졸아 들때쯤 마무리로 물엿 한큰술 넣어주시면 윤기 좌르르~~~ 깨도 한번 더~!! 완성!!", "아작 아작 달콤 짭쪼름~~ 너무 좋아 연근 조림♡ 단짠 단짠 단짠! 진리입니다!"], "title": "[연근조림] 아작 아작 달콤 짭쪼름한 연근 조림 만들기", "servings": "6인분 이상", "cook_time": "30분 이내", "copyright": "양싸", "recipe_id": "6840027", "step_tips": [null, null, null, null, null, null, null, null], "difficulty": "아무나", "source_url": "https://www.10000recipe.com/recipe/6840027", "ingredients": ["연근 800g 2개", "식초 3T", "소금 1/2T", "물 500cc", "간장 20T", "설탕 15T", "물엿 10T", "깨 약간"], "ingredients_struct": [{"qty": "2개", "desc": null, "name": "연근 800g"}, {"qty": "3T", "desc": null, "name": "식초"}, {"qty": "1/2T", "desc": null, "name": "소금"}, {"qty": "500cc", "desc": null, "name": "물"}, {"qty": "20T", "desc": null, "name": "간장"}, {"qty": "15T", "desc": null, "name": "설탕"}, {"qty": "10T", "desc": null, "name": "물엿"}, {"qty": "약간", "desc": null, "name": "깨"}]}'::jsonb);
INSERT INTO recipes (id, recipe_id, source_url, title, servings, cook_time, difficulty, tips, copyright, created_at, updated_at, raw_data) VALUES (289, '6843373', 'https://www.10000recipe.com/recipe/6843373', '백종원 소고기무국 만들기!', '2인분', '30분 이내', '초급', '[]'::jsonb, '혀니ㅋ', 2025-11-22 23:40:30.253556, 2025-11-23 01:27:03.856199, '{"tips": [], "steps": ["이제까지는 소고기무국을 국거리용 고기를 넣고 끓였었는데요. 요번에 집밥백선생에서 불고기용 고기를 쓰는걸 보고 저도 한번 사봤어요! 고기는 살짝 핏불을 빼주시고", "무는 먹기좋게 썰어주세요. 무는 소고기의 부위에 따라 두께가 결정된다고 해요~ 오래 끓여야되면 무 두께를 두껍게 짧게 끓여도 되면 무 두께를 얇게 저는 그냥 얇지도 두껍지도 않게 대충 먹기좋게 썰었어요.", "냄비에 참기름 3스푼을 넣고 소고기를 넣어 볶아줍니다.", "그리고 소고기의 핏기가 없어지면 무도 넣어 같이 볶아주세요.", "볶다보니 재료가 많아 냄비가 작더라구요 ㅜㅜ 큰냄비로 후다닥 옮겨줬어요.", "그리고 어느정도 볶아지면 물을 넣어주세요. 물은 재료의 2배라는데 그냥 충분히 넉넉히 넣어주심 될것 같아요.", "끓기시작하면 위로 올라오는 거품들은 다 깔끔하게 걷어주시고", "다진마늘 1스푼과", "국간장 2스푼을 넣어주세요.", "그리고 뚜껑을 닫고 20분정도 푹~ 끓여줬어요. 오래오래 끓여줄수록 무와 고기맛이 훨씬 좋다고 해요.", "20분정도 끓인후 무가 어느정도익으면 송송썰은 대파를 가득 넣어주시고 설탕 3분의 1스푼정도랑 후추 톡톡 넣고 소금으로 간을 해주면 끝이에요. 설탕은 넣어도 되고 안넣어도 된다는데 확실히 설탕이 들어가야 감칠맛이 더 나는것 같더라구요!", "먹기좋게 국그릇에 담아주면 밥도둑 소고기무국 완성이에요. 확실히 국거리소고기는 조금 질긴감이 있었는데 불고기용을 넣으니 고기도 더 연하고 좋은것 같더라구요. 그리고 처음에 고기를 참기름에 볶아서 그런지 더 고소한것 같아요. 소고기는 양지.불고기 등등 아무거나 다 된다고 하는데 저는 개인적으로 불고기용 고기 추천해요. 확실히 연해서 더 맛있는것 같아요. 그리고 백종원표 소고기무국의 신의 한수는 역시나 설탕! 설탕 그 쪼금 들어간게 단맛이 아닌 정말 대단한 역할을 한것 같아요!!~ 요거 소고기무국 하나면 밥한그릇 뚝딱! 딴거없이 김치만 있어도 호로록~~ 든든하게 먹지요."], "title": "백종원 소고기무국 만들기!", "servings": "2인분", "cook_time": "30분 이내", "copyright": "혀니ㅋ", "recipe_id": "6843373", "step_tips": [null, null, null, null, null, null, null, null, null, null, null, null], "difficulty": "초급", "source_url": "https://www.10000recipe.com/recipe/6843373", "ingredients": ["소고기 불고기용 200g", "무 2~3줌", "대파", "물", "참기름 3스푼", "국간장 2스푼", "다진마늘 1스푼", "설탕 1/3스푼", "소금", "후추"], "ingredients_struct": [{"qty": "200g", "desc": null, "name": "소고기 불고기용"}, {"qty": "2~3줌", "desc": null, "name": "무"}, {"qty": "", "desc": null, "name": "대파"}, {"qty": "", "desc": null, "name": "물"}, {"qty": "3스푼", "desc": null, "name": "참기름"}, {"qty": "2스푼", "desc": null, "name": "국간장"}, {"qty": "1스푼", "desc": null, "name": "다진마늘"}, {"qty": "1/3스푼", "desc": null, "name": "설탕"}, {"qty": "", "desc": null, "name": "소금"}, {"qty": "", "desc": null, "name": "후추"}]}'::jsonb);
INSERT INTO recipes (id, recipe_id, source_url, title, servings, cook_time, difficulty, tips, copyright, created_at, updated_at, raw_data) VALUES (291, '6850020', 'https://www.10000recipe.com/recipe/6850020', '고구마 맛탕 # 초보라면 이 방법으로', '2인분', '30분 이내', '아무나', '[]'::jsonb, '숑하우스', 2025-11-22 23:44:12.976085, 2025-11-23 01:27:03.881365, '{"tips": [], "steps": ["고구마는 깨끗이 씻어 껍질을 벗기고 알맞은 크기로 잘라주세요.", "고구마를 10분정도 물에 담가 전분을 빼주세요.", "비닐팩에 넣은 뒤에 매듭은 살살 묶고 전자레인지 2~4분정도 돌려주세요. (꽉 묶으면 터질 수 있어요) * 약간 쪄주면 튀길 때 시간이 적게 걸린답니다.", "푹 익히는게 아니고 살짝 익혀주세요.", "전자레인지에 꺼낸 후 물기를 제거해 주세요. *튀기기 전 물기 제거는 필수", "튀김 온도는 나무젓가락을 넣어서 기포가 올라오면 OK", "고구마를 넣고 튀겨주세요.(10분 정도) 젓가락으로 찔러봤을 때 쑥 들어가면 다 익은 거에요. -> 체에 걸러 기름을 빼 놔주세요.", "* 소스 만들기 물 4T, 설탕 1T, 올리고당 5T 팬에 넣고 바글바글 끓여주세요.", "끓어오르면 고구마를 넣고 골고루 버무려 주세요. * 중간에 불을 끄고 열기로만 섞어주시면 됩니다."], "title": "고구마 맛탕 # 초보라면 이 방법으로", "servings": "2인분", "cook_time": "30분 이내", "copyright": "숑하우스", "recipe_id": "6850020", "step_tips": [null, null, "전자레인지", null, null, null, null, null, null], "difficulty": "아무나", "source_url": "https://www.10000recipe.com/recipe/6850020", "ingredients": ["고구마 3~4개", "식용유 고구마가 자박할 정도", "설탕 1T", "꿀 또는 올리고당 5T", "물 4T"], "ingredients_struct": [{"qty": "3~4개", "desc": null, "name": "고구마"}, {"qty": "", "desc": null, "name": "식용유 고구마가 자박할 정도"}, {"qty": "1T", "desc": null, "name": "설탕"}, {"qty": "5T", "desc": null, "name": "꿀 또는 올리고당"}, {"qty": "4T", "desc": null, "name": "물"}]}'::jsonb);
INSERT INTO recipes (id, recipe_id, source_url, title, servings, cook_time, difficulty, tips, copyright, created_at, updated_at, raw_data) VALUES (410, '6897772', 'https://www.10000recipe.com/recipe/6897772', '실패 없는 백종원 레시피 :: 소고기뭇국', '4인분', '60분 이내', '아무나', '["Tip 1. 냉동소고기는 꼭 핏물을 제거해줘야 잡내가 나지 않아요. Tip 2. 소고기 : 무 : 물 비율이 1 : 2 : 5 가 적당해요."]'::jsonb, '보동', 2025-11-23 01:54:22.797087, 2025-11-23 01:54:22.797087, '{"tips": ["Tip 1. 냉동소고기는 꼭 핏물을 제거해줘야 잡내가 나지 않아요. Tip 2. 소고기 : 무 : 물 비율이 1 : 2 : 5 가 적당해요."], "steps": ["소고기는 찬물에 10분정도 담가 핏물을 제거해주세요.", "무는 네모지게 토막 썰어주세요. 두께는 0.5cm정도로 너무 두껍지 않고 너무 얇지 않은 두께로 준비해주세요.", "대파 1대는 큼직큼직 어슷 썰어주세요.", "참기름 1큰술을 넣어준 후 고기를 넣고 겉면의 색이 변할 때까지 볶아주세요.", "고기가 갈색으로 변하면 무를 넣어 준 후 살짝 투명해질때까지 볶아주세요.", "무와 고기가 잘 볶아지면 물을 넣고 중불로 끓여주세요. 위에 생기는 거품은 걷어내주세요.", "국간장 2큰술, 소금 1작은술, 다진마늘 1/2큰술, 설탕1/2큰술을 넣어 간을 해주세요.", "중불로 20분간 보글보글 끓여준 후 대파와 후추를 톡톡 뿌려주면 완성!!"], "title": "실패 없는 백종원 레시피 :: 소고기뭇국", "servings": "4인분", "cook_time": "60분 이내", "copyright": "보동", "recipe_id": "6897772", "step_tips": [null, null, null, null, null, null, null, null], "difficulty": "아무나", "source_url": "https://www.10000recipe.com/recipe/6897772", "ingredients": ["무 2컵", "소고기 1컵", "물 5컵", "대파 1대", "참기름 1큰술", "다진마늘 1/2큰술", "국간장 2큰술", "소금 1작은술", "설탕 1/2큰술", "후추 약간"], "ingredients_struct": [{"qty": "2컵", "desc": null, "name": "무"}, {"qty": "1컵", "desc": null, "name": "소고기"}, {"qty": "5컵", "desc": null, "name": "물"}, {"qty": "1대", "desc": null, "name": "대파"}, {"qty": "1큰술", "desc": null, "name": "참기름"}, {"qty": "1/2큰술", "desc": null, "name": "다진마늘"}, {"qty": "2큰술", "desc": null, "name": "국간장"}, {"qty": "1작은술", "desc": null, "name": "소금"}, {"qty": "1/2큰술", "desc": null, "name": "설탕"}, {"qty": "약간", "desc": null, "name": "후추"}]}'::jsonb);
INSERT INTO recipes (id, recipe_id, source_url, title, servings, cook_time, difficulty, tips, copyright, created_at, updated_at, raw_data) VALUES (411, '6901938', 'https://www.10000recipe.com/recipe/6901938', '크림파스타 만들기 크림스파게티 만드는 법 생각보다 간단해요 :)', '1인분', '20분 이내', '초급', '[]'::jsonb, '승혜의야미로그', 2025-11-23 01:56:19.534106, 2025-11-23 01:56:19.534106, '{"tips": [], "steps": ["크림파스타를 만들기 위해 필요한 재료들을 알려드릴게요.", "먼저 베이컨을 먹기 좋은 크기로 잘라주세요. 양송이버섯도 씻어서 잘라주세요.", "오늘 크림파스타는 1인분만 만들 거라 100원 동전 크기 정도의 크림파스타를 만들게요. 보기엔 양이 적어 보여도 면을 익히고 크림소스가 추가되면 양이 딱 좋을 것 같아요.", "끓는 물에 소금을 약간 넣어서 팔팔 끓여주세요.", "파스타 건면을 골고루 펼쳐 넣어주세요.", "젓가락으로 면을 끓는 물 안으로 넣어서 5분 정도 익혀주세요. 처음에 끓는 물에 어느정도 면을 익혀주면 나중에 크림소스랑 볶아주실 때 시간을 단축할 수 있어요!", "끓는 물에서 5분 정도 익힌 파스타면을 채반에 옮겨주세요. ★이때!!!★ 찬물에 헹구시지 마시고 그냥 이대로 파스타면을 식혀주세요.", "이제 크림파스타 소스를 만들 거예요! 달궈진 프라이팬에 올리브유를 적당히 넣고 다진 마늘을 넣고 볶아주세요.", "다진 마늘이 어느 정도 볶아졌으면 버터를 넣어주세요. 그리고 버터가 다 녹았으면 양송이버섯을 넣고 볶아주세요.", "양송이버섯이 어느 정도 노릇하게 익었으면 채썬 양파와 베이컨을 넣어주세용", "채썬 양파와 베이컨이 잘 익을 때까지 볶아볶아줍니당!", "그리고 흰우유 180ml를 넣고 보글보글 끓여주세요!", "체다 치즈 2장을 넣어 크림파스타 소스를 진하게 만들어줍니다. 더욱 진한 크림파스타를 드시고 싶으시면 체다 치즈를 더 넣으셔도 좋아요!", "체다 치즈가 잘 녹을 때까지 보글보글 계속 끓여줍니다. 크림소스를 끓일수록 색깔이 점점 진해져요! 그리고 중간에 크림소스 간을 보셔서 소금으로 간을 맞춰주세요. 저도 크림소스가 밍밍해서 소금을 조금씩 넣어가면서 간을 맞췄어요!", "채반에서 쉬고 있었던 파스타면을 넣어주세요.", "파스타면과 크림소스를 잘 섞어주세요. 걸쭉하게 드시고 싶으시면 오래 끓이시면 되고, 그냥 묽게 드시고 싶으시면 잠깐만 끓이셔서 바로 드시면 돼요! 저는 걸쭉한 크림파스타를 좋아하기 때문에 오래 끓여줄 거예용! 이쯤에서 그릇에 옮겨 담아줄게요.", "완성된 크림파스타 위에 후추를 솔솔 뿌려주면 완성입니당! 양이 딱 적당한 것 같아요!", "꾸덕꾸덕 걸쭉걸쭉하니 딱 제가 원하는 농도로 잘 만들어졌어요! 처음 만들어 본 크림파스타! 맛은 어떨지 한 번 먹어볼게요.", "진짜 거짓말 안하고 밖에서 파는 거랑 맛이 정말 똑같아요!!! 너무 맛있어서 놀랬어요. 집에서 쉽게 만든 크림파스타가 이렇게 맛있다니!!! 이건 대박사건이예요!!!!!!", "크림파스타를 먹다가 냉장고에 있던 피클이 생각나서 함께 먹었어요. 크림파스타 ♥ 피클은 사랑이죠! 너무너무너무 맛있어요 진짜!!! 따봉"], "title": "크림파스타 만들기 크림스파게티 만드는 법 생각보다 간단해요 :)", "servings": "1인분", "cook_time": "20분 이내", "copyright": "승혜의야미로그", "recipe_id": "6901938", "step_tips": [null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null], "difficulty": "초급", "source_url": "https://www.10000recipe.com/recipe/6901938", "ingredients": ["올리브유 약간", "파스타면 1인분", "베이컨 작은 거 4장", "체다치즈 2장", "소금 약간", "후추 약간", "흰우유 180ml", "양송이버섯 2개", "다진 마늘 1스푼", "버터 1숟갈", "채 썬 양파 적당량"], "ingredients_struct": [{"qty": "약간", "desc": null, "name": "올리브유"}, {"qty": "1인분", "desc": null, "name": "파스타면"}, {"qty": "4장", "desc": null, "name": "베이컨 작은 거"}, {"qty": "2장", "desc": null, "name": "체다치즈"}, {"qty": "약간", "desc": null, "name": "소금"}, {"qty": "약간", "desc": null, "name": "후추"}, {"qty": "180ml", "desc": null, "name": "흰우유"}, {"qty": "2개", "desc": null, "name": "양송이버섯"}, {"qty": "1스푼", "desc": null, "name": "다진 마늘"}, {"qty": "1숟갈", "desc": null, "name": "버터"}, {"qty": "적당량", "desc": null, "name": "채 썬 양파"}]}'::jsonb);
INSERT INTO recipes (id, recipe_id, source_url, title, servings, cook_time, difficulty, tips, copyright, created_at, updated_at, raw_data) VALUES (412, '6903507', 'https://www.10000recipe.com/recipe/6903507', '오징어 볶음, 향과 맛이 일품! 백종원 오징어 볶음', '4인분', '20분 이내', '아무나', '[]'::jsonb, 'hancy002', 2025-11-23 01:59:03.894882, 2025-11-23 01:59:03.894882, '{"tips": [], "steps": ["양배추, 당근, 양파, 파(준비량의 반)는 길쭉하고 굵게, 고추도 어슷큼직하게 썹니다. 오징어도 깨끗하게 손질해서 먹기좋은 크기로 썹니다.", "팬에 식용유 3큰술과 송송썬 파를 넣은 후 불을 올려 볶아요. 파기름이 충분히 나오게, 노르스름해질때까지 볶습니다.", "파가 노르스름하게 볶아지면 오징어를 넣고 볶다가 설탕 1큰술을 넣어 볶습니다.", "마늘 1큰술 고추장 1큰술을 넣어고 볶습니다. 볶는 시간은 최소로 하세요, 마늘넣고 팬들어가며 섞어주는식으로 볶고, 고추장 넣고도 마찬가지로요.", "간장 5큰술, 고춧가루 3큰술을 넣고 볶습니다. 너무 뻑뻑한 느낌이 들면 물 반컵을 넣고 볶습니다.", "이제 준비한 채소를 볶던 팬에 전부 넣습니다.", "잘 섞어가며 채소의 숨이 죽지않게 단시간으로 볶다가 불에서 내리기 직전 참기름을 촤악~ 둘러주고 끝!!", "그릇이나 달군 팬에 먹음직스럽게 담고 통깨를 솔솔 뿌려 상에 냅니다. 완성!입니다. 맛있게 드세요~"], "title": "오징어 볶음, 향과 맛이 일품! 백종원 오징어 볶음", "servings": "4인분", "cook_time": "20분 이내", "copyright": "hancy002", "recipe_id": "6903507", "step_tips": [null, null, null, null, null, null, null, null], "difficulty": "아무나", "source_url": "https://www.10000recipe.com/recipe/6903507", "ingredients": ["오징어 큰사이즈 2마리", "양배추 1/4통", "당근 1/2개", "양파 1개", "풋고추 2개", "파 2뿌리", "식용유 3큰술", "설탕 1큰술", "마늘 1큰술", "고추장 1큰술", "간장 5큰술", "고춧가루 3큰술", "물 1/2컵", "참기름 1큰술", "통깨 적당량"], "ingredients_struct": [{"qty": "2마리", "desc": null, "name": "오징어 큰사이즈"}, {"qty": "1/4통", "desc": null, "name": "양배추"}, {"qty": "1/2개", "desc": null, "name": "당근"}, {"qty": "1개", "desc": null, "name": "양파"}, {"qty": "2개", "desc": null, "name": "풋고추"}, {"qty": "2뿌리", "desc": null, "name": "파"}, {"qty": "3큰술", "desc": null, "name": "식용유"}, {"qty": "1큰술", "desc": null, "name": "설탕"}, {"qty": "1큰술", "desc": null, "name": "마늘"}, {"qty": "1큰술", "desc": null, "name": "고추장"}, {"qty": "5큰술", "desc": null, "name": "간장"}, {"qty": "3큰술", "desc": null, "name": "고춧가루"}, {"qty": "1/2컵", "desc": null, "name": "물"}, {"qty": "1큰술", "desc": null, "name": "참기름"}, {"qty": "적당량", "desc": null, "name": "통깨"}]}'::jsonb);
INSERT INTO recipes (id, recipe_id, source_url, title, servings, cook_time, difficulty, tips, copyright, created_at, updated_at, raw_data) VALUES (293, '6851272', 'https://www.10000recipe.com/recipe/6851272', '배추겉절이 만드는 법 배추겉절이 황금레시피', '3인분', '60분 이내', '아무나', '[]'::jsonb, '꽃청춘이주부', 2025-11-22 23:47:21.200944, 2025-11-23 01:27:03.903367, '{"tips": [], "steps": ["재료:알배추1통,쪽파10개,굵은소금1/2컵 양념재료:참기름1스푼,새우젓1스푼,액젓3스푼,고추가루6스푼,설탕1스푼,마늘1스푼,매실청2스푼,소금 (계량은 모두 밥숟가락과 종이컵기준입니다)", "배추를 깨끗하게 씻고, 배추한장을 반으로 자른후 어슷하게 사진처럼 잘라줍니다. 손으로 하시는 분들도 계신데 저는 칼을 이용해서 잘라주었어요", "굵은소금1/2컵을 준비한후 물을 1컵을 준비해서 배추 사이사이에 넣어서 30분에서 1시간정도 절여줍니다.", "배추는 중간중간 한번씩 섞어서 골고루 절여지도록 해줍니다.", "쪽파를 10줄을 준비한뒤 3cm~5cm크기로 잘라서 준비합니다.", "이제 양념장을 만들어 줄께요. 새우젓1스푼,액젓3스푼,고추가루6스푼,설탕1스푼,마늘1스푼,매실청2스푼", "양념장이 골고루 섞이도록 해주고 만약에 너무 퍽퍽하다면 물을 2스푼정도 넣어줍니다.", "배추가 잘절여졌는지 아는 방법은 배추 줄기부분을 구부려봤을때 잘휘어지면 잘 절여진거랍니다. 절여진 배추는 찬물에 2-3번정도 헹구어 체에 걸러 물기를 빼줍니다.", "이제 큰볼에 절인배추와 쪽파를 넣고~", "만들어둔 양념장을 넣어줍니다. 양념장이 잘섞이도록 살살 버무려준다음", "참기름을1스푼을 넣고 다시한번 버무려 주세요. 그리고 모자란 간은 소금으로 맞추어주시면 됩니다.", "요렇게 버부려 준다음 깨를 넣으셔도 되고 안넣으셔도 되고~", "방금 막해서 맛있는 배추겉저리가 완성이 되었어요!"], "title": "배추겉절이 만드는 법 배추겉절이 황금레시피", "servings": "3인분", "cook_time": "60분 이내", "copyright": "꽃청춘이주부", "recipe_id": "6851272", "step_tips": [null, null, null, null, null, null, null, null, null, null, null, null, null], "difficulty": "아무나", "source_url": "https://www.10000recipe.com/recipe/6851272", "ingredients": ["알배추 1통", "쪽파 10개", "굵은소금 1/2컵", "참기름 1스푼", "새우젓 1스푼", "액젓 3스푼", "고추가루 6스푼", "설탕 1스푼", "마늘 1스푼", "매실청 2스푼", "소금 약간"], "ingredients_struct": [{"qty": "1통", "desc": null, "name": "알배추"}, {"qty": "10개", "desc": null, "name": "쪽파"}, {"qty": "1/2컵", "desc": null, "name": "굵은소금"}, {"qty": "1스푼", "desc": null, "name": "참기름"}, {"qty": "1스푼", "desc": null, "name": "새우젓"}, {"qty": "3스푼", "desc": null, "name": "액젓"}, {"qty": "6스푼", "desc": null, "name": "고추가루"}, {"qty": "1스푼", "desc": null, "name": "설탕"}, {"qty": "1스푼", "desc": null, "name": "마늘"}, {"qty": "2스푼", "desc": null, "name": "매실청"}, {"qty": "약간", "desc": null, "name": "소금"}]}'::jsonb);
INSERT INTO recipes (id, recipe_id, source_url, title, servings, cook_time, difficulty, tips, copyright, created_at, updated_at, raw_data) VALUES (294, '6851661', 'https://www.10000recipe.com/recipe/6851661', '쇠고기미역국 맛있게 끓이는 방법', '2인분', '30분 이내', '아무나', '[]'::jsonb, '율맘써니', 2025-11-22 23:49:13.148104, 2025-11-23 01:27:03.914242, '{"tips": [], "steps": ["핏물을 물에 씻겨내지 마세요!! 맛이 떨어져요. 간장과 마늘로 밑간을 해주세요. 기호에 따라 살짝 후춧가루를 넣으셔도 돼요.", "참기름 한 큰술을 넣고 볶아주세요", "불린 미역은 먹기 좋게 자른 후 간장 1T를 넣고 조물조물 간을 해주세요", "미역 볶을 때도 참기름을 한 큰술 넣어주심 좋은데 전 기름기가 많은듯해서 패스했어요.", "쌀뜨물이 있으면 넣고 끓여주세요. 없으면 생수로~ 물은 18컵 정도,, 정말 넉넉히 넣고 오랫동안 끓여줘야 더 맛있는 미역국이 완성돼요", "센 불에서 40분, 중불에서 30분, 약불에서 40분 정도 끓여줬어요", "약불로 끓일 때 간을 해주세요. 뜨거울 때 간을 보면 자칫 짜질 수 있으니 주의하세요"], "title": "쇠고기미역국 맛있게 끓이는 방법", "servings": "2인분", "cook_time": "30분 이내", "copyright": "율맘써니", "recipe_id": "6851661", "step_tips": [null, null, null, null, null, null, null], "difficulty": "아무나", "source_url": "https://www.10000recipe.com/recipe/6851661", "ingredients": ["불린미역", "소고기 1컵", "다진마늘 0.5T", "간장 2T", "멸치액젓 2T", "소금 약간", "생수 18컵"], "ingredients_struct": [{"qty": "", "desc": null, "name": "불린미역"}, {"qty": "1컵", "desc": null, "name": "소고기"}, {"qty": "0.5T", "desc": null, "name": "다진마늘"}, {"qty": "2T", "desc": null, "name": "간장"}, {"qty": "2T", "desc": null, "name": "멸치액젓"}, {"qty": "약간", "desc": null, "name": "소금"}, {"qty": "18컵", "desc": null, "name": "생수"}]}'::jsonb);
INSERT INTO recipes (id, recipe_id, source_url, title, servings, cook_time, difficulty, tips, copyright, created_at, updated_at, raw_data) VALUES (296, '6851866', 'https://www.10000recipe.com/recipe/6851866', '부대찌개 황금레시피 /백종원 부대찌개 맛보장레시피', '3인분', '60분 이내', '초급', '["*김치가 너무 신 경우에는 설탕을 조금 더 넣어주세요"]'::jsonb, '쏭민2', 2025-11-22 23:52:44.382159, 2025-11-23 01:27:03.934570, '{"tips": ["*김치가 너무 신 경우에는 설탕을 조금 더 넣어주세요"], "steps": ["통조림 음식은 유리그릇이나 다른용기에 담아 두시는게 환경호르몬 영향이 적다네요, 캔참치 , 스팸 , 각종 통조림류 등등 저는 원래 항상 고기나 햄 ,어묵 등은 데쳐서 기름과 불순물을 제거 해요 ㅎ 끓는물 부어서 5분정도 두세요~!", "소세지는 냉동이였기때문에 팔팔 끓여서 해동했어요~", "부대찌개 황금레시피 양념장은 1~2 냉장고 숙성하면 더 깊은맛이 나지만... 귀차니즘 으로 그냥 섞지도 않고 준비했어요 ㅎ 잘 섞어주셔도 되지만..어차피 끓으면서 섞이니까 편하게 만들께요! 고추장2T , 고춧가루2T ,다진마늘1T ,간장3T , 설탕1T 넣고 물은 600~700 정도 넣어주세요~!", "준비된 백종원 부대찌개 양념장이 끓을때 까지 나머지 재료 준비해주세요 ! 김치 , 떡 , 햄 ,양파, 파 등등", "신김치 저기서 3분의1 정도 사용했어요~! 김치의 맛에 따라 맛이다를수 있어요 혹시 김치가 너무 신 경우에는 설탕을 조금 더 넣어주세요 ㅎ", "냉동떡도 준비했어요 ㅎ 더 미리 꺼내야했는데 ... 있는줄도 모르다가 ㅜ;; 냉동 파 꺼내다가 발견했네요 ㅎㅎ 양파도 썰어주세요~", "부대찌개 황금레시피 양념장이 끓으면 김치먼저 넣어주시는게 좋아요~ 처음부터 몽땅 쓸어넣어도 좋지만 ㅎ 전 김치가 물렁물렁 해지는게 더 좋아서 제일 먼저 넣었어요 ㅎ", "초벌한 소세지를 건져서 먹기좋게 썰어주세요 ㅎ", "양념장이 한번더 끓으면 스팸 ! 먼저 넣고 소세지를 넣었어요 ㅎ 소세지는 초벌로 삶았고 스팸은 그냥 뜨거운물에 담궜던거라 같이 넣으셔도 전혀 상관없어요 ㅎ", "소세지 까지 넣어 팔팔 끓여주세요~ ^^", "팔팔 끓어 간이 딱 맞으면 야채를 넣을꺼에요 ㅎ 혹 , 간이 안맞으면 조금더 간을 하시면 됩니다!", "잊고 있던 떡도 투하~! 생떡이면 마지막에! 저처럼 냉동떡은 햄 넣을때 같이 넣으셔도 좋아요 ㅎ", "파도 듬뿍 넣어주세용~! ㅎ 한번더 끓을때까지 끓이면 완성된 부대찌개 황금레시피 !"], "title": "부대찌개 황금레시피 /백종원 부대찌개 맛보장레시피", "servings": "3인분", "cook_time": "60분 이내", "copyright": "쏭민2", "recipe_id": "6851866", "step_tips": [null, null, null, null, null, null, null, null, null, null, null, null, null], "difficulty": "초급", "source_url": "https://www.10000recipe.com/recipe/6851866", "ingredients": ["소세지 1팩", "스팸 1캔", "고추장 2T", "고춧가루 2T", "다진마늘 1T", "간장 3T", "설탕 1T", "물 600~700ml", "김치 1줌", "양파 1/2개", "파 약간", "고기or베이컨 생략가능 적당량", "치즈 생략가능 1장", "라면사리 생략가능 1개"], "ingredients_struct": [{"qty": "1팩", "desc": null, "name": "소세지"}, {"qty": "1캔", "desc": null, "name": "스팸"}, {"qty": "2T", "desc": null, "name": "고추장"}, {"qty": "2T", "desc": null, "name": "고춧가루"}, {"qty": "1T", "desc": null, "name": "다진마늘"}, {"qty": "3T", "desc": null, "name": "간장"}, {"qty": "1T", "desc": null, "name": "설탕"}, {"qty": "600~700ml", "desc": null, "name": "물"}, {"qty": "1줌", "desc": null, "name": "김치"}, {"qty": "1/2개", "desc": null, "name": "양파"}, {"qty": "약간", "desc": null, "name": "파"}, {"qty": "적당량", "desc": null, "name": "고기or베이컨 생략가능"}, {"qty": "1장", "desc": null, "name": "치즈 생략가능"}, {"qty": "1개", "desc": null, "name": "라면사리 생략가능"}]}'::jsonb);
INSERT INTO recipes (id, recipe_id, source_url, title, servings, cook_time, difficulty, tips, copyright, created_at, updated_at, raw_data) VALUES (413, '6905196', 'https://www.10000recipe.com/recipe/6905196', '국물이 너무 개운해요~맑은콩나물국 맛있게 끓이는법(김진옥요리가좋다)', '4인분', '15분 이내', '아무나', '["1.저의 계량은 밥숟가락 한숟가락이 1T입니다~ 2.칼칼한 맛을 즐기시는 분은 청양고추 썰어서 넣어도 좋습니다. 3. 멸치액젓대신 까나리액젓 넣으셔도 좋고요..새우젓을 다져서 넣어도 좋습니다."]'::jsonb, '김진옥요리가좋다', 2025-11-23 02:01:10.656565, 2025-11-23 02:01:10.656565, '{"tips": ["1.저의 계량은 밥숟가락 한숟가락이 1T입니다~ 2.칼칼한 맛을 즐기시는 분은 청양고추 썰어서 넣어도 좋습니다. 3. 멸치액젓대신 까나리액젓 넣으셔도 좋고요..새우젓을 다져서 넣어도 좋습니다."], "steps": ["콩나물은 누런부분과 껍질부분 제거하고 두세번 세척후 소쿠리에 받쳐줍니다. 미리 멸치다시마육수 500ml도 준비해주세요~", "냄비에 씻은 콩나물을 넣고 멸치다시마육수 500ml를 넣은후 물 700ml를 넣고요~", "센불로 켠후 끓으면 중약불로 줄여 5분동안 끓여줍니다.", "5분경과후~ 다진마늘1/2T. 다진파5T. 국간장1T. 멸치액젓1T를 넣은후~ 한번 바글 끓인후 간을 보셔서 싱거우면 소금간을 추가하세요~ 저는 소금1/3T정도 넣었습니다."], "title": "국물이 너무 개운해요~맑은콩나물국 맛있게 끓이는법(김진옥요리가좋다)", "servings": "4인분", "cook_time": "15분 이내", "copyright": "김진옥요리가좋다", "recipe_id": "6905196", "step_tips": [null, null, null, null], "difficulty": "아무나", "source_url": "https://www.10000recipe.com/recipe/6905196", "ingredients": ["콩나물 4줌", "다진파 5T", "멸치다시마육수 500ml", "다진마늘 1/2T", "국간장 1T", "멸치액젓 1T", "소금 1/3T"], "ingredients_struct": [{"qty": "4줌", "desc": null, "name": "콩나물"}, {"qty": "5T", "desc": null, "name": "다진파"}, {"qty": "500ml", "desc": null, "name": "멸치다시마육수"}, {"qty": "1/2T", "desc": null, "name": "다진마늘"}, {"qty": "1T", "desc": null, "name": "국간장"}, {"qty": "1T", "desc": null, "name": "멸치액젓"}, {"qty": "1/3T", "desc": null, "name": "소금"}]}'::jsonb);
INSERT INTO recipes (id, recipe_id, source_url, title, servings, cook_time, difficulty, tips, copyright, created_at, updated_at, raw_data) VALUES (414, '6905743', 'https://www.10000recipe.com/recipe/6905743', '절대 실패없는 제육볶음 황금레시피 감칠맛과 매운맛이 좋아요~!!', '3인분', '30분 이내', '초급', '["☆ 돼지고기 앞다리살은 적당히 기름이 있어 제육볶음을 하기에 알맞답니다~!!☆ ☆ 제육볶음에는 야채를 여러가지 넣으면 지저분해 보여서 양파 고추 파 이렇게 간단하게만 넣어주시는게 좋답니다~!!☆"]'::jsonb, '따봉이kitchen', 2025-11-23 02:02:35.849068, 2025-11-23 02:02:35.849068, '{"tips": ["☆ 돼지고기 앞다리살은 적당히 기름이 있어 제육볶음을 하기에 알맞답니다~!!☆ ☆ 제육볶음에는 야채를 여러가지 넣으면 지저분해 보여서 양파 고추 파 이렇게 간단하게만 넣어주시는게 좋답니다~!!☆"], "steps": ["재료를 준비해주세요~.", "양념재료를 모두 넣어주세요~.", "양념재료가 잘 섞이도록해주세요~.", "대파와 청양고추는 어슷썰어주고 양파는 1cm 두께로 썰어주세요~.", "돼지고기는 한입크기로 썰어주세요~.", "만들어둔 양념장을 고기에 넣어 버무려주세요~.", "양념 후 바로 볶아도 되지만 냉장고에 30분정도 두어 숙성시켜주면 양념이 베어 더욱 맛있답니다~!!", "팬에 식용유 2큰술과 대파를 넣고 강불로 3분정도 볶아 파기름을 내주세요~.", "양념한 고기를 넣어주세요~.", "중불로 볶아 고기를 완전히 익혀주세요~. 약 8분정도면 다 익는답니다~!!", "양파와 청양고추를 넣어주세요~.", "강불로 2분정도 볶아준뒤 불을 꺼주세요~.", "마지막으로 통깨를 뿌려주면 맛있는 제육볶음 완성입니다~!!"], "title": "절대 실패없는 제육볶음 황금레시피 감칠맛과 매운맛이 좋아요~!!", "servings": "3인분", "cook_time": "30분 이내", "copyright": "따봉이kitchen", "recipe_id": "6905743", "step_tips": [null, null, null, null, null, null, null, null, null, null, null, null, null], "difficulty": "초급", "source_url": "https://www.10000recipe.com/recipe/6905743", "ingredients": ["돼지고기 앞다리살 600g", "양파 1/2개", "청양고추 2~3개", "대파 1/3개", "고추장 3큰술", "고춧가루 2큰술", "다진마늘 1큰술", "설탕 또는 매실액 2큰술", "간장 1큰술", "통깨 약간", "후추 약간"], "ingredients_struct": [{"qty": "600g", "desc": null, "name": "돼지고기 앞다리살"}, {"qty": "1/2개", "desc": null, "name": "양파"}, {"qty": "2~3개", "desc": null, "name": "청양고추"}, {"qty": "1/3개", "desc": null, "name": "대파"}, {"qty": "3큰술", "desc": null, "name": "고추장"}, {"qty": "2큰술", "desc": null, "name": "고춧가루"}, {"qty": "1큰술", "desc": null, "name": "다진마늘"}, {"qty": "2큰술", "desc": null, "name": "설탕 또는 매실액"}, {"qty": "1큰술", "desc": null, "name": "간장"}, {"qty": "약간", "desc": null, "name": "통깨"}, {"qty": "약간", "desc": null, "name": "후추"}]}'::jsonb);
INSERT INTO recipes (id, recipe_id, source_url, title, servings, cook_time, difficulty, tips, copyright, created_at, updated_at, raw_data) VALUES (298, '6857593', 'https://www.10000recipe.com/recipe/6857593', '도라지무침 맛있게 무치는 법,도라지무침 레시피', '3인분', '30분 이내', '아무나', '[]'::jsonb, '꽃청춘이주부', 2025-11-22 23:56:09.816210, 2025-11-23 01:27:03.953297, '{"tips": [], "steps": ["재료:도라지 600g,굵은소금1/2스푼,쌀뜬물 양념재료:고추장3스푼,고추가루5스푼,다진마늘1스푼,설탕3스푼,올리고당3스푼,식초10스푼,통깨2스푼", "우선 제일 먼저 해주어야 할일은 도라지 특유의 아린맛을 없애주는 과정이예요. 쌀뜬물에 굵은소금1/2스푼을 넣고 도라지를 20분정도 담구어서 놔둡니다. 요렇게 하면 도라지의 아린맛을 제거해준답니다.", "20분정도 담구어 두었던 도라지는 찬물에서 벅버 빨래하듯이 헹구어 주고 가위를 이용해서 너무 긴것은 잘라서 준비합니다. 그리고 체에 걸러 물기를 제거해줍니다.", "고추장3스푼,고추가루5스푼,다진마늘1스푼,설탕3스푼,올리고당3스푼,식초10스푼", "양념들을 잘섞어줍니다.", "큰볼에 도라지를 옮겨 담은후 미리 만들어 두었던 양념장을 넣어줍니다.", "깨도 듬뿍 2스푼 정도 넣어줍니다.", "양념과 도라지가 잘섞이도록 조물조물 무쳐내주면~", "도라지무침 완성입니다!!"], "title": "도라지무침 맛있게 무치는 법,도라지무침 레시피", "servings": "3인분", "cook_time": "30분 이내", "copyright": "꽃청춘이주부", "recipe_id": "6857593", "step_tips": [null, null, null, null, null, null, null, null, null], "difficulty": "아무나", "source_url": "https://www.10000recipe.com/recipe/6857593", "ingredients": ["도라지 600g", "굵은소금 1/2스푼", "쌀뜬물", "고추장 3스푼", "고추가루 5스푼", "다진마늘 1스푼", "설탕 3스푼", "올리고당 3스푼", "식초 10스푼", "통깨 2스푼"], "ingredients_struct": [{"qty": "600g", "desc": null, "name": "도라지"}, {"qty": "1/2스푼", "desc": null, "name": "굵은소금"}, {"qty": "", "desc": null, "name": "쌀뜬물"}, {"qty": "3스푼", "desc": null, "name": "고추장"}, {"qty": "5스푼", "desc": null, "name": "고추가루"}, {"qty": "1스푼", "desc": null, "name": "다진마늘"}, {"qty": "3스푼", "desc": null, "name": "설탕"}, {"qty": "3스푼", "desc": null, "name": "올리고당"}, {"qty": "10스푼", "desc": null, "name": "식초"}, {"qty": "2스푼", "desc": null, "name": "통깨"}]}'::jsonb);
INSERT INTO recipes (id, recipe_id, source_url, title, servings, cook_time, difficulty, tips, copyright, created_at, updated_at, raw_data) VALUES (299, '6858080', 'https://www.10000recipe.com/recipe/6858080', '백종원 떡볶이 레시피 / 맛있는 떡볶이 추천!!', '2인분', '15분 이내', '아무나', '["- 백종원님은 설탕 4큰술했지만 단거 별로 안좋아하시면 2~3큰술만 넣으셔도 됩니다. - 종이컵 기준으로 생각하시면 됩니다."]'::jsonb, '퐁순이', 2025-11-22 23:57:23.119184, 2025-11-23 01:27:03.965193, '{"tips": ["- 백종원님은 설탕 4큰술했지만 단거 별로 안좋아하시면 2~3큰술만 넣으셔도 됩니다. - 종이컵 기준으로 생각하시면 됩니다."], "steps": ["떡은 따로 불려두거나 그러지 않아도 괜찮아요. 떡 400g을 냄비에 넣어주고", "물은 종이컵으로 2컵 넣어주세요.", "자작하게 잠길정도의 양이에요.", "설탕 4큰술 넣고, 백종원님은 설탕 4큰술이라했는데 단거 별로안좋아하시는분은 2-3큰술 넣으셔도 됩니다.", "간장 2큰술 넣고", "고춧가루 1큰술 넣고", "고추장 1큰술 듬뿍넣어서", "잘 풀어주시고요.", "떡볶이 국물이 걸죽해지도록 보글보글 끓여주세요.", "준비해둔 파를 1컵 넣어주세요.", "물이 많이 졸았죠?!", "물이 어느정도 자작해지면 한번 휘리릭 섞어주면 백종원 떡볶이 완성!"], "title": "백종원 떡볶이 레시피 / 맛있는 떡볶이 추천!!", "servings": "2인분", "cook_time": "15분 이내", "copyright": "퐁순이", "recipe_id": "6858080", "step_tips": [null, null, null, null, null, null, null, null, null, null, null, null], "difficulty": "아무나", "source_url": "https://www.10000recipe.com/recipe/6858080", "ingredients": ["떡 400g", "물 2컵", "대파 1컵", "설탕 4T", "간장 2T", "고추장 1T", "고춧가루 1T"], "ingredients_struct": [{"qty": "400g", "desc": null, "name": "떡"}, {"qty": "2컵", "desc": null, "name": "물"}, {"qty": "1컵", "desc": null, "name": "대파"}, {"qty": "4T", "desc": null, "name": "설탕"}, {"qty": "2T", "desc": null, "name": "간장"}, {"qty": "1T", "desc": null, "name": "고추장"}, {"qty": "1T", "desc": null, "name": "고춧가루"}]}'::jsonb);
INSERT INTO recipes (id, recipe_id, source_url, title, servings, cook_time, difficulty, tips, copyright, created_at, updated_at, raw_data) VALUES (300, '6858140', 'https://www.10000recipe.com/recipe/6858140', '배추김치 간단하고 맛있게 담그는법, 김치간단레시피', '6인분 이상', '60분 이내', '아무나', '[]'::jsonb, '초이맘', 2025-11-22 23:58:47.216323, 2025-11-23 01:27:03.974067, '{"tips": [], "steps": ["배추가 다듬을것도 없이 너무 좋아요. 그리고 요즘 배추가 여름배추보다 고소하고 맛있어요.", "포기째하기도 그렇고 자르기도 그렇고 해서 잎사기 다 뗘서 빨리 배추절여서 김치 담으려고요.", "배추잎사귀 뗘서 3~4개씩 차곡차곡 놓고 배추윗쪽 부분에만 굵은소금 뿌려주었어요.", "그리고 소금 씻기지 않게 물을 위에 부어주던지 아님 배추를 물에 한번 젹셔주고 소금 뿌려주어도돼고요.", "반복해서 배추를 반대로 해주고 맨위에는 소금을 골고루 뿌려주면돼요. 절일때 들어간 소금의양은", "그리고 비닐이나 함지로 덮어 놓으면 빨리절여지거든요. 그동안 양념들 준비해 주었어요.", "쪽파, 대파 다듬어서 준비해 놓았어요.", "생강을 다져서 넣어주었어요.", "대파, 쪽파 썰어주었어요. 생강을 다져서 넣어주었어요.", "각종 양념준비~", "고추가루와 설탕준비완료.", "무는 잘라서 준비했어요.", "절이기 시작해서 1시간정도 절인것 같아요. 아주 잘 절여진것 같아요.", "배추를 씻어서 소쿠리에 물 빠지라고 담아 놓았어요.", "준비해놓은 무를 썰어 무채까지 썰어놓았어요.", "무채 썰어 놓은것을 함지에 담아놓았어요. 무채 썰어 놓은것을 함지에 담아놓았어요.", "요 한접시는 속으로만 골라 먼저 겉절이식으로 따로 버무려서 먹으려고 접시에 담아서 먹으라고 딸램들 주고요.", "이제 무채를 버무려야지요. 위에 준비해둔 양념을 몽땅 넣어주고 버무려주었어요.", "무채를 버무려 놓았어요. 무채완성~", "물기뺀 배추를 무채에 넣어 버무려주었어요. 배추김치 완성되었어요.", "그리고 배추 김치 버무려 놓은것을 차곡차곡", "김치볼에 담아보았어요."], "title": "배추김치 간단하고 맛있게 담그는법, 김치간단레시피", "servings": "6인분 이상", "cook_time": "60분 이내", "copyright": "초이맘", "recipe_id": "6858140", "step_tips": [null, null, null, null, null, null, null, null, null, null, "계량스푼", null, null, null, null, null, null, null, null, null, null, null], "difficulty": "아무나", "source_url": "https://www.10000recipe.com/recipe/6858140", "ingredients": ["배추 절임 2.4kg", "쪽파 200g", "대파 3대", "굵은소금 절임 200g", "무 700g 1/2개", "멸치액젓 5스푼", "새우젓 2스푼", "고추가루 15스푼", "설탕 2스푼", "다진마늘 3스푼", "매실액 4스푼"], "ingredients_struct": [{"qty": "2.4kg", "desc": null, "name": "배추 절임"}, {"qty": "200g", "desc": null, "name": "쪽파"}, {"qty": "3대", "desc": null, "name": "대파"}, {"qty": "200g", "desc": null, "name": "굵은소금 절임"}, {"qty": "1/2개", "desc": null, "name": "무 700g"}, {"qty": "5스푼", "desc": null, "name": "멸치액젓"}, {"qty": "2스푼", "desc": null, "name": "새우젓"}, {"qty": "15스푼", "desc": null, "name": "고추가루"}, {"qty": "2스푼", "desc": null, "name": "설탕"}, {"qty": "3스푼", "desc": null, "name": "다진마늘"}, {"qty": "4스푼", "desc": null, "name": "매실액"}]}'::jsonb);
INSERT INTO recipes (id, recipe_id, source_url, title, servings, cook_time, difficulty, tips, copyright, created_at, updated_at, raw_data) VALUES (301, '6858833', 'https://www.10000recipe.com/recipe/6858833', '뜨끈한 국물이 일품인 시금치된장국/시금치두부된장국 만들기♥', '4인분', '30분 이내', '아무나', '["두부를 넣어서 만들어도 너무 좋아요! 더욱 건강해지는 느낌이랍니다."]'::jsonb, '꽃라라', 2025-11-23 00:00:51.810135, 2025-11-23 01:27:03.985967, '{"tips": ["두부를 넣어서 만들어도 너무 좋아요! 더욱 건강해지는 느낌이랍니다."], "steps": ["물 4컵에 다시멸치와 다시마를 넣고 팔팔 끓여주세요. 물이 끓기 시작하면 다시마를 건지고 5분정도 더 끓인다음 멸치도 건저주세요.", "시금치는 물에 흔들어 깨끗히 씻어 속에 있는 흙을 제거해주세요.", "깨끗히 씻은 시금치의 시든 잎은 떼고, 뿌리부분은 자르며 다듬어 주세요.", "대파는 송송 또는 어슷 썰어준비합니다.", "두부는 작게(엄지손가락 한 마디만큼의 크기로) 잘라주세요.", "팔팔 끓고 있는 멸치다시마 국물에 시금지를 넣고", "된장 2큰술을 풀은 다음 센불에서 팔팔 끓여주세요.", "국물이 팔팔 끓기 시작 하면 두부를 넣구 중간불로 줄여 10분간 끓여주세요.", "그런다음 어슷썰기한 파와", "다진마늘 0.5큰술을 넣고 1~2분간 더 끓인 후 마무리 합니다.", "완성!"], "title": "뜨끈한 국물이 일품인 시금치된장국/시금치두부된장국 만들기♥", "servings": "4인분", "cook_time": "30분 이내", "copyright": "꽃라라", "recipe_id": "6858833", "step_tips": [null, null, null, null, null, null, null, null, null, null, null], "difficulty": "아무나", "source_url": "https://www.10000recipe.com/recipe/6858833", "ingredients": ["된장 2큰술", "다진마늘 0.5큰술", "시금치 2~3줌", "대파 1대", "다시마 5*5 1개", "다시멸치 13~15마리", "두부 1/2모"], "ingredients_struct": [{"qty": "2큰술", "desc": null, "name": "된장"}, {"qty": "0.5큰술", "desc": null, "name": "다진마늘"}, {"qty": "2~3줌", "desc": null, "name": "시금치"}, {"qty": "1대", "desc": null, "name": "대파"}, {"qty": "1개", "desc": null, "name": "다시마 5*5"}, {"qty": "13~15마리", "desc": null, "name": "다시멸치"}, {"qty": "1/2모", "desc": null, "name": "두부"}]}'::jsonb);
INSERT INTO recipes (id, recipe_id, source_url, title, servings, cook_time, difficulty, tips, copyright, created_at, updated_at, raw_data) VALUES (415, '6906655', 'https://www.10000recipe.com/recipe/6906655', '양념장이 참 맛있는 두부조림', '2인분', '30분 이내', '아무나', '["두부를 너무 바싹 구워주면 포슬포슬한 맛이 없어요~ 양념장에 두부를 으깨서 밥에 비벼먹을꺼니, 두부의 양면을 바싹 익히지 마세요~!"]'::jsonb, '치타숑', 2025-11-23 02:05:20.207744, 2025-11-23 02:05:20.207744, '{"tips": ["두부를 너무 바싹 구워주면 포슬포슬한 맛이 없어요~ 양념장에 두부를 으깨서 밥에 비벼먹을꺼니, 두부의 양면을 바싹 익히지 마세요~!"], "steps": ["두부는 체에 받쳐 물기를 빼주세요", "양파는 얇게 썰어주시고 파는 송송 썰어둡니다", "양념장도 만들어주세요", "두부도 먹기 좋게 썰어주세요", "식용류 1/2 큰 술, 들기름 1 큰 술를 두룬 팬에 두부를 구워주세요 양면을 다 구워주시면 됩니다 1분정도씩 부들부들하게 구워요", "두부가 구워졌다면 야채와 양념장을 올리고 5분더 끓여주세요", "이제 뚜껑을 덮고 1분 더 끓여줍니다", "너무 간단하게 완성이죠~^^"], "title": "양념장이 참 맛있는 두부조림", "servings": "2인분", "cook_time": "30분 이내", "copyright": "치타숑", "recipe_id": "6906655", "step_tips": [null, null, null, null, null, null, null, null], "difficulty": "아무나", "source_url": "https://www.10000recipe.com/recipe/6906655", "ingredients": ["두부 1모", "양파 1/2개", "파 1/2대", "식용유 1/2큰술", "들기름 1큰술", "물 100ml", "간장 4큰술", "고춧가루 2큰술", "굴소스 1/2큰술", "다진 마늘 1큰술", "설탕 1큰술", "깨 1큰술", "참기름 1큰술"], "ingredients_struct": [{"qty": "1모", "desc": null, "name": "두부"}, {"qty": "1/2개", "desc": null, "name": "양파"}, {"qty": "1/2대", "desc": null, "name": "파"}, {"qty": "1/2큰술", "desc": null, "name": "식용유"}, {"qty": "1큰술", "desc": null, "name": "들기름"}, {"qty": "100ml", "desc": null, "name": "물"}, {"qty": "4큰술", "desc": null, "name": "간장"}, {"qty": "2큰술", "desc": null, "name": "고춧가루"}, {"qty": "1/2큰술", "desc": null, "name": "굴소스"}, {"qty": "1큰술", "desc": null, "name": "다진 마늘"}, {"qty": "1큰술", "desc": null, "name": "설탕"}, {"qty": "1큰술", "desc": null, "name": "깨"}, {"qty": "1큰술", "desc": null, "name": "참기름"}]}'::jsonb);
INSERT INTO recipes (id, recipe_id, source_url, title, servings, cook_time, difficulty, tips, copyright, created_at, updated_at, raw_data) VALUES (416, '6906766', 'https://www.10000recipe.com/recipe/6906766', '계란장조림 황금레시피 짜지않고 맛있게', '4인분', '30분 이내', '초급', '["tip. 계란을 삶을때 식초와 소금을 넣어주면 삶은후 껍질이 잘 까져요"]'::jsonb, '혀니ㅋ', 2025-11-23 02:07:19.617467, 2025-11-23 02:07:19.617467, '{"tips": ["tip. 계란을 삶을때 식초와 소금을 넣어주면 삶은후 껍질이 잘 까져요"], "steps": ["냄비에 계란이 잠길정도로 물을 붓고 소금 1스푼, 식초 스푼을 넣어 계란을 삶아줍니다 계란상태는 완숙, 반숙 선택사항인데요 반숙은 물이 끓기 시작하고 7분정도 완숙은 10~15분정도 삶아주시면 될것 같아요", "다 삶아지면 빠르게 찬물로 이동해 담궈주고 껍질을 까서 준비해줍니다", "진간장 4스푼 / 국간장 2스푼 설탕 2스푼 / 올리고당 스푼 / 물 1컵반 + 통마늘도 함께 냄비에 분량의 양념과 통마늘을 넣고 바글바글 끓여줍니다", "간장양념이 끓으면 삶은 계란을 넣어주고", "계란의 겉면이 색이 입혀질때쯤 청양고추도 듬성듬성 썰어 넣어 중불에서 뭉근하게 끓여줍니다", "국물이 거의 줄어들고 달걀에 양념이 잘 베어 거뭇해지면 계란외에 건더기는 건져주시면 끝!! 간을 보시고 좀더 짭쪼름한게 좋다 하시면 좀더 조려주시면 되겠죠?"], "title": "계란장조림 황금레시피 짜지않고 맛있게", "servings": "4인분", "cook_time": "30분 이내", "copyright": "혀니ㅋ", "recipe_id": "6906766", "step_tips": [null, null, null, null, null, null], "difficulty": "초급", "source_url": "https://www.10000recipe.com/recipe/6906766", "ingredients": ["계란 5-6개", "소금 1스푼", "식초 1스푼", "청양고추 1-2개", "통마늘 1줌", "진간장 4스푼", "국간장 2스푼", "설탕 2스푼", "올리고당 0.5~1스푼", "물 1.5컵"], "ingredients_struct": [{"qty": "5-6개", "desc": null, "name": "계란"}, {"qty": "1스푼", "desc": null, "name": "소금"}, {"qty": "1스푼", "desc": null, "name": "식초"}, {"qty": "1-2개", "desc": null, "name": "청양고추"}, {"qty": "1줌", "desc": null, "name": "통마늘"}, {"qty": "4스푼", "desc": null, "name": "진간장"}, {"qty": "2스푼", "desc": null, "name": "국간장"}, {"qty": "2스푼", "desc": null, "name": "설탕"}, {"qty": "0.5~1스푼", "desc": null, "name": "올리고당"}, {"qty": "1.5컵", "desc": null, "name": "물"}]}'::jsonb);
INSERT INTO recipes (id, recipe_id, source_url, title, servings, cook_time, difficulty, tips, copyright, created_at, updated_at, raw_data) VALUES (304, '6862107', 'https://www.10000recipe.com/recipe/6862107', '백종원 갈치조림 황금레시피 비린내 잡는 비결', '4인분', '60분 이내', '아무나', '["쌀뜬물과 된장 생강 후춧가루로 비린내를 최대한 잡아줫어요"]'::jsonb, '서자매맘', 2025-11-23 00:06:49.714001, 2025-11-23 01:27:04.014253, '{"tips": ["쌀뜬물과 된장 생강 후춧가루로 비린내를 최대한 잡아줫어요"], "steps": ["갈치 6토막을 쌀뜬물에 담궈 비린내를 잡아준다 (30분정도)", "그동안 무를 썰어준준다", "냄비에 무가 잠길정도로 물을 넣고 무를 익혀준다 (푹익혀야 되는 무를 생선을 같이 넣고 익힐경우 갈치가 부스러질수 잇기 때문에 먼저 익혀줫어요)", "양념장은 고춧가루 3큰술, 고추장 1큰술, 간장 1큰술, 맛술 1큰술, 다진마늘 1큰술, 설탕 1큰술, 된장 반큰술, 다진생강 조금, 후추를 조금 넣어 만들어 준다", "무가 어느정도 익으면 갈치를 차곡차곡 넣고 양파반개와 양념장 반정도를 넣고 익혀준다 (익으면서 양.념장이 내려가기 때문에 나눠서 넣어주면 골고루 양념이 베어요)", "영념이 퍼지면 나머지 양념장도 넣어준다", "마지막으로 파와 청양고추를 넣어주면 칼칼하고 맛잇는 백종원 갈치조림 완성!! (파흰부분을 다 먹어서 잎부분만 넣엇더니 색감이 안사네요..ㅎ)"], "title": "백종원 갈치조림 황금레시피 비린내 잡는 비결", "servings": "4인분", "cook_time": "60분 이내", "copyright": "서자매맘", "recipe_id": "6862107", "step_tips": [null, null, null, null, null, null, null], "difficulty": "아무나", "source_url": "https://www.10000recipe.com/recipe/6862107", "ingredients": ["갈치 6토막", "무 적당량", "양파 1/2개", "청양고추 1.5개", "대파 조금", "고춧가루 3큰술", "고추장 1큰술", "간장 1큰술", "맛술 1큰술", "다진마늘 1큰술", "설탕 1큰술", "된장 1/2큰술", "다진생강 조금", "후추 톡톡"], "ingredients_struct": [{"qty": "6토막", "desc": null, "name": "갈치"}, {"qty": "적당량", "desc": null, "name": "무"}, {"qty": "1/2개", "desc": null, "name": "양파"}, {"qty": "1.5개", "desc": null, "name": "청양고추"}, {"qty": "조금", "desc": null, "name": "대파"}, {"qty": "3큰술", "desc": null, "name": "고춧가루"}, {"qty": "1큰술", "desc": null, "name": "고추장"}, {"qty": "1큰술", "desc": null, "name": "간장"}, {"qty": "1큰술", "desc": null, "name": "맛술"}, {"qty": "1큰술", "desc": null, "name": "다진마늘"}, {"qty": "1큰술", "desc": null, "name": "설탕"}, {"qty": "1/2큰술", "desc": null, "name": "된장"}, {"qty": "조금", "desc": null, "name": "다진생강"}, {"qty": "톡톡", "desc": null, "name": "후추"}]}'::jsonb);
INSERT INTO recipes (id, recipe_id, source_url, title, servings, cook_time, difficulty, tips, copyright, created_at, updated_at, raw_data) VALUES (306, '6865491', 'https://www.10000recipe.com/recipe/6865491', '육회 만드는 법, 육회 양념 황금 레시피로 맛있게 만들기', '2인분', '10분 이내', '아무나', '["다진마늘을 많이 넣을수록 맛있어요. 소고기는 체온이 닿으면 검게 변하기 때문에 빠르게 무쳐내주세요."]'::jsonb, '먹순', 2025-11-23 00:10:31.333781, 2025-11-23 01:27:04.033338, '{"tips": ["다진마늘을 많이 넣을수록 맛있어요. 소고기는 체온이 닿으면 검게 변하기 때문에 빠르게 무쳐내주세요."], "steps": ["빛깔좋은 육회용 고기를 정육점에서 구매해주세요. 육회용 고기는 우둔(엉덩이살), 홍두깨살, 앞다리살이 지방이 적어서 육회용으로 적합해요.", "육회용 고기의 핏기를 제거하는 방법은 키친타월을 바닥에 1장 깔고 고기를 올려 얇게 편 후 키친타월을 1장 더 깔아주세요.", "쪽파는 송송 썰어주고, 마늘은 편썰어주세요.", "배는 껍질을 까준 후 1/3개의 밑면 기둥을 잘라 세운 후 얇게 썰어 채썰어주세요", "핏물이 제거된 고기를 꺼내고 볼에 고기와 송송 다진 쪽파를 넣어주세요.", "양념을 해주세요. 소금 1/2T, 설탕 1/2T, 국간장 1/2T, 참기름 1T, 매실액 1/2T, 다진마늘 1T, 통깨 1/2T", "위생장갑을 끼고 후다닥 잘 무쳐주세요,", "그릇에 배를 깔고 준비한 육회, 편마늘, 노른자를 올려주세요.", "육회 완성입니다. 10분만에 휘리릭 만들어 낼 수 있는 고급 요리랍니다."], "title": "육회 만드는 법, 육회 양념 황금 레시피로 맛있게 만들기", "servings": "2인분", "cook_time": "10분 이내", "copyright": "먹순", "recipe_id": "6865491", "step_tips": [null, null, null, null, null, null, null, null, null], "difficulty": "아무나", "source_url": "https://www.10000recipe.com/recipe/6865491", "ingredients": ["소고기 앞다리/우둔/엉덩이 1/2근", "배 1/3개", "쪽파 2대", "계란 노른자 1알", "소금 1/2T", "설탕 1/2T", "국간장 1/2T", "참기름 1T", "매실액 1/2T", "다진마늘 1T", "통깨 1/2T"], "ingredients_struct": [{"qty": "1/2근", "desc": null, "name": "소고기 앞다리/우둔/엉덩이"}, {"qty": "1/3개", "desc": null, "name": "배"}, {"qty": "2대", "desc": null, "name": "쪽파"}, {"qty": "1알", "desc": null, "name": "계란 노른자"}, {"qty": "1/2T", "desc": null, "name": "소금"}, {"qty": "1/2T", "desc": null, "name": "설탕"}, {"qty": "1/2T", "desc": null, "name": "국간장"}, {"qty": "1T", "desc": null, "name": "참기름"}, {"qty": "1/2T", "desc": null, "name": "매실액"}, {"qty": "1T", "desc": null, "name": "다진마늘"}, {"qty": "1/2T", "desc": null, "name": "통깨"}]}'::jsonb);
INSERT INTO recipes (id, recipe_id, source_url, title, servings, cook_time, difficulty, tips, copyright, created_at, updated_at, raw_data) VALUES (307, '6867091', 'https://www.10000recipe.com/recipe/6867091', '매콤한 쭈꾸미볶음 황금레시피, 주꾸미 손질법과 만드는 법을 한 번에 ~', '2인분', '30분 이내', '초급', '[]'::jsonb, '뽕림이', 2025-11-23 00:12:33.498284, 2025-11-23 01:27:04.043733, '{"tips": [], "steps": ["먼저 주꾸미부터 손질해보도록 해요! ^^", "우선 주꾸미 머리를 과감하게 뒤집어 오른쪽 사진에서 보이는 내장을 제거해줍니다. (머리를 뒤집었을 때, 하얗고 동그란 내용물이 보인다면 그건 주꾸미의 알이니 요리에 넣어드시면 돼요. 알은 흐르는 물에 살짝 헹궈내기만 하면 돼요.)", "내장 제거가 완료됐다면 주꾸미의 이빨도 제거해주세요. 사진처럼 머리통 쪽을 쭉 밀어주면 이빨이 슉 ~ 나와요.", "내장과 입을 다 제거했다면, 밀가루를 적당량 넣고 손빨래하듯이 바락바락 주물러줍니다. 불순물이 다 빠져나온 것 같다 싶으시면 이제 흐르는 물에 주꾸미를 깨끗이 헹궈준 뒤 체에 밭쳐 물기를 빼주세요.", "참! 야채도 손질해줘야겠죠? 양파는 가늘게 채 썰어서 준비해주시고요, 청양고추와 대파는 송송 썰어 준비합니다.", "양념장은 간장 1 큰 술 반, 미림 1 큰 술, 물엿 1 큰 술 반, 매실액 1 큰 술", "다진 마늘 반 큰 술, 고춧가루 2 큰 술, 청양 고춧가루 1 큰 술, 고추장 1 큰 술을 넣어주신 뒤", "후추를 톡톡톡 넣어 잘 섞어주면 주꾸미 볶음 양념장이 완성돼요.", "물기를 빼둔 주꾸미는 끓는 물에 살짝 데쳐준 뒤 체에 밭쳐 물기를 빼주세요.", "팬에 기름을 조금 둘러준 뒤 야채부터 볶아줍니다. 양파와 대파를 넣고 달달 ~", "양파가 투명해졌다 싶으면 데쳐둔 주꾸미와 양념장을 넣고 센 불에 휘리릭 볶아줍니다. 너무 오래 볶으면 질겨지니 적당히 볶아주세요 ^^", "마지막으로 송송 썰어둔 청양고추도 샤샥 넣어준 뒤 토치로 가볍게 지져 불 맛을 좀 내줬어요 ㅋㅋㅋㅋㅋ", "음 ~ 맛있어요! ^^"], "title": "매콤한 쭈꾸미볶음 황금레시피, 주꾸미 손질법과 만드는 법을 한 번에 ~", "servings": "2인분", "cook_time": "30분 이내", "copyright": "뽕림이", "recipe_id": "6867091", "step_tips": [null, null, null, null, null, null, null, null, null, null, null, null, null], "difficulty": "초급", "source_url": "https://www.10000recipe.com/recipe/6867091", "ingredients": ["쭈꾸미 8-9마리", "대파 1/2개", "양파 1/2개", "청양고추 1개", "간장 1.5큰술", "미림 1큰술", "고추장 1큰술", "물엿 1.5큰술", "매실액 1큰술", "다진 마늘 1큰술", "고춧가루 3큰술"], "ingredients_struct": [{"qty": "8-9마리", "desc": null, "name": "쭈꾸미"}, {"qty": "1/2개", "desc": null, "name": "대파"}, {"qty": "1/2개", "desc": null, "name": "양파"}, {"qty": "1개", "desc": null, "name": "청양고추"}, {"qty": "1.5큰술", "desc": null, "name": "간장"}, {"qty": "1큰술", "desc": null, "name": "미림"}, {"qty": "1큰술", "desc": null, "name": "고추장"}, {"qty": "1.5큰술", "desc": null, "name": "물엿"}, {"qty": "1큰술", "desc": null, "name": "매실액"}, {"qty": "1큰술", "desc": null, "name": "다진 마늘"}, {"qty": "3큰술", "desc": null, "name": "고춧가루"}]}'::jsonb);
INSERT INTO recipes (id, recipe_id, source_url, title, servings, cook_time, difficulty, tips, copyright, created_at, updated_at, raw_data) VALUES (417, '6911743', 'https://www.10000recipe.com/recipe/6911743', '수미네반찬 김치전 만들기 바삭하게', '1인분', '10분 이내', '초급', '["방송에서는 밀가루와 부침가루 비율을 8:2로 섞었는데 저는 부침가루만 넣었어요"]'::jsonb, '혀니ㅋ', 2025-11-23 02:09:11.111926, 2025-11-23 02:09:11.111926, '{"tips": ["방송에서는 밀가루와 부침가루 비율을 8:2로 섞었는데 저는 부침가루만 넣었어요"], "steps": ["먼저 김치는 볼에 넣어 가위를 이용해 쫑쫑 잘게 썰어서 준비합니다 방송에서는 줄기부분이 아삭해서 줄기부분 위주로 쓴다고 하는데 저는 그냥 섞어서 사용했어요", "그리고 부침가루 1컵 가득 넣고 김치국물 1/3컵 정도 넣어주고 다진마늘 반스푼도 넣어줍니다 수미네반찬 포인트는 바로 다진마늘! 다진마늘 넣으니까 뭔가 감칠맛이 더 나는것 같았어요", "물도 2/3컵 넣어주는데요 물은 넣어가며 반죽의 농도를 맞춰주면 되요 반죽이 너무 되다면 물을 살짝 추가해줍니다 물 넣고 쉐킷쉐킷 잘 섞어주세요", "기름두른 팬에 반죽을 올려 동그랗게 모양을 잡아줘 앞뒤로 노릇하게 구워줍니다", "접시에 예쁘게 담아주니 먹음직스러운 김치전 만들기 완성♥"], "title": "수미네반찬 김치전 만들기 바삭하게", "servings": "1인분", "cook_time": "10분 이내", "copyright": "혀니ㅋ", "recipe_id": "6911743", "step_tips": [null, null, null, null, null], "difficulty": "초급", "source_url": "https://www.10000recipe.com/recipe/6911743", "ingredients": ["김치 2컵", "부침가루 1컵", "김치국물 1/3컵", "물 2/3컵", "다진마늘 1/2스푼"], "ingredients_struct": [{"qty": "2컵", "desc": null, "name": "김치"}, {"qty": "1컵", "desc": null, "name": "부침가루"}, {"qty": "1/3컵", "desc": null, "name": "김치국물"}, {"qty": "2/3컵", "desc": null, "name": "물"}, {"qty": "1/2스푼", "desc": null, "name": "다진마늘"}]}'::jsonb);
INSERT INTO recipes (id, recipe_id, source_url, title, servings, cook_time, difficulty, tips, copyright, created_at, updated_at, raw_data) VALUES (418, '6912220', 'https://www.10000recipe.com/recipe/6912220', '순두부찌개. 바지락, 고기 없이도 기가 막힌 순두부찌개 만드는 법 / 만들기 / 순두부찌개 황금 레시피', '1인분', '30분 이내', '아무나', '["처음부터 물양을 많이 잡지 마시고, 육수를 어느 정도 넣은 후 맛을 보고 더해주시길 추천합니다. 건강을 생각하신다면 할말없지만 소금과 고추가루는 적당량 이상이 들어가야 맛이 납니다. 바지락, 돼지고기없이 소금과 고추가루마저 적게 들어가면 맛이 터져야하는 포인트가 없어져요."]'::jsonb, '케이쿡', 2025-11-23 02:10:15.664504, 2025-11-23 02:10:15.664504, '{"tips": ["처음부터 물양을 많이 잡지 마시고, 육수를 어느 정도 넣은 후 맛을 보고 더해주시길 추천합니다. 건강을 생각하신다면 할말없지만 소금과 고추가루는 적당량 이상이 들어가야 맛이 납니다. 바지락, 돼지고기없이 소금과 고추가루마저 적게 들어가면 맛이 터져야하는 포인트가 없어져요."], "steps": ["제일 먼저 멸치 육수를 끓여주세요. 멸치외에 있으면 표고버섯 약간, 다시마 약간 넣고 끓이면 되는데 없으면 멸치만 넣고 그냥 끓여도 됩니다. 그 다음은 채소를 손질해야겠죠. 대파 1/4과 양파 1/4을 잘게 썰어주시고요.", "매콤한걸 좋아하시는분은 청양고추 하나 어슷하게 썰어주시고", "호박 1/4은 반달 모양으로 썰어주세요.", "재료손질은 벌써 끝났네요. 다음은 준비한 뚝배기나 냄비에 참기름 1큰술, 식용유 2큰술을 넣어주세요.", "그리고 준비한 양파, 대파를 넣고 볶아주세요.", "그리고 고추가루 1큰술 반을 넣고 고추기름을 만들어줍니다. 매운걸 못드시는 분은 한큰술만 넣으세요.", "고추기름을 만들었으면 소금 반큰술, 설탕 한꼬집을 넣어주세요. 설탕은 안넣으셔도 되긴 한데 보통 식당에서는 넣죠.", "그 다음엔 굴소스 1큰술, 간장 1큰술을 넣고 저어서 섞어주세요.", "그 다음은 멸치육수를 부어주세요. 준비된 냄비에 반 정도를 채워주세요. 너무 많이 부으면 순두부 넣을때 넘칩니다.", "자 이제 팔팔 끓여줍니다. 끓기 시작하면 호박과 고추를 넣고, 다진마늘도 한큰술 넣어주세요~", "그 다음은 순두부를 넣어줍니다.", "마지막으로 달걀과 파를 넣어 마무리 해줍니다.", "제눈에는 엄청 맛있어 보이는데 어떠세요? 사실 순두부찌개의 맛을 좌우하는 바지락이나 돼지고기 없이 맛을 내려면 쉽지 않은데요. 제가 생각하는 포인트는 바지락이나 돼지고기가 없으면 굴소스 정도는 꼭 들어가야 하고, 멸치육수도 필요합니다. 그리고 간이 적당히 맞아야 합니다."], "title": "순두부찌개. 바지락, 고기 없이도 기가 막힌 순두부찌개 만드는 법 / 만들기 / 순두부찌개 황금 레시피", "servings": "1인분", "cook_time": "30분 이내", "copyright": "케이쿡", "recipe_id": "6912220", "step_tips": [null, null, null, null, null, null, null, null, null, null, null, null, null], "difficulty": "아무나", "source_url": "https://www.10000recipe.com/recipe/6912220", "ingredients": ["순두부", "대파 1/4개", "양파 1/4개", "애호박 1/4개", "청양고추 1개", "달걀 1개", "참기름 1큰술", "식용유 2큰술", "고추가루 1.5큰술", "소금 1/2큰술", "설탕 1꼬집", "굴소스 1큰술", "간장 1큰술", "다진 마늘 1큰술", "멸치육수"], "ingredients_struct": [{"qty": "", "desc": null, "name": "순두부"}, {"qty": "1/4개", "desc": null, "name": "대파"}, {"qty": "1/4개", "desc": null, "name": "양파"}, {"qty": "1/4개", "desc": null, "name": "애호박"}, {"qty": "1개", "desc": null, "name": "청양고추"}, {"qty": "1개", "desc": null, "name": "달걀"}, {"qty": "1큰술", "desc": null, "name": "참기름"}, {"qty": "2큰술", "desc": null, "name": "식용유"}, {"qty": "1.5큰술", "desc": null, "name": "고추가루"}, {"qty": "1/2큰술", "desc": null, "name": "소금"}, {"qty": "1꼬집", "desc": null, "name": "설탕"}, {"qty": "1큰술", "desc": null, "name": "굴소스"}, {"qty": "1큰술", "desc": null, "name": "간장"}, {"qty": "1큰술", "desc": null, "name": "다진 마늘"}, {"qty": "", "desc": null, "name": "멸치육수"}]}'::jsonb);
INSERT INTO recipes (id, recipe_id, source_url, title, servings, cook_time, difficulty, tips, copyright, created_at, updated_at, raw_data) VALUES (419, '6913492', 'https://www.10000recipe.com/recipe/6913492', '국물이 일품인 잔치국수 만들기. 멸치국수 레시피/양념장, 육수만드는법', '4인분', '30분 이내', '아무나', '["처음에 멸치를 볶아서 해주셔도 되는데 그냥 해도 맛의 차이가 크지 않습니다. 그리고 호박도 볶은 다음 나중에 고명으로 올려도 되는데 볶으면 느끼하면서 우리가 좋아하는 맛이 우러나오긴 합니다. 대신 호박을 볶지 않고 본 레시피대로 하면 육수가 깔끔하고 시원한 맛을 내주는 장점이 있습니다."]'::jsonb, 'k케이푸드', 2025-11-23 02:12:46.385759, 2025-11-23 02:12:46.385759, '{"tips": ["처음에 멸치를 볶아서 해주셔도 되는데 그냥 해도 맛의 차이가 크지 않습니다. 그리고 호박도 볶은 다음 나중에 고명으로 올려도 되는데 볶으면 느끼하면서 우리가 좋아하는 맛이 우러나오긴 합니다. 대신 호박을 볶지 않고 본 레시피대로 하면 육수가 깔끔하고 시원한 맛을 내주는 장점이 있습니다."], "steps": ["가장 먼저 물 2L에 멸치 20~30여 마리, 대파 1/4, 통마늘 2~3개 를 넣고 육수를 우려줍니다.", "육수가 끓는 동안 당근, 양파, 애호박, 표고, 대파를 손질해줍니다.", "채썰듯이 준비해주세요.", "육수는 10분 정도 끓여주시고, 망에 걸러 내용물을 전부 빼주세요. 육수는 너무 오래끓이면 도리어 맛이 텁텁해집니다.", "육수에 손질한 채소를 넣어주시고 다시 끓여주세요.", "멸치의 깊은 맛에 채소의 시원함이 가미가 됩니다. 끓이면서 거품 제거도 해주시구요.", "국간장 1큰술, 진간장 1큰술, 소금은 맛을 봐가며 간을 해줍니다. 다진마늘 1큰술도 넣어주시구요. 너무 싱거우면 국수를 말았을때 싱거워집니다. 적당히 간간하게 해주세요.", "마지막으로 달걀을 풀어 끓는 육수에 부어주시고 불을 꺼주세요.", "양념장은 진간장 5큰술, 참깨 1큰술, 청양고추 2개, 설탕 1작은술, 고춧가루 1작은술, 그리고 물 2큰술을 넣어 잘 섞어주면 완성입니다. 참기름을 넣는분도 계신데 전 참기름이 들어가면 좀 느끼하더라구요. 취향대로 하시면 되요", "소면 1인분은 보통 남자분은 500원짜리 동전크기 정도를 잡으면 맞습니다. 전 배고프니까 600원짜리입니다. ㅋㅋ 여성분은 400원(?)짜리", "끓는 물에 소면을 넣고 넘쳐흐르기 전에 물을 반컵 넣고 가라앉히고, 다시 끓어오르면 물을 반컵 넣으세요. 이런식으로 3번째 물을 넣을때 불을 꺼주시고", "체에 받쳐 차가운물에 빨듯이 박박 씻어주세요.", "육수와 양념장을 부어주면 완성!!", "고명으로 김치, 김 등을 추가하셔도 됩니다. 자 맛있게 드세요. 후루룩 정말 잘 넘어가죠?"], "title": "국물이 일품인 잔치국수 만들기. 멸치국수 레시피/양념장, 육수만드는법", "servings": "4인분", "cook_time": "30분 이내", "copyright": "k케이푸드", "recipe_id": "6913492", "step_tips": [null, null, null, null, null, null, null, null, null, null, null, null, null, null], "difficulty": "아무나", "source_url": "https://www.10000recipe.com/recipe/6913492", "ingredients": ["국물용 멸치 20~30마리", "대파 1/2", "양파 1/2", "호박 1/3", "당근 1/3", "다진마늘 1.5큰술", "소면 양껏", "표고버섯 1개", "달걀 2개", "청양고추 2개"], "ingredients_struct": [{"qty": "20~30마리", "desc": null, "name": "국물용 멸치"}, {"qty": "1/2", "desc": null, "name": "대파"}, {"qty": "1/2", "desc": null, "name": "양파"}, {"qty": "1/3", "desc": null, "name": "호박"}, {"qty": "1/3", "desc": null, "name": "당근"}, {"qty": "1.5큰술", "desc": null, "name": "다진마늘"}, {"qty": "양껏", "desc": null, "name": "소면"}, {"qty": "1개", "desc": null, "name": "표고버섯"}, {"qty": "2개", "desc": null, "name": "달걀"}, {"qty": "2개", "desc": null, "name": "청양고추"}]}'::jsonb);
INSERT INTO recipes (id, recipe_id, source_url, title, servings, cook_time, difficulty, tips, copyright, created_at, updated_at, raw_data) VALUES (420, '6915139', 'https://www.10000recipe.com/recipe/6915139', '수육 맛있게 삶는법 백종원 레시피로 부드럽게', '4인분', '60분 이내', '초급', '["고기는 물이 끓은 후 넣어주어야 육즙이 도망가지 않고 삶는 시간 강불 2-0분 중불 20분 약불 25분을 생각해두면 누구나 쉽게 만들 수 있답니다."]'::jsonb, '먹순', 2025-11-23 02:16:23.606828, 2025-11-23 02:16:23.606828, '{"tips": ["고기는 물이 끓은 후 넣어주어야 육즙이 도망가지 않고 삶는 시간 강불 2-0분 중불 20분 약불 25분을 생각해두면 누구나 쉽게 만들 수 있답니다."], "steps": ["돼지고기는 물에 담가 약 30분간 핏물을 빼주세요.", "육수용으로 준비한 양파,월계수잎,대파,된장,통마늘,통후추,미림을 모두 넣고 물을 팔팔 끓여주세요.", "돼지고기는 수육용 앞다리살을 준비해도 좋고 삼겹살을 준비해도 좋아요. 앞다리살은 삼겹살보다 기름기가 적어요. 저는 앞다리를 준비했어요. 빨리 익히기 위해 절반을 잘라주고 시작했는데요 속까지 골고루 잘 익기 위해 한 토막당 칼집을 2-3번 내주세요.", "물이 팔팔 끓어오르면 고기를 투하해주세요. 여기서 고기는 껍데기쪽부터 넣어주는게 좋아요. 돼지고기가 물에 잠길정도로 물이 넉넉해야해요.", "백종원수육 맛있게 삶는법 포인트는 바로 삶는시간인데요 먼저 물이 고기를 넣고 물이 다시 팔팔 끓어오르면 강불에 20분 중불에 20분 약불에 25분으로 1시간정도 끓여주면 끝이에요. 번거로우면 처음부터 중불에 40분정도 끓여줘도 좋아요. 잡내가 날아가라고 저는 뚜껑을 열고 삶아주었어요.", "시간이 지나니 물이 졸아들면서 된장으로 인해 색깔도 예쁘게 물들었죠? 익었는지 안익었는지 확인하는 법은 젓가락으로 고기를 깊숙히 찔러보았을 때 핏물이 나오지 않으면 다 익었다는 증거에요. 보통 1시간이면 속까지 완벽하게 익더라구요", "맛있게 익은 수육은 두툼하게 썰어주세요."], "title": "수육 맛있게 삶는법 백종원 레시피로 부드럽게", "servings": "4인분", "cook_time": "60분 이내", "copyright": "먹순", "recipe_id": "6915139", "step_tips": [null, null, null, null, null, null, null], "difficulty": "초급", "source_url": "https://www.10000recipe.com/recipe/6915139", "ingredients": ["돼지고기 앞다리살또는삼겹살 300g", "통마늘 8알", "양파 1/2개", "미림 3T", "된장 2T", "월계수잎 3장", "통후추 8알", "대파 1/2대"], "ingredients_struct": [{"qty": "300g", "desc": null, "name": "돼지고기 앞다리살또는삼겹살"}, {"qty": "8알", "desc": null, "name": "통마늘"}, {"qty": "1/2개", "desc": null, "name": "양파"}, {"qty": "3T", "desc": null, "name": "미림"}, {"qty": "2T", "desc": null, "name": "된장"}, {"qty": "3장", "desc": null, "name": "월계수잎"}, {"qty": "8알", "desc": null, "name": "통후추"}, {"qty": "1/2대", "desc": null, "name": "대파"}]}'::jsonb);
INSERT INTO recipes (id, recipe_id, source_url, title, servings, cook_time, difficulty, tips, copyright, created_at, updated_at, raw_data) VALUES (421, '6953648', 'https://www.10000recipe.com/recipe/6953648', '잡채 황금레시피로 불지않게 맛있게 만드는법', '4인분', '60분 이내', '초급', '["당면은 삶지 않아요. 불린 당면은 양념과 같이 볶아줘야 당면이 불지 않아요. 당면보다 야채, 고기가 많아야 더 건강하고 맛있는 잡채를 즐길 수 있습니다."]'::jsonb, '쿡딱', 2025-11-23 02:17:51.736959, 2025-11-23 02:17:51.736959, '{"tips": ["당면은 삶지 않아요. 불린 당면은 양념과 같이 볶아줘야 당면이 불지 않아요. 당면보다 야채, 고기가 많아야 더 건강하고 맛있는 잡채를 즐길 수 있습니다."], "steps": ["당면과 건 목이버섯은 각각 1시간, 20분정도 불려주세요.", "잡채 야채 재료들을 길쭉하게 썰어 준비해줄께요. 목이버섯은 손가락크기정도로 썰어주세요.", "잡채용 돼지고기와 표고버섯에 밑간을 해줄께요. 볼에 고기와 표고버섯을 넣고 간장, 맛술, 설탕, 다진마늘, 참기름, 후추 넣고 밑간이 베이게 골고루 주물주물 해주세요.", "끓는 물에 소금을 넣고 시금치 넣고 다시 끓어오르면 건져내어 찬물에 헹구고 물기를 꼭 짜주세요. 물기 짠 시금치에 소금과 참기름만 넣고 살살 무쳐줄께요.", "잡채양념 - 간장, 물, 후추, 올리고당, 설탕, 굴소스, 식용유를 정량대로 넣고 큰 볼에 잘 섞어주면 양념 완성입니다.", "먼저 달궈진 궁중팬에 기름을 살짝 둘러 센불에서 양파, 당근, 파프리카, 목이버섯을 넣고 볶아주세요. 적당히 숨이 죽으면 불을 끄고 따로 접시에 옮겨 담아 한김 식혀주세요.", "같은 팬에 바로 밑간 해 놓은 돼지고기와 표고버섯도 달달달 ~ 볶아주세요. 볶아진 고기도 접시에 펼쳐 한김 식혀줄께요.", "고기 볶았던 팬에 강불로 불을 올리고 잡채양념을 넣고 끓이다가 끓어오르면 바로 불린 당면을 넣고 볶듯이 끓여주세요.", "당면이 익으면 가위로 먹기 좋게 한번씩 잘라주고, 양념이 없어질때 까지 볶다가 불을 꺼주세요.", "당면까지 다 볶으면 미리 준비해놓은 야채와 고기를 바로 위에 붓고 참기름 뿌려서 골고루 무쳐주세요. 뜨거우니 면장갑과 위생장갑 이용해주세요.", "참깨 솔솔 뿌려 고소함 업 시키면 잡채 완성입니다. 비주얼도 맛도 끝내줍니다. ^^"], "title": "잡채 황금레시피로 불지않게 맛있게 만드는법", "servings": "4인분", "cook_time": "60분 이내", "copyright": "쿡딱", "recipe_id": "6953648", "step_tips": [null, null, null, null, null, null, null, null, null, null, null], "difficulty": "초급", "source_url": "https://www.10000recipe.com/recipe/6953648", "ingredients": ["당면 300g", "돼지고기 300g", "말린 목이버섯 3개", "시금치 1/2단", "당근 1/2개", "양파 1개", "노란파프리카 1/2개", "빨간파프리카 1/2개", "생 표고버섯 3개", "진간장 2Ts", "맛술 1Ts", "설탕 1Ts", "참기름 1Ts", "다진마늘 1Ts", "후추 조금", "진간장 1/3컵", "설탕 2Ts", "올리고당 2Ts", "식용유 3Ts", "후추 약간", "굴소스 1ts", "물 1컵"], "ingredients_struct": [{"qty": "300g", "desc": null, "name": "당면"}, {"qty": "300g", "desc": null, "name": "돼지고기"}, {"qty": "3개", "desc": null, "name": "말린 목이버섯"}, {"qty": "1/2단", "desc": null, "name": "시금치"}, {"qty": "1/2개", "desc": null, "name": "당근"}, {"qty": "1개", "desc": null, "name": "양파"}, {"qty": "1/2개", "desc": null, "name": "노란파프리카"}, {"qty": "1/2개", "desc": null, "name": "빨간파프리카"}, {"qty": "3개", "desc": null, "name": "생 표고버섯"}, {"qty": "2Ts", "desc": null, "name": "진간장"}, {"qty": "1Ts", "desc": null, "name": "맛술"}, {"qty": "1Ts", "desc": null, "name": "설탕"}, {"qty": "1Ts", "desc": null, "name": "참기름"}, {"qty": "1Ts", "desc": null, "name": "다진마늘"}, {"qty": "조금", "desc": null, "name": "후추"}, {"qty": "1/3컵", "desc": null, "name": "진간장"}, {"qty": "2Ts", "desc": null, "name": "설탕"}, {"qty": "2Ts", "desc": null, "name": "올리고당"}, {"qty": "3Ts", "desc": null, "name": "식용유"}, {"qty": "약간", "desc": null, "name": "후추"}, {"qty": "1ts", "desc": null, "name": "굴소스"}, {"qty": "1컵", "desc": null, "name": "물"}]}'::jsonb);
INSERT INTO recipes (id, recipe_id, source_url, title, servings, cook_time, difficulty, tips, copyright, created_at, updated_at, raw_data) VALUES (309, '6867636', 'https://www.10000recipe.com/recipe/6867636', '배추겉절이 만드는 법', '6인분 이상', '2시간 이상', '아무나', '[]'::jsonb, '뽕림이', 2025-11-23 00:16:49.294539, 2025-11-23 01:28:47.878798, '{"tips": [], "steps": ["배추는 밑동에 십자(+) 칼집을 내준 뒤 손으로 쪼개 4등분을 해주시고요.", "사진에서처럼 밑동을 잘라준 다음 먹기 좋은 크기로 배춧잎을 잘라줍니다. (손으로 쭉쭉 찢어주셔도 돼요.)", "그다음 굵은소금 한 줌을 배추에 골고루 뿌려준 뒤 물 한 컵을 흩뿌리듯 뿌려 3-4시간 정도 절여주시는데요. 배추에 간이 고루 배일 수 있도록 중간에 한두 번 정도 섞어주시는 센스 ~ (소금물을 만들어 절여주셔도 됩니다.)", "3시간이 지나자 배추에 숨이 어느 정도 죽었어요.", "절인 배추는 흐르는 물에 두어 번 정도 헹궈 체에 밭쳐 물기를 빼주세요. 그리고 나서 배춧잎과 줄기 부분의 간을 봐주시는데요. 이때 배추가 조금 짜게 절여졌다면 액젓의 양을 줄여주시고, 싱겁다면 소금이나 액젓을 더 넣어주세요 ^^ 저는 짜지도 싱겁지도 않게 절여져 위의 레시피대로 양념을 넣어줬어요.", "절인 배추에 검지손가락 길이로 잘라둔 쪽파를 넣고 고춧가루 반 컵을 투척 ~", "이어서 다진 마늘 1 큰 술과 매실청 2 큰 술, 액젓 4 큰 술, 설탕 2 큰 술을 넣고 잘 버무려주세요.", "이렇게 ~", "마지막으로 간을 한 번 봐주세요. 싱겁다면 소금을, 감칠맛이 부족한 것 같으면 액젓을, 단맛이 부족하다 설탕을 ~ 저는 입맛에 딱 맞아서 따로 간을 추가하지 않았어요.", "보기만 해도 군침이 자르르 흐르는 배추 겉절이 ♩ 덕분에 다이어트 중이라는 사실도 잊고, 밥을 한 그릇 반이나 처묵처묵했다는 건 비밀 >_< 아, 맛있게 잘 먹었다 ''-''*"], "title": "배추겉절이 만드는 법", "servings": "6인분 이상", "cook_time": "2시간 이상", "copyright": "뽕림이", "recipe_id": "6867636", "step_tips": [null, null, null, null, null, null, null, null, null, null], "difficulty": "아무나", "source_url": "https://www.10000recipe.com/recipe/6867636", "ingredients": ["알배기 배추 1통", "쪽파 1줌", "굵은 소금 배추 절이기 1줌", "굵은 고춧가루 1/2컵", "다진 마늘 1큰술", "매실청 2큰술", "설탕 2큰술", "멸치 액젓 4큰술", "소금 입맛에 맞게 적당량"], "ingredients_struct": [{"qty": "1통", "desc": null, "name": "알배기 배추"}, {"qty": "1줌", "desc": null, "name": "쪽파"}, {"qty": "1줌", "desc": null, "name": "굵은 소금 배추 절이기"}, {"qty": "1/2컵", "desc": null, "name": "굵은 고춧가루"}, {"qty": "1큰술", "desc": null, "name": "다진 마늘"}, {"qty": "2큰술", "desc": null, "name": "매실청"}, {"qty": "2큰술", "desc": null, "name": "설탕"}, {"qty": "4큰술", "desc": null, "name": "멸치 액젓"}, {"qty": "적당량", "desc": null, "name": "소금 입맛에 맞게"}]}'::jsonb);
INSERT INTO recipes (id, recipe_id, source_url, title, servings, cook_time, difficulty, tips, copyright, created_at, updated_at, raw_data) VALUES (310, '6867648', 'https://www.10000recipe.com/recipe/6867648', '된장 국물이 시원하고 얼큰한 배추 된장국 만들기', '2인분', '10분 이내', '아무나', '["고기랑도 잘 어울리고 그냥 밥 말아서 먹기에도 딱좋은 된장국입니다! 국거리 없을때마다 해 드시기에 시원하고 매우 간단해요~"]'::jsonb, '춤추는곰', 2025-11-23 00:18:31.561492, 2025-11-23 01:28:47.955867, '{"tips": ["고기랑도 잘 어울리고 그냥 밥 말아서 먹기에도 딱좋은 된장국입니다! 국거리 없을때마다 해 드시기에 시원하고 매우 간단해요~"], "steps": ["일단 멸치 다시 육수를 끓여주세요!", "알배추는 반통정도 툭툭 썰어주세요~", "된장은 집된장, 시판 된장 다 괜찮습니다", "육수가 끓으면 육수에 된장을 풀어줍니다~ 두스푼!", "된장을 넣은채로 바글바글 끓여주세요", "알배추를 넣어주시구요", "다진마늘 반스푼 넣어주세요", "고춧가루 반스푼 넣어주세요", "바글바글 또 끓여줍니다", "대파를 송송 잘라서 넣어주세요", "배추가 약간 흐물흐물 하게 익혀지면 끝!"], "title": "된장 국물이 시원하고 얼큰한 배추 된장국 만들기", "servings": "2인분", "cook_time": "10분 이내", "copyright": "춤추는곰", "recipe_id": "6867648", "step_tips": ["냄비", "도마", null, null, null, null, null, null, null, null, null], "difficulty": "아무나", "source_url": "https://www.10000recipe.com/recipe/6867648", "ingredients": ["알배추 1/2통", "대파 0.5-1대", "된장 2T", "고춧가루 0.5T", "다진마늘 0.5T", "멸치다시육수"], "ingredients_struct": [{"qty": "1/2통", "desc": null, "name": "알배추"}, {"qty": "0.5-1대", "desc": null, "name": "대파"}, {"qty": "2T", "desc": null, "name": "된장"}, {"qty": "0.5T", "desc": null, "name": "고춧가루"}, {"qty": "0.5T", "desc": null, "name": "다진마늘"}, {"qty": "", "desc": null, "name": "멸치다시육수"}]}'::jsonb);
INSERT INTO recipes (id, recipe_id, source_url, title, servings, cook_time, difficulty, tips, copyright, created_at, updated_at, raw_data) VALUES (312, '6868573', 'https://www.10000recipe.com/recipe/6868573', '아삭 건강한 깍두기 담그는법~', '6인분 이상', '90분 이내', '아무나', '["양념에 매실청과 사과를 넣어서 상큼한 맛을 더했는데요. 과일을 넣으면 김치가 훨씬 맛있어지는 효과가 있어요. 설탕에서 찾지 못하는 맛이라죠. 상큼한 김치가 입에 착착 달라붙는답니다."]'::jsonb, '팬이맘', 2025-11-23 00:21:33.893558, 2025-11-23 01:28:47.974122, '{"tips": ["양념에 매실청과 사과를 넣어서 상큼한 맛을 더했는데요. 과일을 넣으면 김치가 훨씬 맛있어지는 효과가 있어요. 설탕에서 찾지 못하는 맛이라죠. 상큼한 김치가 입에 착착 달라붙는답니다."], "steps": ["깍두기 맛있게 담그는법! 무 2개 준비하고요. 양파 1/2개, 사과 1/2개, 마늘 생강 쪽파 모두 다듬고 씻고요.", "보이는 대로 사과 양파 마늘 생강 모두 손질되었고요.", "무는 반으로 자르고 또 자르고~ 예쁘게 잘라줬어요.", "크기는 이만하게~", "무에 소금 3.5큰술을 넣고 잘 절여지게 섞어서 한 시간 뒀답니다.", "무가 절여지는 동안 쪽파도 썰고요. 깍두기 길이 정도 썰었네요.", "준비된 양념 재료를 잘라줬고요 믹서기에 휘릭 갈아줬답니다.", "풀을 쑬 건데요. 풀은 찹쌀 풀도 좋지만 부드러운 밀가루 풀도 괜찮아요. 음식을 만들면 음식이 더 곱게 보여요. 미니튀김팬에 물 한 컵 붓고요. 밀가루 2큰술 넣어 잘 풀어 준 다음 잘 저어가면서 풀을 쑵니다. 식혀주고요.~", "볼에다 양념 만들기 돌입!! 양념 간 것과", "쪽파 그리고 새우젓 1큰술 투하! 밀가루 풀도 투하!!", "까나리액젓 2큰술, 매실청 3큰술 넣었어요.", "고춧가루는 넉넉하게 7큰술 넣었고요. 깍두기 양념을 골고루 버무려 줍니다.", "싱거워서 소금 1큰술 더 투하!!", "양념을 버무려줬고요.", "무깍두기는 체에 걸러서 수분을 뺍니다. 물에 헹구지 않아요.~", "볼에 담고 준비한 양념을 넣고요.", "휘리릭 무치면 무깍두기 완성!!", "통에 담고요.~ 양념이 제대로네요. 먹음직 먹음직! (근데 말이죠~ 달지 않아요. 이번엔 시원한 맛으로 먹으려고 사과와 매실청만 넣었어요. 새콤달콤한 맛을 원한다면 뉴슈가 0.5작은술 정도나 설탕을 조금 더 넣어주면 된답니다.)"], "title": "아삭 건강한 깍두기 담그는법~", "servings": "6인분 이상", "cook_time": "90분 이내", "copyright": "팬이맘", "recipe_id": "6868573", "step_tips": [null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null], "difficulty": "아무나", "source_url": "https://www.10000recipe.com/recipe/6868573", "ingredients": ["무 2개", "천일염 3.5큰술", "밀가루 2큰술", "물 200ml", "고춧가루 7큰술", "매실청 3큰술", "사과 1/2쪽", "쪽파 5뿌리", "양파 1/2개", "생강 0.5큰술", "마늘 3큰술", "까나리액젓 2큰술", "새우젓 1큰술", "소금 1큰술"], "ingredients_struct": [{"qty": "2개", "desc": null, "name": "무"}, {"qty": "3.5큰술", "desc": null, "name": "천일염"}, {"qty": "2큰술", "desc": null, "name": "밀가루"}, {"qty": "200ml", "desc": null, "name": "물"}, {"qty": "7큰술", "desc": null, "name": "고춧가루"}, {"qty": "3큰술", "desc": null, "name": "매실청"}, {"qty": "1/2쪽", "desc": null, "name": "사과"}, {"qty": "5뿌리", "desc": null, "name": "쪽파"}, {"qty": "1/2개", "desc": null, "name": "양파"}, {"qty": "0.5큰술", "desc": null, "name": "생강"}, {"qty": "3큰술", "desc": null, "name": "마늘"}, {"qty": "2큰술", "desc": null, "name": "까나리액젓"}, {"qty": "1큰술", "desc": null, "name": "새우젓"}, {"qty": "1큰술", "desc": null, "name": "소금"}]}'::jsonb);
INSERT INTO recipes (id, recipe_id, source_url, title, servings, cook_time, difficulty, tips, copyright, created_at, updated_at, raw_data) VALUES (422, '6983886', 'https://www.10000recipe.com/recipe/6983886', '치킨스튜 닭고기 프리카세(Fricassée) 쉽게 만드는 법', '2인분', '30분 이내', '중급', '[]'::jsonb, '별바라기쿡방', 2025-11-23 02:20:10.526199, 2025-11-23 02:20:10.526199, '{"tips": [], "steps": ["양파와 표고버섯은 채 썰어 놓습니다. 버섯은 좋아하시는 버섯 쓰면 됩니다.", "닭은 손질해서 먹기 좋게 잘라 깨끗이 세척합니다. 물기를 제거하고 잘 익을 수 있게 칼집도 해놓습니다.", "예열된 프라이팬에 기름을 두르고 버터 20g도 넣어 녹입니다. 그리고 손질된 닭을 앞뒤로 노릇노릇하게 구워줍니다. 어느 정도 노릇하게 구워지면 따로 빼놓습니다.", "동일한 프라이팬에 닭기름으로 양파와 다진마늘 1큰술을 넣고 볶아줍니다.", "양파가 투명해지면 버섯도 넣어서 같이 볶아줍니다.", "버섯이 다 볶아지면 밀가루 2큰술을 넣고 살짝 볶아주세요.", "물 200ml, 우유 200ml, 맛술 2큰술, 케첩 2큰술, 간장 2큰술, 식초 2큰술, 설탕 2큰술, 소금 1/2작은술을 넣고 잘 섞어주세요.", "로즈마리, 파슬리, 후추도 넣어서 잘 섞어주세요.", "빼놨던 닭을 넣어서 뚜껑을 닫고 중약불로 10분 끓여주세요. 10분 후에, 닭을 뒤집어서 약불로 10분 더 끓여주세요.(총 20분)", "그릇에 옮겨서 파슬리를 뿌려주면 완성입니다."], "title": "치킨스튜 닭고기 프리카세(Fricassée) 쉽게 만드는 법", "servings": "2인분", "cook_time": "30분 이내", "copyright": "별바라기쿡방", "recipe_id": "6983886", "step_tips": [null, null, null, null, null, null, null, null, null, null], "difficulty": "중급", "source_url": "https://www.10000recipe.com/recipe/6983886", "ingredients": ["닭 5호", "양파 1/4개", "표고버섯 3개", "버터 20g", "식용유 2큰술", "기름 적당량", "맛술 2큰술", "케첩 2큰술", "간장 2큰술", "식초 2큰술", "설탕 2큰술", "소금 1/2큰술", "밀가루 2큰술", "우유 200ml", "물 200ml", "다진마늘 1큰술", "후추 조금", "파슬리가루 조금", "로즈마리 조금"], "ingredients_struct": [{"qty": "5호", "desc": null, "name": "닭"}, {"qty": "1/4개", "desc": null, "name": "양파"}, {"qty": "3개", "desc": null, "name": "표고버섯"}, {"qty": "20g", "desc": null, "name": "버터"}, {"qty": "2큰술", "desc": null, "name": "식용유"}, {"qty": "적당량", "desc": null, "name": "기름"}, {"qty": "2큰술", "desc": null, "name": "맛술"}, {"qty": "2큰술", "desc": null, "name": "케첩"}, {"qty": "2큰술", "desc": null, "name": "간장"}, {"qty": "2큰술", "desc": null, "name": "식초"}, {"qty": "2큰술", "desc": null, "name": "설탕"}, {"qty": "1/2큰술", "desc": null, "name": "소금"}, {"qty": "2큰술", "desc": null, "name": "밀가루"}, {"qty": "200ml", "desc": null, "name": "우유"}, {"qty": "200ml", "desc": null, "name": "물"}, {"qty": "1큰술", "desc": null, "name": "다진마늘"}, {"qty": "조금", "desc": null, "name": "후추"}, {"qty": "조금", "desc": null, "name": "파슬리가루"}, {"qty": "조금", "desc": null, "name": "로즈마리"}]}'::jsonb);
INSERT INTO recipes (id, recipe_id, source_url, title, servings, cook_time, difficulty, tips, copyright, created_at, updated_at, raw_data) VALUES (423, '6993115', 'https://www.10000recipe.com/recipe/6993115', '생굴무침 양념 레시피 굴무생채 물기 없이 쫄깃한 굴무침만들기', '4인분', '60분 이내', '아무나', '["저는 새콤달콤한 무침양념보다는 김치 같은 스타일을 좋아해서 간장 대신 액젓을 사용했는데요 액젓이 싫으면 간장을 사용하셔도 됩니다."]'::jsonb, '요리하는러라', 2025-11-23 02:22:14.453389, 2025-11-23 02:22:14.453389, '{"tips": ["저는 새콤달콤한 무침양념보다는 김치 같은 스타일을 좋아해서 간장 대신 액젓을 사용했는데요 액젓이 싫으면 간장을 사용하셔도 됩니다."], "steps": ["굴은 봉지끝을 조금만 잘라 충전수를 버리고 굴만 볼에 담은 후 찬물을 자박하게 붓고 굵은소금 반 스푼을 넣어 씻어줍니다.", "씻는 방법은 숟가락으로 굴을 휘휘 젓고 살살 뒤집어 가며 헹구다가 체에 거르고, 다시 그릇으로 옮겨 물을 받아 휘휘 젓고 체에 거르고를~ 맑은 물이 나올 때까지 반복하면서 씻어주면 돼요.", "이렇게 물이 맑아지고 굴이 뽀얗게 될 때까지 씻어주면 굴손질 끝!", "이제 굴에 밑간을 해줄게요 볼에 세척한 생굴을 담고 맛술 2, 고운소금 0.5숟가락을 넣은 다음 고루 섞은 후 체에 밭쳐 냉장실에 40분간 재워둡니다. 채반 아래에는 굴에서 나오는 수분이 굴에 닿지 않도록 오목한 그릇을 받쳐주세요.", "굴을 재우는 동안 무 한 토막은 얇게 나박나박 저며 썬 다음 볼에 담고 고운 소금 0.3숟가락을 넣고 고루 버무려 30분간 절여줍니다.", "절인 굴과 무에서 나온 물은 버려주고 무와 굴은 헹구지 않아요~", "볼에 물기 쭉 뺀 생굴과 무를 넣고 고춧가루 5, 설탕 0.5, 다진마늘 2 다진생강 0.2, 매실청 2, 액젓 1.5를 넣고 숟가락으로 살살 섞어서 무쳐줍니다. 간을 보고 싱거우면 액젓을 추가하세요 저는 반스푼 추가해서 총 두스푼 넣어주었어요", "처음에는 색이 이게 맞나? 싶어도 시간이 조금 지나면 고춧가루가 퍼지면서 먹음직스럽게 물든답니다 :) 이렇게 만든 생굴무침은 양념에 버무려서 밀폐용기에 담아 두어시간 숙성시켜 주면 굴도 쫄깃해지면서 더 맛있어진답니다.", "먹기 직전에 버무려야 해서 한번 먹을만큼만 만들었던 굴 무침을 이 레시피대로 하면 더 많이 만들어서 이틀 정도 즐길 수 있답니다."], "title": "생굴무침 양념 레시피 굴무생채 물기 없이 쫄깃한 굴무침만들기", "servings": "4인분", "cook_time": "60분 이내", "copyright": "요리하는러라", "recipe_id": "6993115", "step_tips": [null, null, null, null, null, null, null, null, null], "difficulty": "아무나", "source_url": "https://www.10000recipe.com/recipe/6993115", "ingredients": ["굴 500g", "무 200g", "고운소금 0.8숟가락", "맛술 2숟가락", "고춧가루 5숟가락", "설탕 0.5숟가락", "다진마늘 2숟가락", "다진생강 0.2숟가락", "매실청 2숟가락", "액젓 2숟가락", "통깨 약간"], "ingredients_struct": [{"qty": "500g", "desc": null, "name": "굴"}, {"qty": "200g", "desc": null, "name": "무"}, {"qty": "0.8숟가락", "desc": null, "name": "고운소금"}, {"qty": "2숟가락", "desc": null, "name": "맛술"}, {"qty": "5숟가락", "desc": null, "name": "고춧가루"}, {"qty": "0.5숟가락", "desc": null, "name": "설탕"}, {"qty": "2숟가락", "desc": null, "name": "다진마늘"}, {"qty": "0.2숟가락", "desc": null, "name": "다진생강"}, {"qty": "2숟가락", "desc": null, "name": "매실청"}, {"qty": "2숟가락", "desc": null, "name": "액젓"}, {"qty": "약간", "desc": null, "name": "통깨"}]}'::jsonb);
INSERT INTO recipes (id, recipe_id, source_url, title, servings, cook_time, difficulty, tips, copyright, created_at, updated_at, raw_data) VALUES (315, '6871892', 'https://www.10000recipe.com/recipe/6871892', '백종원 육개장, 육개장 만드는거 어렵지않네 ~', '4인분', '30분 이내', '초급', '[]'::jsonb, '엘린84', 2025-11-23 00:27:15.283920, 2025-11-23 01:31:26.221189, '{"tips": [], "steps": ["고사리, 대파, 표고버섯은 먹기좋은 크기로 잘라서 준비해주시구요 숙주는 깨끗이 씻어서 준비해주세요", "그리고 큰 냄비나 웍에 식용유 2큰술, 참기름 4큰술 넣어줬어요 양에 따라 참기름은 좀 더 넣으셔도 되요", "그리고 큼직큼직하게 썰어둔 대파를 먼저 달달 볶아주세요 ~", "살짝 복은뒤에 소고기도 넣어서 같이 볶아주시구요", "소고기 겉면이 어느정도 익었다 싶을때 고춧가루 3큰술을 넣어서 한번 휘리릭 볶아주세요", "그리고 물을 넣어주시는데요 재료에 따라 물양은 더 추가하셔도 좋아요", "물을 넣어주고 살짝 끓어오르기 시작하면 미리 준비해두었던 고사리와 표고버섯을 넣고 같이 끓여주세요 토란대도 준비하셨다면 토란대도 같이 넣어서 끓여주세요", "그리고 이위에 다진마늘 1큰술, 국간장 2큰술을 넣어줬어요 간은 드시는 기호에 따라 국간장이나 소금을 더 추가하시면 되는데요 전 소금을 1/2큰술 정도 더 넣어서 끓여줬어요 신랑은 살짝 싱겁다고 하긴 했는데 제입맛엔 딱이였거든요 ~ 드셔보시면서 간은 추가해주시면 될것같아요", "그리고 마지막에 씻어두었던 숙주를 올려서 바글바글 끓여주시면 된답니다 ~", "아주 먹음직스럽게, 어느정도 비주얼도 그럴싸하죠 ~^^ 그동안 육개장을 왜이렇게 어렵게 끓였었나 싶더라구요 이렇게 쉬운 레시피가 있는데 말이죠 ㅋ", "저는 국물보다 건더기양이 좀 더 많았었는데 육개장은 또 이런 건더기 먹는 재미도 있어서 딱 좋더라구요 ~ 취향에따라 마지막에 계란 풀어서 넣어주셔도 좋아요 ~"], "title": "백종원 육개장, 육개장 만드는거 어렵지않네 ~", "servings": "4인분", "cook_time": "30분 이내", "copyright": "엘린84", "recipe_id": "6871892", "step_tips": [null, null, null, null, null, null, null, null, null, null, null], "difficulty": "초급", "source_url": "https://www.10000recipe.com/recipe/6871892", "ingredients": ["소고기", "고사리", "대파", "숙주", "표고버섯", "식용유 2큰술", "참기름 4큰술", "고춧가루 3큰술", "다진마늘 1큰술", "국간장 2큰술", "소금 약간"], "ingredients_struct": [{"qty": "", "desc": null, "name": "소고기"}, {"qty": "", "desc": null, "name": "고사리"}, {"qty": "", "desc": null, "name": "대파"}, {"qty": "", "desc": null, "name": "숙주"}, {"qty": "", "desc": null, "name": "표고버섯"}, {"qty": "2큰술", "desc": null, "name": "식용유"}, {"qty": "4큰술", "desc": null, "name": "참기름"}, {"qty": "3큰술", "desc": null, "name": "고춧가루"}, {"qty": "1큰술", "desc": null, "name": "다진마늘"}, {"qty": "2큰술", "desc": null, "name": "국간장"}, {"qty": "약간", "desc": null, "name": "소금"}]}'::jsonb);
INSERT INTO recipes (id, recipe_id, source_url, title, servings, cook_time, difficulty, tips, copyright, created_at, updated_at, raw_data) VALUES (316, '6871896', 'https://www.10000recipe.com/recipe/6871896', '오이지 무침 꼬들꼬들 아삭하게 만드는법', '3인분', '15분 이내', '초급', '["여름 밥상 최고의 반찬! 냉장고에 시원하게 넣어두셨다가 드셔보세요. 시원함은 기본에 참기름의 고소함과 고춧가루의 살짝 매콤함 그리고 매실액의 상큼함까지! 결혼 전에는 친정엄마가 항상 해주셨지만 똑같은 맛을 내기 힘들었는데요. 이번에는 맛이 거의 비슷하게 무쳐져서 기분 좋았던 요리 시간이었습니다. 냉장고에 오이지가 잔뜩 있으시다면 시원하게 무쳐보시는 것은 어떠세요? 만드는법도 간단하니까요.^-^"]'::jsonb, '미소앨범by하준맘', 2025-11-23 00:28:57.379647, 2025-11-23 01:31:26.229226, '{"tips": ["여름 밥상 최고의 반찬! 냉장고에 시원하게 넣어두셨다가 드셔보세요. 시원함은 기본에 참기름의 고소함과 고춧가루의 살짝 매콤함 그리고 매실액의 상큼함까지! 결혼 전에는 친정엄마가 항상 해주셨지만 똑같은 맛을 내기 힘들었는데요. 이번에는 맛이 거의 비슷하게 무쳐져서 기분 좋았던 요리 시간이었습니다. 냉장고에 오이지가 잔뜩 있으시다면 시원하게 무쳐보시는 것은 어떠세요? 만드는법도 간단하니까요.^-^"], "steps": ["[염도 제거] 냉장고 안에서 시원하게 보관된 오이지는 너무 두껍지 않게 얇게 썰어 주신 후 찬물에 담가서 염도를 제거해주셔야 해요. (소금물에 절인 거라 그냥 무치면 짜거든요)", "짠 정도에 따라 담가놓는 시간이 다르지만 저는 많이 짠 편이 아니어서 10분 정도 담가두니 적당했답니다. 10분 후 오이지 하나 드셔보시고 여전히 많이 짜다 싶으시면 물을 갈아서5분 정도만 더 담가 놓아 주세요!", "[오이지 수분제거] 짠맛을 제거한 오이는 면보를 이용해서 최대한 꾹! 짜서 물기를 제거해주셔야 해요. 그래야 오도독! 오도독! 한 식감을 제대로 느끼실 수 있거든요.", "수분을 최대한 짜낸 상태인데요. 많이 쭈글 쭈글 해졌죠? 이제 양념해주고 무쳐주면 완성됩니다. 오이지 무침 만드는법 너무 간단하죠!", "[무치기] 볼에 수분을 제거한 오이를 담아주시고 송송 썰어놓은 대파 한 줌을 넣고 양념해주세요. 고춧가루 반 스푼, 설탕 반 스푼, 매실액 1스푼, 간 마늘 반 스푼, 참기름 1스푼, 으깬 통깨 1스푼", "위생장갑을 착용하시고 조물조물 양념이 잘 베도록 무쳐 주시면 된답니다", "여름에 더 잘 어울리는 시원한 오이지 무침!이렇게 초 간단하게 완성되었습니다."], "title": "오이지 무침 꼬들꼬들 아삭하게 만드는법", "servings": "3인분", "cook_time": "15분 이내", "copyright": "미소앨범by하준맘", "recipe_id": "6871896", "step_tips": [null, "큰 볼", "면보", null, null, null, null], "difficulty": "초급", "source_url": "https://www.10000recipe.com/recipe/6871896", "ingredients": ["오이지 2개", "다지듯 송송 썰어놓은 대파 1줌", "고춧가루 1/2숟가락", "설탕 1/2스푼", "매실액 1스푼", "간마늘 1스푼", "참기름 1스푼", "으깬통깨 1스푼"], "ingredients_struct": [{"qty": "2개", "desc": null, "name": "오이지"}, {"qty": "1줌", "desc": null, "name": "다지듯 송송 썰어놓은 대파"}, {"qty": "1/2숟가락", "desc": null, "name": "고춧가루"}, {"qty": "1/2스푼", "desc": null, "name": "설탕"}, {"qty": "1스푼", "desc": null, "name": "매실액"}, {"qty": "1스푼", "desc": null, "name": "간마늘"}, {"qty": "1스푼", "desc": null, "name": "참기름"}, {"qty": "1스푼", "desc": null, "name": "으깬통깨"}]}'::jsonb);
INSERT INTO recipes (id, recipe_id, source_url, title, servings, cook_time, difficulty, tips, copyright, created_at, updated_at, raw_data) VALUES (317, '6872216', 'https://www.10000recipe.com/recipe/6872216', '고사리 나물 볶음 레시피, 들기름 향이 솔솔', '4인분', '30분 이내', '초급', '["부드럽다고 해서 푹 퍼진 게 아닌 꼬들꼬들하면서도 구수한 맛이 있는 나물 반찬이랍니다. 고소한 들기름 향도 솔솔 나는 게 식용유를 넣은 것보다 향도 훨씬 좋고요. 이대로 반찬으로 먹거나 잘게 잘라 비빔밥으로 쓱싹 비벼 먹어도 너무나 맛있답니다. 맛있게 만들어 드세요♡"]'::jsonb, '베리츄', 2025-11-23 00:30:34.881236, 2025-11-23 01:31:26.237913, '{"tips": ["부드럽다고 해서 푹 퍼진 게 아닌 꼬들꼬들하면서도 구수한 맛이 있는 나물 반찬이랍니다. 고소한 들기름 향도 솔솔 나는 게 식용유를 넣은 것보다 향도 훨씬 좋고요. 이대로 반찬으로 먹거나 잘게 잘라 비빔밥으로 쓱싹 비벼 먹어도 너무나 맛있답니다. 맛있게 만들어 드세요♡"], "steps": ["말린 고사리를 사용할 경우 하루 전날 불려 쌀뜨물(없다면 물)에 넣고 중불로 15분 정도 삶아주세요. 고사리가 부드러워지면 건져내 찬물에 헹궈주면 됩니다. 삶은 고사리는 시장에서도 많이 판매하고 있으니 구입하는데 어렵진 않으실 거예요. 물기가 있는 채로 볶아줄 거라서 뚝뚝 떨어지지 않을 정도로만 손으로 눌러가며 물기를 제거해주시고요. 300g, 약 2줌 반 정도 준비해주시면 됩니다.", "중약불로 달군 팬에 들기름 4큰술와 고사리 300g을 넣어주세요.", "뚜껑을 덮어 7-8분간 볶아주세요.", "쉽게 탈 것 같지만 고사리가 수분을 머금고 있어 골고루 익혀진답니다. 뚜껑을 덮어 익혀주기 때문에 수분이 날아가지 않아요. 촉촉하면서도 부드러운 고사리볶음을 만들 수 있어요.", "국간장 1큰술, 다진마늘 1큰술, 다진파 1큰술, 설탕 1작은술을 넣어주세요. 이때 모자란 간은 소금으로 더해주세요.", "중불에서 1분간 골고루 볶아준 뒤 뚜껑을 덮어 다시 3분간 볶아주세요. 깨소금을 넉넉히 넣어주며 마무리.", "고사리가 질긴 편이라면 뚜껑을 덮기 전 물 4-5큰술을 같이 넣어주세요."], "title": "고사리 나물 볶음 레시피, 들기름 향이 솔솔", "servings": "4인분", "cook_time": "30분 이내", "copyright": "베리츄", "recipe_id": "6872216", "step_tips": [null, null, null, null, null, null, null], "difficulty": "초급", "source_url": "https://www.10000recipe.com/recipe/6872216", "ingredients": ["삶은 고사리 약2.5줌 300g", "다진마늘 1큰술", "다진파 1큰술", "국간장 1큰술", "설탕 1작은술", "들기름 4큰술", "깨소금 조금"], "ingredients_struct": [{"qty": "300g", "desc": null, "name": "삶은 고사리 약2.5줌"}, {"qty": "1큰술", "desc": null, "name": "다진마늘"}, {"qty": "1큰술", "desc": null, "name": "다진파"}, {"qty": "1큰술", "desc": null, "name": "국간장"}, {"qty": "1작은술", "desc": null, "name": "설탕"}, {"qty": "4큰술", "desc": null, "name": "들기름"}, {"qty": "조금", "desc": null, "name": "깨소금"}]}'::jsonb);
INSERT INTO recipes (id, recipe_id, source_url, title, servings, cook_time, difficulty, tips, copyright, created_at, updated_at, raw_data) VALUES (330, '6881688', 'https://www.10000recipe.com/recipe/6881688', '갈릭새우버터구이. 쉽고 폼나는 새우요리.', '3인분', '30분 이내', '아무나', '["익은 마늘과 같이 먹으면 더 맛있답니다."]'::jsonb, '롱만이', 2025-11-23 00:55:22.794902, 2025-11-23 01:38:37.184569, '{"tips": ["익은 마늘과 같이 먹으면 더 맛있답니다."], "steps": ["새우를 물에 씻고 꼬리부분을 남기고 머리와 내장을 제거해주었어요. 새우 등의 내장은 이쑤시개로 2-3번째 등을 찔러서 쏘옥~ 빼주시면 된답니다.", "손질된 새우를 소금, 후추로 밑간을 해주고 10분정도 놔두었어요.", "그동안 통마늘을 편썰어 준비해주시고요. 팬에 올리브유를 두른후 마늘을 넣어서 마늘향을 내주세요.", "마늘이 익어가면 밑간한 새우를 넣고 맛술 1T를 넣어서 혹시 모를 비린향을 날려주세요. 화이트와인을 사용하셔도 좋지요 : )", "새우와 마늘을 가끔 볶아가면서 익혀주세요.", "새우가 빨갛게 다 익으면 버터 1스푼을 넣고 섞어주세요.", "버터가 새우와잘 섞어지면 불을 꺼주세요. 저는 바질가루가 있어서 뿌려 향을 더 내주었어요 : )(생략하셔도 됩니다)", "30분도 걸리지 않고갈릭버터새우구이가 완성된답니다 : )"], "title": "갈릭새우버터구이. 쉽고 폼나는 새우요리.", "servings": "3인분", "cook_time": "30분 이내", "copyright": "롱만이", "recipe_id": "6881688", "step_tips": [null, null, null, null, null, null, null, null], "difficulty": "아무나", "source_url": "https://www.10000recipe.com/recipe/6881688", "ingredients": ["생새우 or 냉동새우 15마리", "통마늘 7-8개", "올리브유 1T", "버터 1T", "맛술 1T", "소금 약간", "후추 약간"], "ingredients_struct": [{"qty": "15마리", "desc": null, "name": "생새우 or 냉동새우"}, {"qty": "7-8개", "desc": null, "name": "통마늘"}, {"qty": "1T", "desc": null, "name": "올리브유"}, {"qty": "1T", "desc": null, "name": "버터"}, {"qty": "1T", "desc": null, "name": "맛술"}, {"qty": "약간", "desc": null, "name": "소금"}, {"qty": "약간", "desc": null, "name": "후추"}]}'::jsonb);
INSERT INTO recipes (id, recipe_id, source_url, title, servings, cook_time, difficulty, tips, copyright, created_at, updated_at, raw_data) VALUES (424, '7002443', 'https://www.10000recipe.com/recipe/7002443', '쫄깃한 식감과 버터의 풍미가 느껴지는 닭고기스테이크', '2인분', '30분 이내', '아무나', '[]'::jsonb, '만개의레시피', 2025-11-23 02:23:59.434905, 2025-11-23 02:23:59.434905, '{"tips": [], "steps": ["닭다리살은 소금, 후추, 바질가루를 뿌려 재료 준비하는 동안 재워요.", "감자, 아스파라거스는 먹기 좋게 손질해서 준비해요.", "예열된 팬에 올리브유를 넣고 밑간한 닭고기를 넣어요.", "감자는 익는 시간이 길어 고기와 함께 넣어 익혀요.", "약 1분간 센불에서 굽고 뒤집어 한쪽을 1분간 더 구워요.", "약불로 줄이고 준비한 채소, 버터를 넣어 함께 익혀요.(약 5분)", "아스파라거스는 빨리 꺼내고 감자와 닭고기는 2~3분 더 익혀내요.", "익혀진 재료를 모두 꺼내고 소스 재료를 넣어 살짝 끓여 내요.", "접시에 익혀낸 재료들을 담고 소스를 뿌려 완성해요."], "title": "쫄깃한 식감과 버터의 풍미가 느껴지는 닭고기스테이크", "servings": "2인분", "cook_time": "30분 이내", "copyright": "만개의레시피", "recipe_id": "7002443", "step_tips": [null, null, null, null, null, null, null, null, null], "difficulty": "아무나", "source_url": "https://www.10000recipe.com/recipe/7002443", "ingredients": ["닭다리살 정육 300g", "소금 약간", "후추 약간", "바질가루 약간", "버터 1숟가락", "올리브유 3숟가락", "감자", "아스파라거스", "간장 3숟가락", "올리고당 3숟가락", "케찹 1숟가락"], "ingredients_struct": [{"qty": "300g", "desc": null, "name": "닭다리살 정육"}, {"qty": "약간", "desc": null, "name": "소금"}, {"qty": "약간", "desc": null, "name": "후추"}, {"qty": "약간", "desc": null, "name": "바질가루"}, {"qty": "1숟가락", "desc": null, "name": "버터"}, {"qty": "3숟가락", "desc": null, "name": "올리브유"}, {"qty": "", "desc": null, "name": "감자"}, {"qty": "", "desc": null, "name": "아스파라거스"}, {"qty": "3숟가락", "desc": null, "name": "간장"}, {"qty": "3숟가락", "desc": null, "name": "올리고당"}, {"qty": "1숟가락", "desc": null, "name": "케찹"}, {"qty": "약간", "desc": null, "name": "후추"}]}'::jsonb);
INSERT INTO recipes (id, recipe_id, source_url, title, servings, cook_time, difficulty, tips, copyright, created_at, updated_at, raw_data) VALUES (425, '7011936', 'https://www.10000recipe.com/recipe/7011936', '쉽게 닭볶음탕 맛있게 만드는법 닭볶음탕 황금레시피 닭도리탕', '4인분', '30분 이내', '아무나', '["***밥숟가락 계량 ***닭볶음에 물대신 멸치다시마육수를 넣고 끓이면 감칠맛이 나서 더욱 맛있습니다. ****매운거 싫은분들은 청양고추 양 줄이거나 생략하세요"]'::jsonb, '김진옥요리가좋다', 2025-11-23 02:25:48.714657, 2025-11-23 02:25:48.714657, '{"tips": ["***밥숟가락 계량 ***닭볶음에 물대신 멸치다시마육수를 넣고 끓이면 감칠맛이 나서 더욱 맛있습니다. ****매운거 싫은분들은 청양고추 양 줄이거나 생략하세요"], "steps": ["감자는 작은크기로 3개였습니다. 토막낸 닭크기와 비슷하게 썰어서 찬물에 담궈 녹말기를 제거합니다. ***감자가 클때는 2개만 준비하세요~ ***감자대신 고구마를 준비하셔도 좋습니다~", "양파는 작은크기로 1개반을 굵게 채썰어줍니다. 대파1줄기는 굵게 썰고요~ 청양고추5개는 어슷하게 썰어줍니다.", "토막낸 닭1마리를 끓는물에 1분정도만 살짝 데친후 찬물에 헹궈 체에 받쳐줍니다.", "데친닭을 볶음팬에 넣고요~ 손질한 감자를 넣어준후... 고추장3T.고춧가루3T반.후춧가루소량.다진마늘1T.소금1/4T정도.간장3T.미림2T.올리고당2T반을 넣고 물800ml를 넣어줍니다. ***양념은 기호에 맞게 조절하세요 ***물대신 멸치다시마육수를 넣으면 훨씬 맛있습니다~", "볶음팬의 뚜껑은 덮고요~ 센불로 켠후 끓어오르면 중약불로 줄여 20분동안 끓여줍니다. 중간중간 한번씩 나무주걱으로 뒤적이고요~ 20분 경과후 준비한 양파.대파.청양고추를 넣고 5분정도만 더 끓여주면 완성입니다. ***마지막에 드셔보셔서 기호에 맞게 부족한 양념 추가하세요 ****닭볶음탕의 국물이 너무 줄어들면 물을 조금 추가하시고요~ 국물이 너무 많을때는 센불로 켜주세요"], "title": "쉽게 닭볶음탕 맛있게 만드는법 닭볶음탕 황금레시피 닭도리탕", "servings": "4인분", "cook_time": "30분 이내", "copyright": "김진옥요리가좋다", "recipe_id": "7011936", "step_tips": ["도마", "도마", "냄비", "볶음팬", null], "difficulty": "아무나", "source_url": "https://www.10000recipe.com/recipe/7011936", "ingredients": ["닭 1마리", "감자 2~3개", "양파 1~1.5개", "대파 1개", "청양고추 5개", "고추장 3T", "고춧가루 3.5T", "다진마늘 1T", "후춧가루 소량", "소금 1/4T", "간장 3T", "미림 2T", "올리고당 2T"], "ingredients_struct": [{"qty": "1마리", "desc": null, "name": "닭"}, {"qty": "2~3개", "desc": null, "name": "감자"}, {"qty": "1~1.5개", "desc": null, "name": "양파"}, {"qty": "1개", "desc": null, "name": "대파"}, {"qty": "5개", "desc": null, "name": "청양고추"}, {"qty": "3T", "desc": null, "name": "고추장"}, {"qty": "3.5T", "desc": null, "name": "고춧가루"}, {"qty": "1T", "desc": null, "name": "다진마늘"}, {"qty": "소량", "desc": null, "name": "후춧가루"}, {"qty": "1/4T", "desc": null, "name": "소금"}, {"qty": "3T", "desc": null, "name": "간장"}, {"qty": "2T", "desc": null, "name": "미림"}, {"qty": "2T", "desc": null, "name": "올리고당"}]}'::jsonb);
INSERT INTO recipes (id, recipe_id, source_url, title, servings, cook_time, difficulty, tips, copyright, created_at, updated_at, raw_data) VALUES (319, '6872492', 'https://www.10000recipe.com/recipe/6872492', '우엉조림맛있게하는법 황금레시피 요거지요!', '4인분', '60분 이내', '초급', '["식초물에 담구는 과정은 꼭 하셔야해요 안그러면 떫어서 먹을수 없답니다"]'::jsonb, '엘린84', 2025-11-23 00:33:47.806730, 2025-11-23 01:31:26.252843, '{"tips": ["식초물에 담구는 과정은 꼭 하셔야해요 안그러면 떫어서 먹을수 없답니다"], "steps": ["우엉은 너무 굵거나 너무 얇은 우엉은 맛이없다고해요. 굵기가 적당하고 단단한 것으로 고르고 겉면에 흠이없고 매끈한 것이 좋다고해요. 우엉 고르실때 참고하시면 좋을듯해요~", "우엉은 먹기좋은 크기로 잘라서 얇게 채썰어 주세요.", "그 다음은 우엉의 떫은맛을 제거해줘야 하는데요. 물에 식초 1큰술을 넣어서 식초물을 만들어주시고 채썰어 놓은 우엉을 넣어서 조물조물 씻어주세요", "그리고 찬물에 헹궈서 준비해주세요", "냄비에 물 2컵반, 간장 5큰술, 설탕 3큰술, 참기름 1큰술을 넣어주세요. 물엿은 조금 끓이다가 넣어줄꺼랍니다.", "그리고 채썰어둔 우엉을 넣고 센불로 끓여주세요.", "센불로 끓이다가 끓어오르기 시작하면 중불로 줄여서 끓여주세요.", "물엿은 우엉의 색이 갈색으로 변하면 1큰술 넣고 약불로 줄여서 졸여주시면 된답니다.", "그리고 저는 마지막으로 통깨를 솔솔 뿌려서 마무리 해줬는데요. 통깨가 없으시다면 안넣어주셔도 상관없어요~"], "title": "우엉조림맛있게하는법 황금레시피 요거지요!", "servings": "4인분", "cook_time": "60분 이내", "copyright": "엘린84", "recipe_id": "6872492", "step_tips": [null, null, null, null, null, null, null, null, null], "difficulty": "초급", "source_url": "https://www.10000recipe.com/recipe/6872492", "ingredients": ["우엉 2뿌리", "식초 1큰술", "물 2.5컵", "간장 5큰술", "설탕 3큰술", "물엿 1큰술", "참기름 1큰술", "통깨 약간"], "ingredients_struct": [{"qty": "2뿌리", "desc": null, "name": "우엉"}, {"qty": "1큰술", "desc": null, "name": "식초"}, {"qty": "2.5컵", "desc": null, "name": "물"}, {"qty": "5큰술", "desc": null, "name": "간장"}, {"qty": "3큰술", "desc": null, "name": "설탕"}, {"qty": "1큰술", "desc": null, "name": "물엿"}, {"qty": "1큰술", "desc": null, "name": "참기름"}, {"qty": "약간", "desc": null, "name": "통깨"}]}'::jsonb);
INSERT INTO recipes (id, recipe_id, source_url, title, servings, cook_time, difficulty, tips, copyright, created_at, updated_at, raw_data) VALUES (320, '6873683', 'https://www.10000recipe.com/recipe/6873683', '엄마의 레시피, 소고기 미역국 끓이는 법', '4인분', '60분 이내', '초급', '["미역국 끓이는 법 핵심 정리 1. 쌀뜨물 혹은 미역 불린 물 사용하기 2. 물은 한 번에 넣지 않고 2차례 나눠 넣기"]'::jsonb, '베리츄', 2025-11-23 00:35:37.031646, 2025-11-23 01:31:26.259613, '{"tips": ["미역국 끓이는 법 핵심 정리 1. 쌀뜨물 혹은 미역 불린 물 사용하기 2. 물은 한 번에 넣지 않고 2차례 나눠 넣기"], "steps": ["키친타올을 이용해 소고기 핏물을 닦아주세요.", "미역은 물 500ml(약 2.5컵)에 10분간 불려주세요.", "불린 미역은 가위를 이용해 먹기 좋은 크기로 잘라주세요.", "미역은 체를 이용해 건져주세요. 이때 미역 불린 물은 버리지 않고 미역국 끓일 때 물 대신 사용해주세요.", "중불로 달군 냄비에 참기름 1큰술을 두른 뒤 다진마늘 1큰술과 소고기를 넣고 볶아주세요.", "소고기 겉면이 절반 정도 익을 때쯤 국간장 1큰술을 넣어 볶아주세요.", "미역을 넣고 푸른색을 띨 때까지 달달 볶아주세요.", "쌀뜨물 혹은 미역 불린 물 400mL(약 2컵)를 붓고 강불로 올려주세요.", "국물이 끓기 시작하면 물 1L(약 5컵)를 넣어주세요. 다시 끓어오르면 중약불로 줄인 뒤 15분간 끓여주세요.", "국간장 1큰술을 넣고 부족한 간은 소금으로 더해주세요. 엄마 손맛 가득한 미역국 완성입니다."], "title": "엄마의 레시피, 소고기 미역국 끓이는 법", "servings": "4인분", "cook_time": "60분 이내", "copyright": "베리츄", "recipe_id": "6873683", "step_tips": [null, null, null, null, null, null, null, null, null, null], "difficulty": "초급", "source_url": "https://www.10000recipe.com/recipe/6873683", "ingredients": ["소고기 국거리용 180g", "미역 20g 1줌", "쌀뜨물 혹은 물 / 종이컵 7컵 1.4L", "다진마늘 1큰술", "참기름 1큰술", "국간장 2큰술", "소금 약간"], "ingredients_struct": [{"qty": "180g", "desc": null, "name": "소고기 국거리용"}, {"qty": "1줌", "desc": null, "name": "미역 20g"}, {"qty": "1.4L", "desc": null, "name": "쌀뜨물 혹은 물 / 종이컵 7컵"}, {"qty": "1큰술", "desc": null, "name": "다진마늘"}, {"qty": "1큰술", "desc": null, "name": "참기름"}, {"qty": "2큰술", "desc": null, "name": "국간장"}, {"qty": "약간", "desc": null, "name": "소금"}]}'::jsonb);
INSERT INTO recipes (id, recipe_id, source_url, title, servings, cook_time, difficulty, tips, copyright, created_at, updated_at, raw_data) VALUES (321, '6873935', 'https://www.10000recipe.com/recipe/6873935', '백종원 감자탕 레시피, 생각보다 너무 쉽고 맛있어요', '3인분', '2시간 이상', '초급', '["돼지등뼈는 푹 익혀야 살이 잘 발라지니깐 오랜시간동안 푹 끓여주시는게 좋답니다"]'::jsonb, '엘린84', 2025-11-23 00:37:37.604737, 2025-11-23 01:31:26.267725, '{"tips": ["돼지등뼈는 푹 익혀야 살이 잘 발라지니깐 오랜시간동안 푹 끓여주시는게 좋답니다"], "steps": ["돼지등뼈는 핏물을 어느정도 제거해주어야 하는데요 물안에 푹 담궈놓고 두번정도 물갈이 해주고 2시간정도 담궈놨어요", "핏물이 어느정도 제거된다음 한번 팔팔 끓여주어야해요 끓는물에 등뼈를 넣어서 한번 푹 삶아주세요", "무청도 한팩사왔는데 양이 많아서 반정도만 사용했어요 팩에 들어있는 무청은 한번 씻어주고 살짝 잘라주었어요", "감자도 먹기 좋게 잘라서 준비해주었어요", "어느정도 삶아낸 등뼈는 고기만 따로 건져내주시구요", "등뼈를 냄비에 넣고 잠길정도로 물을 넣어주었어요", "그리고 감자를 넣어주고 나머지 양념을 바로 넣어주세요 된장 1큰술, 고추장 1큰술, 다진마늘 1큰술, 고춧가루 3큰술, 국간장 1/2컵, 액젓 3큰술 을 먼저 넣어주었구요", "대파도 큼직하게 잘라서 넣어주고", "무청도 위쪽에 수북이 얹어주었어요", "그리고 들깨가루도 넉넉히 5큰술 정도 넣어주고 팔팔 끓여주세요 백종원님이 이 들깨가루가 충분히 들어가야 밖에서 사먹는 감자탕맛이 난다고 하시더라구요 ㅎㅎ", "팔팔 끓이는 중!! 간은 보시면서 쎄다싶으시면 물을 더 넣어주시면 되요", "마지막에 깻잎도 좀 넣어주고 마무리 ~"], "title": "백종원 감자탕 레시피, 생각보다 너무 쉽고 맛있어요", "servings": "3인분", "cook_time": "2시간 이상", "copyright": "엘린84", "recipe_id": "6873935", "step_tips": [null, null, null, null, null, null, null, null, null, null, null, null], "difficulty": "초급", "source_url": "https://www.10000recipe.com/recipe/6873935", "ingredients": ["돼지등뼈 1.3kg", "감자 2개", "무청 1줌", "대파 1대", "깻잎 약간", "물 적당량", "고추장 1큰술", "된장 1큰술", "고춧가루 3큰술", "다진마늘 1큰술", "국간장 1/2컵", "액젓 3큰술", "들깨가루 4~5큰술"], "ingredients_struct": [{"qty": "1.3kg", "desc": null, "name": "돼지등뼈"}, {"qty": "2개", "desc": null, "name": "감자"}, {"qty": "1줌", "desc": null, "name": "무청"}, {"qty": "1대", "desc": null, "name": "대파"}, {"qty": "약간", "desc": null, "name": "깻잎"}, {"qty": "적당량", "desc": null, "name": "물"}, {"qty": "1큰술", "desc": null, "name": "고추장"}, {"qty": "1큰술", "desc": null, "name": "된장"}, {"qty": "3큰술", "desc": null, "name": "고춧가루"}, {"qty": "1큰술", "desc": null, "name": "다진마늘"}, {"qty": "1/2컵", "desc": null, "name": "국간장"}, {"qty": "3큰술", "desc": null, "name": "액젓"}, {"qty": "4~5큰술", "desc": null, "name": "들깨가루"}]}'::jsonb);
INSERT INTO recipes (id, recipe_id, source_url, title, servings, cook_time, difficulty, tips, copyright, created_at, updated_at, raw_data) VALUES (322, '6876357', 'https://www.10000recipe.com/recipe/6876357', '닭볶음탕 진짜진짜 황금레시피 알려 드려요~~^^', '3인분', '60분 이내', '초급', '["닭한마리 기준 800g 정도 생각 하시고 두마리를 하실때는 기준양의 1.5배 정도 넣으시면 될것같아요 예전에 해먹었던 계란말이와 닭볶음탕 사진도 있어서 올려요~~~~~ 그리고 간장은 원래 제 레시피대로 하자면 11큰술인데 싱겁게 드시는분들은 취향껏 조절 하시길요 꼭요! 저의 다른 요리가 궁금 하시다면 아래 유튜브채널주소를 클릭하시고 유튜브채널로 놀러오셔요 감사합니다^^"]'::jsonb, '주부9단요리톡톡', 2025-11-23 00:39:53.513347, 2025-11-23 01:31:26.275852, '{"tips": ["닭한마리 기준 800g 정도 생각 하시고 두마리를 하실때는 기준양의 1.5배 정도 넣으시면 될것같아요 예전에 해먹었던 계란말이와 닭볶음탕 사진도 있어서 올려요~~~~~ 그리고 간장은 원래 제 레시피대로 하자면 11큰술인데 싱겁게 드시는분들은 취향껏 조절 하시길요 꼭요! 저의 다른 요리가 궁금 하시다면 아래 유튜브채널주소를 클릭하시고 유튜브채널로 놀러오셔요 감사합니다^^"], "steps": ["닭 한마리를 준비 합니다 저희집은 가족이 5명이라 두마리를 준비했어요 대식가거든요 ㅎㅎ", "당면을 물에 불려 줍니다", "닭을 깨끗이 씻어 손질 해 줍니다", "닭 사이사이 붙어있는 기름을 제거해주면 좋아요", "잡내를 없애기 위해 우유에 30분정도 담가 둡니다", "지금부터 이부분은 해도되고 건너 뛰어도 되는 과정 인데요 닭을 한번후루룩 끓여 줍니다", "닭끓인 물을 버리고 차가운물로 헹궈줍니다 이부분에서 제가 두가지를 해봤는데요 1.닭을 우유에 담갔다가 씻은후 삶지않고 조리한경우 2.닭을우유에 담갔다가 삶아서 조리한 경우 한번 삶아서 육수를 버리고난 닭볶음탕은 깊은맛이 없더라구요", "고기를 냄비에두고 닭한마리기준 간장9~11 고추장4 고춧가루2 양파갈은거1/2 마늘5알 요리당6 청주1 후추약간 액젓1", "이렇게 양념소스를 만들어 주세요 요거 진짜 맛집 하고 거의 흡사한 맛이에요 맛집은 낙지나 새우를 첨가해 주기도 하죠!", "냄비에 양념장과 육수600ml를 넣고 한소끔 끓여 줍니다 물대신 육수를 넣어주시면 좀더 감칠맛이 나는데 물로하셔도 맛있어요 육수는 물로 대체 가능", "그사이에 야채손질을 해주시는데요 감자는 모서리를 깎아서 넣는게 좋아요 그렇지않으면 감자가 으깨져서 국물이 텁텁해 질수가 있거든요 깎고 남은 감자는 된장찌개에 넣으시면 좋아요", "한소끔 끓을때 감자를 넣어 뚜껑을 덮고 중불에 30분정도 끓여 주세요", "대파 양파 당근 고추를 적당한 크기로 잘라 준비해주세요", "이제 어느정도 닭과 감자가익었네요", "나머지 야채를 넣고", "한번더 끓입니다 국물이 넉넉한게 좋으신 분들은 육수를 조금더 추가하고 양념도 살짝 추가 하시면 됩니다", "아까 준비해둔 당면을 살짝 삶아 첨가해주세요 삶지않고 충분히 불려서 넣으셔도 됩니다 불릴시간이 없으시면 삶아서 넣어주세요 당면은 안넣으셔도 상관 없어요 참기름 후추(선택가능)도 살짝 첨가해주심 끝"], "title": "닭볶음탕 진짜진짜 황금레시피 알려 드려요~~^^", "servings": "3인분", "cook_time": "60분 이내", "copyright": "주부9단요리톡톡", "recipe_id": "6876357", "step_tips": [null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null], "difficulty": "초급", "source_url": "https://www.10000recipe.com/recipe/6876357", "ingredients": ["닭 1마리", "당면", "감자 3개", "당근 1/2쪽", "양파 1~1.5개", "고추 3개", "대파 1대", "다진마늘 5쪽", "우유 200ml", "멸치", "다시마", "표고버섯", "간장 8~11큰술", "고추장 4큰술", "고춧가루 2큰술", "요리당 6큰술", "간양파 1/2개", "청주 1큰술", "물 400~600ml", "후추 약간", "참기름 약간", "액젓 1큰술"], "ingredients_struct": [{"qty": "1마리", "desc": null, "name": "닭"}, {"qty": "", "desc": null, "name": "당면"}, {"qty": "3개", "desc": null, "name": "감자"}, {"qty": "1/2쪽", "desc": null, "name": "당근"}, {"qty": "1~1.5개", "desc": null, "name": "양파"}, {"qty": "3개", "desc": null, "name": "고추"}, {"qty": "1대", "desc": null, "name": "대파"}, {"qty": "5쪽", "desc": null, "name": "다진마늘"}, {"qty": "200ml", "desc": null, "name": "우유"}, {"qty": "", "desc": null, "name": "멸치"}, {"qty": "", "desc": null, "name": "다시마"}, {"qty": "", "desc": null, "name": "표고버섯"}, {"qty": "8~11큰술", "desc": null, "name": "간장"}, {"qty": "4큰술", "desc": null, "name": "고추장"}, {"qty": "2큰술", "desc": null, "name": "고춧가루"}, {"qty": "6큰술", "desc": null, "name": "요리당"}, {"qty": "1/2개", "desc": null, "name": "간양파"}, {"qty": "1큰술", "desc": null, "name": "청주"}, {"qty": "400~600ml", "desc": null, "name": "물"}, {"qty": "약간", "desc": null, "name": "후추"}, {"qty": "약간", "desc": null, "name": "참기름"}, {"qty": "1큰술", "desc": null, "name": "액젓"}]}'::jsonb);
INSERT INTO recipes (id, recipe_id, source_url, title, servings, cook_time, difficulty, tips, copyright, created_at, updated_at, raw_data) VALUES (426, '7032089', 'https://www.10000recipe.com/recipe/7032089', '알배기배추 겉절이 김치 만드는법', '2인분', '90분 이내', '중급', '["-여름 배추가 싱겁고 단맛이 적으니 단맛을 보충하기 위해 배즙음료와 설탕을 약간 추가하고 꽃게 액젓과 새우젓 까나리액젓등 양념 맛을 더 신경 써서 담아요."]'::jsonb, 'Tina소울푸드', 2025-11-23 02:27:36.794257, 2025-11-23 02:27:36.794257, '{"tips": ["-여름 배추가 싱겁고 단맛이 적으니 단맛을 보충하기 위해 배즙음료와 설탕을 약간 추가하고 꽃게 액젓과 새우젓 까나리액젓등 양념 맛을 더 신경 써서 담아요."], "steps": ["알배기 배추 밑동을 잘라 내고 잎을 분리해 놓아요.", "알배기 배추를 물에 담가 한번 씻어 체에 건져 주세요.", "물 2리터에 굵은 천일염 반컵을 녹여 주세요.", "알배기 배추에 소금물을 부어 주세요. 위에 굵은 소금을 약간 더 뿌려 주세요. 배추를 1시간 정도 절이면서 중간에 한 두번 정도 뒤집어 고루 절여 주세요.", "찹쌀가루나 밀가루로 풀을 쑤어 주거나 밥이나 죽을 이용해도 좋아요. 저는 이번엔 냉동실에 보관했던 죽이 있어서 죽을 한번 끓여서 식혀 줬어요.", "배추는 물에 가볍게 헹궈 주세요.", "배추를 바로 건져 체에 받쳐 물기를 빼주세요.", "믹서에 고추가루를 제외한 다른 김치 양념을 넣고 갈아 주세요.", "갈아 놓은 김치 양념에 식혀 놓은 풀과 고추가루를 5-6스푼을 넣어 섞어 주세요. 고추가루를 미리 불려 주면 색이 더 고와져요.", "대파를 송송 썰어 줬어요. 쪽파를 활용해도 되고 없으면 대파도 괜찮아요.", "양파 반개를 채썰어 주세요.", "배추를 큰 용기에 담고 채썰어 놓은 양파와 대파를 넣어 주세요.", "양념을 넣고 잘 버무려 주세요.", "날씨가 더우니 한나절 정도만 실온에 놔뒀다가 냉장고에 보관해요."], "title": "알배기배추 겉절이 김치 만드는법", "servings": "2인분", "cook_time": "90분 이내", "copyright": "Tina소울푸드", "recipe_id": "7032089", "step_tips": ["도마", "믹싱볼", "볼", null, "냄비", null, null, "믹서기", null, null, null, null, null, null], "difficulty": "중급", "source_url": "https://www.10000recipe.com/recipe/7032089", "ingredients": ["알배기배추 작은것 2포기", "대파 1대", "양파 1/2개", "고추가루 5-6스푼", "마늘 7톨", "생강 1/2톨", "까나리액젓 2큰술", "꽃게액젓 1큰술", "새우젓 1스푼", "배즙음료 3큰술", "설탕 1스푼", "찹쌀가루 또는 밀가루 2스푼", "물 200ml", "물 2L", "천일염 1/2컵"], "ingredients_struct": [{"qty": "2포기", "desc": null, "name": "알배기배추 작은것"}, {"qty": "1대", "desc": null, "name": "대파"}, {"qty": "1/2개", "desc": null, "name": "양파"}, {"qty": "5-6스푼", "desc": null, "name": "고추가루"}, {"qty": "7톨", "desc": null, "name": "마늘"}, {"qty": "1/2톨", "desc": null, "name": "생강"}, {"qty": "2큰술", "desc": null, "name": "까나리액젓"}, {"qty": "1큰술", "desc": null, "name": "꽃게액젓"}, {"qty": "1스푼", "desc": null, "name": "새우젓"}, {"qty": "3큰술", "desc": null, "name": "배즙음료"}, {"qty": "1스푼", "desc": null, "name": "설탕"}, {"qty": "2스푼", "desc": null, "name": "찹쌀가루 또는 밀가루"}, {"qty": "200ml", "desc": null, "name": "물"}, {"qty": "2L", "desc": null, "name": "물"}, {"qty": "1/2컵", "desc": null, "name": "천일염"}]}'::jsonb);
INSERT INTO recipes (id, recipe_id, source_url, title, servings, cook_time, difficulty, tips, copyright, created_at, updated_at, raw_data) VALUES (324, '6877896', 'https://www.10000recipe.com/recipe/6877896', '볶음김치 황금레시피 김치볶음 밑반찬', '2인분', '10분 이내', '아무나', '["나만의 김치볶음 황금레시피 볶음김치는 반찬으로 먹다가 술안주 없을 땐 두부김치로 만들어드세요. 차가운 두부는 끓는 물에 살짝 데쳐 뜨끈하게 먹으면 더욱더 맛있답니다"]'::jsonb, '베리츄', 2025-11-23 00:44:00.845874, 2025-11-23 01:34:44.838447, '{"tips": ["나만의 김치볶음 황금레시피 볶음김치는 반찬으로 먹다가 술안주 없을 땐 두부김치로 만들어드세요. 차가운 두부는 끓는 물에 살짝 데쳐 뜨끈하게 먹으면 더욱더 맛있답니다"], "steps": ["익은 김치의 양념을 가볍게 털어낸 뒤 먹기 좋은 크기로 썰어주세요.", "신김치에 김칫국물 1과 1/2큰술, 설탕 2큰술을 넣고 고루 버무려주세요.", "대파는 어슷 썰기 해주고 양파는 0.3cm 두께로 썰어 준비해주세요.", "달군 팬에 식용유 2큰술을 두르고 김치를 1분간 볶아주세요.", "아래의 양념을 넣고 잘 섞이도록 저어가며 볶아주세요.", "양념 국물의 양이 1/4정도로 졸아들 때까지 충분히 볶아준 뒤 썰어둔 채소를 넣어주세요.", "양파가 익을 때까지 볶아주면 볶음김치 완성이에요. 기호에 따라 통깨도 솔솔 뿌려주세요."], "title": "볶음김치 황금레시피 김치볶음 밑반찬", "servings": "2인분", "cook_time": "10분 이내", "copyright": "베리츄", "recipe_id": "6877896", "step_tips": [null, null, null, null, null, null, null], "difficulty": "아무나", "source_url": "https://www.10000recipe.com/recipe/6877896", "ingredients": ["익은김치 3컵 400g", "김칫국물 1.5큰술", "설탕 2큰술", "양파(중) 2/3개", "대파(흰부분) 20cm", "식용유 2큰술", "참기름 1/3큰술", "통깨 1큰술", "간장 2/3큰술", "올리고당 1.5큰술", "고춧가루 1.5큰술", "맛술 1.5큰술", "참기름 1큰술"], "ingredients_struct": [{"qty": "400g", "desc": null, "name": "익은김치 3컵"}, {"qty": "1.5큰술", "desc": null, "name": "김칫국물"}, {"qty": "2큰술", "desc": null, "name": "설탕"}, {"qty": "2/3개", "desc": null, "name": "양파(중)"}, {"qty": "20cm", "desc": null, "name": "대파(흰부분)"}, {"qty": "2큰술", "desc": null, "name": "식용유"}, {"qty": "1/3큰술", "desc": null, "name": "참기름"}, {"qty": "1큰술", "desc": null, "name": "통깨"}, {"qty": "2/3큰술", "desc": null, "name": "간장"}, {"qty": "1.5큰술", "desc": null, "name": "올리고당"}, {"qty": "1.5큰술", "desc": null, "name": "고춧가루"}, {"qty": "1.5큰술", "desc": null, "name": "맛술"}, {"qty": "1큰술", "desc": null, "name": "참기름"}, {"qty": "1큰술", "desc": null, "name": "통깨"}]}'::jsonb);
INSERT INTO recipes (id, recipe_id, source_url, title, servings, cook_time, difficulty, tips, copyright, created_at, updated_at, raw_data) VALUES (325, '6879215', 'https://www.10000recipe.com/recipe/6879215', '소불고기 황금 양념 레시피', '2인분', '30분 이내', '고급', '[]'::jsonb, '스와티라마', 2025-11-23 00:45:48.395174, 2025-11-23 01:34:44.845028, '{"tips": [], "steps": ["소고기 등심에 설탕 4스푼, 물엿 2스푼을 넣어요.", "거기에 매실액(저는 깔라마시 꿀로 대체) 다진마늘 3스푼, 간장 12스푼 후추 약간을 넣고 주물러 양념이 배게 해줍니다.", "여기에 참기름 1스푼을 넣고 주물러 30분 기다려줘요.", "기다리는 동안 야채와 버섯 손질도 샤샤샥^^", "재워 둔 고기에 야채를 모두 넣고 참기름을 2스푼 더 첨가한 뒤 섞어주고 센 불에 구우면 끝!!", "아아, 제가 했지만 너무 맛있어요 ㅠㅜ ㅎㅎㅎ 혹시라도 고기 냄새에 좀 민감하시면 청주나 맛술 한스푼 추가 추천해요~ 밥에 올려서 촵촵 정말 맛있게 먹었어요 :)"], "title": "소불고기 황금 양념 레시피", "servings": "2인분", "cook_time": "30분 이내", "copyright": "스와티라마", "recipe_id": "6879215", "step_tips": [null, null, null, null, null, null], "difficulty": "고급", "source_url": "https://www.10000recipe.com/recipe/6879215", "ingredients": ["소불고기 700g", "양파 1개", "대파 1대", "팽이버섯 1팩", "느타리버섯 1팩", "설탕 4T", "물엿 2T", "매실액 1T", "다진마늘 3T", "간장 12T", "후추 약간", "참기름 3T"], "ingredients_struct": [{"qty": "700g", "desc": null, "name": "소불고기"}, {"qty": "1개", "desc": null, "name": "양파"}, {"qty": "1대", "desc": null, "name": "대파"}, {"qty": "1팩", "desc": null, "name": "팽이버섯"}, {"qty": "1팩", "desc": null, "name": "느타리버섯"}, {"qty": "4T", "desc": null, "name": "설탕"}, {"qty": "2T", "desc": null, "name": "물엿"}, {"qty": "1T", "desc": null, "name": "매실액"}, {"qty": "3T", "desc": null, "name": "다진마늘"}, {"qty": "12T", "desc": null, "name": "간장"}, {"qty": "약간", "desc": null, "name": "후추"}, {"qty": "3T", "desc": null, "name": "참기름"}]}'::jsonb);
INSERT INTO recipes (id, recipe_id, source_url, title, servings, cook_time, difficulty, tips, copyright, created_at, updated_at, raw_data) VALUES (326, '6879533', 'https://www.10000recipe.com/recipe/6879533', '생생정보통 잡채 황금레시피 이거였네', '4인분', '30분 이내', '아무나', '["-생생정보통의 레시피가 간장 1 : 물엿 2 비율이 맞아요. 이 비율로 하실 때는 올리고당은 피해 주시고 물엿을 사용해 주세요. -단거 싫어하시는 분들은 물엿을 조금만 넣어 맛을 본 후 추가해 주시는게 좋아요."]'::jsonb, '엘린84', 2025-11-23 00:47:42.532564, 2025-11-23 01:34:44.852725, '{"tips": ["-생생정보통의 레시피가 간장 1 : 물엿 2 비율이 맞아요. 이 비율로 하실 때는 올리고당은 피해 주시고 물엿을 사용해 주세요. -단거 싫어하시는 분들은 물엿을 조금만 넣어 맛을 본 후 추가해 주시는게 좋아요."], "steps": ["목이버섯은 물에 살짝 불려서 사용할꺼예요 물에 버섯을 한줌정도 넣어서 불려주세요", "잡채용 고기에는 밑간을 살짝 했다가 볶아줄꺼예요 다진마늘, 간장, 참기름 1작은술씩 넣어주고 미림 2작은술, 후추 약간 넣어 20분정도 밑간해줬어요", "부추, 양파, 당근, 파프리카등의 야채는 먹기좋은 크기로 잘라서 준비해주세요", "당면은 끓는물에 11분 삶아주는게 맛있는 잡채 만드는 포인트예요 !", "당면이 삶아지는 동안에 부추를 제외한 나머지 야채와", "고기를 후라이팬에 따로 볶아서 준비해주세요", "당면은 11분이 지나면 바로 채에 걸러 찬물에 헹궈서 준비해주세요", "그리고 바로 당면에 양념을 입혀줄껀데요 위에서 말씀드렸다 싶이 간장과 물엿은 1:2 비율로 넣어주시면 되요", "양념이 팔팔 끓어오르기 시작하면 준비해두었던 당면을 넣어주고", "카놀라유를 4큰술 정도 둘러주세요 ~ 그래야 당면끼리 서로 달라붙지 않고 불지 않는다고 하더라구요 ~", "그리고 센불로 양념이 졸아들때까지 저어가면서 당면에 색을 곱게 입혀주시면 된답니다 ~", "당면의 양념이 어느정도 졸아들면 큰 양푼이나 그릇에 넣고 한김 식혀준다음 미리 준비해두었던 야채와 고기를 전부 넣고 골고루 맛있게 비벼주시면 된답니다 ~!!", "저희 신랑은 당면을 그리 좋아하진 않아서 저는 당면보다 야채랑 고기를 더 많이 넣어줬는데요 이렇게 하니 훨씬 맛있게 잘 먹는것 같더라구요 ~"], "title": "생생정보통 잡채 황금레시피 이거였네", "servings": "4인분", "cook_time": "30분 이내", "copyright": "엘린84", "recipe_id": "6879533", "step_tips": [null, null, null, null, null, null, null, null, null, null, null, null, null], "difficulty": "아무나", "source_url": "https://www.10000recipe.com/recipe/6879533", "ingredients": ["당면 1.5줌", "당근 약간", "파프리카 약간", "목이버섯 1줌", "양파 1/2개", "부추 약간", "잡채용 돼지고기 1줌", "다진마늘 1작은술", "진간장 1작은술", "참기름 1작은술", "미림 맛술 2작은술", "후추 약간", "간장 10큰술", "물엿 평평하게 깍아서 20큰술"], "ingredients_struct": [{"qty": "1.5줌", "desc": null, "name": "당면"}, {"qty": "약간", "desc": null, "name": "당근"}, {"qty": "약간", "desc": null, "name": "파프리카"}, {"qty": "1줌", "desc": null, "name": "목이버섯"}, {"qty": "1/2개", "desc": null, "name": "양파"}, {"qty": "약간", "desc": null, "name": "부추"}, {"qty": "1줌", "desc": null, "name": "잡채용 돼지고기"}, {"qty": "1작은술", "desc": null, "name": "다진마늘"}, {"qty": "1작은술", "desc": null, "name": "진간장"}, {"qty": "1작은술", "desc": null, "name": "참기름"}, {"qty": "2작은술", "desc": null, "name": "미림 맛술"}, {"qty": "약간", "desc": null, "name": "후추"}, {"qty": "10큰술", "desc": null, "name": "간장"}, {"qty": "20큰술", "desc": null, "name": "물엿 평평하게 깍아서"}]}'::jsonb);
INSERT INTO recipes (id, recipe_id, source_url, title, servings, cook_time, difficulty, tips, copyright, created_at, updated_at, raw_data) VALUES (327, '6880798', 'https://www.10000recipe.com/recipe/6880798', '안동찜닭 황금레시피 찜닭 레시피 중에서 최고!', '3인분', '60분 이내', '중급', '["1.닭을 끓이기전에 칼집을 내면 양념이 더 잘 스며들어요. 2. 닭 잡내제거는 필수입니다.(쌀뜨물 or 우유, 한번 끓여내기,미림 또는 소주 넣기 등) 3. 캐러멜소스가 없으시다면 찜닭만의 진한 국물색을위해 인스턴스커피1개는 꼭 넣어주세요! 4. 당면은 마지막에 2분30초만 끓이기!(바로 드실경우) 5. 바로드시는게 아니라면 당면은 꼭! 먹기전에 넣어주세요. (당면이 국물을 다 흡수해버린답니다.)"]'::jsonb, '미소앨범by하준맘', 2025-11-23 00:49:49.997525, 2025-11-23 01:36:35.051619, '{"tips": ["1.닭을 끓이기전에 칼집을 내면 양념이 더 잘 스며들어요. 2. 닭 잡내제거는 필수입니다.(쌀뜨물 or 우유, 한번 끓여내기,미림 또는 소주 넣기 등) 3. 캐러멜소스가 없으시다면 찜닭만의 진한 국물색을위해 인스턴스커피1개는 꼭 넣어주세요! 4. 당면은 마지막에 2분30초만 끓이기!(바로 드실경우) 5. 바로드시는게 아니라면 당면은 꼭! 먹기전에 넣어주세요. (당면이 국물을 다 흡수해버린답니다.)"], "steps": ["[당면 불리기] 큰 볼에 당면 한줌 분량을 넣고 당면이 잠길 정도의 찬물을 넣어주세요. 그냥 사용하면 억세기 때문에 약 1시간 정도 불려 주었습니다.", "1시간 정도 불려주면 부피가 늘어나는데요. 참고해주셔서 취향에 따라 가감해 주세요.", "< 야채 손질 > 당근 1/3개는 둥글 납작한 모양으로 양파 1개는 듦성 큼직하게 오이 1/3개는 어슷썰기로 대파 1/2개는 손가락 길이 정도로 큼직하게 썰어서 준비해주세요.", "[닭 잡내 제거 1차] 손질되고 토막 난 7호 닭 1마리는 흐르는 물로 1차 세척을 해주세요. 큰 볼에 닭이 모두 잠길 정도의 쌀뜨물을 담고 약 30분 동안 잡내를 제거해주시고요.", "[닭 잡내 제거 2차] 1차 잡내 제거를 마친 닭은 흐르는 찬물로 한번 헹궈 주세요. 냄비에 닭을 모두 넣고 물과 미림 3스푼 혹은 소주 3스푼을 넣고 강불로 끓여주세요.", "보글보글 끓기 시작하면 닭은 바로 건져내 주시면 된답니다. \" 기름기 제거와 잡내는 확실히 잡혔겠죠! \"", "[안동찜닭 소스 만들기] 조금 전 사용했던 냄비에 물을 모두 버리고 종이컵 4컵 분량의 물과 닭을 넣어주세요.", "이어서 베이스 소스인 진간장 13스푼을 넣어주시고요.", "황금레시피 필살기인 커피 1스푼을 넣고 10분 정도 강불에서 끓여주세요. \" 커피는 잔류 잡내 제거에 큰 도움을 주며 색상때문에 넣는 캐러멜소스를 안넣어도 찜닭의 진한 국물 색상을 만들어주기도 한답니다\" 저는 오늘 두가지 다 준비되어있어 다 넣었어요!", "10분 후 설탕 3스푼 넣고 살살 저어 주시며 1분 동안 끓여주세요.", "물엿6스푼 도 함께 넣어주세요.", "깔끔한 국물맛을 위해 올라오는 거품은 걷어내 주세요.", "[야채 넣고 끓이기] \" 이제 야채를 넣어줄 차례! \" 고추와 대파를 제외하고 손질해 놓은 감자, 당근, 오이, 양파를 넣고 으깨지지 않게 살살 저어 주세요.", "다진 마늘 3스푼, 후추 톡 3번,캐러멜 소스 1스푼을 넣고 뚜껑을 닫고 10분간 강불로 끓여주세요.", "후추 톡! 3번", "캐러멜소스1스푼", "손질해 놓은 대파 1/2개, 홍고추 1개 불려놓은 당면 한 줌을 모두 넣어주세요. 그리고 정확히 2분 30초만 끓여주시는 게 최적의 당면 식감을 만드는 포인트라고 하네요.", "보는 것만으로도 그때의 맛이 생각나는 식욕 돋게 하는! 찜닭 완성입니다. ^_^", "일단 거두절미하고 닭다리 맛부터 볼게요! 적당히 탄력 있는 닭살은 입에 넣고 후릅! 하면 살과 뼈가 분리돼요. 평소 안동찜닭을 좋아하시는 친정 아빠는 맛을 보시더니 파는 것보다 훨씬 맛있다고 A 뿔뿔 뿔! 이다를 외쳐주셨답니다. \" 엄청 칭찬해 주셨어요 우헤헤헤 험험..\"", "찜닭 맛이 거기서 거기일 수도 있겠지만 어른, 아이 할 것 없이 모두 드시기도 좋고적당한 짭조름한 맛이 어우러진 꽤 괜찮은 레시피였답니다."], "title": "안동찜닭 황금레시피 찜닭 레시피 중에서 최고!", "servings": "3인분", "cook_time": "60분 이내", "copyright": "미소앨범by하준맘", "recipe_id": "6880798", "step_tips": ["큰볼", null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null], "difficulty": "중급", "source_url": "https://www.10000recipe.com/recipe/6880798", "ingredients": ["손질된 닭 한마리 7호", "당면 1줌", "감자 큰 거 2개", "양파 1개", "당근 1/3개", "오이 1/3개", "대파 1/2개", "청고추 1개", "물 4종이컵", "진간장 13스푼", "물엿 5스푼", "설탕 3스푼", "캐러멜소스 생략가능 1스푼", "다진마늘 3스푼", "후춧가루 톡 3번", "인스턴트커피 1봉", "미림 혹은 소주 3스푼", "쌀뜨물 또는 우유"], "ingredients_struct": [{"qty": "7호", "desc": null, "name": "손질된 닭 한마리"}, {"qty": "1줌", "desc": null, "name": "당면"}, {"qty": "2개", "desc": null, "name": "감자 큰 거"}, {"qty": "1개", "desc": null, "name": "양파"}, {"qty": "1/3개", "desc": null, "name": "당근"}, {"qty": "1/3개", "desc": null, "name": "오이"}, {"qty": "1/2개", "desc": null, "name": "대파"}, {"qty": "1개", "desc": null, "name": "청고추"}, {"qty": "4종이컵", "desc": null, "name": "물"}, {"qty": "13스푼", "desc": null, "name": "진간장"}, {"qty": "5스푼", "desc": null, "name": "물엿"}, {"qty": "3스푼", "desc": null, "name": "설탕"}, {"qty": "1스푼", "desc": null, "name": "캐러멜소스 생략가능"}, {"qty": "3스푼", "desc": null, "name": "다진마늘"}, {"qty": "3번", "desc": null, "name": "후춧가루 톡"}, {"qty": "1봉", "desc": null, "name": "인스턴트커피"}, {"qty": "3스푼", "desc": null, "name": "미림 혹은 소주"}, {"qty": "", "desc": null, "name": "쌀뜨물 또는 우유"}]}'::jsonb);
INSERT INTO recipes (id, recipe_id, source_url, title, servings, cook_time, difficulty, tips, copyright, created_at, updated_at, raw_data) VALUES (328, '6881450', 'https://www.10000recipe.com/recipe/6881450', '소갈비찜 만드는 법 - 생일상차림 메뉴', '4인분', '2시간 이상', '아무나', '[]'::jsonb, '시크제이맘', 2025-11-23 00:52:04.965414, 2025-11-23 01:38:37.099647, '{"tips": [], "steps": ["갈비는 찬물에 3~4시간 정도 담가 핏물을 빼주세요. 중간에 물을 3~4번 정도 갈아주세요. 탄산수, 콜라를 이용해 핏물을 제거하면 시간을 단축시킬 수 있답니다. 참고하세요. 그리고 저는 호주산 소갈비를 이용했어요. 살도 많고 가격도 착해서 이용하는데 맛도 괜찮더라고요 ^^", "냄비에 갈비를 삶아줄 물을 담고 끓여주세요. 팔팔 끓어오르면 핏물을 뺀 갈비를 넣고 3분 정도 데쳐주세요. 데치는 과정을 통해 기름기와 잡내를 제거할 수 있답니다.", "데친 갈비는 찬물에 헹궈 물기를 빼주세요.", "믹서기에 양파 1/2, 배 1/2를 넣고 갈아주세요. 갈아놓은 양파, 배를 그릇에 담고 나머지 양념재료 간장 10, 굴 소스 1, 맛술 5, 청주 4, 설탕 2, 올리고 당 2, 다진 마늘 2, 다진 생강 0.3, 후춧가루 0.3, 참기름 0.5를 넣고 섞어 줍니다. 배 대신 키위를 이용하셔도 좋아요", "양념소스가 완성되면 데쳐 놓은 갈비에 부어 재워주세요. 바로 다시는 것보단 하루 정도 냉장고에 넣어 숙성 시켜주심 휠씬 맛있답니다. 아님 바로 해서 드셔도 괜찮고요.", "무, 당근은 큼직하게 썰어 동글동글하게 다듬어주고, 대파는 어슷 썰어주고 그 외 대추, 밤 등 함께 넣어도 좋아요.", "하루 숙성시킨 소갈비를 그릇에 담고 여기에 물 1컵(종이컵)을 붓고 뚜껑을 닫고 고기가 푹 익을 때까지 끓여주세요. 압력솥으로 하면 고기가 더 야 들하니 잘 익어요. 그리고 압력솥으로 하실 땐 물을 넣지 마세요. 물을 넣게 되면 맛없어요.", "고기가 익으면 뚜껑을 열고 기름을 숟가락으로 걷어내고 무, 당근을 넣어 주고 국물이 자 박해질 때까지 익혀주세요.", "마지막에 준비해 놓은 대파를 넣고 살짝 더 익혀 마무리해줍니다.", "소갈비찜 완성"], "title": "소갈비찜 만드는 법 - 생일상차림 메뉴", "servings": "4인분", "cook_time": "2시간 이상", "copyright": "시크제이맘", "recipe_id": "6881450", "step_tips": [null, null, null, null, null, null, null, null, null, null], "difficulty": "아무나", "source_url": "https://www.10000recipe.com/recipe/6881450", "ingredients": ["소갈비 800~900g", "무 두께 5cm 정도 2토막", "당근 1/2개", "대파 1대", "배 1/2개", "양파 1/2개", "다진 마늘 2스푼", "간장 10스푼", "올리고 당 2스푼", "굴 소스 1스푼", "맛술 5스푼", "청주 4스푼", "설탕 2스푼", "다진 생강 0.3스푼", "후춧가루 0.3스푼", "참기름 0.5스푼"], "ingredients_struct": [{"qty": "800~900g", "desc": null, "name": "소갈비"}, {"qty": "2토막", "desc": null, "name": "무 두께 5cm 정도"}, {"qty": "1/2개", "desc": null, "name": "당근"}, {"qty": "1대", "desc": null, "name": "대파"}, {"qty": "1/2개", "desc": null, "name": "배"}, {"qty": "1/2개", "desc": null, "name": "양파"}, {"qty": "2스푼", "desc": null, "name": "다진 마늘"}, {"qty": "10스푼", "desc": null, "name": "간장"}, {"qty": "2스푼", "desc": null, "name": "올리고 당"}, {"qty": "1스푼", "desc": null, "name": "굴 소스"}, {"qty": "5스푼", "desc": null, "name": "맛술"}, {"qty": "4스푼", "desc": null, "name": "청주"}, {"qty": "2스푼", "desc": null, "name": "설탕"}, {"qty": "0.3스푼", "desc": null, "name": "다진 생강"}, {"qty": "0.3스푼", "desc": null, "name": "후춧가루"}, {"qty": "0.5스푼", "desc": null, "name": "참기름"}]}'::jsonb);
INSERT INTO recipes (id, recipe_id, source_url, title, servings, cook_time, difficulty, tips, copyright, created_at, updated_at, raw_data) VALUES (329, '6881457', 'https://www.10000recipe.com/recipe/6881457', '바삭하고 달짝지근~ 고소한 멸치볶음! 효자밑반찬이 따로 없어요~:: 멸치주먹밥/멸치효능', '4인분', '15분 이내', '초급', '["멸치 효능 멸치는 칼슘및 인이 풍부해 뼈를 튼튼하게 해줘서 어린이 성장발육에 좋고, 갱년기여성의 골다공증예방에도 도움을 줍니다. 불포화지방산인 DHC와 EPA가 풍부해, 뇌세포의 활발한 활동을 촉진시켜줌으로 두되발달과,뇌의 활성화에 좋습니다. 따라서 기억력 및 지능향상에도 도움을 줘, 치매예방의 효과도 있습니다. 멸치의 타우린성분은 콜레스테롤의 수치를 줄여주기에 혈압조절에 큰도움을 주며, 각종 심혈관계 질환 및 성인병예방에도 효과적입니다.멸치엔, 항산화작용을 하는 베타카로틴 성분이 있어, 노화예방과 피부미용에도 도움을 줍니다. 그밖에 오메가3지방산은 심장병과 동맥경화, 성인병을 예방해 줍니다. (멸치를 먹을때 칼슘이 체내로 흡수되는 양을 늘리려면, 궁합이 좋은 버섯이나 견과류를 함께 볶아주시면 좋다는 점!)"]'::jsonb, '마이쏭', 2025-11-23 00:53:57.189188, 2025-11-23 01:38:37.176690, '{"tips": ["멸치 효능 멸치는 칼슘및 인이 풍부해 뼈를 튼튼하게 해줘서 어린이 성장발육에 좋고, 갱년기여성의 골다공증예방에도 도움을 줍니다. 불포화지방산인 DHC와 EPA가 풍부해, 뇌세포의 활발한 활동을 촉진시켜줌으로 두되발달과,뇌의 활성화에 좋습니다. 따라서 기억력 및 지능향상에도 도움을 줘, 치매예방의 효과도 있습니다. 멸치의 타우린성분은 콜레스테롤의 수치를 줄여주기에 혈압조절에 큰도움을 주며, 각종 심혈관계 질환 및 성인병예방에도 효과적입니다.멸치엔, 항산화작용을 하는 베타카로틴 성분이 있어, 노화예방과 피부미용에도 도움을 줍니다. 그밖에 오메가3지방산은 심장병과 동맥경화, 성인병을 예방해 줍니다. (멸치를 먹을때 칼슘이 체내로 흡수되는 양을 늘리려면, 궁합이 좋은 버섯이나 견과류를 함께 볶아주시면 좋다는 점!)"], "steps": ["멸치양은 요정도 준비 해 봤어요~ 시장에서 한봉지 산 양!!", "먼저, 마른팬을 달궈 기름을 두르지않고 중간불에 멸치를 휘리릭~ 볶아줍니다.타지않게 골고루 볶아주세요~! 견과류를 넣고 싶다면 요때 같이 볶아주시면되요! 비린내가 나지않게 하면서 바삭한 멸치볶음을 만드는 과정이랍니다~", "멸치가 약간 노릇~하게 될때까지 잘 볶아주시면 되요", "이렇게 한번 덖어내면 맛있는 멸치볶음이 만들어진답니다^^", "한번 덖어낸 멸치는 잠시 다른그릇에 옮겨놓고~~", "재료준비를 해 주어요~ 파는 다져서 준비 해 주고~매콤한맛을 좋아하신다면 청양고추도 송송썰어 준비 해 주시면 되요~ 멸치볶음 양념은, 분량의 간장와 올리고당, 설탕을 넣어 섞어 만들어 주어요.소주나 맛술이 있으면 한큰술 넣어줘도 좋구요~", "달군팬에 기름을 넉넉히 두르고~", "다진마늘 1큰술을 넣어 볶아줍니다. 불을 좀 줄여서 볶아야 타지 않겠죠??", "그리고 다진파도 투입! 마이쏭은 그냥 송송 썰어준 파를 투척! 파향이 잘 우러나게 볶아주세요.", "이제! 마늘과 파를 이용한 파기름에, 멸치를 넣어 함께 볶아줍니다", "멸치를 기름에 코팅시켜준다~ 생각하시구, 골고루 볶아주시면 되요~", "그 다음엔~ 소스 투척!!! 소스를 넣으면 늘러붙기도 하고 탈 수 있으니 요때 불은 off 해 두는걸로!! 소스가 골고루 묻게 잘 뒤적여준 다음!!", "오늘 멸치볶음의 하이라이트!", "마요네즈를 한큰술 듬~뿍 넣어 줍니다! 진미채볶음 할때도 그렇고~ 요 마요네즈는 신의 한수! 더 부드럽고~ 한층 고소한 맛을 느낄 수 있으실꺼에요!!", "마무으리! 로 꼬소~한 통깨 팍팍!! 뿌려주면!!!", "건강하고 맛있는 멸치볶음이 완성된답니다.", "마이쏭은 멸치볶음 만들어, 도시락메뉴로 와따! 인 멸치주먹밥을 만들어 먹기도 해요~ 가위로 잘게 썰은 멸치를 밥에 넣고, 간장, 참기름, 설탕조금, 깨소금, 김가루 넣고 조물조물~해서 동그랗게 뭉쳐~ 간단! 하게 만든 주먹밥도 참 별미랍니다!!"], "title": "바삭하고 달짝지근~ 고소한 멸치볶음! 효자밑반찬이 따로 없어요~:: 멸치주먹밥/멸치효능", "servings": "4인분", "cook_time": "15분 이내", "copyright": "마이쏭", "recipe_id": "6881457", "step_tips": [null, "프라이팬", null, null, null, null, null, null, null, null, null, null, null, null, null, null, null], "difficulty": "초급", "source_url": "https://www.10000recipe.com/recipe/6881457", "ingredients": ["멸치", "다진파 1/2뿌리", "다진마늘 1큰술", "통깨", "견과류", "간장 1.5큰술", "올리고당 4큰술", "설탕 1큰술", "마요네즈 듬뿍 1큰술", "소주 or 맛술 1큰술"], "ingredients_struct": [{"qty": "", "desc": null, "name": "멸치"}, {"qty": "1/2뿌리", "desc": null, "name": "다진파"}, {"qty": "1큰술", "desc": null, "name": "다진마늘"}, {"qty": "", "desc": null, "name": "통깨"}, {"qty": "", "desc": null, "name": "견과류"}, {"qty": "1.5큰술", "desc": null, "name": "간장"}, {"qty": "4큰술", "desc": null, "name": "올리고당"}, {"qty": "1큰술", "desc": null, "name": "설탕"}, {"qty": "1큰술", "desc": null, "name": "마요네즈 듬뿍"}, {"qty": "1큰술", "desc": null, "name": "소주 or 맛술"}]}'::jsonb);
INSERT INTO recipes (id, recipe_id, source_url, title, servings, cook_time, difficulty, tips, copyright, created_at, updated_at, raw_data) VALUES (427, '7037475', 'https://www.10000recipe.com/recipe/7037475', '실패할일 없는 김장김치양념 /절임배추20kg/ 김장김치 양념비율 황금레시피 /김장담그기', '6인분 이상', '120분 이내', '중급', '["*밥숟가락 계량입니다. *배와 사과의 양은 무게로 확인하세요.과일이 너무 많이 들어가는것도 좋지 않습니다. 제가 사용한 사과는 아주 작았습니다. *양념장은 기호에 맞게 조절해서 넣으세요. *김치양념은 넉넉한 양입니다. 이유는요 추운 날씨에는 절임배추가 배추공장에서 아무리 잘 절여서 보내도 택배로 오면서 배추가 살아서 오거든요..그래서 덜 절여진 상태로 배송이 됩니다. 그러면 김치양념이 많이 들어가게 됩니다. 날씨가 포근할때 받은 절임배추라면 김치양념이 많이 남고요 추운 날씨에 절임배추받으시면 김치양념 거의 맞을겁니다. *김치양념 남으시면 파김치,깍두기.총각김치.겉절이 담그시면 됩니다. *절임배추는 택배로 도착하면 박스채 아래위 뒤집어서 한시간~몇시간은 서늘한곳(베란다같은곳)에 보관후 꺼내세요 그래야 골고루 박스 아래위 배추가 절여진 배추맛을 느낄수 있습니다. *절임배추가 도착하는 날 문자를 받으시면 멸치다시마육수와 찹쌀풀 미리 끓여 식혀주세요 *무채를 넣고 싶지 않은분들은 무채써는 대신 무1개(1600g)을 석박지처럼 큼직하게 썰어서 소금1T반에 30분정도 절인후 살짝 헹궈서 김치양념에 버무린후 배추김치 사이사이 석박지처럼 넣어서 드시면 됩니다. *생새우는 김장철에 시장에 많이 파는데요~요즘은 인터넷으로도 많이 판매합니다. 김장김치는 생새우와 홍갓이 들어가야 시원한 맛이 납니다. 생새우 구입하셔서 남으면 소분해서 냉동보관후 1년내내 김치 담그실때 넣으면 맛있답니다. *생새우 구입이 어려운 분들은 생새우 빼시는 대신에 새우젓을 350g 넣고요~ 대신 멸치액젓을 600g으로 줄인후 양념장을 버무린후 드셔보셔서 싱거우면 소금을 추가하시면 됩니다. *김장김치는 오랫동안 물러지지 않게 숙성시키려면 최대한 공기와의 접촉을 차단시켜야합니다. 오랫동안 먹을 김치통에는 김장비닐을 씌어서 김치를 담아주거나 김장비닐에 보관하는것이 싫은 분들은 김치통에 김치를 담고 푸른겉잎을 맨위에 올려준후 밀봉하시면 됩니다."]'::jsonb, '김진옥요리가좋다', 2025-11-23 02:29:34.016596, 2025-11-23 02:29:34.016596, '{"tips": ["*밥숟가락 계량입니다. *배와 사과의 양은 무게로 확인하세요.과일이 너무 많이 들어가는것도 좋지 않습니다. 제가 사용한 사과는 아주 작았습니다. *양념장은 기호에 맞게 조절해서 넣으세요. *김치양념은 넉넉한 양입니다. 이유는요 추운 날씨에는 절임배추가 배추공장에서 아무리 잘 절여서 보내도 택배로 오면서 배추가 살아서 오거든요..그래서 덜 절여진 상태로 배송이 됩니다. 그러면 김치양념이 많이 들어가게 됩니다. 날씨가 포근할때 받은 절임배추라면 김치양념이 많이 남고요 추운 날씨에 절임배추받으시면 김치양념 거의 맞을겁니다. *김치양념 남으시면 파김치,깍두기.총각김치.겉절이 담그시면 됩니다. *절임배추는 택배로 도착하면 박스채 아래위 뒤집어서 한시간~몇시간은 서늘한곳(베란다같은곳)에 보관후 꺼내세요 그래야 골고루 박스 아래위 배추가 절여진 배추맛을 느낄수 있습니다. *절임배추가 도착하는 날 문자를 받으시면 멸치다시마육수와 찹쌀풀 미리 끓여 식혀주세요 *무채를 넣고 싶지 않은분들은 무채써는 대신 무1개(1600g)을 석박지처럼 큼직하게 썰어서 소금1T반에 30분정도 절인후 살짝 헹궈서 김치양념에 버무린후 배추김치 사이사이 석박지처럼 넣어서 드시면 됩니다. *생새우는 김장철에 시장에 많이 파는데요~요즘은 인터넷으로도 많이 판매합니다. 김장김치는 생새우와 홍갓이 들어가야 시원한 맛이 납니다. 생새우 구입하셔서 남으면 소분해서 냉동보관후 1년내내 김치 담그실때 넣으면 맛있답니다. *생새우 구입이 어려운 분들은 생새우 빼시는 대신에 새우젓을 350g 넣고요~ 대신 멸치액젓을 600g으로 줄인후 양념장을 버무린후 드셔보셔서 싱거우면 소금을 추가하시면 됩니다. *김장김치는 오랫동안 물러지지 않게 숙성시키려면 최대한 공기와의 접촉을 차단시켜야합니다. 오랫동안 먹을 김치통에는 김장비닐을 씌어서 김치를 담아주거나 김장비닐에 보관하는것이 싫은 분들은 김치통에 김치를 담고 푸른겉잎을 맨위에 올려준후 밀봉하시면 됩니다."], "steps": ["절임배추가 오면 박스채 아래위 뒤집어서 한시간~몇시간 서늘한곳(베란다같은곳)에 보관합니다.", "찹쌀풀 만들기 : 절임배추 오기전에 멸치다시마육수와 찹쌀풀을 미리 만들어 식혀주는것이 좋습니다. 냄비에 멸치다시마육수1300g(1300ml).찹쌀가루90g(7T)를 넣고 거품기로 풀어준후 중불에서 3~5분정도 저어주면서 끓여준후 완전히 식혀줍니다.", "홍갓400g.쪽파200g 세척하시고요 2cm정도 길이로 썰어 준비합니다.", "무1개 큰사이즈(1600g) 세척후 반을 갈라준후 채썰어줍니다.", "배1/2개.사과1/2개.양파반개.대파흰부분3개. 무500g 토막내어 믹서기에 넣고요", "생새우180g.새우젓200g.멸치다시마육수1300g을 믹서기에 같이 넣고 곱게 갈아줍니다.", "큰 그릇에 식혀 놓은 찹쌀풀 넣고요~ 믹서기에 갈은것 넣고요~ 다진마늘400g.다진생강100g.소금5T(50g). 매실청4T.멸치액젓800g(700ml). 고춧가루1100g(1800ml) 넣고 섞어준후 준비한 무채와 홍갓.쪽파를 넣고 버무려 김치양념장 마무리합니다. **소금은 모든 양념장 재료를 넣고 버무린후 드셔보신후 기호에 맞게 조절해서 넣으세요!!!", "절임배추는 체에 받쳐 물기를 1시간 빼줍니다.", "물기뺀 절임배추에 준비한 양념장을 골고루 흰줄기부분 위주로 버무려주면 완성입니다.", "버무린 김치를 김치통에 차곡차곡 담아준후 절인배추의 푸르고 억센겉잎 몇장만 떼어 양념장에 버무려 맨위에 덮어준후 밀봉하면 더 맛있게 숙성이 된답니다. 또는 김장비닐을 김치통에 씌어준후 김치를 담아준후 밀봉해주셔도 됩니다."], "title": "실패할일 없는 김장김치양념 /절임배추20kg/ 김장김치 양념비율 황금레시피 /김장담그기", "servings": "6인분 이상", "cook_time": "120분 이내", "copyright": "김진옥요리가좋다", "recipe_id": "7037475", "step_tips": [null, "냄비", "볼", "채칼", null, "믹서기", null, null, null, "김치통"], "difficulty": "중급", "source_url": "https://www.10000recipe.com/recipe/7037475", "ingredients": ["절임배추 1상자 7~9포기 20kg", "무 1600g 채썰때 사용 1개", "홍갓 400g", "쪽파 200g", "멸치다시마육수 1300ml 1300g", "찹쌀가루 7T 90g", "배 250g 1/2개", "사과 100g 1/2개", "대파 흰부분 3개", "무 500g", "양파 1/2개", "새우젓 200g", "생새우 180g", "찹쌀풀 식힌", "다진마늘 400g", "다진생강 100g", "멸치액젓 700ml 800g", "고춧가루 1100g", "매실청 4T", "소금 50g 양념장에 소금은 버무린후 보신후 마지막에 기호에 맞게 넣기 5T"], "ingredients_struct": [{"qty": "20kg", "desc": null, "name": "절임배추 1상자 7~9포기"}, {"qty": "1개", "desc": null, "name": "무 1600g 채썰때 사용"}, {"qty": "400g", "desc": null, "name": "홍갓"}, {"qty": "200g", "desc": null, "name": "쪽파"}, {"qty": "1300g", "desc": null, "name": "멸치다시마육수 1300ml"}, {"qty": "90g", "desc": null, "name": "찹쌀가루 7T"}, {"qty": "1/2개", "desc": null, "name": "배 250g"}, {"qty": "1/2개", "desc": null, "name": "사과 100g"}, {"qty": "3개", "desc": null, "name": "대파 흰부분"}, {"qty": "500g", "desc": null, "name": "무"}, {"qty": "1/2개", "desc": null, "name": "양파"}, {"qty": "200g", "desc": null, "name": "새우젓"}, {"qty": "180g", "desc": null, "name": "생새우"}, {"qty": "1300g", "desc": null, "name": "멸치다시마육수 1300ml"}, {"qty": "", "desc": null, "name": "찹쌀풀 식힌"}, {"qty": "400g", "desc": null, "name": "다진마늘"}, {"qty": "100g", "desc": null, "name": "다진생강"}, {"qty": "800g", "desc": null, "name": "멸치액젓 700ml"}, {"qty": "1100g", "desc": null, "name": "고춧가루"}, {"qty": "4T", "desc": null, "name": "매실청"}, {"qty": "5T", "desc": null, "name": "소금 50g 양념장에 소금은 버무린후 보신후 마지막에 기호에 맞게 넣기"}]}'::jsonb);
INSERT INTO recipes (id, recipe_id, source_url, title, servings, cook_time, difficulty, tips, copyright, created_at, updated_at, raw_data) VALUES (428, '7037582', 'https://www.10000recipe.com/recipe/7037582', '깍두기담그는법/ 깍두기 담그기 /가을무김치 황금레시피/ 국밥집 깍두기양념/ 식당 깍두기 /맛없는 여름무 해결', '4인분', '60분 이내', '아무나', '["가을무는 씁쓸하고, 딱딱하고, 단단해서 맛이 없는 편이지만, 오늘의부엌레시피로 담아두면, 식당처럼, 국밥집 깍두기 완성!!!"]'::jsonb, '오늘의부엌', 2025-11-23 02:32:13.634619, 2025-11-23 02:32:13.634619, '{"tips": ["가을무는 씁쓸하고, 딱딱하고, 단단해서 맛이 없는 편이지만, 오늘의부엌레시피로 담아두면, 식당처럼, 국밥집 깍두기 완성!!!"], "steps": ["무 1개 = 2.7kg 껍질 제거하고 깍둑깍둑 네모나게 썰어주세요", "뉴슈가 1 숟가락 깎아서 = 10g 무에 뿌려주고 남은 건 물 100ml 섞어서 뿌려주세요", "굵은 소금 숟가락 4번 = 60g ❗️1 숟가락 = 16g 물 500ml = 국그릇 1번 + 2/3 섞어서 부어주세요 ☺️", "⏰ 10분 마다 위 아래 뒤집어주면서 골고루 소금에 절여줍니다❗️", "⏰ 45분 후, 2번 반복 깨끗이 씻어주세요!", "양념을 고루 섞어주세요~", "깨끗이 물기 뺀 절인 무에 양념 넣고 골고루 위 아래 뒤집어가면서 버무려주세요!", "참깨 뿌리고 마무리!❗️실온, 냉장고 밖에서 1~2일 숙성하고 냉장보관 하셔도 좋아요"], "title": "깍두기담그는법/ 깍두기 담그기 /가을무김치 황금레시피/ 국밥집 깍두기양념/ 식당 깍두기 /맛없는 여름무 해결", "servings": "4인분", "cook_time": "60분 이내", "copyright": "오늘의부엌", "recipe_id": "7037582", "step_tips": ["조리용필러", "스텐대야", null, null, null, null, null, null], "difficulty": "아무나", "source_url": "https://www.10000recipe.com/recipe/7037582", "ingredients": ["무 2.7kg 1개", "뉴슈가 깎아서10g 1숟가락", "물 100ml 1차 뉴슈가랑 섞어서 사용하는 물 10숟가락", "굵은 소금 60g 1숟가락= 6g 4숟가락", "물 2차 소금과 물을 섞을 때 사용 3500ml", "작은 사과 갈아서 없으면 사과즙 가능 1개", "다진 마늘 1.5숟가락", "다진 생강 1숟가락", "고춧가루 100g 10숟가락", "설탕 1.5숟가락", "멸치액젓 20ml 또는 까나리액젓 2숟가락", "새우젓 28g 2숟가락"], "ingredients_struct": [{"qty": "1개", "desc": null, "name": "무 2.7kg"}, {"qty": "1숟가락", "desc": null, "name": "뉴슈가 깎아서10g"}, {"qty": "10숟가락", "desc": null, "name": "물 100ml 1차 뉴슈가랑 섞어서 사용하는 물"}, {"qty": "4숟가락", "desc": null, "name": "굵은 소금 60g 1숟가락= 6g"}, {"qty": "3500ml", "desc": null, "name": "물 2차 소금과 물을 섞을 때 사용"}, {"qty": "1개", "desc": null, "name": "작은 사과 갈아서 없으면 사과즙 가능"}, {"qty": "1.5숟가락", "desc": null, "name": "다진 마늘"}, {"qty": "1숟가락", "desc": null, "name": "다진 생강"}, {"qty": "10숟가락", "desc": null, "name": "고춧가루 100g"}, {"qty": "1.5숟가락", "desc": null, "name": "설탕"}, {"qty": "2숟가락", "desc": null, "name": "멸치액젓 20ml 또는 까나리액젓"}, {"qty": "2숟가락", "desc": null, "name": "새우젓 28g"}]}'::jsonb);
INSERT INTO recipes (id, recipe_id, source_url, title, servings, cook_time, difficulty, tips, copyright, created_at, updated_at, raw_data) VALUES (278, '6832126', 'https://www.10000recipe.com/recipe/6832126', '깍두기 쉽게 담그는법/새우젓, 찹쌀풀없이 담그기', '3인분', '15분 이내', '아무나', '["작은무 2개 기준입니다~ (큰무는 1개로 가능) 새우젓과 찹쌀풀없이도 가능해요. 이정도양은 소금에 먼저 재우지 않아도 되요. 하루 실온에 두고 다음날 냉장고에 넣어주세요."]'::jsonb, '비진', 2025-11-22 23:06:52.750296, 2025-11-23 01:23:39.975432, '{"tips": ["작은무 2개 기준입니다~ (큰무는 1개로 가능) 새우젓과 찹쌀풀없이도 가능해요. 이정도양은 소금에 먼저 재우지 않아도 되요. 하루 실온에 두고 다음날 냉장고에 넣어주세요."], "steps": ["무는 깍둑깍둑 깍둑썰기 해주세요~ 소금에 절여지면서 줄어드니까 너무 작게는 썰지마시고요.", "고춧가루 5T 넣어 색을 먼저 입히고~ 버무려주세요.", "나머지 양념넣고 버무려주세요. (천일염3T, 설탕3T, 다진마늘2T, 멸치액젓2~3T, 파)", "끝이예요! 너무 간단한가요? ㅎㅎ 소금에 먼저 절이기도 하지만 이정도양은 그냥 같이 버무려도 괜찮더라고요~", "버무려서 통에 옮겨담았어요~ 색도 빨갛게 너무 예쁘게 나왔어요. 하루 실온에 두고 다음날 냉장고에 넣어주세요. 초보인지도 모를 비주얼~ ㅋㅋ"], "title": "깍두기 쉽게 담그는법/새우젓, 찹쌀풀없이 담그기", "servings": "3인분", "cook_time": "15분 이내", "copyright": "비진", "recipe_id": "6832126", "step_tips": [null, null, null, null, null], "difficulty": "아무나", "source_url": "https://www.10000recipe.com/recipe/6832126", "ingredients": ["무 2개", "고춧가루 5T", "천일염 3T", "다진 마늘 2T", "설탕 3T", "멸치액젓 2~3T", "쪽파 or 대파 적당히"], "ingredients_struct": [{"qty": "2개", "desc": null, "name": "무"}, {"qty": "5T", "desc": null, "name": "고춧가루"}, {"qty": "3T", "desc": null, "name": "천일염"}, {"qty": "2T", "desc": null, "name": "다진 마늘"}, {"qty": "3T", "desc": null, "name": "설탕"}, {"qty": "2~3T", "desc": null, "name": "멸치액젓"}, {"qty": "적당히", "desc": null, "name": "쪽파 or 대파"}]}'::jsonb);
INSERT INTO recipes (id, recipe_id, source_url, title, servings, cook_time, difficulty, tips, copyright, created_at, updated_at, raw_data) VALUES (335, '6884805', 'https://www.10000recipe.com/recipe/6884805', '감바스 알 아히요 만들기', '3인분', '15분 이내', '초급', '["살짝 구운 바게트 빵과 먹기 딱 좋은 감바스 알 아히요는 감바스- 새우 아히요-마늘이란 뜻으로 마늘과 새우를 이용한 요리이다 튀긴 마늘향과 새우의 조화가 환상적이고 와인 안주로 참 좋다 비주얼 또한 괜찮으니 파티 요리 또는 손님 초대 메뉴로 딱이다"]'::jsonb, '판교댁쏭아', 2025-11-23 01:05:05.077054, 2025-11-23 01:45:33.676241, '{"tips": ["살짝 구운 바게트 빵과 먹기 딱 좋은 감바스 알 아히요는 감바스- 새우 아히요-마늘이란 뜻으로 마늘과 새우를 이용한 요리이다 튀긴 마늘향과 새우의 조화가 환상적이고 와인 안주로 참 좋다 비주얼 또한 괜찮으니 파티 요리 또는 손님 초대 메뉴로 딱이다"], "steps": ["마늘은 편으로 썰어서 준비", "새우는 소금과 후추를 넣어 준비 소금은 1/3 t 정도가 적당하다", "페페론치노를 넣어 오일의 느끼함을 잡아준다 페페론치노는 잘게 잘라 줄수록 매운맛이 더 난다", "작은 팬을 사용 올리브오일을 넣고 끓여준 뒤 페페론치와 마늘을 넣어 튀겨준다", "소금과 후추로 밑간을 한 새우를 같이 넣고 튀겨준다", "좋아하는 허브를 같이 넣어 줘도 좋다 하지만 향이 강한 허브를 넣어 줬더니 마늘향을 못 느끼겠더라는^^;;", "새우가 익으면 조리 과정은 끝이 난다 바게트빵과 같이 먹고 남은 올리브오일은 스파게티 면만 익혀서 넣어 주면 오일파스타가 만들어진다"], "title": "감바스 알 아히요 만들기", "servings": "3인분", "cook_time": "15분 이내", "copyright": "판교댁쏭아", "recipe_id": "6884805", "step_tips": [null, null, null, null, null, null, null], "difficulty": "초급", "source_url": "https://www.10000recipe.com/recipe/6884805", "ingredients": ["새우 3컵", "올리브오일 1.5컵", "마늘 1/2컵", "페페론치노 4~5개", "소금 톡톡", "후추 톡톡", "바게트빵"], "ingredients_struct": [{"qty": "3컵", "desc": null, "name": "새우"}, {"qty": "1.5컵", "desc": null, "name": "올리브오일"}, {"qty": "1/2컵", "desc": null, "name": "마늘"}, {"qty": "4~5개", "desc": null, "name": "페페론치노"}, {"qty": "톡톡", "desc": null, "name": "소금"}, {"qty": "톡톡", "desc": null, "name": "후추"}, {"qty": "", "desc": null, "name": "바게트빵"}]}'::jsonb);
INSERT INTO recipes (id, recipe_id, source_url, title, servings, cook_time, difficulty, tips, copyright, created_at, updated_at, raw_data) VALUES (336, '6884873', 'https://www.10000recipe.com/recipe/6884873', '닭도리탕 양념장 황금레시피로 맛있게', '3인분', '30분 이내', '초급', '["아이들 먹을 닭도리탕은 청양고추를 빼고 설탕을 살짝 더 넣어 주니 잘 먹는다 손가락 쪽쪽 빨아 가며 닭 다리를 잡고 뜯는 아이들~ 아이들은 국물에 밥까지 비벼 먹더니 감자가 너무 맛있단다 역시 닭볶음탕 감자를 밥과 같이 먹으면~ 말이 필요 없지~^^ 치킨을 먹을 때 닭 다리가 두 개인 게 늘 불만이었던 가족들~ 닭다리 왕창 넣고 만든 닭도리탕으로 저녁상이 만족스럽다^^"]'::jsonb, '판교댁쏭아', 2025-11-23 01:06:51.137060, 2025-11-23 01:45:33.687309, '{"tips": ["아이들 먹을 닭도리탕은 청양고추를 빼고 설탕을 살짝 더 넣어 주니 잘 먹는다 손가락 쪽쪽 빨아 가며 닭 다리를 잡고 뜯는 아이들~ 아이들은 국물에 밥까지 비벼 먹더니 감자가 너무 맛있단다 역시 닭볶음탕 감자를 밥과 같이 먹으면~ 말이 필요 없지~^^ 치킨을 먹을 때 닭 다리가 두 개인 게 늘 불만이었던 가족들~ 닭다리 왕창 넣고 만든 닭도리탕으로 저녁상이 만족스럽다^^"], "steps": ["닭 다리는 끓는 물에 한번 데쳐서 준비", "당근, 감자, 양파를 썰어서 넣어 준다", "분량의 양념을 섞어서 양념장 황금 레시피 만들기", "양념을 넣어 물을 자작하게 붓는다 처음부터 물을 너무 많이 넣지 말고 재료에 양념이 잘 베일 수 있도록 처음에는 물을 조금만 넣고 끓인 다음 부족한 물을 나중에 보충해 준다", "재료에 양념이 잘 베이게 끓여주다가 부족한 물을 보충해서 끓여주는데 감자가 익을 때까지만 익혀주면 된다", "국물이 잘 조려지고 감자가 다 익었을 때 청양고추와 대파를 넣고 잘 섞어 준다", "국물 맛을 보니 정말 끝내준다~ 닭도리탕을 좋아해서 자주 만들어 먹었는데 단골 닭도리탕 집이 생기면서 요즘 뜸하게 만들어 먹었더니 간만에 집에서 만든 닭도리탕 정말 맛있네^^"], "title": "닭도리탕 양념장 황금레시피로 맛있게", "servings": "3인분", "cook_time": "30분 이내", "copyright": "판교댁쏭아", "recipe_id": "6884873", "step_tips": [null, null, null, null, null, null, null], "difficulty": "초급", "source_url": "https://www.10000recipe.com/recipe/6884873", "ingredients": ["감자 2개", "양파 1개", "당근 1/2개", "청양고추 3개", "대파 1개", "고추장 2큰술", "고춧가루 5큰술", "간장 4큰술", "맛술 1큰술", "설탕 2큰술", "마늘 1큰술"], "ingredients_struct": [{"qty": "2개", "desc": null, "name": "감자"}, {"qty": "1개", "desc": null, "name": "양파"}, {"qty": "1/2개", "desc": null, "name": "당근"}, {"qty": "3개", "desc": null, "name": "청양고추"}, {"qty": "1개", "desc": null, "name": "대파"}, {"qty": "2큰술", "desc": null, "name": "고추장"}, {"qty": "5큰술", "desc": null, "name": "고춧가루"}, {"qty": "4큰술", "desc": null, "name": "간장"}, {"qty": "1큰술", "desc": null, "name": "맛술"}, {"qty": "2큰술", "desc": null, "name": "설탕"}, {"qty": "1큰술", "desc": null, "name": "마늘"}]}'::jsonb);
INSERT INTO recipes (id, recipe_id, source_url, title, servings, cook_time, difficulty, tips, copyright, created_at, updated_at, raw_data) VALUES (338, '6887142', 'https://www.10000recipe.com/recipe/6887142', '닭볶음탕 황금레시피, 밖에서 사 먹는 닭도리탕 맛을 집에서 내봤어요 ~', '2인분', '60분 이내', '초급', '[]'::jsonb, '뽕림이', 2025-11-23 01:09:49.941315, 2025-11-23 01:45:33.702172, '{"tips": [], "steps": ["먼저 감자는 1개당 4등분으로 나누어줬고요. 테두리를 둥그렇게 깎아 준비했어요. 양파와 당근은 먹기 좋은 크기로 잘라주시고요. 대파(또는 쪽파)는 송송 썰어주세요.", "고춧가루 2 큰 술, 고추장 4 큰 술, 다진 마늘 1 큰 술, 진간장 10 큰 술, 설탕 4 큰 술, 올리고당 1 큰 술, 미림 2 큰 술, 생강가루 1 작은 술, 후춧가루 약간 넣고 잘 섞어 양념장을 만들어주세요.", "닭볶음용 닭은 불필요한 지방 덩어리 손질 후 흐르는 물에 깨끗이 씻어주시고요.", "끓는 물에 살짝 데쳐준 뒤 흐르는 물에 닭을 헹궈주세요.", "냄비에 닭과 양념장, 물 600ml를 넣어주시고요.", "20-30분 후 국물이 어느 정도 졸아들고 닭과 감자가 익으면 양파와 당근도 넣어주시고요. 한소끔 더 끓여주세요.", "저는 조금 더 졸여줬고요. 마지막으로 송송 썬 대파(또는 쪽파)를 넣고 마무리해주었어요.", "닭볶음탕 맛있게 먹는 방법 알려드릴까요?", "많이들 알고 계시는 방법이겠지만, 일단 닭고기 한 점을 앞접시에 갖다 놓고 살만 싹 발라내요. 그리고 나서 포슬포슬 잘 익은 감자도 하나 가져오고요. 국물을 세 숟가락 정도 담아주세요. 마지막으로 김이 모락모락 나는 갓 지은 흰쌀밥을 한 숟가락 푹 퍼서 대충 비벼 먹는 거죠 ~", "식당에서 먹는 닭볶음탕 그대로 집에서 쉽게 만들어 먹을 수 있는 오늘의 뽕림이표 닭볶음탕 황금레시피 - 이웃님들도 한 번 만들어드셔보세요 :)"], "title": "닭볶음탕 황금레시피, 밖에서 사 먹는 닭도리탕 맛을 집에서 내봤어요 ~", "servings": "2인분", "cook_time": "60분 이내", "copyright": "뽕림이", "recipe_id": "6887142", "step_tips": [null, null, null, null, null, null, null, null, null, null], "difficulty": "초급", "source_url": "https://www.10000recipe.com/recipe/6887142", "ingredients": ["닭볶음탕용 닭 1마리", "감자 2개", "양파 1개", "당근 1/3개", "다진 대파 또는 쪽파 2줌", "물 600ml", "통깨 약간", "고춧가루 2큰술", "고추장 4큰술", "진간장 10큰술", "다진 마늘 1큰술", "설탕 4큰술", "올리고당 1큰술", "생강가루 1작은술", "미림 2큰술", "후춧가루 약간"], "ingredients_struct": [{"qty": "1마리", "desc": null, "name": "닭볶음탕용 닭"}, {"qty": "2개", "desc": null, "name": "감자"}, {"qty": "1개", "desc": null, "name": "양파"}, {"qty": "1/3개", "desc": null, "name": "당근"}, {"qty": "2줌", "desc": null, "name": "다진 대파 또는 쪽파"}, {"qty": "600ml", "desc": null, "name": "물"}, {"qty": "약간", "desc": null, "name": "통깨"}, {"qty": "2큰술", "desc": null, "name": "고춧가루"}, {"qty": "4큰술", "desc": null, "name": "고추장"}, {"qty": "10큰술", "desc": null, "name": "진간장"}, {"qty": "1큰술", "desc": null, "name": "다진 마늘"}, {"qty": "4큰술", "desc": null, "name": "설탕"}, {"qty": "1큰술", "desc": null, "name": "올리고당"}, {"qty": "1작은술", "desc": null, "name": "생강가루"}, {"qty": "2큰술", "desc": null, "name": "미림"}, {"qty": "약간", "desc": null, "name": "후춧가루"}]}'::jsonb);
INSERT INTO recipes (id, recipe_id, source_url, title, servings, cook_time, difficulty, tips, copyright, created_at, updated_at, raw_data) VALUES (341, '6891526', 'https://www.10000recipe.com/recipe/6891526', '두부조림 양념장 만드는 법', '2인분', '60분 이내', '아무나', '[]'::jsonb, '시크제이맘', 2025-11-23 01:15:55.853598, 2025-11-23 01:47:19.558697, '{"tips": [], "steps": ["먹기 좋게 한 입 크기로 도톰하게 썰어주고 키친타월을 이용해 물기를 제거하고 그 위에 소금을 뿌려 밑간을 해주세요. 물기를 제거하고 소금으로 밑간을 해주면 두부가 단단해진답니다. 그리고 나중에 조리할 때 양념이 겉돌지 않고 않아요.", "양념장을 만들어주세요. 다진 대 파3,다진 마늘 0.5를 넣어주고 이때 대파를 넉넉하게 넣어주면 양념 맛도 순해지고 감칠맛도 좋답니다.", "나머지 양념재료인 고춧가루 1, 간장 3, 맛술 1, 설탕 0.5, 참기름 1을 모두 한데 넣고 고루 섞어주세요.", "달군 팬에 식용유 평소 보다 조금 넉넉하게 두르고 물기를 빼놓은 두부를 넣어 앞, 뒤로 노릇노릇하게 부쳐주세요.", "두부가 전체적으로 노릇하게 부쳐지면 준비해 놓은 양념장을 숟가락을 이용해 조금씩 떠 두부 위에 고루 얹어 주세요.", "그리고 양념장 담은 볼에 물(종이컵 기준) 1/4을 담아 전체적으로 조금씩 끼얹어 주세요", "불은 중불로 해주시고 국물을 숟가락으로 떠 두부 위에 끼얹고 두부를 한 번씩 뒤집어 가며 자박자박하게 조려 마무리합니다.", "두부조림 완성 ^^"], "title": "두부조림 양념장 만드는 법", "servings": "2인분", "cook_time": "60분 이내", "copyright": "시크제이맘", "recipe_id": "6891526", "step_tips": [null, null, null, null, null, null, null, null], "difficulty": "아무나", "source_url": "https://www.10000recipe.com/recipe/6891526", "ingredients": ["두부 1모", "물 1/4컵", "소금 약간", "고춧가루 1스푼", "간장 3스푼", "맛술 1스푼", "다진 마늘 0.5스푼", "다진 대파 3스푼", "설탕 0.5스푼", "참기름 1스푼"], "ingredients_struct": [{"qty": "1모", "desc": null, "name": "두부"}, {"qty": "1/4컵", "desc": null, "name": "물"}, {"qty": "약간", "desc": null, "name": "소금"}, {"qty": "1스푼", "desc": null, "name": "고춧가루"}, {"qty": "3스푼", "desc": null, "name": "간장"}, {"qty": "1스푼", "desc": null, "name": "맛술"}, {"qty": "0.5스푼", "desc": null, "name": "다진 마늘"}, {"qty": "3스푼", "desc": null, "name": "다진 대파"}, {"qty": "0.5스푼", "desc": null, "name": "설탕"}, {"qty": "1스푼", "desc": null, "name": "참기름"}]}'::jsonb);
INSERT INTO recipes (id, recipe_id, source_url, title, servings, cook_time, difficulty, tips, copyright, created_at, updated_at, raw_data) VALUES (429, '7037991', 'https://www.10000recipe.com/recipe/7037991', '표고버섯 볶음 만드는법', '2인분', '15분 이내', '초급', '["- 표고버섯을 마른 후라이팬에 수분을 날리듯이 볶아 주세요. - 국간장과 물을 섞어 간을 해주면 짜지 않게 만들 수 있어요."]'::jsonb, 'Tina소울푸드', 2025-11-23 02:34:22.566362, 2025-11-23 02:34:22.566362, '{"tips": ["- 표고버섯을 마른 후라이팬에 수분을 날리듯이 볶아 주세요. - 국간장과 물을 섞어 간을 해주면 짜지 않게 만들 수 있어요."], "steps": ["표고버섯은 물에 씻지 말고 젖은 키친타올로 이물질을 털어내 주세요. 표고버섯을 썰어 주세요.", "마른 후라이팬에 중강불로 표고버섯을 수분을 말리면서 숨이 죽을 정도로 볶아 주세요.", "국간장과 물을 섞어서 넣고 양념이 고루 배이도록 재빠르게 잘 섞어 주세요.", "들기름을 한스푼 넣고 잘 섞어 준 뒤 참깨 뿌려 완성해요."], "title": "표고버섯 볶음 만드는법", "servings": "2인분", "cook_time": "15분 이내", "copyright": "Tina소울푸드", "recipe_id": "7037991", "step_tips": ["도마", "프라이팬", null, null], "difficulty": "초급", "source_url": "https://www.10000recipe.com/recipe/7037991", "ingredients": ["표고버섯 10개", "국간장 1/2스푼", "물 1스푼", "들기름 1스푼", "참깨 약간"], "ingredients_struct": [{"qty": "10개", "desc": null, "name": "표고버섯"}, {"qty": "1/2스푼", "desc": null, "name": "국간장"}, {"qty": "1스푼", "desc": null, "name": "물"}, {"qty": "1스푼", "desc": null, "name": "들기름"}, {"qty": "약간", "desc": null, "name": "참깨"}]}'::jsonb);
INSERT INTO recipes (id, recipe_id, source_url, title, servings, cook_time, difficulty, tips, copyright, created_at, updated_at, raw_data) VALUES (275, '1785098', 'https://www.10000recipe.com/recipe/1785098', '돼지고기 김치찌개 맛내는 비법', '3인분', '30분 이내', '초급', '[]'::jsonb, '완소연홍', 2025-11-22 22:59:31.877486, 2025-11-23 01:23:39.767699, '{"tips": [], "steps": ["돼지고기는 분량의 양념을 넣어 조물조물 해주신후 30분 이상 재웁니다.", "냄비에 썰어둔 김치와 밑간한 돼지고기, 김칫국물 5큰술, 참기름 1작은술을 넣어 약불에서 3~5분간 충분히 볶아줍니다.", "돼지고기 자체에 지방이 붙어있으니 참기름은 많이 넣지 않으셔도 된답니다. 이렇게 충분히 볶아주세요~.", "충분히 볶아진 김치에 물 1컵을 넣어 끓여줍니다.", "물 1컵을 넣어 보글보글 끓여준후 나머지 1컵을 더 부워주도록 합니다. 물을 한꺼번에 부워서 끓이는것보다 이렇게 나눠서 끓여주면 국물맛이 더욱 좋아진답니다.", "보글보글 국물이 끓으면 여기에 양파와 두부를 넣어줍니다.", "국간장을 넣어줍니다.", "모든 재료가 한데 잘 어우러졌다면 다진마늘과 어슷 썬 고추 1개를 넣어줍니다.", "부족한 간은 소금으로 해주시고 대파와 나머지 고추 1개를 더 넣어 한소끔 더 끓이신후 마무리 합니다."], "title": "돼지고기 김치찌개 맛내는 비법", "servings": "3인분", "cook_time": "30분 이내", "copyright": "완소연홍", "recipe_id": "1785098", "step_tips": [null, null, null, null, null, null, null, null, null], "difficulty": "초급", "source_url": "https://www.10000recipe.com/recipe/1785098", "ingredients": ["물 250ml 기준 2컵", "돼지고기 찌개용 또는 목살 250g", "신김치 200g", "김칫국물 5큰술", "참기름 1작은술", "양파 1/2개", "청고추 2개", "대파 약간", "고추장 1큰술", "미림 1큰술", "국간장 1/2큰술", "소금 1꼬집", "다진마늘 1큰술", "후추 약간"], "ingredients_struct": [{"qty": "2컵", "desc": null, "name": "물 250ml 기준"}, {"qty": "250g", "desc": null, "name": "돼지고기 찌개용 또는 목살"}, {"qty": "200g", "desc": null, "name": "신김치"}, {"qty": "5큰술", "desc": null, "name": "김칫국물"}, {"qty": "1작은술", "desc": null, "name": "참기름"}, {"qty": "1/2개", "desc": null, "name": "양파"}, {"qty": "2개", "desc": null, "name": "청고추"}, {"qty": "약간", "desc": null, "name": "대파"}, {"qty": "1큰술", "desc": null, "name": "고추장"}, {"qty": "1큰술", "desc": null, "name": "미림"}, {"qty": "1/2큰술", "desc": null, "name": "국간장"}, {"qty": "1꼬집", "desc": null, "name": "소금"}, {"qty": "1큰술", "desc": null, "name": "다진마늘"}, {"qty": "약간", "desc": null, "name": "후추"}]}'::jsonb);
INSERT INTO recipes (id, recipe_id, source_url, title, servings, cook_time, difficulty, tips, copyright, created_at, updated_at, raw_data) VALUES (340, '6889570', 'https://www.10000recipe.com/recipe/6889570', '돼지고기 김치찜 만드는 법', '4인분', '120분 이내', '아무나', '[]'::jsonb, '시크제이맘', 2025-11-23 01:13:14.849687, 2025-11-23 01:45:33.718697, '{"tips": [], "steps": ["청주 3, 다진 마늘 1, 생강가루 0.3, 후춧가루 약간을 넣어 돼지고기 밑간을 해주세요. 김치찜에 넣을 고기는 큼지막하게 넣거나 또는 덩어리로 넣어주고 먹기 직전에 가위로 싹둑싹둑 잘라 드심 된답니다.", "김치 1/4포기를 준비해주세요. *오래된 묵은지는 흐르는 물에 김칫소를 씻어 사용하세요. 또 너무 신 김치는 미리 설탕을 넣어 조물조물 무쳐 주셔도 되고요. 그럼 신맛이 달아난답니다", "양파는 채 썰어 주고 대파, 청양고추는 어슷 썰어 주세요.", "물 3컵을 그릇에 담고 양념재료인 된장 0.5, 국간장 5, 설탕 2를 넣고 고루 섞어 주세요. 여기에 새우젓 1숟가락 정도 추가하셔도 좋아요.", "냄비에 밑간해 놓은 돼지고기를 넣고 김치도 함께 넣어주세요.", "그리고 양념해 놓은 육수를 모두 붓고", "고춧가루 3, 양파, 대파, 청양고추를 모두 넣고 1시간 30분 정도 푹 끓여주세요. 처음에는 뚜껑을 열고 센 불에서 10분 정도 끓여주다 (그래야지 고기 잡내가 날아가요) 그다음 뚜껑을 닫고 불은 약불로 줄이고 뭉근하게 익혀줍니다. 김치가 가정마다 염도, 맵기도 그렇고 신맛도 모두 다르니 이럴 땐 설탕과 고춧가루를 조절해 가며 입맛에 맞게 간을 해주세요. 김치가 짤 때는 물에 살짝 씻어주거나 김칫소를 털어주거나 국물을 짜주세요. 1시간 이상 푹 끓이다 보면 고기에서 기름이 나와 김치에도 배어 윤기가 나고 고기는 야들야들하니 연해진답니다.", "돼지고기 김치찜 완성 ^^ 김치찜 하실 땐 돼지고기에 밑간을 해주심 잡내를 없앨 수 있으니~기억해 주시고요. 무엇보다 신선한 고기 구입이 우선이겠죠."], "title": "돼지고기 김치찜 만드는 법", "servings": "4인분", "cook_time": "120분 이내", "copyright": "시크제이맘", "recipe_id": "6889570", "step_tips": [null, null, null, null, null, null, null, null], "difficulty": "아무나", "source_url": "https://www.10000recipe.com/recipe/6889570", "ingredients": ["돼지고기 600g", "김치 1/4포기", "양파 1/2개", "청양고추 1~2개", "대파 1/2대", "고춧가루 3스푼", "다진 마늘 1스푼", "생강가루 0.3스푼", "청주 3스푼", "후춧가루 약간", "물 3컵", "된장 0.5스푼", "국간장 5스푼", "설탕 2스푼"], "ingredients_struct": [{"qty": "600g", "desc": null, "name": "돼지고기"}, {"qty": "1/4포기", "desc": null, "name": "김치"}, {"qty": "1/2개", "desc": null, "name": "양파"}, {"qty": "1~2개", "desc": null, "name": "청양고추"}, {"qty": "1/2대", "desc": null, "name": "대파"}, {"qty": "3스푼", "desc": null, "name": "고춧가루"}, {"qty": "1스푼", "desc": null, "name": "다진 마늘"}, {"qty": "0.3스푼", "desc": null, "name": "생강가루"}, {"qty": "3스푼", "desc": null, "name": "청주"}, {"qty": "약간", "desc": null, "name": "후춧가루"}, {"qty": "3컵", "desc": null, "name": "물"}, {"qty": "0.5스푼", "desc": null, "name": "된장"}, {"qty": "5스푼", "desc": null, "name": "국간장"}, {"qty": "2스푼", "desc": null, "name": "설탕"}]}'::jsonb);
INSERT INTO recipes (id, recipe_id, source_url, title, servings, cook_time, difficulty, tips, copyright, created_at, updated_at, raw_data) VALUES (430, '7038306', 'https://www.10000recipe.com/recipe/7038306', '초간단 숙주무침 레시피', '4인분', '5분 이내', '아무나', '[]'::jsonb, '뿡씨스터즈', 2025-11-23 02:35:42.830055, 2025-11-23 02:35:42.830055, '{"tips": [], "steps": ["숙주 1봉지 깨끗히 씻어 주세요", "냄비에 물이 끓어 오르면 숙주를 넣고 약 1분 데쳐 주세요", "데친 숙주를 건져 믹싱볼에 담아 주세요", "대파 1/3대 송송송 썰어 데친 숙주에 넣어 주세요", "연두 1큰술", "참기름 1큰술", "조물조물 무쳐 주세요", "깨를 뿌려주고 마무리~", "간단하고 맛있는 비빔밥을 부르는 비주얼 숙주무침 맛있게 만들어 드세요~"], "title": "초간단 숙주무침 레시피", "servings": "4인분", "cook_time": "5분 이내", "copyright": "뿡씨스터즈", "recipe_id": "7038306", "step_tips": ["볼", "냄비", null, null, null, null, null, null, null], "difficulty": "아무나", "source_url": "https://www.10000recipe.com/recipe/7038306", "ingredients": ["숙주 1봉지", "대파 1/3대", "연두 1큰술", "참기름 1큰술", "깨 적당히"], "ingredients_struct": [{"qty": "1봉지", "desc": null, "name": "숙주"}, {"qty": "1/3대", "desc": null, "name": "대파"}, {"qty": "1큰술", "desc": null, "name": "연두"}, {"qty": "1큰술", "desc": null, "name": "참기름"}, {"qty": "적당히", "desc": null, "name": "깨"}]}'::jsonb);
INSERT INTO recipes (id, recipe_id, source_url, title, servings, cook_time, difficulty, tips, copyright, created_at, updated_at, raw_data) VALUES (431, '7040324', 'https://www.10000recipe.com/recipe/7040324', '풀 없이 갓김치 담그는 법 홍갓김치 담그기 양념 만들기', '6인분 이상', '90분 이내', '초급', '["두꺼운 갓은 뿌리부분에 열십자로 칼집을 줘서 절이면 부드럽게 잘 절여진답니다"]'::jsonb, '동그랑', 2025-11-23 02:37:01.491279, 2025-11-23 02:37:01.491279, '{"tips": ["두꺼운 갓은 뿌리부분에 열십자로 칼집을 줘서 절이면 부드럽게 잘 절여진답니다"], "steps": ["마트에서 산 홍갓 한단입니다. 크기가 큰 것도 있고 작은 것도 있는데요. 큰 것은 갓김치를 담그고 작은 갓은 갓 피클을 만들 거라서 굵은 것과 가는 것을 구분했어요.", "갓은 누런 잎은 떼주고 줄기 사이사이 흙이 있는 것은 깨끗이 씻어 줍니다. 줄기가 두꺼운 것은 뿌리 쪽에 열십자(+)로 칼집을 내주면 소금에 잘 절여지고 양념도 잘 밴답니다.", "물 1.2리터에 소금 반 컵을 넣고 잘 녹여줍니다. 갓 양이 적어서 이 정도면 충분히 잘 절여진답니다.", "만들어 놓은 소금물에 홍갓을 넣고 3, 40 분 정도 절여줍니다. 이때 두꺼운 줄기 부분이 소금 물에 잠기도록 살짝 기울여 주면 골고루 잘 절여진답니다.", "3,40분 정도 절이니 줄기부터 잎까지 잘 절여졌어요. 물에 한 번만 헹궈 물기를 꼭 짜서 준비합니다.", "김치 버무릴 다라이에 고춧가루 6 큰 술, 다진 마늘 2 큰 술, 생강청(간 생강) 반 큰 술, 설탕 1.5 큰 술, 배즙(갈아만든 배 주스) 3 큰 술, 액젓 2 큰 술, 새우젓 2 큰 술을 넣고 섞어 갓김치 양념을 만들어줍니다.", "만들어 놓은 양념에 소금에 절여 물기 짜둔 갓을 넣고 한 줄기씩 들고 양념을 골고루 발라줍니다.", "저는 김치에 양념을 듬뿍 바른 걸 좋아하는데요. 양념 바르는 정도는 식성에 따라 바르면 되겠지요.", "알싸하니 맛있는 홍갓김치 입니다."], "title": "풀 없이 갓김치 담그는 법 홍갓김치 담그기 양념 만들기", "servings": "6인분 이상", "cook_time": "90분 이내", "copyright": "동그랑", "recipe_id": "7040324", "step_tips": ["믹싱볼", "조리용나이프", "믹싱볼", null, null, "숟가락", null, "밀폐용기", "접시"], "difficulty": "초급", "source_url": "https://www.10000recipe.com/recipe/7040324", "ingredients": ["홍갓 500g 1단", "굵은소금 갓 절일 때 1/2컵", "물 갓 절일 때 1.2l", "고춧가루 6큰술", "다진 마늘 2큰술", "생강청 간 생강 1/2큰술", "설탕 1.5큰술", "배즙 갈아만든 배 주스 3큰술", "액젓 2큰술", "새우젓 2큰술"], "ingredients_struct": [{"qty": "1단", "desc": null, "name": "홍갓 500g"}, {"qty": "1/2컵", "desc": null, "name": "굵은소금 갓 절일 때"}, {"qty": "1.2l", "desc": null, "name": "물 갓 절일 때"}, {"qty": "6큰술", "desc": null, "name": "고춧가루"}, {"qty": "2큰술", "desc": null, "name": "다진 마늘"}, {"qty": "1/2큰술", "desc": null, "name": "생강청 간 생강"}, {"qty": "1.5큰술", "desc": null, "name": "설탕"}, {"qty": "3큰술", "desc": null, "name": "배즙 갈아만든 배 주스"}, {"qty": "2큰술", "desc": null, "name": "액젓"}, {"qty": "2큰술", "desc": null, "name": "새우젓"}]}'::jsonb);
INSERT INTO recipes (id, recipe_id, source_url, title, servings, cook_time, difficulty, tips, copyright, created_at, updated_at, raw_data) VALUES (287, '6838943', 'https://www.10000recipe.com/recipe/6838943', '백종원 오징어볶음 만드는 법 환상이네', '2인분', '30분 이내', '아무나', '["설탕을 먼저 넣어줘야 메인재료에 간이 맛있게 베인다고 하네요"]'::jsonb, '고래언니', 2025-11-22 23:36:24.093178, 2025-11-23 01:27:03.769528, '{"tips": ["설탕을 먼저 넣어줘야 메인재료에 간이 맛있게 베인다고 하네요"], "steps": ["오징어는 잘 씻어서 준비해주시고 채소도 적당량 준비해서 잘라서 준비해주세요", "오징어 몸통에 다이아몬드 모양으로 칼집을 내준 후 적당한 크기로 잘라줍니다", "팬에 기름을 적당히 두르고 대파를 넣어 파기름을 내며 볶아주고", "파기름이 나왔을 때 잘라놓은 오징어를 넣고 설탕과 다진마늘을 넣어서 볶아주세요", "오징어가 하얗게 익어가는게 보일정도로 볶아졌을때", "분량의 고추장, 고추가루, 간장을 넣고 볶아주세요", "본 레시피는 이때 물을 2/3컵 넣지만 저는 야채를 많이 넣을거라 물 넣는건 생략했어요", "양념이 오징어와 잘 어울어졌을 때 잘라놓은 양파와 양배추를 넣고 쌘불에 야채의 수분이 너무 나오지 않게 볶아주세요", "양파와 양배추에도 양념이 베이고 마지막 참기름까지 넣어주면", "집밥 백선생 백종원 오징어볶음이 환상의 맛으로 완성되었어요", "양념이 너무 맛있어서 소면도 삶아 팬에 남아있는 양념을 샥샥 비벼서 먹었드랬죠"], "title": "백종원 오징어볶음 만드는 법 환상이네", "servings": "2인분", "cook_time": "30분 이내", "copyright": "고래언니", "recipe_id": "6838943", "step_tips": [null, null, null, null, null, null, null, null, null, null, null], "difficulty": "아무나", "source_url": "https://www.10000recipe.com/recipe/6838943", "ingredients": ["오징어 2마리", "대파 1뿌리", "양파 1개", "양배추 적당히", "당근 생략가능", "설탕 1T", "다진마늘 1T", "고추장 1T", "고추가루 3T", "간장 5T", "참기름 1T"], "ingredients_struct": [{"qty": "2마리", "desc": null, "name": "오징어"}, {"qty": "1뿌리", "desc": null, "name": "대파"}, {"qty": "1개", "desc": null, "name": "양파"}, {"qty": "적당히", "desc": null, "name": "양배추"}, {"qty": "", "desc": null, "name": "당근 생략가능"}, {"qty": "1T", "desc": null, "name": "설탕"}, {"qty": "1T", "desc": null, "name": "다진마늘"}, {"qty": "1T", "desc": null, "name": "고추장"}, {"qty": "3T", "desc": null, "name": "고추가루"}, {"qty": "5T", "desc": null, "name": "간장"}, {"qty": "1T", "desc": null, "name": "참기름"}]}'::jsonb);
INSERT INTO recipes (id, recipe_id, source_url, title, servings, cook_time, difficulty, tips, copyright, created_at, updated_at, raw_data) VALUES (290, '6845428', 'https://www.10000recipe.com/recipe/6845428', '제육볶음 만드는법 # 기사식당st 레시피', '2인분', '30분 이내', '초급', '["매실액이없으면 설탕을넣으시되 단맛의 차이가있으니 조금씩넣어서 간을보세요! 고기와야채를 볶을땐 센불로해주셔야 물이생기지않아요 :)"]'::jsonb, '트래블러버클로이', 2025-11-22 23:42:34.564435, 2025-11-23 01:27:03.869030, '{"tips": ["매실액이없으면 설탕을넣으시되 단맛의 차이가있으니 조금씩넣어서 간을보세요! 고기와야채를 볶을땐 센불로해주셔야 물이생기지않아요 :)"], "steps": ["팬에 불을 켜지않고 핏물을 키친타월로 가볍게 제거한 돼지앞다리살1근을 넣고 마늘반스푼, 간장1스푼, 후추가루약간을넣고 조물조물 재워주세요", "고추가루2스푼, 진간장1스푼, 마늘반스푼, 물엿1스푼, 매실액2스푼(없으면 설탕2/3수저로대체), 고추장크게1스푼,후추톡톡해서 양념장을 만들어주시고", "파와 양파 당근등 기호에맞는 채소를 손질해서 준비해주세요", "센불에 고기를 볶다가 반정도 익을때쯤", "당근 양파등을 먼저 넣어 센불에 볶아주세요 ( 약한불에서하면 물이나올수있어요!)", "양파가 반투명해질때쯤 준비된 양념의 2/3을 넣어 볶아줍니다 양념이 들어간뒤로 탈수있으니 중불로 줄여주세요", "고기가 익고난뒤 간을 한번보시고 부족하면 나머지 양념장을 다 넣어주세요 (전다사용했어요!)", "불끄기3분전 나머지 고추와 파등을넣어 센불로 볶아주시면 끝!", "예쁘게 담아서 맛있게드세요 :)"], "title": "제육볶음 만드는법 # 기사식당st 레시피", "servings": "2인분", "cook_time": "30분 이내", "copyright": "트래블러버클로이", "recipe_id": "6845428", "step_tips": [null, null, null, null, null, null, null, null, null], "difficulty": "초급", "source_url": "https://www.10000recipe.com/recipe/6845428", "ingredients": ["돼지고기앞다리살 1근", "양파 1개", "당근 1/3개", "마늘 1스푼", "파 약간", "고추 기호에맞게", "간장 2스푼", "물엿 1스푼", "매실액 2스푼", "고추장 1스푼", "고춧가루 2스푼", "후추가루 약간"], "ingredients_struct": [{"qty": "1근", "desc": null, "name": "돼지고기앞다리살"}, {"qty": "1개", "desc": null, "name": "양파"}, {"qty": "1/3개", "desc": null, "name": "당근"}, {"qty": "1스푼", "desc": null, "name": "마늘"}, {"qty": "약간", "desc": null, "name": "파"}, {"qty": "기호에맞게", "desc": null, "name": "고추"}, {"qty": "2스푼", "desc": null, "name": "간장"}, {"qty": "1스푼", "desc": null, "name": "물엿"}, {"qty": "2스푼", "desc": null, "name": "매실액"}, {"qty": "1스푼", "desc": null, "name": "고추장"}, {"qty": "2스푼", "desc": null, "name": "고춧가루"}, {"qty": "약간", "desc": null, "name": "후추가루"}]}'::jsonb);
INSERT INTO recipes (id, recipe_id, source_url, title, servings, cook_time, difficulty, tips, copyright, created_at, updated_at, raw_data) VALUES (292, '6850626', 'https://www.10000recipe.com/recipe/6850626', '[찌개요리]된장찌개 맛있게 끓이는법,된장찌개 만드는법', '2인분', '30분 이내', '아무나', '[]'::jsonb, '꽃청춘이주부', 2025-11-22 23:45:46.973212, 2025-11-23 01:27:03.893172, '{"tips": [], "steps": ["재료:두부1/2모,양파1/2개,감자1/2개,호박1/3개,대파1/2개,청양고추2개 된장2스푼,마늘1/2스푼,물6컵,다시마,멸치등 (2인분기준으로조리했으며 계랑은 밥숟가락과 종이컵입니다)", "우선 냄비에 물을 6컵을 넣고 다시다나 멸치등 있는재료를 이용해서 육수를 내줍니다. (15분정도 끓여주었어요) 물은 종이컵으로 6컵을 해도, 끓이는동안 증발이 되서 실제로는 4컵이나5컵정도의 양이 됩니다^^", "두부1/2모,양파1/2개,감자1/2개,호박1/3개,대파1/2개,청양고추2개를 먹기 좋은 크기로 잘라서 준비합니다.", "역시 된장찌개는 뚝배기에 해서 먹어야 제맛이죠 멸치육수낸물에 된장을 2스푼을 풀어서 넣어줍니다. 고추장과 달리 된장은 가정에서 쓰시는 된장에 따라서 맛과 간이 틀리니 꼭 처음에는 된장을 1스푼정도만 넣고 끓이다가 간을 맞추어주세요.", "감자를 먼저 넣어줍니다. 감자를 넣고 2분정도 더끓여주면!", "양파와 호박을 넣어주세요.", "그리고 마늘1/2스푼을 넣고,", "청양고추와 대파를 넣어서 조금더 끓여줍니다. 여기서 간을 한번더 봐주신후 부족하다싶으면 된장을 더 풀어주면 됩니다. 물론 짜다면 육수를 더넣으시면 되구요^^", "불을 끄기전 두부를 넣고,", "고추가루 1/2스푼을 넣고 30초만 더끓여주면!!", "보글보글 된장찌개 완성입니다!!! 뭐 사실 재료에 순서없이 다넣고 한꺼번에 호로록 끓여도 된다지요! ㅎㅎㅎ"], "title": "[찌개요리]된장찌개 맛있게 끓이는법,된장찌개 만드는법", "servings": "2인분", "cook_time": "30분 이내", "copyright": "꽃청춘이주부", "recipe_id": "6850626", "step_tips": [null, null, null, null, null, null, null, null, null, null, null], "difficulty": "아무나", "source_url": "https://www.10000recipe.com/recipe/6850626", "ingredients": ["두부 1/2모", "양파 1/2개", "감자 1/2개", "호박 1/3개", "대파 1/2개", "청양고추 2개", "된장 2스푼", "마늘 1/2스푼", "물 6컵", "다시마", "멸치"], "ingredients_struct": [{"qty": "1/2모", "desc": null, "name": "두부"}, {"qty": "1/2개", "desc": null, "name": "양파"}, {"qty": "1/2개", "desc": null, "name": "감자"}, {"qty": "1/3개", "desc": null, "name": "호박"}, {"qty": "1/2개", "desc": null, "name": "대파"}, {"qty": "2개", "desc": null, "name": "청양고추"}, {"qty": "2스푼", "desc": null, "name": "된장"}, {"qty": "1/2스푼", "desc": null, "name": "마늘"}, {"qty": "6컵", "desc": null, "name": "물"}, {"qty": "", "desc": null, "name": "다시마"}, {"qty": "", "desc": null, "name": "멸치"}]}'::jsonb);
INSERT INTO recipes (id, recipe_id, source_url, title, servings, cook_time, difficulty, tips, copyright, created_at, updated_at, raw_data) VALUES (295, '6851792', 'https://www.10000recipe.com/recipe/6851792', '우리집 황금레시피로 카레 만드는 법,카레재료', '3인분', '30분 이내', '아무나', '[]'::jsonb, '꽃청춘이주부', 2025-11-22 23:51:04.235992, 2025-11-23 01:27:03.922758, '{"tips": [], "steps": ["재료:카레가루100g,카레용돼지고기150g 감자큰거1개,당근1/2개,양파2개(중간사이즈),새송이버섯2개 우유200ml,버터1스푼,후추,물800ml,마늘1스푼 소개한 재료는 카레가루 1봉지샀을때 양입니다", "오늘의 주인공 카레가루예요 저는 개인적으로 매운맛을 선호한답니다^^", "우선 제일먼저 해야할일은 카레용돼지고기를 후추로 톡톡세번 그리고 자박하게 잠길정도로 우유를 부어줍니다. 우유와 후추가 돼지고기 특유의 잡내를 잡아준답니다. 15분정도 재워둡니다.", "양파중간사이즈 2개, 감자큰거 1개,당근1/2개,새송이버섯2개(없으면 패스하셔도무관) 을 먹기 좋은 크기로 잘라서 준비합니다.", "카레를 할 냄비를 준비하신후에 버터1스푼과 마늘1스푼을 넣고", "양파썰어둔것을 모두 넣어서 볶아줍니다. 버터를 넣으면 고소한맛이 나서 좋더라구요^^", "양파의 볶는냄새가 맛있게 올라오면 돼지고기재워둔것을 우유도 함께 모두 넣어 보글보글 끓여줍니다. 고기의 색이 변하면,", "감자와 당근을 넣어줍니다.", "감자가 서걱하게 익을정도로 볶아주다가,", "물 800ml를 넣어줍니다.", "물이 보글보글 끓기 시작하면 남은 우유와 새송이버섯을 넣고 카레가루를 넣어줍니다.", "가루가 뭉치지 않게 조금씩 넣어서 충분히 풀면서 끓여준뒤 마지막에 후추톡톡 3번해주면 카레 완성이예요.", "그릇에 밥한공기 퍼서 담고, 옆에 예쁘게 카레를 담아내면~", "한그릇 레시피인 카레만들기 완성입니다!!!"], "title": "우리집 황금레시피로 카레 만드는 법,카레재료", "servings": "3인분", "cook_time": "30분 이내", "copyright": "꽃청춘이주부", "recipe_id": "6851792", "step_tips": [null, null, null, null, null, null, null, null, null, null, null, null, null, null], "difficulty": "아무나", "source_url": "https://www.10000recipe.com/recipe/6851792", "ingredients": ["카레가루 100g", "카레용 돼지고기 150g", "감자 큰거 1개", "당근 1/2개", "양파 중간사이즈 2개", "새송이버섯 2개", "우유 200ml", "버터 1스푼", "후추 약간", "물 800ml", "마늘 1스푼"], "ingredients_struct": [{"qty": "100g", "desc": null, "name": "카레가루"}, {"qty": "150g", "desc": null, "name": "카레용 돼지고기"}, {"qty": "1개", "desc": null, "name": "감자 큰거"}, {"qty": "1/2개", "desc": null, "name": "당근"}, {"qty": "2개", "desc": null, "name": "양파 중간사이즈"}, {"qty": "2개", "desc": null, "name": "새송이버섯"}, {"qty": "200ml", "desc": null, "name": "우유"}, {"qty": "1스푼", "desc": null, "name": "버터"}, {"qty": "약간", "desc": null, "name": "후추"}, {"qty": "800ml", "desc": null, "name": "물"}, {"qty": "1스푼", "desc": null, "name": "마늘"}]}'::jsonb);
INSERT INTO recipes (id, recipe_id, source_url, title, servings, cook_time, difficulty, tips, copyright, created_at, updated_at, raw_data) VALUES (297, '6856975', 'https://www.10000recipe.com/recipe/6856975', '간단하게 쌈장만드는법/집에서 쌈장만들기⊙', '6인분 이상', '10분 이내', '아무나', '["견과류나 양파, 당근, 호박 등을 넣어서 고급진 쌈장을 만들어 봐도 좋을거 같아요."]'::jsonb, '꽃라라', 2025-11-22 23:54:54.130868, 2025-11-23 01:27:03.944501, '{"tips": ["견과류나 양파, 당근, 호박 등을 넣어서 고급진 쌈장을 만들어 봐도 좋을거 같아요."], "steps": ["된장1.5~2큰술,", "고추장1큰술을 넣으며 기본양념을 만들어 주세요. 이떄 된장2 : 고추장 1 비율로 하시면 더욱 맛나게 만드실 수 있을거 같아요 ! (고추장이 없으시면 고춧가루로 해도 무난하답니다)", "다진마늘 1큰술,", "올리고당 1큰술,", "매실액 1큰술, 참기름 약간, 깨소금 약간을 넣고 잘 어우려지도록 섞으면 끝 ! (매실액이 없으시면 생략해셔도 좋아요 !)"], "title": "간단하게 쌈장만드는법/집에서 쌈장만들기⊙", "servings": "6인분 이상", "cook_time": "10분 이내", "copyright": "꽃라라", "recipe_id": "6856975", "step_tips": [null, null, null, null, null], "difficulty": "아무나", "source_url": "https://www.10000recipe.com/recipe/6856975", "ingredients": ["된장 1.5~2큰술", "고추장 1큰술", "다진마늘 1큰술", "올리고당 1큰술", "매실액 1큰술", "참기름 약간", "깨소금 약간"], "ingredients_struct": [{"qty": "1.5~2큰술", "desc": null, "name": "된장"}, {"qty": "1큰술", "desc": null, "name": "고추장"}, {"qty": "1큰술", "desc": null, "name": "다진마늘"}, {"qty": "1큰술", "desc": null, "name": "올리고당"}, {"qty": "1큰술", "desc": null, "name": "매실액"}, {"qty": "약간", "desc": null, "name": "참기름"}, {"qty": "약간", "desc": null, "name": "깨소금"}]}'::jsonb);
INSERT INTO recipes (id, recipe_id, source_url, title, servings, cook_time, difficulty, tips, copyright, created_at, updated_at, raw_data) VALUES (303, '6861312', 'https://www.10000recipe.com/recipe/6861312', '수육 만들기! 보쌈 만드는법어렵지 않아요', '4인분', '120분 이내', '아무나', '[]'::jsonb, '츄츄맘', 2025-11-23 00:04:44.885556, 2025-11-23 01:27:04.004599, '{"tips": [], "steps": ["수육용 고기는 삼겹살이 비계도 고루 있어서 부드럽고 씹힘이 좋아 많이 사용되요! 그래서 저도 항상 수육용고기는 삼겹살로 하고 있답니다 ㅎ", "우선 삼겹살 앞뒤로 후추를 고루고루 잘 뿌려주세요", "그리고 삼겹살 겉면 전체에 굴소스를 발라줍니다", "아무것도 두르지 않은 팬을 미리 달궈서 달아 오르면, 삼겹살을 넣고 겉면을 노릇하게 익혀주세요 미리 팬에 익혀야 육즙이 빠지지 않아 맛있어요!", "냄비에 고기가 푹잠길정도로 물을 넣고 월계수잎과 고기", "된장 2큰술, 파 1대, 마늘 9알, 생강을 넣어 30~40분, 센불 20~30분 중불로 익힌 후 불을 끄고 5분 뜸을 들여 주세요 (저는 파뿌리도 넣었어요)", "어느덧 수육이 맛있게 익었네요 ㅎ 고기가 충분히 잠길정도로 있었던 물이 반으로 줄었어요 ㅎㅎ", "인스턴트커피를 넣지 않았는데도 색이 참 예뻐요♡", "맛있게 잘 익은 고기는 먹기좋게 썰어 접시에 담아 내면 되구요, 썰었는데 혹시 속이 덜 익었다면 다시 익혀 줘야겠죠? 하지만 가능하면 한번에 다 익히는게 좋아요. 그래야 육즙이 빠지지 않아 맛있어진답니다!", "마지막으로 겉절이 올리고 깨소금 팍팍 뿌려줬어요 ㅎㅎ 너무나 맛있게 잘 익은 수육이네요 ㅎㅎ 수육만드는법 별거 없죠???ㅎㅎ"], "title": "수육 만들기! 보쌈 만드는법어렵지 않아요", "servings": "4인분", "cook_time": "120분 이내", "copyright": "츄츄맘", "recipe_id": "6861312", "step_tips": [null, null, null, null, null, null, null, null, null, null], "difficulty": "아무나", "source_url": "https://www.10000recipe.com/recipe/6861312", "ingredients": ["수육용 삼겹살 1근", "굴소스 약간", "후추 조금", "파 1대", "마늘 9알", "된장 2큰술", "생강 작은 것 1개", "월계수잎 4-5잎"], "ingredients_struct": [{"qty": "1근", "desc": null, "name": "수육용 삼겹살"}, {"qty": "약간", "desc": null, "name": "굴소스"}, {"qty": "조금", "desc": null, "name": "후추"}, {"qty": "1대", "desc": null, "name": "파"}, {"qty": "9알", "desc": null, "name": "마늘"}, {"qty": "2큰술", "desc": null, "name": "된장"}, {"qty": "1개", "desc": null, "name": "생강 작은 것"}, {"qty": "4-5잎", "desc": null, "name": "월계수잎"}]}'::jsonb);
INSERT INTO recipes (id, recipe_id, source_url, title, servings, cook_time, difficulty, tips, copyright, created_at, updated_at, raw_data) VALUES (305, '6864674', 'https://www.10000recipe.com/recipe/6864674', '참치김치찌개 황금레시피 맛있게 끓여먹어요~', '2인분', '10분 이내', '아무나', '[]'::jsonb, '뽀새댁', 2025-11-23 00:08:55.464043, 2025-11-23 01:27:04.023818, '{"tips": [], "steps": ["신김치 국그릇 가득, 대파 1뿌리, 참치 1캔, 식용유 3스푼, 고추가루 1스푼, 김치국물 3스푼, 물 400ml", "김치 국그릇 가득 담은 걸 냄비에 옮겨주세요", "식용유 3스푼을 김치위에 돌돌 돌려 뿌려주신 다음 약-중 중간 불에서 달달 볶아주세요", "다음 참치 1캔을 함께 넣어 달달 볶아주세요 이 때 참치캔 기름은 버리지마시고 함께 넣어주세요", "물 400ml를 넣어 끓여주세요", "다음 김치국물 3스푼 넣고 팔팔 끓여줍니다", "계속 끓이다가 대파 한뿌리 송송 썰어주신 걸 넣어주세요~ 다진 마늘 좋아하시면 다진마늘 티스푼으로 1스푼 넣어주셔도 좋아요", "마지막으로 김치찌개 색감을 더 이쁘게, 그리고 얼큰하게 해주기위해 고추가루 1스푼을 넣어준 다음 끓여주시면 끝~", "설 기간동안 기름기 많은 음식들로 느끼했던 속이 얼큰하니 정말 맛있게도 먹었네요~ 저랑 신랑은 얼큰한 국물먹다가 맛있어서 라면 사리 하나 넣어서 다시 끓여먹었답니다", "만드는 법은 정말 간단하지만 맛이 일품이라고 신랑에게 칭찬받은 참치김치찌개 레시피 다른 반찬 없이"], "title": "참치김치찌개 황금레시피 맛있게 끓여먹어요~", "servings": "2인분", "cook_time": "10분 이내", "copyright": "뽀새댁", "recipe_id": "6864674", "step_tips": [null, null, null, null, null, null, null, null, null, null], "difficulty": "아무나", "source_url": "https://www.10000recipe.com/recipe/6864674", "ingredients": ["신김치 1국그릇", "대파 1뿌리", "참치 1캔", "식용유 3스푼", "고추가루 1스푼", "김치국물 3스푼", "물 400ml"], "ingredients_struct": [{"qty": "1국그릇", "desc": null, "name": "신김치"}, {"qty": "1뿌리", "desc": null, "name": "대파"}, {"qty": "1캔", "desc": null, "name": "참치"}, {"qty": "3스푼", "desc": null, "name": "식용유"}, {"qty": "1스푼", "desc": null, "name": "고추가루"}, {"qty": "3스푼", "desc": null, "name": "김치국물"}, {"qty": "400ml", "desc": null, "name": "물"}]}'::jsonb);
INSERT INTO recipes (id, recipe_id, source_url, title, servings, cook_time, difficulty, tips, copyright, created_at, updated_at, raw_data) VALUES (308, '6867256', 'https://www.10000recipe.com/recipe/6867256', '백종원레시피로 만든 콩나물무침으로 밥 한 끼 뚝딱 ~', '2인분', '10분 이내', '아무나', '[]'::jsonb, '뽕림이', 2025-11-23 00:14:29.101177, 2025-11-23 01:27:04.053554, '{"tips": [], "steps": ["콩나물은 흐르는 물에 여러 번 조심스레 씻어준 뒤 체에 밭쳐 물기를 빼둡니다. 당근은 색내기용으로 조금 넣어줬어요. 안 넣으셔도 무방합니다. 대파도 송송 잘라 준비합니다.", "냄비에 물이 끓기 시작하면 소금 반 큰 술과 콩나물을 넣어줍니다. 콩나물은 센 불에서 팔팔 끓여주시고요. 데치는 시간은 양에 따라 달라지는데요. 보통 4-6분 사이가 적당하다고 하니 참고하세요! 뽕림이는 5분 정도 삶아주니까 딱 좋더라고요.", "데친 콩나물은 체에 밭쳐 물기를 충분히 빼주세요.", "어느 정도 물기가 빠졌다면 볼에 콩나물을 넣고, 채 썬 당근, 대파를 넣어줍니다.", "그리고 나서 고춧가루 2 큰 술, 소금 적당량, 다진 마늘 반 큰 술, 깨소금을 적당량 넣어주세요.", "진간장도 한 큰 술 투척한 뒤 콩나물 대가리가 떨어지지 않도록 조심스레 섞어주세요.", "마지막으로 참기름 한 큰 술 두르고 조물조물해준 뒤 맛을 봐주세요. 약간 싱거우시다면 간장 또는 소금으로 간을 해주시면 됩니다.", "저는 딱 좋더라는 ^^", "이렇게 10분 만에 완성된 초간단 콩나물무침! 오늘도 백종원 아저씨의 레시피 덕분에 힘들이지 않고 반찬 하나 뚝딱 만들었네요 ^^"], "title": "백종원레시피로 만든 콩나물무침으로 밥 한 끼 뚝딱 ~", "servings": "2인분", "cook_time": "10분 이내", "copyright": "뽕림이", "recipe_id": "6867256", "step_tips": [null, null, null, null, null, null, null, null, null], "difficulty": "아무나", "source_url": "https://www.10000recipe.com/recipe/6867256", "ingredients": ["콩나물 1봉지", "대파 또는 쪽파 1/6대", "당근 1/5개", "고춧가루 2큰술", "다진 마늘 1/2큰술", "참기름 1큰술", "진간장 1큰술", "소금 취향껏", "깨소금 적당량"], "ingredients_struct": [{"qty": "1봉지", "desc": null, "name": "콩나물"}, {"qty": "1/6대", "desc": null, "name": "대파 또는 쪽파"}, {"qty": "1/5개", "desc": null, "name": "당근"}, {"qty": "2큰술", "desc": null, "name": "고춧가루"}, {"qty": "1/2큰술", "desc": null, "name": "다진 마늘"}, {"qty": "1큰술", "desc": null, "name": "참기름"}, {"qty": "1큰술", "desc": null, "name": "진간장"}, {"qty": "취향껏", "desc": null, "name": "소금"}, {"qty": "적당량", "desc": null, "name": "깨소금"}]}'::jsonb);
INSERT INTO recipes (id, recipe_id, source_url, title, servings, cook_time, difficulty, tips, copyright, created_at, updated_at, raw_data) VALUES (311, '6868260', 'https://www.10000recipe.com/recipe/6868260', '파김치 황금레시피,파김치 담그는법', '4인분', '30분 이내', '초급', '["쪽파머리부분이 두꺼우면 비슷한 크기로 쪼개주시면 더 맛있게 드실수 있어요."]'::jsonb, '눈꽃식탁', 2025-11-23 00:20:14.005816, 2025-11-23 01:28:47.963637, '{"tips": ["쪽파머리부분이 두꺼우면 비슷한 크기로 쪼개주시면 더 맛있게 드실수 있어요."], "steps": ["쪽파는 깨끗이 다듬고 흐르는 물에 깨끗이 씻어주세요. 물기를 제거해주세요.", "설탕2.5Ts,고춧가루 15Ts,물10Ts,멸치액젓15Ts,다진마늘3Ts를 만들어 놓고", "쟁반에 파를 조금씩 잡고 골고루 조금씩 뭍혀주세요. 머리부분에 더 꼼꼼히 발라주셔야 좋아요.", "먹기좋을 정도로 돌돌말아주셔도 좋고 그냥 펴서 켜켜히 담고 살짝 눌러주세요."], "title": "파김치 황금레시피,파김치 담그는법", "servings": "4인분", "cook_time": "30분 이내", "copyright": "눈꽃식탁", "recipe_id": "6868260", "step_tips": [null, null, null, null], "difficulty": "초급", "source_url": "https://www.10000recipe.com/recipe/6868260", "ingredients": ["쪽파 1단", "설탕 2.5Ts", "고춧가루 15Ts", "물 10Ts", "멸치액젓 15Ts", "다진마늘 3Ts"], "ingredients_struct": [{"qty": "1단", "desc": null, "name": "쪽파"}, {"qty": "2.5Ts", "desc": null, "name": "설탕"}, {"qty": "15Ts", "desc": null, "name": "고춧가루"}, {"qty": "10Ts", "desc": null, "name": "물"}, {"qty": "15Ts", "desc": null, "name": "멸치액젓"}, {"qty": "3Ts", "desc": null, "name": "다진마늘"}]}'::jsonb);
INSERT INTO recipes (id, recipe_id, source_url, title, servings, cook_time, difficulty, tips, copyright, created_at, updated_at, raw_data) VALUES (313, '6869539', 'https://www.10000recipe.com/recipe/6869539', '꼬막무침 삶는방법부터 양념장까지 완벽하게!!', '3인분', '60분 이내', '아무나', '[]'::jsonb, '뚱이네♡', 2025-11-23 00:23:57.659775, 2025-11-23 01:31:26.135412, '{"tips": [], "steps": ["꼬막은 깨지거나 흠이 없고 색과 골이 선명한 것이 좋아요!", "장갑을 끼고 소금물에 조개를 넣고 바락바락 씻어주세요 2. 처음에는 모래나 껍질등이 나오다가 3~4번 씻다보면 깨끗한 물이 나옵니다 3.바닷물과 비슷하게 만든 소금물에 조개를 넣고 까만봉지나 호일을 덮어 어둡게 만들어주면 안에 있던 뻘을 뱉아내요", "꼬막을 데칠때는 물이 끓으려고 할때 꼬막을 넣고 15바퀴정도 젓가락을 이용해 같은 방향으로 저어주세요 그래야 꼬막살이 한쪽으로 붙어있어요", "꼬막 세개쯤 입을 열면 조개만 잘 건져주세요 찬물에 헹구면 안되요^^", "분량대로 양념장을 만들어주세요", "한김식은 꼬막은 뒤쪽으로 숟가락을 넣고 비틀어서 껍질을 까주세요", "그런다음 꼬막에 양념장을 올려주면 완성!!"], "title": "꼬막무침 삶는방법부터 양념장까지 완벽하게!!", "servings": "3인분", "cook_time": "60분 이내", "copyright": "뚱이네♡", "recipe_id": "6869539", "step_tips": [null, null, null, null, null, null, null], "difficulty": "아무나", "source_url": "https://www.10000recipe.com/recipe/6869539", "ingredients": ["꼬막 500g", "고춧가루 2T", "설탕 1T", "간장 4T", "맛술 0.5T", "참기름 0.5T", "다진마늘 0.5T", "다진파 2T", "깨 솔솔"], "ingredients_struct": [{"qty": "500g", "desc": null, "name": "꼬막"}, {"qty": "2T", "desc": null, "name": "고춧가루"}, {"qty": "1T", "desc": null, "name": "설탕"}, {"qty": "4T", "desc": null, "name": "간장"}, {"qty": "0.5T", "desc": null, "name": "맛술"}, {"qty": "0.5T", "desc": null, "name": "참기름"}, {"qty": "0.5T", "desc": null, "name": "다진마늘"}, {"qty": "2T", "desc": null, "name": "다진파"}, {"qty": "솔솔", "desc": null, "name": "깨"}]}'::jsonb);
INSERT INTO recipes (id, recipe_id, source_url, title, servings, cook_time, difficulty, tips, copyright, created_at, updated_at, raw_data) VALUES (314, '6870256', 'https://www.10000recipe.com/recipe/6870256', '백종원오이무침,초간단오이무침 만드는 법', '2인분', '15분 이내', '아무나', '[]'::jsonb, '꽃청춘이주부', 2025-11-23 00:25:55.931181, 2025-11-23 01:31:26.213442, '{"tips": [], "steps": ["백종원오이무침,초간단오이무침 만드는 법", "재료:오이2개,양파1/2개,굵은소금1스푼 양념재료:고추가루2스푼,설탕1스푼,매실액1스푼,간장2스푼,다진마늘1/2스푼,식초2스푼,깨1스푼 계량은 밥숟가락기준", "오이2개를 준비해주세요. 오이의 겉면은 소금으로 씻어준뒤 겉 껍질을 조금만 제거해주세요[이미지참고] 껍질을 모두 제거해 버리면 식감이 좋지 않아요^^", "오이를 먹기 좋은 크기로 잘라주세요 썰어둔 오이에 굵은 소금1스푼을 넣고 소금에 10분정도 절여줍니다.", "오이를 절이는 동안 양파 1/2개를 준비한뒤 채썰어주세요.", "10분여가 지나고 나면 오이를 찬물에 헹구어 체어 걸러서 물기를 제거해주세요.", "[오이무침 양념장 만들기] 고추가루2스푼,설탕1스푼,매실액1스푼,간장2스푼,다진마늘1/2스푼,식초2스푼,깨1스푼", "양념장을 골고루 섞어줍니다.", "큰 그릇을 준비한뒤 만들어 놓은 양념장과 양파,오이를 한곳넣고~", "살살살 버무려 주세요.", "요즘 오이가 엄청 저렴하니 아삭한 식감에 맛있는 오이무침 어떠신가요?"], "title": "백종원오이무침,초간단오이무침 만드는 법", "servings": "2인분", "cook_time": "15분 이내", "copyright": "꽃청춘이주부", "recipe_id": "6870256", "step_tips": [null, null, null, null, null, null, null, null, null, null, null], "difficulty": "아무나", "source_url": "https://www.10000recipe.com/recipe/6870256", "ingredients": ["오이 2개", "양파 1/2개", "굵은소금 1스푼", "고추가루 2스푼", "설탕 1스푼", "매실액 1스푼", "간장 2스푼", "다진마늘 1/2스푼", "식초 2스푼", "깨 1스푼"], "ingredients_struct": [{"qty": "2개", "desc": null, "name": "오이"}, {"qty": "1/2개", "desc": null, "name": "양파"}, {"qty": "1스푼", "desc": null, "name": "굵은소금"}, {"qty": "2스푼", "desc": null, "name": "고추가루"}, {"qty": "1스푼", "desc": null, "name": "설탕"}, {"qty": "1스푼", "desc": null, "name": "매실액"}, {"qty": "2스푼", "desc": null, "name": "간장"}, {"qty": "1/2스푼", "desc": null, "name": "다진마늘"}, {"qty": "2스푼", "desc": null, "name": "식초"}, {"qty": "1스푼", "desc": null, "name": "깨"}]}'::jsonb);
INSERT INTO recipes (id, recipe_id, source_url, title, servings, cook_time, difficulty, tips, copyright, created_at, updated_at, raw_data) VALUES (318, '6872350', 'https://www.10000recipe.com/recipe/6872350', '식당에서 먹던 맛과 비주얼 그대로, 폭탄 계란찜 만드는 법', '2인분', '15분 이내', '초급', '[]'::jsonb, '뽕림이', 2025-11-23 00:32:05.085730, 2025-11-23 01:31:26.244798, '{"tips": [], "steps": ["폭탄계란찜을 만들기 전 재료부터 준비해줍니다. 계란 3개, 참기름 1 큰 술, 소금 1/3 큰 술, 설탕 1/3 큰 술, 대파 또는 쪽파 약간, 통깨 조금, 물 100ml", "작은 뚝배기에 계란 3개를 깨뜨려 넣은 뒤 거품기로 계란을 풀어줍니다", "설탕 1/3 큰 술, 소금 1/3 큰 술을 넣고 한 번 더 거품기로 잘 섞어주기!", "그리고 나서 물 100ml를 넣어주고 또 한 번 거품기로 휘리릭 ~", "뚝배기를 가스레인지에 올린 뒤 계란이 몽글몽글 익을 때까지 젓가락으로 저어줍니다. 중불입니다.", "이렇게 계란이 몽글몽글해지면,", "송송 썰어둔 쪽파를 투척한 뒤 뚜껑을 닫고 4-5분가량 익혀주세요.", "4-5분 후 뚜껑을 열어보면, 아주 먹음직스럽게 부풀어 오른 계란찜을 만나볼 수 있다는!!! +_+", "부풀어 오른 계란찜 위에 적당량의 통깨와 참기름을 뿌려주면 폭탄 계란찜 만드는 법은 이렇게 간단하게 끝이 나요!", "계란찜 만들기가 이렇게 쉬운 거였나 싶을 정도로 넘나 쉬웠던 폭탄 계란찜 만들기 ♥", "뜨거운 계란찜을 한 숟가락 퍼서 맛을 보니, 대박 ㅠㅠㅠㅠㅠㅠㅠㅠ 이거 진짜 식당에서 먹던 바로 그 계란찜 맛이네요 ㅎㅎㅎ 역시 백주부님 레시피는 진짜 최고 최고 ♪"], "title": "식당에서 먹던 맛과 비주얼 그대로, 폭탄 계란찜 만드는 법", "servings": "2인분", "cook_time": "15분 이내", "copyright": "뽕림이", "recipe_id": "6872350", "step_tips": ["반찬접시", "뚝배기", null, null, null, "나무요리젓가락", null, null, null, "나무수저세트", null], "difficulty": "초급", "source_url": "https://www.10000recipe.com/recipe/6872350", "ingredients": ["계란 3개", "소금 1/3큰술", "설탕 1/3큰술", "대파 또는 쪽파 적당량", "통깨 적당량", "참기름 1큰술", "물 100ml"], "ingredients_struct": [{"qty": "3개", "desc": null, "name": "계란"}, {"qty": "1/3큰술", "desc": null, "name": "소금"}, {"qty": "1/3큰술", "desc": null, "name": "설탕"}, {"qty": "적당량", "desc": null, "name": "대파 또는 쪽파"}, {"qty": "적당량", "desc": null, "name": "통깨"}, {"qty": "1큰술", "desc": null, "name": "참기름"}, {"qty": "100ml", "desc": null, "name": "물"}]}'::jsonb);
INSERT INTO recipes (id, recipe_id, source_url, title, servings, cook_time, difficulty, tips, copyright, created_at, updated_at, raw_data) VALUES (323, '6876544', 'https://www.10000recipe.com/recipe/6876544', '미역줄기볶음 짜지 않게 비린내 없이!', '2인분', '30분 이내', '아무나', '[]'::jsonb, '베리츄', 2025-11-23 00:42:28.746277, 2025-11-23 01:34:44.762919, '{"tips": [], "steps": ["염장 미역줄기는 흐르는 물에 3-4번 정도 씻은 후 찬물에 15분간 담가 소금기를 빼주세요.", "미역줄기는 물기를 꼭 짠 뒤 한입 크기(4cm)로 썰어주세요.", "양파와 당근은 채 썰어주세요.", "팬에 식용유를 두르고 중불에서 다진마늘 1큰술을 볶아주세요.", "향이 올라오면 강불로 올려 채썬 양파와 당근을 넣고 1분간 볶아주세요.", "미역줄기를 넣고 1분, 국간장 1/2큰술을 넣고 3분 볶아주세요.", "참기름 1큰술과 깨 1/2큰술을 넣어 30초간 더 볶아주면 완성이에요."], "title": "미역줄기볶음 짜지 않게 비린내 없이!", "servings": "2인분", "cook_time": "30분 이내", "copyright": "베리츄", "recipe_id": "6876544", "step_tips": [null, null, null, null, null, null, null], "difficulty": "아무나", "source_url": "https://www.10000recipe.com/recipe/6876544", "ingredients": ["염장 미역줄기 300g 1팩", "당근 1/6개", "양파(중) 1/3개", "식용유 2큰술", "다진마늘 1큰술", "국간장 1/2큰술", "참기름 1큰술", "깨 1/2큰술"], "ingredients_struct": [{"qty": "1팩", "desc": null, "name": "염장 미역줄기 300g"}, {"qty": "1/6개", "desc": null, "name": "당근"}, {"qty": "1/3개", "desc": null, "name": "양파(중)"}, {"qty": "2큰술", "desc": null, "name": "식용유"}, {"qty": "1큰술", "desc": null, "name": "다진마늘"}, {"qty": "1/2큰술", "desc": null, "name": "국간장"}, {"qty": "1큰술", "desc": null, "name": "참기름"}, {"qty": "1/2큰술", "desc": null, "name": "깨"}]}'::jsonb);
INSERT INTO recipes (id, recipe_id, source_url, title, servings, cook_time, difficulty, tips, copyright, created_at, updated_at, raw_data) VALUES (334, '6884636', 'https://www.10000recipe.com/recipe/6884636', '부대찌개 양념 만드는법 홀릭되는 맛임', '2인분', '30분 이내', '초급', '[]'::jsonb, '블레스그레이스', 2025-11-23 01:02:43.760978, 2025-11-23 01:42:24.842598, '{"tips": [], "steps": ["고추는 어슷썰고 두부는 한입크기로 썰어주세요.", "스팸은 반드시 얇게 잘라주세요. 두꺼우면 국물 맛이 제대로 안 배고 맛이 따로 놀아요. 비엔나는 사선으로 잘라주세요.", "떡은 너무 많이 넣으면 국물이 텁텁해지므로 반드시 1줌만 넣어주세요.", "김치도 많이 넣으면 김치맛이 많이 나요. 적당한 밸런스가 중요한데요. 밥공기 1/4 넣어주세요.", "된장반큰술,고추가루 4큰술(듬뿍), 마늘2큰술, 국간장2큰술, 설탕반큰술, 물 소주컵 반컵을 섞어주세요.", "두부, 햄, 떡을 테두리에 두르고 김치는 가운데 넣어주세요.", "양념장 올려주세요.", "사골곰탕 육수를 1봉지 붓고", "물 보충을 해주세요.", "대파와 청양고추 홍고추 모두 올려주세요.", "이제 팔팔 끓입니다.", "청양고추와 대파가 어우러져 매콤한 향이 올라와요. 냄새부터 다르답니다.", "부대찌개 만드는법 이대루 하면 반드시 성공!", "라면은 먹다가 나중에 추가해서 먹어도 되구요~ 저는 팔팔 끓인 후 바로 넣어줬어요.", "라면을 끓이려면 국물이 여유가 있어야 해요. 라면 넣기 전 육수가 너무 졸았다면 물 보충을 해주고 끓이세요.", "짜잔 요 정도 국물이어야 맛있답니다.", "칼칼하면서 진한 맛이랍니다. 부대찌개 완성!"], "title": "부대찌개 양념 만드는법 홀릭되는 맛임", "servings": "2인분", "cook_time": "30분 이내", "copyright": "블레스그레이스", "recipe_id": "6884636", "step_tips": [null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null], "difficulty": "초급", "source_url": "https://www.10000recipe.com/recipe/6884636", "ingredients": ["김치 1줌 1/4밥그릇", "비엔나 20개", "스팸 1개", "두부 1/3모", "떡 1줌", "대파 10센티 4개", "홍고추 2개", "청양고추 큰거 2개", "사골곰탕 1봉지", "된장 1/2큰술", "고추가루 4큰술", "마늘 2큰술", "국간장 2큰술", "설탕 1/2큰술", "물 1/2소주컵"], "ingredients_struct": [{"qty": "1/4밥그릇", "desc": null, "name": "김치 1줌"}, {"qty": "20개", "desc": null, "name": "비엔나"}, {"qty": "1개", "desc": null, "name": "스팸"}, {"qty": "1/3모", "desc": null, "name": "두부"}, {"qty": "1줌", "desc": null, "name": "떡"}, {"qty": "4개", "desc": null, "name": "대파 10센티"}, {"qty": "2개", "desc": null, "name": "홍고추"}, {"qty": "2개", "desc": null, "name": "청양고추 큰거"}, {"qty": "1봉지", "desc": null, "name": "사골곰탕"}, {"qty": "1/2큰술", "desc": null, "name": "된장"}, {"qty": "4큰술", "desc": null, "name": "고추가루"}, {"qty": "2큰술", "desc": null, "name": "마늘"}, {"qty": "2큰술", "desc": null, "name": "국간장"}, {"qty": "1/2큰술", "desc": null, "name": "설탕"}, {"qty": "1/2소주컵", "desc": null, "name": "물"}]}'::jsonb);
INSERT INTO recipes (id, recipe_id, source_url, title, servings, cook_time, difficulty, tips, copyright, created_at, updated_at, raw_data) VALUES (337, '6886360', 'https://www.10000recipe.com/recipe/6886360', '쉽고 간단하게 ''냄비밥'' 하는 법', '2인분', '60분 이내', '중급', '["저렇게 하면 2~3공기 분량의 밥이 나와요."]'::jsonb, '녜딘Nyedin', 2025-11-23 01:08:22.698625, 2025-11-23 01:45:33.696149, '{"tips": ["저렇게 하면 2~3공기 분량의 밥이 나와요."], "steps": ["제일 먼저 2컵 분량의 쌀을 깨끗하게 씻어주신 뒤 물에 30분 불려줍니다.", "30분이 지난 후, 쌀 2컵 + 물 2컵 반을 냄비에 넣고 센 불에 올려줍니다.", "그럼 몇 분 지나지 않아 금방 물이 끓어오릅니다. 그 때 뚜껑을 열어주세요.", "물이 조금 줄어들면 중불로 불을 줄여줍니다.", "물이 많이 줄어들었다면 약불로 줄여주세요. 그리고 물기가 하나도 없이 타닥타닥 소리가 난다면 불을 꺼주세요!", "불을 끄고 뚜껑을 닫고 5분간 뜸을 들여줍니다.", "바닥에 달라붙지 않고 꼬슬꼬슬한 밥이 완성됐어요~"], "title": "쉽고 간단하게 ''냄비밥'' 하는 법", "servings": "2인분", "cook_time": "60분 이내", "copyright": "녜딘Nyedin", "recipe_id": "6886360", "step_tips": [null, "냄비", null, null, null, null, null], "difficulty": "중급", "source_url": "https://www.10000recipe.com/recipe/6886360", "ingredients": ["쌀 360ml 2컵", "물 450ml 2.5컵"], "ingredients_struct": [{"qty": "2컵", "desc": null, "name": "쌀 360ml"}, {"qty": "2.5컵", "desc": null, "name": "물 450ml"}]}'::jsonb);
INSERT INTO recipes (id, recipe_id, source_url, title, servings, cook_time, difficulty, tips, copyright, created_at, updated_at, raw_data) VALUES (339, '6887815', 'https://www.10000recipe.com/recipe/6887815', '아삭한 봄동 겉절이', '2인분', '15분 이내', '초급', '["*겉절이할때 소금에 절이지 않고 바로 무치면 아삭한 식감을 살릴 수 있어요 : )"]'::jsonb, '마튈다', 2025-11-23 01:11:54.679486, 2025-11-23 01:45:33.712020, '{"tips": ["*겉절이할때 소금에 절이지 않고 바로 무치면 아삭한 식감을 살릴 수 있어요 : )"], "steps": ["봄동은 잎을 하나씩 떼어 흐르는 물에 여러번 씻어 주세요.", "뿌리쪽은 짤라내고 잎 사이즈에 따라 3등분에서 6등분으로 잘라주세요.", "다진마늘 ½T, 멸치액젓 2T, 매실액2T, 참기름 2T, 설탕 1수저, 고춧가루3T, 통깨 듬뿍, 소금 살짝 넣어주세요.", "조물조물 버무려 주세요.", "아삭아삭 봄동 겉절이 완성입니다."], "title": "아삭한 봄동 겉절이", "servings": "2인분", "cook_time": "15분 이내", "copyright": "마튈다", "recipe_id": "6887815", "step_tips": [null, null, null, null, null], "difficulty": "초급", "source_url": "https://www.10000recipe.com/recipe/6887815", "ingredients": ["봄동 1다발", "고춧가루 3T", "멸치액젓 2T", "매실액 2T", "설탕 1T", "참기름 2T", "다진마늘 1/2T", "통깨 듬뿍", "소금 살짝"], "ingredients_struct": [{"qty": "1다발", "desc": null, "name": "봄동"}, {"qty": "3T", "desc": null, "name": "고춧가루"}, {"qty": "2T", "desc": null, "name": "멸치액젓"}, {"qty": "2T", "desc": null, "name": "매실액"}, {"qty": "1T", "desc": null, "name": "설탕"}, {"qty": "2T", "desc": null, "name": "참기름"}, {"qty": "1/2T", "desc": null, "name": "다진마늘"}, {"qty": "듬뿍", "desc": null, "name": "통깨"}, {"qty": "살짝", "desc": null, "name": "소금"}]}'::jsonb);
INSERT INTO recipes (id, recipe_id, source_url, title, servings, cook_time, difficulty, tips, copyright, created_at, updated_at, raw_data) VALUES (432, '7044262', 'https://www.10000recipe.com/recipe/7044262', '초간단 계란국 끓이는 법 기본계란국 레시피', '2인분', '10분 이내', '초급', '["육수팩이 없으시면 더 간단히 알약육수를 넣어주셔도 된답니다."]'::jsonb, '윤씨네키친', 2025-11-23 02:38:50.082805, 2025-11-23 02:38:50.082805, '{"tips": ["육수팩이 없으시면 더 간단히 알약육수를 넣어주셔도 된답니다."], "steps": ["냄비에 물 600ml를 올려주고 육수팩을 넣어 끓여주세요. 물이 끓어오르면 중불로 맞춰주시고 5분 더 끓여 주세요.", "계란2알은 풀어 준비해주세요.", "대파는 어슷썰기해 준비해주세요.", "5분이 지나면 육수팩을 건져주세요.", "계란물을 빙 둘러 넣어주세요. 그리고 바로 저으면 계란이 풀어지기 때문에 젓지말고 덩어리 지게 익혀주세요.", "참치액 1t 로 간을 맞춰 줍니다.", "대파를 넣어주시고 한소끔 끓으면 불을 꺼주세요.", "간이 부족하시다면 소금으로 간을 더 맞춰주시면 됩니다."], "title": "초간단 계란국 끓이는 법 기본계란국 레시피", "servings": "2인분", "cook_time": "10분 이내", "copyright": "윤씨네키친", "recipe_id": "7044262", "step_tips": ["냄비", "거품기", "도마", "젓가락", null, null, null, "그릇"], "difficulty": "초급", "source_url": "https://www.10000recipe.com/recipe/7044262", "ingredients": ["계란 2알", "물 600ml", "대파 1/2대", "액젓 1t", "소금 1꼬집", "육수팩 한알육수 대체가능 1개"], "ingredients_struct": [{"qty": "2알", "desc": null, "name": "계란"}, {"qty": "600ml", "desc": null, "name": "물"}, {"qty": "1/2대", "desc": null, "name": "대파"}, {"qty": "1t", "desc": null, "name": "액젓"}, {"qty": "1꼬집", "desc": null, "name": "소금"}, {"qty": "1개", "desc": null, "name": "육수팩 한알육수 대체가능"}]}'::jsonb);
INSERT INTO recipes (id, recipe_id, source_url, title, servings, cook_time, difficulty, tips, copyright, created_at, updated_at, raw_data) VALUES (433, '7044402', 'https://www.10000recipe.com/recipe/7044402', '고사리볶음 레시피/ 말린고사리 마른고사리 삶는 법/ 건고사리 불리기', '6인분 이상', '2시간 이상', '초급', '[]'::jsonb, '심플민', 2025-11-23 02:40:06.017076, 2025-11-23 02:40:06.017076, '{"tips": [], "steps": ["마른 고사리를 먼저 부드럽게 불리는 작업부터 합니다. 바싹 마른 건고사리로 충분히 불리는 시간이 필요했어요. 보통 5시간가량 불림해주는데 이번엔 부모님께서 더 바싹 말린 상태의 고사리를 보내주셔서 5시간으로도 좀 부드러움이 부족하여 1시간가량 더 불려주었습니다. 이렇게 건고사리의 상태에 따라 불리는 시간을 조금씩 가감해 주시면 좋아요.", "불리는 시간 동안 중간 두세 차례 물을 바꿔주면서 불려주면 특유 향도 제거하면서 깨끗하게 불리는데 도움이 됩니다.", "불리는 사이 볶는 양념과 함께 필요한 파 소량 잘게 썰어 준비합니다. 대략 3 큰 술 가량 정도면 되어요.", "5~6시간 불린 모습이고요. 말린 고사리가 제법 통통해졌고요. 너무 무르지 않게 적당하게 불린 상태에서 건져 가볍게 헹구어준 후 삶아 줄 준비를 합니다.", "잠길 정도의 적당량의 물과 함께 약간 센 불에서 냄비에 끓여줍니다. 끓기 시작하면 중불로 줄여준 뒤 15분가량 삶아줍니다.", "어느 정도 시간이 지나면 삶은 정도를 체크해 봅니다. 더 부드러운 시감을 원할 땐 시간을 좀 더 두고 삶아주고요. 적당하면 불을 끄고 뚜껑을 덮은 그대로의 상태에서 20분 정도 뜸을 들이듯 더 두도록 해요.", "이제 삶은 작업까지 모두 끝나면 채반에 두고 찬물에 헹구어 주어 양념에 버무려 볶아주도록 할게요.", "물기를 꾹 짠 상태로 양념할 볼에 넣어주세요. 길기 때문에 가위로 두세 차례 듬성듬성 썰어주면 좋아요.", "국간장 1 큰 술 참치액 2/3 큰 술 다진마늘 1 큰 술 위 분량의 양념재료를 넣고 조물조물 밑간 양념을 먼저 해주도록 해요.", "달군 팬에 식용유 3 큰 술 정도를 넣고 밑간 한 고사리를 넣고 볶아줍니다. 양념이 고루 배도록 4~5분가량 고루 섞어가면서 볶아주세요.", "마지막으로 썰어놓은 파와 들기름 1~2 큰 술을 넣고 고루 섞어 가볍게 볶으며 고소하게 마무리합니다. 간을 보고 싱거울 경우 소금 소량으로 맞추면 되어요. 적당한 부드러움으로 맛 좋은 산나물 밑반찬 즐겼습니다. 이렇게 밑반찬으로도 충분히 좋고요. 고추장 추가해 밥에 쓱쓱 비벼 먹는 비빔밥으로 즐겨도 한 그릇 덮밥으로 최고 재료가 되어줍니다. 볶는 과정에서 감칠맛이 더욱 배어 고기 이상으로 맛과 식감 모두 잡을 수 있어 개인적으로 참 좋아하는 나물인데요. 산에서 나는 소고기라고 불리는 이유가 따로 있는 게 아닐 만큼 영양이나 맛 가득한 고사리로 다가오는 대보름 나물 반찬으로 맛있게 만들어 보시기 바랍니다."], "title": "고사리볶음 레시피/ 말린고사리 마른고사리 삶는 법/ 건고사리 불리기", "servings": "6인분 이상", "cook_time": "2시간 이상", "copyright": "심플민", "recipe_id": "7044402", "step_tips": ["믹싱볼", null, "도마", null, "냄비", "요리젓가락", "채반", "주방가위", "계량스푼", "볶음팬", null], "difficulty": "초급", "source_url": "https://www.10000recipe.com/recipe/7044402", "ingredients": ["말린고사리 삶은 고사리 300g 50g", "식용유 3큰술", "국간장 1큰술", "참치액 2/3큰술", "다진마늘 1큰술", "다진파 3큰술", "들기름 1~2큰술", "깨 소량"], "ingredients_struct": [{"qty": "50g", "desc": null, "name": "말린고사리 삶은 고사리 300g"}, {"qty": "3큰술", "desc": null, "name": "식용유"}, {"qty": "1큰술", "desc": null, "name": "국간장"}, {"qty": "2/3큰술", "desc": null, "name": "참치액"}, {"qty": "1큰술", "desc": null, "name": "다진마늘"}, {"qty": "3큰술", "desc": null, "name": "다진파"}, {"qty": "1~2큰술", "desc": null, "name": "들기름"}, {"qty": "소량", "desc": null, "name": "깨"}]}'::jsonb);
INSERT INTO recipes (id, recipe_id, source_url, title, servings, cook_time, difficulty, tips, copyright, created_at, updated_at, raw_data) VALUES (434, '7045100', 'https://www.10000recipe.com/recipe/7045100', '당근라페 만들기 당근요리 당근라페 황금레시피', '4인분', '30분 이내', '초급', '["이거 샐러드 처럼 그냥먹어도 좋고 빵에 올려 샌드위치로, 김밥에 넣어 당근라페김밥으로 다양하게 활용하실수 있고 무엇보다도 맛이 최고랍니다. 다이어트에도 좋은거 아시죠? 안해먹을 이유가 없어요"]'::jsonb, '윤씨네키친', 2025-11-23 02:42:22.726685, 2025-11-23 02:42:22.726685, '{"tips": ["이거 샐러드 처럼 그냥먹어도 좋고 빵에 올려 샌드위치로, 김밥에 넣어 당근라페김밥으로 다양하게 활용하실수 있고 무엇보다도 맛이 최고랍니다. 다이어트에도 좋은거 아시죠? 안해먹을 이유가 없어요"], "steps": ["흙당근이라 흙을 깨끗히 씻어주고 필러로 껍질을 제거해주었어요.", "저는 작은크기의 당근이라 6개정도 되는데 큰당근이면 2개정도 분량입니다.", "채칼이나 슬라이서를 이용해 당근을 채썰어주세요. 없으시면 칼로 채썰어주셔도 좋아요.", "볼에 채썬 당근을 넣어주시고 소금 1T를 넣어 절여주세요. 너무 짜게 드시지 않는 분들은 소금양을 조금 줄여서 넣어주세요.", "20-30분후 중간중간 뒤적거려주시면 이렇게 물이 나와요", "물은 버려주시고 손으로 한번 꽉 짜주세요.", "다시 볼에 담아주시고 이제 양념을 넣을께요. 엑스트라버진 올리브오일 6T넣습니다.", "레몬즙은 4T 넣을께요.", "올리고당 4T 넣어주시고", "홀그레인 머스타드 1.5T 넣어줍니다.", "골고루 양념이 잘 묻도록 잘 섞어주세요.", "마지막으로 후추를 뿌려주시면 완성입니다."], "title": "당근라페 만들기 당근요리 당근라페 황금레시피", "servings": "4인분", "cook_time": "30분 이내", "copyright": "윤씨네키친", "recipe_id": "7045100", "step_tips": ["믹싱볼", "주방필러", null, "믹싱볼", "스푼", "위생장갑", null, null, null, null, null, null], "difficulty": "초급", "source_url": "https://www.10000recipe.com/recipe/7045100", "ingredients": ["당근 작은사이즈 약 650g 6개", "소금 절임용 1T", "올리브오일 6T", "레몬즙 4T", "홀그레인머스타드 1.5T", "올리고당 4T", "후추 약간"], "ingredients_struct": [{"qty": "6개", "desc": null, "name": "당근 작은사이즈 약 650g"}, {"qty": "1T", "desc": null, "name": "소금 절임용"}, {"qty": "6T", "desc": null, "name": "올리브오일"}, {"qty": "4T", "desc": null, "name": "레몬즙"}, {"qty": "1.5T", "desc": null, "name": "홀그레인머스타드"}, {"qty": "4T", "desc": null, "name": "올리고당"}, {"qty": "약간", "desc": null, "name": "후추"}]}'::jsonb);
INSERT INTO recipes (id, recipe_id, source_url, title, servings, cook_time, difficulty, tips, copyright, created_at, updated_at, raw_data) VALUES (435, '7046432', 'https://www.10000recipe.com/recipe/7046432', '이것만 알면 OK! 밤 맛있게 삶는 방법', '2인분', '30분 이내', '초급', '[]'::jsonb, '집밥먹는깡주부', 2025-11-23 02:44:12.906340, 2025-11-23 02:44:12.906340, '{"tips": [], "steps": ["밤이 충분히 잠길 정도의 물에 소금 반 숟가락과 밤을 넣어 1시간 정도 담가 둡니다. 소금은 숟가락으로 저어 잘 녹여주세요 이때 물 위로 둥둥 떠오르는 밤은 벌레 먹은 썩은 밤이니 건져냅니다 밤을 물에 충분히 불려주면 나중에 껍질 까기가 한결 수월해요", "1시간 뒤 흐르는 물에 가볍게 헹궈주세요", "냄비에 물을 적당량 붓고 찜기를 올린 후 세척한 밤을 넣어주세요 *찜기가 없다면 물에 바로 넣어 찌셔도 됩니다", "불을 센 불로 올린 후 뚜껑을 닫아요 물이 팔팔 끓어오르면 중약 불로 낮춘 후 20분간 더 쪄주세요 *밤의 크기에 따라서 삶는 시간은 조금씩 조절해 주세요", "20분 후 불을 끄고 뚜껑을 열지 않고 10분간 뜸을 들입니다. 이렇게 뜸 들이는 과정을 거치면 좀 더 포슬포슬한 식감을 즐기실 수 있어요 10분 뒤 열어본 모습이에요 아마도 포슬포슬 맛있게 잘 익었을 거예요", "미리 차가운 얼음물을 준비해서 뜨거운 밤을 바로 넣어주는 것도 중요해요 밤을 얼음 물에 바로 담그는 이유는 이렇게 하면 밤 알맹이와 껍질 사이에 간격이 생겨 껍질 벗기기가 수월하기 때문이에요 메추리알 삶고 나서도 바로 찬물에 담가서 헹궈주면 껍질이 잘 벗겨지잖아유~"], "title": "이것만 알면 OK! 밤 맛있게 삶는 방법", "servings": "2인분", "cook_time": "30분 이내", "copyright": "집밥먹는깡주부", "recipe_id": "7046432", "step_tips": ["믹싱볼", "채반", "냄비", null, null, null], "difficulty": "초급", "source_url": "https://www.10000recipe.com/recipe/7046432", "ingredients": ["생밤 약간", "굵은소금 0.5숟가락", "물 얼음물"], "ingredients_struct": [{"qty": "약간", "desc": null, "name": "생밤"}, {"qty": "0.5숟가락", "desc": null, "name": "굵은소금"}, {"qty": "", "desc": null, "name": "물 얼음물"}]}'::jsonb);
INSERT INTO recipes (id, recipe_id, source_url, title, servings, cook_time, difficulty, tips, copyright, created_at, updated_at, raw_data) VALUES (436, '7048296', 'https://www.10000recipe.com/recipe/7048296', '주꾸미볶음 대박집 쭈꾸미볶음 양념 레시피! 주꾸미 손질법', '2인분', '30분 이내', '중급', '[]'::jsonb, '태화식품공업(주)', 2025-11-23 02:45:27.447435, 2025-11-23 02:45:27.447435, '{"tips": [], "steps": ["주꾸미는 깨끗하게 손질하고 끓는 물에 10초간 짧게 데쳐주세요.", "분량의 양념을 섞어 양념장을 만들어주세요.", "팬에 기름을 두르고 대파와 양배추를 볶은 후 데친 주꾸미와 양념장을 센불에 빠르게 볶아 완성해주세요."], "title": "주꾸미볶음 대박집 쭈꾸미볶음 양념 레시피! 주꾸미 손질법", "servings": "2인분", "cook_time": "30분 이내", "copyright": "태화식품공업(주)", "recipe_id": "7048296", "step_tips": ["냄비", "소스볼", "볶음팬"], "difficulty": "중급", "source_url": "https://www.10000recipe.com/recipe/7048296", "ingredients": ["주꾸미 500g", "양배추 100g", "대파 1대", "양파 1/2개", "범일고추장 1큰술", "진간장 2.5큰술", "고춧가루 3큰술", "올리고당 2큰술", "설탕 1큰술", "참기름 1큰술", "카레 가루 1/2큰술", "다진 마늘 1/4큰술"], "ingredients_struct": [{"qty": "500g", "desc": null, "name": "주꾸미"}, {"qty": "100g", "desc": null, "name": "양배추"}, {"qty": "1대", "desc": null, "name": "대파"}, {"qty": "1/2개", "desc": null, "name": "양파"}, {"qty": "1큰술", "desc": null, "name": "범일고추장"}, {"qty": "2.5큰술", "desc": null, "name": "진간장"}, {"qty": "3큰술", "desc": null, "name": "고춧가루"}, {"qty": "2큰술", "desc": null, "name": "올리고당"}, {"qty": "1큰술", "desc": null, "name": "설탕"}, {"qty": "1큰술", "desc": null, "name": "참기름"}, {"qty": "1/2큰술", "desc": null, "name": "카레 가루"}, {"qty": "1/4큰술", "desc": null, "name": "다진 마늘"}]}'::jsonb);
INSERT INTO recipes (id, recipe_id, source_url, title, servings, cook_time, difficulty, tips, copyright, created_at, updated_at, raw_data) VALUES (437, '7048974', 'https://www.10000recipe.com/recipe/7048974', '시금치무침 황금레시피 /시금치나물 레시피 /겨울제철반찬', NULL, NULL, '아무나', '[]'::jsonb, '서리Yaam', 2025-11-23 02:46:42.642832, 2025-11-23 02:46:42.642832, '{"tips": [], "steps": ["시금치나물 레시피 시작전에 나물 먼저 데칠게요. 뿌리끝이 달아서 살려서 다듬을게요 칼로 살살 겉에 있는 흙을 긁어주세요", "냄비에 물을 먼저 끓인 후 굵은소금 1숟가락 먼저 넣어주세요. 시금치는 깨끗이 씻은 뒤 끓는물에 넣어주시면 돼요", "너무 오래 삶으면 물러져서 식감이 맛이 없기 때문에 1분~1분 30초정도 살짝만 데쳐주세요", "삶아진 나물은 바로 찬물에 헹궈 열기를 빼주세요 그래야 남은 열기에 더 익지 않아요", "나물 물기를 짜줄땐 너무 꽉 짜면 나물이 말라서 맛이 없으니 적당히 물기를 짜주셔야 해요", "시금치무침 황금레시피 양념은 국간장 1숟가락", "액젓 1숟가락, 다진마늘 1숟가락, 참기름 1숟가락 깨 약간 넣어주시면 돼요 이때 시금치 양이 적다면 국간장, 액젓을 조금만 넣어보시고 싱거우면 조금씩 추가하는 방법으로 간을 맞추면 돼요", "양념을 다 넣었으면 손에 힘을 빼고 살살 조물조물 무쳐주시면 돼요.조금 더 깔끔한 맛을 원하면 다진마늘은 생략하셔도 좋아요 시금치나물 레시피 완성이에요"], "title": "시금치무침 황금레시피 /시금치나물 레시피 /겨울제철반찬", "servings": null, "cook_time": null, "copyright": "서리Yaam", "recipe_id": "7048974", "step_tips": ["조리용나이프", "냄비", null, null, "채반", "믹싱볼", null, null], "difficulty": "아무나", "source_url": "https://www.10000recipe.com/recipe/7048974", "ingredients": ["시금치 1단", "굵은소금 1숟가락", "국간장 1숟가락", "액젓 1숟가락", "다진마늘 1숟가락", "참기름 1숟가락", "깨 약간"], "ingredients_struct": [{"qty": "1단", "desc": null, "name": "시금치"}, {"qty": "1숟가락", "desc": null, "name": "굵은소금"}, {"qty": "1숟가락", "desc": null, "name": "국간장"}, {"qty": "1숟가락", "desc": null, "name": "액젓"}, {"qty": "1숟가락", "desc": null, "name": "다진마늘"}, {"qty": "1숟가락", "desc": null, "name": "참기름"}, {"qty": "약간", "desc": null, "name": "깨"}]}'::jsonb);
INSERT INTO recipes (id, recipe_id, source_url, title, servings, cook_time, difficulty, tips, copyright, created_at, updated_at, raw_data) VALUES (438, '7050395', 'https://www.10000recipe.com/recipe/7050395', '부드러운 소고기장조림레시피', '4인분', '60분 이내', '아무나', '[]'::jsonb, '몽글쿡', 2025-11-23 02:48:24.509055, 2025-11-23 02:48:24.509055, '{"tips": [], "steps": ["우둔살 200g을 끓는 물에 넣고 데친 후 물 500ml에 대파를 넣고 40분~50분 정도 푹 끓여주세요 부드럽고 결이 찢어질 정도예요", "고기 삶은 물은 버리지 말고 체어 걸려서 같이 활용하면 맛이 더 깊어져요 약 2~300ml 정도의 고기 육수가 나와요", "우둔살은 부드럽게 잘 삶아도 질긴 힘줄이나 막이 섞여 있어서 아이 먹일 때 신경 써줘야 해요 힘줄은 질기고 소화도 잘 안되기 때문에 깔끔하게 제거하는 게 좋아요", "고기 삶은 육수와 준비한 양념장 간장 3, 설탕 1, 맛술, 1 ,생강가루 약간, 통마늘 5개를 넣어요 중약불에서 10~15분가량 자작하게 졸여요", "중간에 거품은 걷어내야 깔끔한 우둔살 장조림을 만들 수 있어요.", "알룰로스 0.5 , 간장 1은 간을 보고 부족하다 싶을 때 추가로 넣어 마무리합니다. 국물이 거의 졸아들면 불을 꺼주세요", "정성스럽게 고기를 부드럽게 삶고 양념에 자작하게 졸여 만든 장조림 한통 아이가 먹기 편한 식감이라 밥반찬으로 딱이에요"], "title": "부드러운 소고기장조림레시피", "servings": "4인분", "cook_time": "60분 이내", "copyright": "몽글쿡", "recipe_id": "7050395", "step_tips": ["냄비", null, "요리집게", "요리스푼", null, null, "접시"], "difficulty": "아무나", "source_url": "https://www.10000recipe.com/recipe/7050395", "ingredients": ["우둔살 200g", "육수 2~300ml", "대파 1대", "진간장 4", "설탕 1", "알룰로스 0.5", "맛술 1", "생강가루 0.2작은술", "통마늘 4~5개"], "ingredients_struct": [{"qty": "200g", "desc": null, "name": "우둔살"}, {"qty": "2~300ml", "desc": null, "name": "육수"}, {"qty": "1대", "desc": null, "name": "대파"}, {"qty": "4", "desc": null, "name": "진간장"}, {"qty": "1", "desc": null, "name": "설탕"}, {"qty": "0.5", "desc": null, "name": "알룰로스"}, {"qty": "1", "desc": null, "name": "맛술"}, {"qty": "0.2작은술", "desc": null, "name": "생강가루"}, {"qty": "4~5개", "desc": null, "name": "통마늘"}]}'::jsonb);
INSERT INTO recipes (id, recipe_id, source_url, title, servings, cook_time, difficulty, tips, copyright, created_at, updated_at, raw_data) VALUES (439, '7052977', 'https://www.10000recipe.com/recipe/7052977', '두부간장조림', '2인분', '30분 이내', '초급', '[]'::jsonb, '다시봄', 2025-11-23 02:50:28.618278, 2025-11-23 02:50:28.618278, '{"tips": [], "steps": ["두부 1모를 물기를 모두 제거한후 두툼하게 길게 6등분으로 잘라서 준비합니다.", "두부 1모를 물기를 모두 제거한후 두툼하게 길게 6등분으로 잘라서 준비합니다. 두부가 구워지는 동안에 간장두부조림 양념장을 만들어주세요. 두부조림양념장(간장,설탕,고춧가루,통깨,참기름,매실액)", "두부가 노릇하게 구워지면 미리 만들어둔 양념장을 두부위에 살포시 올려주세요. 뚜껑을 닫아 약불로 양파가 익을때까지 졸여주세요.", "양념장을 두부위에 조심스럽게 올려주세요.", "간장두부조림이 완성이 되었습니다."], "title": "두부간장조림", "servings": "2인분", "cook_time": "30분 이내", "copyright": "다시봄", "recipe_id": "7052977", "step_tips": ["도마", "프라이팬", "접시", null, null], "difficulty": "초급", "source_url": "https://www.10000recipe.com/recipe/7052977", "ingredients": ["두부 1모", "간장 2스푼", "설탕 1스푼", "매실액 1스푼", "고춧가루 1스푼", "통깨 1스푼", "참기름 1스푼", "대파 약간"], "ingredients_struct": [{"qty": "1모", "desc": null, "name": "두부"}, {"qty": "2스푼", "desc": null, "name": "간장"}, {"qty": "1스푼", "desc": null, "name": "설탕"}, {"qty": "1스푼", "desc": null, "name": "매실액"}, {"qty": "1스푼", "desc": null, "name": "고춧가루"}, {"qty": "1스푼", "desc": null, "name": "통깨"}, {"qty": "1스푼", "desc": null, "name": "참기름"}, {"qty": "약간", "desc": null, "name": "대파"}]}'::jsonb);
INSERT INTO recipes (id, recipe_id, source_url, title, servings, cook_time, difficulty, tips, copyright, created_at, updated_at, raw_data) VALUES (440, '7056751', 'https://www.10000recipe.com/recipe/7056751', '소불고기 황금레시피 / 실패 없는 소불고기 양념 만들기', '2인분', '60분 이내', '아무나', '["소불고기 300g이며 고기 좋아하는 성인 2인이 푸짐하게 즐기기 좋은 양이에요. 또, 어린아이를 포함한 4인 가족이 함께 먹기에도 넉넉한 편이에요. 물론 식성에 따라 다를 수 있어요. 간단하지만 든든한 저녁메뉴로 소불고기 추천해요 :)"]'::jsonb, '몽글쿡', 2025-11-23 02:51:41.427735, 2025-11-23 02:51:41.427735, '{"tips": ["소불고기 300g이며 고기 좋아하는 성인 2인이 푸짐하게 즐기기 좋은 양이에요. 또, 어린아이를 포함한 4인 가족이 함께 먹기에도 넉넉한 편이에요. 물론 식성에 따라 다를 수 있어요. 간단하지만 든든한 저녁메뉴로 소불고기 추천해요 :)"], "steps": ["소고기는 키친타월로 핏물을 제거하고, 한 장씩 펼쳐서 먹기 좋게 썰어주세요. 고기 사이에 있는 기름기는 제거해 주세요. 먹기 좋게 손질한 고기는 양념이 더 고루 잘 배고, 질겨질 걱정도 줄어들어요. 양파 1/2개는 채 썰고, 대파 1/2대 어슷하게 썰어주세요. 당근 약간만 채 썰어 준비하고, 표고버섯 2개도 얇게 채 썰어주세요", "진간장 3, 설탕 1, 다진 마늘 1, 다진 파 1, 맛술 1, 참기름 1, 배즙 또는 사과즙 2, 후추 약간, 깨소금 약간을 넣고 잘 섞어 양념장을 만들어주세요. 손질한 소고기를 양념장에 넣고 골고루 버무린 뒤, 냉장고에 20~30분 이상 재워두세요.", "팬에 식용유를 약간 두르고 센 불에서 소 불고기를 볶아주세요.", "고기가 반쯤 익었을 때 준비한 채소를 넣고 함께 볶아주세요.", "국물이 약간 졸아들면 깨를 뿌려 마무리해 주세요. 기호에 따라 참기름을 소량 더해주셔도 좋아요.", "접시에 예쁘게 담아 신선한 채소에 쌈 싸 먹어도 맛있고, 그냥 밥 위에 올려 먹어도 너무 맛있어요."], "title": "소불고기 황금레시피 / 실패 없는 소불고기 양념 만들기", "servings": "2인분", "cook_time": "60분 이내", "copyright": "몽글쿡", "recipe_id": "7056751", "step_tips": ["도마", "믹싱볼", "프라이팬", null, null, "접시"], "difficulty": "아무나", "source_url": "https://www.10000recipe.com/recipe/7056751", "ingredients": ["소고기 불고기용 300g", "양파 1/2개", "대파 1/2대", "당근 약간", "표고버섯 2개", "통깨 약간", "식용유 약간", "진간장 3스푼", "설탕 1스푼", "다진 마늘 1스푼", "다진 파 1스푼", "맛술 1스푼", "참기름 1스푼", "배즙 또는 사과즙 2스푼", "후추 약간", "깨소금 약간"], "ingredients_struct": [{"qty": "300g", "desc": null, "name": "소고기 불고기용"}, {"qty": "1/2개", "desc": null, "name": "양파"}, {"qty": "1/2대", "desc": null, "name": "대파"}, {"qty": "약간", "desc": null, "name": "당근"}, {"qty": "2개", "desc": null, "name": "표고버섯"}, {"qty": "약간", "desc": null, "name": "통깨"}, {"qty": "약간", "desc": null, "name": "식용유"}, {"qty": "3스푼", "desc": null, "name": "진간장"}, {"qty": "1스푼", "desc": null, "name": "설탕"}, {"qty": "1스푼", "desc": null, "name": "다진 마늘"}, {"qty": "1스푼", "desc": null, "name": "다진 파"}, {"qty": "1스푼", "desc": null, "name": "맛술"}, {"qty": "1스푼", "desc": null, "name": "참기름"}, {"qty": "2스푼", "desc": null, "name": "배즙 또는 사과즙"}, {"qty": "약간", "desc": null, "name": "후추"}, {"qty": "약간", "desc": null, "name": "깨소금"}]}'::jsonb);
INSERT INTO recipes (id, recipe_id, source_url, title, servings, cook_time, difficulty, tips, copyright, created_at, updated_at, raw_data) VALUES (441, '7058121', 'https://www.10000recipe.com/recipe/7058121', '바삭한 잔멸치볶음 간단 레시피 / 지리멸치 / 아이 멸치볶음 만드는 법', '6인분 이상', '30분 이내', '초급', '[]'::jsonb, '심플민', 2025-11-23 02:53:43.923497, 2025-11-23 02:53:43.923497, '{"tips": [], "steps": ["마른 팬에 먼저 1차로 볶아줍니다. 타지 않도록 중불에서 살짝 노릇해질 정도로 고르게 저어가면서 볶아 수분을 날려주는 작업을 통해 비린 맛을 제거할 수 있어요. 이때 잔 부스러기가 많이 나왔다면 얇은 채망에 한번 걸러주는 것도 좋습니다. 견과류를 추가할 경우에도 이렇게 한 번 볶아주면 특유의 쩐내를 덜어내는데 도움이 됩니다.", "수분 날려 준 뒤 이제 바삭하게 만들어 줄게요. 식용유 4큰술 가량 넉넉하게 둘러주고요. 기름 코팅을 하며 튀기듯 만들어 줍니다. 넉넉하게 넣을수록 좋지만 너무 많은 기름은 부담스럽기에 적당량만 넣어주세요. 저는 오늘은 올리브유를 활용했습니다.", "미림 3큰술을 추가해 고루 섞어주도록 합니다. 이렇게 1차적으로 조리는 마무리에요. ^^", "미림까지 넣고 바삭하게 만들어 준 멸.치는 불을 끄고 넓게 펼쳐 고루 식혀주도록 합니다. 30분가량 두고요. 이렇게 열기가 식은 상태에서 단맛을 내주는 설탕이나 올리고당을 넣어야 돌처럼 굳지 않고 촉촉하게 만들 수 있답니다.", "20~30분 후 설탕 1큰술, 올리고당 3큰술 둘러 비비듯 고루 섞어줍니다.", "마무리로 깨소금 넉넉하게 넣고 고소하게 마무리합니다. 만들면서 과자처럼 집어먹는 맛이 좋아 볶는 내내 여러 번 먹었네요. ㅎㅎ 육류를 주로 먹는 아이들을 위해 조금씩이라도 꼭 내주는 밑반찬 메뉴로 칼슘 가득한 멸치요리로 이만한 것이 없는 거 같아요. 만드는 방법도 간단하고 말이에요. 저희 집 아이들은 견과류를 좋아하지 않아 생략했지만 기름에 볶아내는 과정 후 취향에 맞는 견과류 추가해 함께 볶아주면 고소한 맛까지 살린 멸.치.볶.음으로 만들 수 있답니다. 더운 여름이라 매일같이 불 쓰는 요리하기 힘들 때 이러한 밑반찬 메뉴 하나 만들어 놓으면 든든하니 휘리릭 만드셔서 도시락 반찬으로도 활용해 보세요."], "title": "바삭한 잔멸치볶음 간단 레시피 / 지리멸치 / 아이 멸치볶음 만드는 법", "servings": "6인분 이상", "cook_time": "30분 이내", "copyright": "심플민", "recipe_id": "7058121", "step_tips": ["프라이팬", "계량스푼", null, null, null, null], "difficulty": "초급", "source_url": "https://www.10000recipe.com/recipe/7058121", "ingredients": ["멸치 150g", "식용유 4큰술", "미림 3큰술", "설탕 1큰술", "올리고당 3큰술", "깨 1큰술"], "ingredients_struct": [{"qty": "150g", "desc": null, "name": "멸치"}, {"qty": "4큰술", "desc": null, "name": "식용유"}, {"qty": "3큰술", "desc": null, "name": "미림"}, {"qty": "1큰술", "desc": null, "name": "설탕"}, {"qty": "3큰술", "desc": null, "name": "올리고당"}, {"qty": "1큰술", "desc": null, "name": "깨"}]}'::jsonb);
INSERT INTO recipes (id, recipe_id, source_url, title, servings, cook_time, difficulty, tips, copyright, created_at, updated_at, raw_data) VALUES (442, '7058594', 'https://www.10000recipe.com/recipe/7058594', '얼큰 오징어무국 레시피 / 오징어국 끓이는법', '2인분', '20분 이내', '아무나', '["▶오징어무국을 미리 끓여 놓았다가 데워 드시면 처음 국물맛 보다 진해져서 더 맛있어요."]'::jsonb, '써지니', 2025-11-23 02:55:13.603985, 2025-11-23 02:55:13.603985, '{"tips": ["▶오징어무국을 미리 끓여 놓았다가 데워 드시면 처음 국물맛 보다 진해져서 더 맛있어요."], "steps": ["오징어는 흐르는 물에 문질러서 깨끗하게 세척하고 가로로 길게 반으로 썬 다음에 몸통은 1.2cm 정도 두께로 썰고 다리는 길이에 따라서 2~3등분으로 자르고 2개씩 자른 다음에 /무는 3mm 정도 두께로 나박썰어서 준비합니다.", "양파는 5mm 두께로 채 썰고 / 홍고추와 대파는 어슷 썰고 / 다진 마늘 1큰술, 동전 육수 2개를 준비하면 되세요.", "냄비에 나박 썬 무를 넣고 고추장 고추장 0.5큰술, 물을 살짝만 넣고 가스불 중불 상태에서 무에 고추장이 입혀질 수 있도록 볶아줍니다.", "물 900ml와 동전 육수 2개를 넣고 가스불 센불에 올려줍니다.", "고춧가루 0.5큰술,", "국간장 1.5큰술,", "까나리액젓 1큰술을 넣고", "얼큰 오징어무국이 끓어오르면서 위로 올라오는 거품은 걷어내고 가스불 중불로 줄인 다음에 무의 시원한 맛이 우러나오도록 3분간 끓여줍니다.", "오징어, 양파를 넣고 뒤적여줍니다.", "다시 보글보글 끓어오르면 오징어가 부드럽게 익을 수 있도록 가스불 중불 상태에서 2분간 끓여주세요.", "끓어오르면서 올라오는 거품은 다시 걷어내주면 되세요.", "맛을 보고 부족한 맛은 입맛에 맞게 간을 맞추고 국물이 많이 줄어들어서 국물 양이 적다면 물을 추가하여 끓여준 다음에 국간장이나 액젓으로 간을 맞춰주면 되세요.", "대파와 다진 마늘을 넣고 뒤적여주고", "한소끔 끓여주면 얼큰 오징어국 오징어무국 끓이는법 레시피 완성입니다. (고추는 끓이는 시간에 따라서 칼칼함 정도가 달라지니 조금 더 칼칼하게 오징어국을 드시고 싶다면 고추를 넣고 끓이는 시간을 늘려주면 되세요)"], "title": "얼큰 오징어무국 레시피 / 오징어국 끓이는법", "servings": "2인분", "cook_time": "20분 이내", "copyright": "써지니", "recipe_id": "7058594", "step_tips": ["도마", null, "냄비", "계량컵", null, null, null, null, null, null, null, null, null, null], "difficulty": "아무나", "source_url": "https://www.10000recipe.com/recipe/7058594", "ingredients": ["오징어 손질 후 252g", "무 92g", "양파 62g", "대파 21g", "홍고추 13g 1개", "다진 마늘 1큰술", "고추장 0.5큰술", "고춧가루 0.5큰술", "국간장 1.5큰술", "까나리액젓 1큰술", "동전육수 2개", "물 900ml"], "ingredients_struct": [{"qty": "252g", "desc": null, "name": "오징어 손질 후"}, {"qty": "92g", "desc": null, "name": "무"}, {"qty": "62g", "desc": null, "name": "양파"}, {"qty": "21g", "desc": null, "name": "대파"}, {"qty": "1개", "desc": null, "name": "홍고추 13g"}, {"qty": "1큰술", "desc": null, "name": "다진 마늘"}, {"qty": "0.5큰술", "desc": null, "name": "고추장"}, {"qty": "0.5큰술", "desc": null, "name": "고춧가루"}, {"qty": "1.5큰술", "desc": null, "name": "국간장"}, {"qty": "1큰술", "desc": null, "name": "까나리액젓"}, {"qty": "2개", "desc": null, "name": "동전육수"}, {"qty": "900ml", "desc": null, "name": "물"}]}'::jsonb);
INSERT INTO recipes (id, recipe_id, source_url, title, servings, cook_time, difficulty, tips, copyright, created_at, updated_at, raw_data) VALUES (443, '7059616', 'https://www.10000recipe.com/recipe/7059616', '돼지보쌈삶는법, 보쌈 삶는법 레시피 보쌈용고기 어떤부위로', '4인분', '60분 이내', '아무나', '["된장, 후추를 넣어주면 잡내가 많이 잡혀요. 쇠고기 다시다를 넣어주면 밖에서 먹던 그런 맛을 느낄 수 있을거에요."]'::jsonb, '띠안', 2025-11-23 02:57:42.202140, 2025-11-23 02:57:42.202140, '{"tips": ["된장, 후추를 넣어주면 잡내가 많이 잡혀요. 쇠고기 다시다를 넣어주면 밖에서 먹던 그런 맛을 느낄 수 있을거에요."], "steps": ["먼저 앞다릿살은 팬에 기름을 둘러서 겉면을 익혀줄거에요. 이렇게 익혀서 보쌈을 해주면 더 고소한 맛이 올라오더라구요.", "고루 겉면을 시어링을 해주듯이 익혀주었으면 물을 넣어주세요. 그후 통 양파를 반잘라서 넣고 대파도 반으로 잘라서 넣어주었어요.", "그 후 잡내를 잡기 위한 통후추, 다진마늘, 된장, 월계수잎을 모두 넣어주세요.", "또 어느정도 간이 있어야 맛있기 때문에 쇠고기다시다 약간, 소금을 넣어 살짝의 간을 추가해 주었습니다. 중불로 40분 정도는 푹 익혀주어야 부드러워요. 젓가락으로 찔러보았을때 핏물만 나오지 않으면 모두 다 익은거죠.", "그 후 꺼내서 한김 뜨거운느낌만 살짝 날라가면 썰어주면 맛있고 야들야들하고 냄새 없는 보쌈이 완성이 됩니다."], "title": "돼지보쌈삶는법, 보쌈 삶는법 레시피 보쌈용고기 어떤부위로", "servings": "4인분", "cook_time": "60분 이내", "copyright": "띠안", "recipe_id": "7059616", "step_tips": ["프라이팬", "도마", "스푼", null, "접시"], "difficulty": "아무나", "source_url": "https://www.10000recipe.com/recipe/7059616", "ingredients": ["돼지고기 앞다릿살 2근", "대파 1개", "양파 1개", "통후추 0.5T", "다진마늘 1T", "된장 1T", "쇠고기다시다 0.3T", "월계수잎 5장", "소금 0.3T"], "ingredients_struct": [{"qty": "2근", "desc": null, "name": "돼지고기 앞다릿살"}, {"qty": "1개", "desc": null, "name": "대파"}, {"qty": "1개", "desc": null, "name": "양파"}, {"qty": "0.5T", "desc": null, "name": "통후추"}, {"qty": "1T", "desc": null, "name": "다진마늘"}, {"qty": "1T", "desc": null, "name": "된장"}, {"qty": "0.3T", "desc": null, "name": "쇠고기다시다"}, {"qty": "5장", "desc": null, "name": "월계수잎"}, {"qty": "0.3T", "desc": null, "name": "소금"}]}'::jsonb);
INSERT INTO recipes (id, recipe_id, source_url, title, servings, cook_time, difficulty, tips, copyright, created_at, updated_at, raw_data) VALUES (444, '913370', 'https://www.10000recipe.com/recipe/913370', '만드는 법은 간단하고 맛은 일품인 총각김치', '6인분 이상', '60분 이내', '초급', '["※ 계량은 밥숟가락과 종이컵으로 합니다."]'::jsonb, '뽕브라', 2025-11-23 02:58:53.268395, 2025-11-23 02:58:53.268395, '{"tips": ["※ 계량은 밥숟가락과 종이컵으로 합니다."], "steps": ["먼저 알타리무(3단)는 무와 무청사이의 흙을 칼로 다듬어준 뒤, 흐르는 물에 2번정도 씻어줍니다. 저는 무에 상처가 나지 않도록. 부드러운 수세미로 겉 흙만 제거할 정도로 닦아주었습니다.", "그리고 굵은소금(3컵)을 뿌린 뒤, 물(3L)를 부어 2시간정도 절여줍니다. 무를 썰지 않고 절이므로 좀 오래 절여야해요. 2시간이 정닥하답니다. 알타리무 1단당 굵은소금 1컵, 물 1L를 부어주심 되어요. 좀 더 빨리 절이고 하려면 알타리무를 2등분해서 1시간정도 절이면 됩니다.", "무가 절여질동안 찹쌀풀을 만드는데요. 냄비에 찹쌀가루(3), 물(2컵)을 부어 덩어리 없이 잘 풀고, 불에 올려 숟가락으로 저어가며 끓입니다. 보글보글 끓으면 1분정도 더 저어가며 걸쭉하게 끓여준 뒤 찹쌀풀을 만듭니다. 찹쌀가루가 없다면 찹쌀가루 대신 밀가루(3)를 넣어주세요. 그럼 밀가루풀이 됩니다.", "고춧가루(3컵)+ 멸치액젓(1컵)+ 새우젓(4)+ 다진마늘(6)+ 양파갈은것(1컵)+ 설탕(4.5) 위 재료와 위에서 만든 찹쌀풀을 넣어 양념장을 만들고, 양파를 갈아서 넣으면 시원하니 맛있답니다.", "쪽파(1/2단)는 깨끗이 다듬어 손가락 길이만큼 썰어 준비합니다.", "2시간정도 절여진 알타리무는 흐르는물에 2번정도 깨끗이 헹궈 체반에 받쳐 물기를 빼준 뒤, 쪽파(1/2단), 양념장을 넣고 살살 밑에서 위로 버무려줍니다. 무청이 떨어지지 않게 두손으로 살살 버무려주세요.", "그리고 무청은 떨어지지 않게 무에 돌돌 감고", "김치통에 나란히 차곡차곡 담아준 뒤, 실온에서 2일정도 숙성시켜 냉장보관하면 됩니다. 알타리무를 썰지 않아서 좀 오래 숙성시켜야 익어요. 전 이틀정도 실온에 둔 뒤 냉장보관했습니다. 그리고 먹을때 2등분으로 해서 먹었습니다. 꼭 익으면 냉장보관 하시구요. 냉장고에서 익으면 맛이 없답니다. 실온에 두면 국물도 자작하게 나와서 걸쭉해집니다."], "title": "만드는 법은 간단하고 맛은 일품인 총각김치", "servings": "6인분 이상", "cook_time": "60분 이내", "copyright": "뽕브라", "recipe_id": "913370", "step_tips": [null, null, null, null, null, null, null, null], "difficulty": "초급", "source_url": "https://www.10000recipe.com/recipe/913370", "ingredients": ["알타리무 3단", "쪽파 1/2단", "물 3L", "굵은소금 3컵", "찹쌀가루 3큰술", "물 2컵", "고춧가루 3컵", "멸치액젓 1컵", "새우젓 4큰술", "다진마늘 6큰술", "갈은 양파 1컵", "설탕 4.5큰술"], "ingredients_struct": [{"qty": "3단", "desc": null, "name": "알타리무"}, {"qty": "1/2단", "desc": null, "name": "쪽파"}, {"qty": "3L", "desc": null, "name": "물"}, {"qty": "3컵", "desc": null, "name": "굵은소금"}, {"qty": "3큰술", "desc": null, "name": "찹쌀가루"}, {"qty": "2컵", "desc": null, "name": "물"}, {"qty": "3컵", "desc": null, "name": "고춧가루"}, {"qty": "1컵", "desc": null, "name": "멸치액젓"}, {"qty": "4큰술", "desc": null, "name": "새우젓"}, {"qty": "6큰술", "desc": null, "name": "다진마늘"}, {"qty": "1컵", "desc": null, "name": "갈은 양파"}, {"qty": "4.5큰술", "desc": null, "name": "설탕"}]}'::jsonb);
INSERT INTO cleaned_recipes (id, recipe_id, cleaned_at, planning_version, planning_result, title, opening_remark, closing_remark, created_at, updated_at) VALUES (107, '1785098', 2025-11-22 23:01:06.493453, '1.0', '{"meta": {"title": "돼지고기 김치찌개 맛내는 비법", "servings": 3, "difficulty": "Easy", "description": "완소연홍이 소개하는 돼지고기와 신김치로 끓여 깊은 맛을 내는 김치찌개로, 물 조절과 양념의 조합이 특징인 한 그릇 요리입니다.", "time_estimate": 30}, "tools": ["볼", "냄비", "주걱", "칼", "도마"], "process": [{"tip": "마리네이드를 충분히 흡수하도록 시간을 주세요", "phase": "preparation", "heat_level": null, "step_index": 1, "action_type": "soak", "description": "돼지고기에 분량의 양념을 넣고 고루 버무려 30분 이상 재워 주세요.", "tools_needed": ["볼", "주걱"], "timer_seconds": 1800, "ingredients_needed": ["돼지고기 찌개용 또는 목살"]}, {"tip": "참기름은 많이 넣지 않으셔도 됩니다", "phase": "cooking", "heat_level": "Low", "step_index": 2, "action_type": "fry", "description": "냄비에 썰어둔 김치와 밑간한 돼지고기, 김칫국물 5큰술, 참기름 1작은술을 넣고 약불에서 3~5분간 충분히 볶아주세요.", "tools_needed": ["냄비", "주걱"], "timer_seconds": 180, "ingredients_needed": ["김치", "돼지고기 찌개용 또는 목살", "김칫국물", "참기름"]}, {"tip": "", "phase": "cooking", "heat_level": "Low", "step_index": 3, "action_type": "fry", "description": "참기름의 양을 과하지 않게 유지하며 충분히 볶아 주세요.", "tools_needed": ["냄비", "주걱"], "timer_seconds": 120, "ingredients_needed": ["참기름"]}, {"tip": "보글보글 끓이세요", "phase": "cooking", "heat_level": "High", "step_index": 4, "action_type": "mix", "description": "충분히 볶아진 김치에 물 1컵을 넣어 끓여 주세요.", "tools_needed": ["냄비", "주걱"], "timer_seconds": 600, "ingredients_needed": ["김치", "물"]}, {"tip": "물을 한꺼번에 붓지 말고 나눠 끓이세요", "phase": "cooking", "heat_level": "Medium", "step_index": 5, "action_type": "mix", "description": "물 1컵을 추가로 부워서 끓여 주세요. 물을 나눠 붓는 것이 국물맛을 더 좋게 합니다.", "tools_needed": ["냄비", "주걱"], "timer_seconds": 300, "ingredients_needed": ["물"]}, {"tip": "양파가 투명해질 때까지 끓여 주세요", "phase": "cooking", "heat_level": "Medium", "step_index": 6, "action_type": "mix", "description": "보글보글 끓는 국물에 양파와 두부를 넣어 주세요.", "tools_needed": ["냄비", "주걱"], "timer_seconds": 120, "ingredients_needed": ["양파", "두부"]}, {"tip": "필요 시 소금을 조금 더 추가해 주세요", "phase": "cooking", "heat_level": "Medium", "step_index": 7, "action_type": "season", "description": "국간장을 넣어 간을 맞춰 주세요.", "tools_needed": ["냄비", "주걱"], "timer_seconds": 60, "ingredients_needed": ["국간장"]}, {"tip": "향을 지키기 위해 중불로 조리해 주세요", "phase": "cooking", "heat_level": "Medium", "step_index": 8, "action_type": "mix", "description": "다진마늘과 어슷 썬 고추를 넣어 향을 더해 주세요.", "tools_needed": ["냄비", "주걱"], "timer_seconds": 60, "ingredients_needed": ["다진마늘", "고추"]}, {"tip": "불을 너무 세게 올리지 말고 천천히 마무리하세요", "phase": "finishing", "heat_level": "Low", "step_index": 9, "action_type": "simmer", "description": "마지막으로 부족한 간은 소금으로 간을 맞춘 후 대파와 남은 고추를 넣고 한소끔 더 끓여 마무리합니다.", "tools_needed": ["냄비", "주걱"], "timer_seconds": 180, "ingredients_needed": ["소금", "대파", "고추"]}], "ingredients": {"sub": [{"name": "김칫국물", "unit": "큰술", "usage": "", "amount": 5}, {"name": "참기름", "unit": "작은술", "usage": "", "amount": 1}, {"name": "대파", "unit": "대", "usage": "", "amount": 0.5}, {"name": "고추장", "unit": "큰술", "usage": "", "amount": 1}, {"name": "미림", "unit": "큰술", "usage": "", "amount": 1}, {"name": "국간장", "unit": "큰술", "usage": "", "amount": 0.5}, {"name": "소금", "unit": "꼬집", "usage": "", "amount": 1}, {"name": "다진마늘", "unit": "큰술", "usage": "", "amount": 1}, {"name": "후추", "unit": "작은술", "usage": "", "amount": 0.5}], "main": [{"name": "돼지고기 찌개용 또는 목살", "unit": "g", "notes": "", "amount": 250}, {"name": "신김치", "unit": "g", "notes": "", "amount": 200}, {"name": "물", "unit": "ml", "notes": "2컵 기준으로 환산", "amount": 500}, {"name": "양파", "unit": "개", "notes": "", "amount": 0.5}, {"name": "청고추", "unit": "개", "notes": "", "amount": 2}]}}'::jsonb, '돼지고기 김치찌개 맛내는 비법', '안녕하세요! 지금부터 돼지고기 김치찌개 맛내는 비법 만들기를 시작하겠습니다. 완소연홍이 소개하는 돼지고기와 신김치로 끓여 깊은 맛을 내는 김치찌개로, 물 조절과 양념의 조합이 특징인 한 그릇 요리입니다.', '돼지고기 김치찌개 맛내는 비법 만들기가 완료되었습니다. 맛있게 드세요!', 2025-11-22 23:01:06.493453, 2025-11-22 23:01:06.493453);
