INSERT INTO cleaned_recipes (id, recipe_id, cleaned_at, planning_version, planning_result, title, opening_remark, closing_remark, created_at, updated_at) VALUES (111, '6833097', 2025-11-22 23:10:20.168933, '1.0', '{"meta": {"title": "김치콩나물 국 얼큰하고 맛나게 끓이기!", "servings": 4, "difficulty": "Medium", "description": "저자: 줌마요리의 레시피로, 신김치와 콩나물을 기본으로 멸치 육수에 팔팔 끓여 얼큰하고 칼칼한 맛의 김치콩나물국을 만드는 요리.", "time_estimate": 30}, "tools": ["냄비", "칼", "도마", "국자", "볼", "그릇"], "process": [{"tip": "시큼하면 씻는 정도를 조절해 맛을 부드럽게 만드세요.", "phase": "preparation", "heat_level": null, "step_index": 1, "action_type": "wash", "description": "신김치를 흐르는 물에 가볍게 씻어 준비해 주세요.", "tools_needed": [], "timer_seconds": 60, "ingredients_needed": ["신김치"]}, {"tip": "", "phase": "preparation", "heat_level": null, "step_index": 2, "action_type": "cut", "description": "신김치를 먹기 좋은 크기로 썰어 주세요.", "tools_needed": ["칼", "도마"], "timer_seconds": 60, "ingredients_needed": ["신김치"]}, {"tip": "", "phase": "preparation", "heat_level": null, "step_index": 3, "action_type": "wash", "description": "콩나물을 깨끗이 씻어 준비해 주세요.", "tools_needed": ["볼"], "timer_seconds": 30, "ingredients_needed": ["콩나물"]}, {"tip": "", "phase": "cooking", "heat_level": "High", "step_index": 4, "action_type": "boil", "description": "냄비에 물 1리터 정도를 넣고 멸치를 5분 정도 끓이다가 멸치를 건져낸 뒤, 김치를 먼저 팔팔 끓여 주세요.", "tools_needed": ["냄비"], "timer_seconds": 300, "ingredients_needed": ["물", "멸치", "김치"]}, {"tip": "거품 제거로 맑은 국물이 됩니다.", "phase": "cooking", "heat_level": "Medium", "step_index": 5, "action_type": "drain", "description": "김치가 팔팔 끓으면 표면의 불순물과 거품을 국자로 떠내 주세요.", "tools_needed": ["국자"], "timer_seconds": 60, "ingredients_needed": ["거품"]}, {"tip": "", "phase": "cooking", "heat_level": "High", "step_index": 6, "action_type": "boil", "description": "김치를 5분 이상 끓인 뒤 콩나물을 넣고 함께 끓여 주세요. 이때 물이 부족하면 추가로 물을 넣어 주세요.", "tools_needed": ["냄비"], "timer_seconds": 300, "ingredients_needed": ["김치", "콩나물"]}, {"tip": "", "phase": "cooking", "heat_level": "Medium", "step_index": 7, "action_type": "season", "