INSERT INTO cleaned_recipes (id, recipe_id, cleaned_at, planning_version, planning_result, title, opening_remark, closing_remark, created_at, updated_at) VALUES (126, '6858140', 2025-11-23 00:00:51.704416, '1.0', '{"meta": {"title": "배추김치 간단하고 맛있게 담그는법, 김치간단레시피", "servings": 6, "difficulty": "Easy", "description": "초이맘의 간단하고 맛있는 배추김치 레시피로, 절임 배추와 무채를 매콤한 양념에 버무려 차갑게 숙성시키는 손쉬운 레시피입니다.", "time_estimate": 60}, "tools": ["대야", "도마", "칼", "주걱", "볼", "비닐랩", "김치용기"], "process": [{"tip": "절임은 배추의 수분과 식감을 좌우합니다. 골고루 뿌려 절이세요.", "phase": "preparation", "heat_level": null, "step_index": 1, "action_type": "soak", "description": "배추 절임을 준비하고 굵은소금 절임으로 골고루 절여 주세요.", "tools_needed": ["큰 용기", "비닐랩", "저울"], "timer_seconds": 3600, "ingredients_needed": ["배추 절임", "굵은소금 절임"]}, {"tip": "배추를 씻을 때 물은 너무 많이 흘리지 않도록 주세요.", "phase": "preparation", "heat_level": null, "step_index": 2, "action_type": "wash", "description": "배추 절임의 물기를 제거하고 물기가 많지 않도록 가볍게 다듬어 주세요.", "tools_needed": ["체", "대야"], "timer_seconds": 60, "ingredients_needed": ["배추 절임"]}, {"tip": "무채는 너무 얇지 않게 썰어 식감을 살리세요.", "phase": "preparation", "heat_level": null, "step_index": 3, "action_type": "slice", "description": "무를 두께에 맞춰 썰어 무채를 만듭니다.", "tools_needed": ["도마", "칼"], "timer_seconds": 600, "ingredients_needed": ["무"]}, {"tip": "파의 향을 살리되 너무 곱게 다지지 마세요.", "phase": "preparation", "heat_level": null, "step_index": 4, "action_type": "slice", "description": "쪽파와 대파를 다듬어 알맞게 썰어 준비합니다.", "tools_needed": ["도마", "칼"], "timer_seconds": 180, "ingredients_needed": ["쪽파", "대파"]}, {"tip": "생강은 향이 강하므로 소량만 사용해도 풍미가 살아납니다.", "phase": "preparation", "heat_level": null, "step_index": 5, "action_type": "mince", "description": "생강을 다져서 양념에 넣을 준비를 합니다.", "tools_needed": ["도마", "칼"], "timer_seconds": 60, "ingredients_needed": ["생강"]}, {"tip": "양념의 비율은 취향에 따라 조절하시고, 고추가루의 매운 정도에 따라 조절하세요.", "phase": "preparation", "heat_level": null, "step_index": 6, "action_type": "mix", "description": "고추가루, 설탕, 다진마늘, 매실액, 멸치액젓, 새우젓을 한 그릇에 모아 양념을 만듭니다.", "tools_ne