INSERT INTO cleaned_recipes (id, recipe_id, cleaned_at, planning_version, planning_result, title, opening_remark, closing_remark, created_at, updated_at) VALUES (130, '6862107', 2025-11-23 00:08:55.252872, '1.0', '{"meta": {"title": "백종원 갈치조림 황금레시피 비린내 잡는 비결", "servings": 4, "difficulty": "Easy", "description": "무와 갈치를 주재료로 매콤한 양념에 졸여 비린내를 제거하고 파와 청양고추로 마무리하는 갈치조림으로, 서자매맘의 황금레시피를 따라 완성합니다.", "time_estimate": 60}, "tools": ["볼", "칼", "도마", "냄비", "주걱", "뒤집개"], "process": [{"tip": "쌀뜨물을 사용해 비린내를 효과적으로 제거해 주세요", "phase": "preparation", "heat_level": null, "step_index": 1, "action_type": "soak", "description": "갈치 6토막을 쌀뜨물에 담궈 비린내를 제거해 주세요.", "tools_needed": ["볼", "그릇"], "timer_seconds": 1800, "ingredients_needed": ["갈치"]}, {"tip": "", "phase": "preparation", "heat_level": null, "step_index": 2, "action_type": "slice", "description": "무를 얇게 썰어 준비해 주세요.", "tools_needed": ["칼", "도마"], "timer_seconds": null, "ingredients_needed": ["무"]}, {"tip": "무가 충분히 익도록 주의해 주세요", "phase": "cooking", "heat_level": "High", "step_index": 3, "action_type": "boil", "description": "냄비에 무가 잠길 정도로 물을 넣고 무를 먼저 익혀 주세요. 무가 충분히 익으면 갈치를 넣을 준비를 해 주세요.", "tools_needed": ["냄비", "주걱", "도마", "칼"], "timer_seconds": 600, "ingredients_needed": ["무", "갈치"]}, {"tip": "양념의 간은 취향에 맞춰 조절해 주세요", "phase": "cooking", "heat_level": "Low", "step_index": 4, "action_type": "mix", "description": "고춧가루, 고추장, 간장, 맛술, 다진마늘, 설탕, 된장, 다진생강, 후추를 함께 섞어 양념장을 만들어 주세요.", "tools_needed": ["볼", "주걱"], "timer_seconds": 180, "ingredients_needed": ["고춧가루", "고추장", "간장", "맛술", "다진마늘", "설탕", "된장", "다진생강", "후추"]}, {"tip": "살이 부서지지 않게 조심스럽게 다루어 주세요", "phase": "cooking", "heat_level": "Medium", "step_index": 5, "action_type": "simmer", "description": "무가 어느 정도 익으면 갈치를 차곡차곡 넣고 양파 반개와 양념장 반을 넣어 함께 익혀 주세요. 양념이 내려가므로 나눠 넣어 골고루 배이게 해 주세요.", "tools_needed": ["냄비", "주걱"], "timer_seconds": 600, "ingredients_needed": ["무", "양파", "갈치", "양념장"]}, {"tip": "", "phase": "cooking", "heat_level": "Medium", "step_index": 6, "action_type": "mix", "description"