INSERT INTO cleaned_recipes (id, recipe_id, cleaned_at, planning_version, planning_result, title, opening_remark, closing_remark, created_at, updated_at) VALUES (144, '6873683', 2025-11-23 00:37:37.392425, '1.0', '{"meta": {"title": "엄마의 레시피, 소고기 미역국 끓이는 법", "servings": 4, "difficulty": "Easy", "description": "베리츄가 전하는 소고기와 미역으로 끓인 구수한 미역국으로, 쌀뜨물로 베이스를 만들고 물을 두 차례에 나눠 넣어 깊은 맛을 내는 전통 국물 요리.", "time_estimate": 60}, "tools": ["냄비", "가위", "도마", "주걱", "국자", "키친타월", "체", "그릇"], "process": [{"tip": "", "phase": "preparation", "heat_level": null, "step_index": 1, "action_type": "wash", "description": "소고기의 핏물을 깨끗이 제거해 주세요.", "tools_needed": ["키친타월"], "timer_seconds": null, "ingredients_needed": ["소고기 국거리용"]}, {"tip": "물이 충분히 불어나도록 해 주세요.", "phase": "preparation", "heat_level": null, "step_index": 2, "action_type": "soak", "description": "미역을 오백 밀리리터의 물에 약 10분간 불려 주세요.", "tools_needed": ["그릇"], "timer_seconds": 600, "ingredients_needed": ["미역"]}, {"tip": "", "phase": "preparation", "heat_level": null, "step_index": 3, "action_type": "cut", "description": "불린 미역을 가위를 이용해 먹기 좋은 크기로 잘라 주세요.", "tools_needed": ["가위", "도마"], "timer_seconds": null, "ingredients_needed": ["미역"]}, {"tip": "물은 버리지 말고 따로 보관해 두세요.", "phase": "preparation", "heat_level": null, "step_index": 4, "action_type": "drain", "description": "미역은 체에 밭쳐 물기를 걸러 주세요. 이때 불린 물은 버리지 말고 미역국 물로 사용해 주세요.", "tools_needed": ["체", "볼"], "timer_seconds": null, "ingredients_needed": ["미역"]}, {"tip": "", "phase": "cooking", "heat_level": "Medium", "step_index": 5, "action_type": "fry", "description": "달군 냄비에 참기름 1큰술을 두르고 다진마늘 1큰술과 소고기를 넣고 볶아 주세요.", "tools_needed": ["냄비", "주걱"], "timer_seconds": 300, "ingredients_needed": ["소고기 국거리용", "다진마늘", "참기름"]}, {"tip": "", "phase": "cooking", "heat_level": "Medium", "step_index": 6, "action_type": "season", "description": "소고기 겉면이 절반 정도 익으면 국간장 1큰술을 넣어 볶아 주세요.", "tools_needed": ["냄비", "주걱"], "timer_seconds": 60, "ingredients_needed": ["소고기 국거리용", "국간장"]}, {"tip": "", "phase": "cooking", "heat_level": "Medium", "step_index": 7, "action_type": "fry", "description": "미역을 넣고 색이 푸르게 변할 때까지 계속 볶아 주세요.", "tools_needed": ["냄비", "주걱"], "timer_seconds": 120, "ingredients_needed": ["미역"]}, {"tip": "물을 한 번에 넣지 말고 두 차례에 나눠 넣으세요.", "phase": "cooking", "heat_level": "High", "step_index": 8, "action_type": "mix", "description": "쌀뜨물 또는 미역 불린 물 400밀리리터를 붓고 강불로 올려 주세요.", "tools_needed": ["냄비"], "timer_seconds": 120, "ingredients_needed": ["쌀뜨물 혹은 물"]}, {"tip": "", "phase": "cooking", "heat_level": "High", "step_index": 9, "action_type": "boil", "description": "국물이 끓기 시작하면 물 1리터를 넣어 주세요.", "tools_needed": ["냄비"], "timer_seconds": 120, "ingredients_needed": ["물"]}, {"tip": "", "phase": "cooking", "heat_level": "Medium", "step_index": 10, "action_type": "simmer", "description": "다시 끓어오르면 중약불로 줄인 뒤 15분간 더 끓여 주세요.", "tools_needed": ["냄비"], "timer_seconds": 900, "ingredients_needed": []}, {"tip": "", "phase": "finishing", "heat_level": null, "step_index": 11, "action_type": "season", "description": "국간장 1큰술을 넣고 간을 보신 뒤 소금으로 마지막 간을 맞춰 주세요. 완성된 미역국을 그릇에 담아 내세요.", "tools_needed": ["냄비", "주걱", "그릇"], "timer_seconds": 60, "ingredients_needed": ["국간장", "소금"]}], "ingredients": {"sub": [{"name": "다진마늘", "unit": "큰술", "usage": "향미", "amount": 1}, {"name": "참기름", "unit": "큰술", "usage": "향료", "amount": 1}, {"name": "국간장", "unit": "큰술", "usage": "간 맞춤", "amount": 2}, {"name": "소금", "unit": "", "usage": "마지막 간", "amount": 0}], "main": [{"name": "소고기 국거리용", "unit": "g", "notes": "", "amount": 180}, {"name": "미역", "unit": "g", "notes": "", "amount": 20}, {"name": "쌀뜨물 혹은 물", "unit": "리터", "notes": "", "amount": 1.4}]}}'::jsonb, '엄마의 레시피, 소고기 미역국 끓이는 법', '안녕하세요! 지금부터 엄마의 레시피, 소고기 미역국 끓이는 법 만들기를 시작하겠습니다. 베리츄가 전하는 소고기와 미역으로 끓인 구수한 미역국으로, 쌀뜨물로 베이스를 만들고 물을 두 차례에 나눠 넣어 깊은 맛을 내는 전통 국물 요리.', '엄마의 레시피, 소고기 미역국 끓이는 법 만들기가 완료되었습니다. 맛있게 드세요!', 2025-11-23 00:37:37.392425, 2025-11-23 00:37:37.392425);
INSERT INTO cleaned_recipes (id, recipe_id, cleaned_at, planning_version, planning_result, title, opening_remark, closing_remark, created_at, updated_at) VALUES (145, '6873935', 2025-11-23 00:39:53.289456, '1.0', '{"meta": {"title": "백종원 감자탕 레시피, 생각보다 너무 쉽고 맛있어요", "servings": 3, "difficulty": "Easy", "description": "돼지등뼈를 우려내고 감자와 무청, 대파를 넣어 끓여 들깨가루로 풍미를 더한 감자탕 요리. 저자: 엘린84", "time_estimate": 120}, "tools": ["냄비", "도마", "칼", "거름망", "큰 볼", "주걱", "그릇", "수세미"], "process": [{"tip": "2시간 정도 담가 두고 물을 두 번 갈아 주세요", "phase": "preparation", "heat_level": null, "step_index": 1, "action_type": "soak", "description": "돼지등뼈를 물에 담가 핏물을 충분히 빼 주세요.", "tools_needed": ["큰 볼"], "timer_seconds": 7200, "ingredients_needed": ["돼지등뼈"]}, {"tip": "거품이 올라오면 제거해 주세요", "phase": "cooking", "heat_level": "High", "step_index": 2, "action_type": "boil", "description": "물이 끓기 시작하면 등뼈를 넣고 한 번 팔팔 끓여 살짝 데쳐 주세요.", "tools_needed": ["냄비", "거름망"], "timer_seconds": 900, "ingredients_needed": ["돼지등뼈"]}, {"tip": "씻은 후 물기를 살짝 제거해 두세요", "phase": "preparation", "heat_level": null, "step_index": 3, "action_type": "wash", "description": "무청을 깨끗이 씻어 준비합니다.", "tools_needed": ["수세미"], "timer_seconds": 30, "ingredients_needed": ["무청"]}, {"tip": "", "phase": "preparation", "heat_level": null, "step_index": 4, "action_type": "cut", "description": "무청을 맛있게 먹기 좋게 큼직하게 잘라 주세요.", "tools_needed": ["도마", "칼"], "timer_seconds": 60, "ingredients_needed": ["무청"]}, {"tip": "", "phase": "preparation", "heat_level": null, "step_index": 5, "action_type": "cut", "description": "감자를 먹기 좋게 큼직하게 썰어 준비합니다.", "tools_needed": ["도마", "칼"], "timer_seconds": 60, "ingredients_needed": ["감자"]}, {"tip": "고기의 결을 확인해 잘 익었는지 확인하세요", "phase": "cooking", "heat_level": "Medium", "step_index": 6, "action_type": "drain", "description": "삶아낸 등뼈에서 고기를 국물에서 분리해 건져 내고 남은 뼈는 버립니다.", "tools_needed": ["거름망", "접시"], "timer_seconds": 60, "ingredients_needed": ["돼지등뼈"]}, {"tip": "물 양은 감자와 재료가 잠길 정도로 맞추세요", "phase": "cooking", "heat_level": "Medium", "step_index": 7, "action_type": "mix", "description": "등뼈가 잠길 정도로 물을 부어 주세요.", "tools_needed": ["냄비"], "timer_seconds": null, "ingredients_needed": ["물"]}, {"tip": "양념이 잘 섞이도록 골고루 저어 주세요", "phase": "cooking", "heat_level": "Medium", "step_index": 8, "action_type": "mix", "description": "감자와 양념을 넣어 함께 끓여 맛을 섞어 주세요. 된장 1큰술, 고추장 1큰술, 다진마늘 1큰술, 고춧가루 3큰술, 국간장 1/2컵, 액젓 3큰술를 먼저 넣어주었습니다.", "tools_needed": ["냄비", "주걱"], "timer_seconds": 180, "ingredients_needed": ["감자", "된장", "고추장", "다진마늘", "고춧가루", "국간장", "액젓"]}, {"tip": "", "phase": "cooking", "heat_level": "Medium", "step_index": 9, "action_type": "cut", "description": "대파를 큼직하게 잘라 냄비에 넣어 주세요.", "tools_needed": ["도마", "칼"], "timer_seconds": 20, "ingredients_needed": ["대파"]}, {"tip": "", "phase": "cooking", "heat_level": "Medium", "step_index": 10, "action_type": "layer", "description": "무청을 위쪽에 수북이 얹어 주세요.", "tools_needed": ["도마", "칼", "냄비"], "timer_seconds": 20, "ingredients_needed": ["무청"]}, {"tip": "들깨가루가 충분히 섞여 감자탕 특유의 풍미가 살아납니다", "phase": "cooking", "heat_level": "Medium", "step_index": 11, "action_type": "mix", "description": "들깨가루를 넉넉히 넣고 팔팔 끓이면서 맛이 잘 어우러지게 저어 주세요.", "tools_needed": ["주걱", "냄비"], "timer_seconds": 60, "ingredients_needed": ["들깨가루"]}, {"tip": "", "phase": "finishing", "heat_level": null, "step_index": 12, "action_type": "layer", "description": "마지막으로 깻잎을 얹어 향을 더하고 맛을 마무리합니다.", "tools_needed": ["도마", "칼"], "timer_seconds": 15, "ingredients_needed": ["깻잎"]}], "ingredients": {"sub": [{"name": "깻잎", "unit": "단위", "usage": "", "amount": 0.5}], "main": [{"name": "돼지등뼈", "unit": "kg", "notes": "", "amount": 1.3}, {"name": "감자", "unit": "개", "notes": "", "amount": 2}, {"name": "무청", "unit": "줌", "notes": "", "amount": 1}, {"name": "대파", "unit": "대", "notes": "", "amount": 1}, {"name": "물", "unit": "ml", "notes": "", "amount": 1500}, {"name": "고추장", "unit": "큰술", "notes": "", "amount": 1}, {"name": "된장", "unit": "큰술", "notes": "", "amount": 1}, {"name": "고춧가루", "unit": "큰술", "notes": "", "amount": 3}, {"name": "다진마늘", "unit": "큰술", "notes": "", "amount": 1}, {"name": "국간장", "unit": "컵", "notes": "", "amount": 0.5}, {"name": "액젓", "unit": "큰술", "notes": "", "amount": 3}, {"name": "들깨가루", "unit": "큰술", "notes": "", "amount": 4.5}]}}'::jsonb, '백종원 감자탕 레시피, 생각보다 너무 쉽고 맛있어요', '안녕하세요! 지금부터 백종원 감자탕 레시피, 생각보다 너무 쉽고 맛있어요 만들기를 시작하겠습니다. 돼지등뼈를 우려내고 감자와 무청, 대파를 넣어 끓여 들깨가루로 풍미를 더한 감자탕 요리. 저자: 엘린84', '백종원 감자탕 레시피, 생각보다 너무 쉽고 맛있어요 만들기가 완료되었습니다. 맛있게 드세요!', 2025-11-23 00:39:53.289456, 2025-11-23 00:39:53.289456);
INSERT INTO cleaned_recipes (id, recipe_id, cleaned_at, planning_version, planning_result, title, opening_remark, closing_remark, created_at, updated_at) VALUES (146, '6876544', 2025-11-23 00:44:00.670188, '1.0', '{"meta": {"title": "미역줄기볶음 짜지 않게 비린내 없이!", "servings": 2, "difficulty": "Easy", "description": "베리츄의 간단하고 건강한 반찬으로, 염장 미역줄기와 채소를 간장으로 가볍게 볶아 짭짤하고 고소한 풍미를 더해주는 요리입니다.", "time_estimate": 25}, "tools": ["팬", "칼", "도마"], "process": [{"tip": "소금기가 남지 않도록 충분히 헹궈 주세요", "phase": "preparation", "heat_level": null, "step_index": 1, "action_type": "wash", "description": "염장 미역줄기를 흐르는 물에 3~4회 씻은 뒤 찬물에 15분간 담가 소금기를 빼주세요.", "tools_needed": [], "timer_seconds": 900, "ingredients_needed": ["염장 미역줄기"]}, {"tip": "미역줄기가 길면 볶는 과정에서 너덜해지지 않도록 고르게 썰어주세요", "phase": "preparation", "heat_level": null, "step_index": 2, "action_type": "slice", "description": "미역줄기의 물기를 꼭 짜고 한입 크기(4cm)로 썰어주세요.", "tools_needed": ["칼", "도마"], "timer_seconds": 60, "ingredients_needed": ["염장 미역줄기"]}, {"tip": "양파는 얇게, 당근은 길게 채 썰어 식감이 살아나게 하세요", "phase": "preparation", "heat_level": null, "step_index": 3, "action_type": "slice", "description": "양파와 당근을 채 썰어주세요.", "tools_needed": ["칼", "도마"], "timer_seconds": 60, "ingredients_needed": ["양파", "당근"]}, {"tip": "마늘이 타지 않도록 주의하고 향이 올라올 때까지 볶으세요", "phase": "cooking", "heat_level": "Medium", "step_index": 4, "action_type": "fry", "description": "팬에 식용유를 두르고 중불에서 다진마늘 1큰술을 볶아 향을 내주세요.", "tools_needed": ["팬"], "timer_seconds": 60, "ingredients_needed": ["식용유", "다진마늘"]}, {"tip": "채소의 겉면이 살짝 익을 정도로 빠르게 볶으세요", "phase": "cooking", "heat_level": "High", "step_index": 5, "action_type": "fry", "description": "향이 올라오면 강불로 올려 채썬 양파와 당근을 넣고 1분간 볶아주세요.", "tools_needed": ["팬"], "timer_seconds": 60, "ingredients_needed": ["양파", "당근", "식용유"]}, {"tip": "미역줄기의 수분을 잘 배게 살짝 볶아 주세요", "phase": "cooking", "heat_level": "Medium", "step_index": 6, "action_type": "fry", "description": "미역줄기를 넣고 1분간 볶아주세요.", "tools_needed": ["팬"], "timer_seconds": 60, "ingredients_needed": ["염장 미역줄기"]}, {"t