INSERT INTO cleaned_recipes (id, recipe_id, cleaned_at, planning_version, planning_result, title, opening_remark, closing_remark, created_at, updated_at) VALUES (160, '6867256', 2025-11-23 01:28:47.761096, '1.0', '{"meta": {"title": "백종원레시피로 만든 콩나물무침으로 밥 한 끼 뚝딱 ~", "servings": 2, "difficulty": "Easy", "description": "뽕림이의 레시피를 바탕으로 한 아삭하고 상큼한 콩나물무침으로, 콩나물과 당근, 대파를 간장과 고춧가루로 버무려 간단하게 완성하는 반찬입니다.", "time_estimate": 10}, "tools": ["냄비", "볼", "도마", "칼", "체", "접시", "그릇"], "process": [{"tip": "", "phase": "preparation", "heat_level": null, "step_index": 1, "action_type": "wash", "description": "콩나물은 흐르는 물에 여러 번 씻은 후 체에 밭쳐 물기를 빼주세요. 당근은 색내기용으로 얇게 채 썰고, 대파는 송송 썰어 준비합니다.", "tools_needed": ["볼", "물", "체", "도마", "칼"], "timer_seconds": null, "ingredients_needed": ["콩나물", "당근", "대파"]}, {"tip": "", "phase": "cooking", "heat_level": "High", "step_index": 2, "action_type": "boil", "description": "끓는 물에 소금 반 큰 술을 넣고 콩나물을 넣어 팔팔 끓여 4~5분 정도 데쳐 주세요.", "tools_needed": ["냄비", "주걱"], "timer_seconds": 300, "ingredients_needed": ["콩나물", "소금"]}, {"tip": "", "phase": "cooking", "heat_level": "Off", "step_index": 3, "action_type": "drain", "description": "데친 콩나물은 체에 밭쳐 물기를 충분히 빼주세요.", "tools_needed": ["체"], "timer_seconds": 60, "ingredients_needed": ["콩나물"]}, {"tip": "고르게 섞이도록 천천히 버무려 주세요", "phase": "cooking", "heat_level": null, "step_index": 4, "action_type": "mix", "description": "물기가 어느 정도 빠진 콩나물을 볼에 담고 채 썬 당근과 대파를 넣어 잘 섞어주세요.", "tools_needed": ["볼"], "timer_seconds": 30, "ingredients_needed": ["콩나물", "당근", "대파"]}, {"tip": "향이 올라오면 맛의 균형을 맞춰 주세요", "phase": "cooking", "heat_level": "Medium", "step_index": 5, "action_type": "season", "description": "고춧가루 2큰술, 소금 적당량, 다진 마늘 반 큰술, 깨소금을 넣어 고루 버무려 간을 맞춰주세요.", "tools_needed": ["볼"], "timer_seconds": 30, "ingredients_needed": ["고춧가루", "소금", "다진 마늘", "깨소금"]}, {"tip": "", "phase": "cooking", "heat_level": "Medium", "step_index": 6, "action_type": "mix", "description": "진간장 1큰술을 넣은 뒤 콩나물의 머리 부분이 떨어지지 않도록 조심스럽게 섞어 주세요.", "tools_needed": ["볼"], "timer_s