INSERT INTO cleaned_recipes (id, recipe_id, cleaned_at, planning_version, planning_result, title, opening_remark, closing_remark, created_at, updated_at) VALUES (163, '6879533', 2025-11-23 01:36:34.937875, '1.0', '{"meta": {"title": "생생정보통 잡채 황금레시피 이거였네", "servings": 4, "difficulty": "Medium", "description": "당면과 고기, 야채를 간장과 물엿 소스로 달콤하게 버무려 만드는 잡채", "time_estimate": 30}, "tools": ["그릇", "볼", "주걱", "칼", "도마", "팬", "프라이팬", "냄비", "체", "큰 그릇"], "process": [{"tip": "목이버섯이 충분히 불려 쫄깃한 식감을 확보하도록 해 주세요.", "phase": "preparation", "heat_level": null, "step_index": 1, "action_type": "soak", "description": "목이버섯을 깨끗이 씻은 뒤 물에 살짝 불려 사용해 주세요.", "tools_needed": ["그릇"], "timer_seconds": 600, "ingredients_needed": ["목이버섯"]}, {"tip": "고기에 소스가 잘 밸도록 고루 버무려 주세요.", "phase": "preparation", "heat_level": null, "step_index": 2, "action_type": "mix", "description": "잡채용 돼지고기에 다진마늘, 간장, 참기름을 넣고 골고루 섞어 밑간을 해주세요. 미림 맛술과 후추를 넣고 20분간 재워 두세요.", "tools_needed": ["볼"], "timer_seconds": 1200, "ingredients_needed": ["잡채용 돼지고기", "다진마늘", "간장", "참기름", "미림 맛술", "후추"]}, {"tip": "야채는 큼직하게 자르면 식감이 살아나요.", "phase": "preparation", "heat_level": null, "step_index": 3, "action_type": "cut", "description": "부추, 양파, 당근, 파프리카를 먹기 좋은 크기로 잘라 준비해 주세요.", "tools_needed": ["칼", "도마"], "timer_seconds": 180, "ingredients_needed": ["부추", "양파", "당근", "파프리카"]}, {"tip": "당면은 포장 시간보다 약간 덜 삶아도 됩니다. 식감은 취향에 따라 조절해 주세요.", "phase": "cooking", "heat_level": "High", "step_index": 4, "action_type": "boil", "description": "당면을 끓는 물에 11분 삶아 주세요.", "tools_needed": ["냄비", "체"], "timer_seconds": 660, "ingredients_needed": ["당면"]}, {"tip": "야채는 너무 작게 자르면 식감이 흐려집니다.", "phase": "cooking", "heat_level": "Medium", "step_index": 5, "action_type": "fry", "description": "당면이 삶아지는 동안 부추를 제외한 나머지 야채를 팬에 볶아 준비해 주세요.", "tools_needed": ["팬", "칼", "도마"], "timer_seconds": 180, "ingredients_needed": ["당근", "파프리카", "양파", "목이버섯"]}, {"tip": "고기가 갈색이 되도록 잘 볶아 주세요", "phase": "cooking", "heat_level": "Medium", "step_index": 6, "action_type": "fry", "description"