INSERT INTO cleaned_recipes (id, recipe_id, cleaned_at, planning_version, planning_result, title, opening_remark, closing_remark, created_at, updated_at) VALUES (168, '6889570', 2025-11-23 01:47:19.348837, '1.0', '{"meta": {"title": "돼지고기 김치찜 만드는 법", "servings": 4, "difficulty": "Medium", "description": "김치를 크게 넣고 돼지고기를 함께 푹 끓여 깊고 얼큰한 맛의 김치찜을 완성합니다. (저자: 시크제이맘)", "time_estimate": 120}, "tools": ["냄비", "볼", "도마", "칼", "가위", "국자"], "process": [{"tip": "고기에 밑간이 고루 섞이도록 골고루 버무려 주세요.", "phase": "preparation", "heat_level": null, "step_index": 1, "action_type": "season", "description": "돼지고기에 청주 3스푼, 다진 마늘 1스푼, 생강가루 0.3스푼, 후춧가루 약간을 넣고 밑간을 해주세요.", "tools_needed": ["볼"], "timer_seconds": null, "ingredients_needed": ["돼지고기", "청주", "다진 마늘", "생강가루", "후춧가루"]}, {"tip": "고기 덩어리는 먹기 좋게 크게 준비해 주세요.", "phase": "preparation", "heat_level": null, "step_index": 2, "action_type": "cut", "description": "돼지고기를 큼직하게 덩어리로 잘라 주세요.", "tools_needed": ["도마", "칼", "가위"], "timer_seconds": null, "ingredients_needed": ["돼지고기"]}, {"tip": "묵은지는 흐르는 물에 충분히 씻어 내고 필요하면 설탕으로 맛을 살짝 조절해 주세요.", "phase": "preparation", "heat_level": null, "step_index": 3, "action_type": "wash", "description": "김치를 흐르는 물에 씻어 준비합니다.", "tools_needed": ["볼"], "timer_seconds": null, "ingredients_needed": ["김치"]}, {"tip": "얇게 썰어 향을 잘 내도록 하세요.", "phase": "preparation", "heat_level": null, "step_index": 4, "action_type": "slice", "description": "양파를 채 썰어 주세요.", "tools_needed": ["칼", "도마"], "timer_seconds": null, "ingredients_needed": ["양파"]}, {"tip": "매운맛과 향을 조절하기 쉽도록 얇게 썰어 주세요.", "phase": "preparation", "heat_level": null, "step_index": 5, "action_type": "slice", "description": "대파와 청양고추를 어슷 썰어 주세요.", "tools_needed": ["칼", "도마"], "timer_seconds": null, "ingredients_needed": ["대파", "청양고추"]}, {"tip": "새우젓은 선택사항으로 감칠맛을 더합니다.", "phase": "preparation", "heat_level": null, "step_index": 6, "action_type": "mix", "description": "물 3컵에 된장 0.5스푼, 국간장 5스푼, 설탕 2스푼을 넣고 고루 섞어 육수를 만듭니다. 여기에 새우젓 1숟가락 정도를 추가해도 좋습니다.", "tools_needed": ["볼", "숟가락", "