INSERT INTO cleaned_recipes (id, recipe_id, cleaned_at, planning_version, planning_result, title, opening_remark, closing_remark, created_at, updated_at) VALUES (180, '6906766', 2025-11-23 02:09:10.965496, '1.0', '{"meta": {"title": "계란장조림 황금레시피 짜지않고 맛있게", "servings": 4, "difficulty": "Easy", "description": "혀니ㅋ의 레시피로, 계란을 삶아 간장 양념에 졸여 매콤하고 짭짤한 맛이 어우러지는 계란장조림.", "time_estimate": 30}, "tools": ["냄비", "볼", "도마", "칼", "주걱", "숟가락", "국자", "거름망"], "process": [{"tip": "계란을 삶을 때 식초와 소금을 넣어주면 삶은 후 껍질이 잘 벗겨집니다.", "phase": "cooking", "heat_level": "High", "step_index": 1, "action_type": "boil", "description": "계란이 잠길 만큼의 물을 냄비에 붓고 소금 1스푼과 식초 1스푼을 넣어 삶기 시작합니다. 반숙은 물이 끓기 시작한 뒤 7분 정도, 완숙은 10~15분 정도 삶아주세요.", "tools_needed": ["냄비"], "timer_seconds": 600, "ingredients_needed": ["계란", "소금", "식초"]}, {"tip": "", "phase": "preparation", "heat_level": null, "step_index": 2, "action_type": "soak", "description": "삶은 계란을 빠르게 찬물에 담궈 식히고 껍질을 벗겨 준비합니다.", "tools_needed": ["볼"], "timer_seconds": 120, "ingredients_needed": ["계란"]}, {"tip": "", "phase": "cooking", "heat_level": "High", "step_index": 3, "action_type": "boil", "description": "냄비에 진간장 4스푼, 국간장 2스푼, 설탕 2스푼, 올리고당 0.75스푼, 물 1.5컵과 통마늘을 넣고 바글바글 끓여 양념 베이스를 만듭니다.", "tools_needed": ["냄비"], "timer_seconds": 300, "ingredients_needed": ["진간장", "국간장", "설탕", "올리고당", "물", "통마늘"]}, {"tip": "", "phase": "cooking", "heat_level": "Medium", "step_index": 4, "action_type": "mix", "description": "양념이 끓으면 삶은 계란을 넣어 간이 스며들도록 함께 졸여주세요.", "tools_needed": ["냄비", "주걱"], "timer_seconds": 60, "ingredients_needed": ["계란"]}, {"tip": "", "phase": "cooking", "heat_level": "Medium", "step_index": 5, "action_type": "slice", "description": "계란 겉면에 색이 입혀질 때쯤 청양고추를 듬성듬성 썰어 양념에 넣고 중불에서 뭉근히 끓여 맛이 배도록 조려주세요.", "tools_needed": ["도마", "칼", "냄비"], "timer_seconds": 120, "ingredients_needed": ["청양고추"]}, {"tip": "", "phase": "finishing", "heat_level": "Off", "step_index": 6, "action_type": "drain", "description": "국물이 거의 줄어들고 달걀에 양념이 잘 배었으면 건더기를 건져내고 맛을 최종 확인한 뒤 필요하면 더 조려 마무리합니다.", "tools_needed": ["냄비", "거름망"], "timer_seconds": 60, "ingredients_needed": ["건더기"]}], "ingredients": {"sub": [{"name": "진간장", "unit": "스푼", "usage": "양념", "amount": 4}, {"name": "국간장", "unit": "스푼", "usage": "양념", "amount": 2}, {"name": "설탕", "unit": "스푼", "usage": "양념", "amount": 2}, {"name": "올리고당", "unit": "스푼", "usage": "양념", "amount": 0.75}], "main": [{"name": "계란", "unit": "개", "notes": "", "amount": 6}, {"name": "소금", "unit": "스푼", "notes": "", "amount": 1}, {"name": "식초", "unit": "스푼", "notes": "", "amount": 1}, {"name": "청양고추", "unit": "개", "notes": "", "amount": 1.5}, {"name": "통마늘", "unit": "줌", "notes": "", "amount": 1}, {"name": "물", "unit": "컵", "notes": "", "amount": 1.5}]}}'::jsonb, '계란장조림 황금레시피 짜지않고 맛있게', '안녕하세요! 지금부터 계란장조림 황금레시피 짜지않고 맛있게 만들기를 시작하겠습니다. 혀니ㅋ의 레시피로, 계란을 삶아 간장 양념에 졸여 매콤하고 짭짤한 맛이 어우러지는 계란장조림.', '계란장조림 황금레시피 짜지않고 맛있게 만들기가 완료되었습니다. 맛있게 드세요!', 2025-11-23 02:09:10.965496, 2025-11-23 02:09:10.965496);
INSERT INTO cleaned_recipes (id, recipe_id, cleaned_at, planning_version, planning_result, title, opening_remark, closing_remark, created_at, updated_at) VALUES (181, '6911743', 2025-11-23 02:10:15.543876, '1.0', '{"meta": {"title": "수미네반찬 김치전 만들기 바삭하게", "servings": 1, "difficulty": "Easy", "description": "김치를 잘게 다져 부침가루와 물로 반죽해 프라이팬에서 바삭하게 구워 내는 간단한 김치전 요리", "time_estimate": 10}, "tools": ["볼", "가위", "주걱", "프라이팬", "접시"], "process": [{"tip": "", "phase": "preparation", "heat_level": null, "step_index": 1, "action_type": "cut", "description": "김치를 볼에 담아 가위를 이용해 잘게 썰어 준비해 주세요.", "tools_needed": ["볼", "가위"], "timer_seconds": null, "ingredients_needed": ["김치"]}, {"tip": "다진마늘을 넣는 것이 포인트입니다", "phase": "preparation", "heat_level": null, "step_index": 2, "action_type": "mix", "description": "부침가루, 김치국물, 다진마늘을 넣고 반죽이 되도록 잘 섞어 주세요.", "tools_needed": ["볼", "주걱"], "timer_seconds": null, "ingredients_needed": ["부침가루", "김치국물", "다진마늘"]}, {"tip": "", "phase": "preparation", "heat_level": null, "step_index": 3, "action_type": "mix", "description": "물은 조금씩 넣으며 반죽의 농도를 맞춰 주세요. 반죽이 너무 되면 물을 살짝 더 넣어 섞어 주세요.", "tools_needed": ["볼", "주걱"], "timer_seconds": null, "ingredients_needed": ["물"]}, {"tip": "한 면이 노릇해지면 뒤집고 기름의 양을 조절해 주세요", "phase": "cooking", "heat_level": "Medium", "step_index": 4, "action_type": "fry", "description": "기름을 두른 팬에 반죽을 한 숟가락씩 떠서 동그랗게 모양을 만들고 앞뒤로 노릇하게 구워 주세요.", "tools_needed": ["프라이팬", "주걱"], "timer_seconds": 180, "ingredients_needed": []}, {"tip": "원한다면 간장이나 초고추장을 곁들여 드세요", "phase": "finishing", "heat_level": null, "step_index": 5, "action_type": "layer", "description": "완성된 김치전을 접시에 예쁘게 담아 내어 맛있게 즐겨 주세요.", "tools_needed": ["접시"], "timer_seconds": null, "ingredients_needed": []}], "ingredients": {"sub": [{"name": "다진마늘", "unit": "스푼", "usage": "반죽용", "amount": 0.5}], "main": [{"name": "김치", "unit": "컵", "notes": "", "amount": 2}, {"name": "부침가루", "unit": "컵", "notes": "", "amount": 1}, {"name": "김치국물", "unit": "컵", "notes": "", "amount": 0.333}, {"name": "물", "unit": "컵", "notes": "", "amount": 0.666}]}}'::jsonb, '수미네반찬 김치전 만들기 바삭하게', '안녕하세요! 지금부터 수미네반찬 김치전 만들기 바삭하게 만들기를 시작하겠습니다. 김치를 잘게 다져 부침가루와 물로 반죽해 프라이팬에서 바삭하게 구워 내는 간단한 김치전 요리', '수미네반찬 김치전 만들기 바삭하게 만들기가 완료되었습니다. 맛있게 드세요!', 2025-11-23 02:10:15.543876, 2025-11-23 02:10:15.543876);
