INSERT INTO cleaned_recipes (id, recipe_id, cleaned_at, planning_version, planning_result, title, opening_remark, closing_remark, created_at, updated_at) VALUES (184, '6915139', 2025-11-23 02:17:51.624928, '1.0', '{"meta": {"title": "수육 맛있게 삶는법 백종원 레시피로 부드럽게", "servings": 4, "difficulty": "Easy", "description": "수육용 돼지고기를 된장 육수와 함께 천천히 삶아 부드럽고 담백한 식감을 내는 전통 수육 요리입니다.", "time_estimate": 135}, "tools": ["대접", "칼", "도마", "냄비", "집게", "국자"], "process": [{"tip": "핏물이 빠질수록 육즙이 더 부드럽습니다. 물은 한 번 갈아 담가두세요.", "phase": "preparation", "heat_level": null, "step_index": 1, "action_type": "soak", "description": "돼지고기를 물에 담가 핏물을 약 30분간 빼주세요.", "tools_needed": ["대접"], "timer_seconds": 1800, "ingredients_needed": ["돼지고기 앞다리살 또는 삼겹살"]}, {"tip": "된장을 너무 오래 끓이지 말고 향이 나올 때까지만 끓여 주세요.", "phase": "cooking", "heat_level": "High", "step_index": 2, "action_type": "boil", "description": "육수용 재료를 모두 냄비에 넣고 물을 팔팔 끓여 육수를 만들어 주세요.", "tools_needed": ["냄비"], "timer_seconds": null, "ingredients_needed": ["양파", "월계수잎", "대파", "된장", "통마늘", "통후추", "미림"]}, {"tip": "고기의 두께를 고르게 맞추면 익는 시간이 균일해집니다.", "phase": "preparation", "heat_level": null, "step_index": 3, "action_type": "slice", "description": "돼지고기 앞다리살을 한 토막으로 자르고, 속까지 익도록 칼집을 2-3번 내 주세요.", "tools_needed": ["칼", "도마"], "timer_seconds": null, "ingredients_needed": ["돼지고기 앞다리살 또는 삼겹살"]}, {"tip": "고기가 물에 잠길 정도로 물의 양을 맞춰 주세요.", "phase": "cooking", "heat_level": "High", "step_index": 4, "action_type": "mix", "description": "팔팔 끓는 물에 돼지고기를 투하하여 물에 잠길 만큼 넣어 주세요. 껍데기 쪽부터 넣으면 기름기가 덜 생깁니다.", "tools_needed": ["냄비", "집게"], "timer_seconds": null, "ingredients_needed": ["돼지고기 앞다리살 또는 삼겹살"]}, {"tip": "필요 시 뚜껑을 열고 거품을 제거해 주세요.", "phase": "cooking", "heat_level": "High", "step_index": 5, "action_type": "boil", "description": "물이 끓으면 강불로 20분 끓여 주세요.", "tools_needed": ["냄비", "집게"], "timer_seconds": 1200, "ingredients_needed": ["돼지고기 앞다리살 또는 삼겹살"]}, {"tip": "거품이 올라오면 제거해 주세요.", "phase": "cooking", "heat_level": "Medium", "step_index": 6, "action_type": "boil", "descriptio