INSERT INTO cleaned_recipes (id, recipe_id, cleaned_at, planning_version, planning_result, title, opening_remark, closing_remark, created_at, updated_at) VALUES (185, '6953648', 2025-11-23 02:20:10.413268, '1.0', '{"meta": {"title": "잡채 황금레시피로 불지않게 맛있게 만드는법", "servings": 4, "difficulty": "Easy", "description": "저자 쿡딱의 손맛이 살아 있는 잡채로, 당면과 돼지고기, 버섯, 시금치를 달콤짭짤한 양념으로 볶아낸 대표 반찬입니다.", "time_estimate": 60}, "tools": ["볼", "대야", "칼", "도마", "냄비", "체", "궁중팬", "팬", "가위", "주걱"], "process": [{"tip": "당면은 불린 상태에서 양념과 함께 볶아야 질감이 좋습니다.", "phase": "preparation", "heat_level": null, "step_index": 1, "action_type": "soak", "description": "당면을 물에 불려주세요.", "tools_needed": ["볼", "대야"], "timer_seconds": null, "ingredients_needed": ["당면"]}, {"tip": "목이버섯은 불려 부드럽게 한 뒤 손가락 크기로 썰어 준비합니다.", "phase": "preparation", "heat_level": null, "step_index": 2, "action_type": "soak", "description": "건 목이버섯을 20분 정도 불려주세요.", "tools_needed": ["볼"], "timer_seconds": 1200, "ingredients_needed": ["말린 목이버섯"]}, {"tip": "썰 때 손가락이 다치지 않게 주의해 주세요.", "phase": "preparation", "heat_level": null, "step_index": 3, "action_type": "slice", "description": "목이버섯을 손가락 크기로 썰어주세요.", "tools_needed": ["칼", "도마"], "timer_seconds": null, "ingredients_needed": ["말린 목이버섯"]}, {"tip": "야채의 두께는 비슷하게 맞추면 볶을 때 고르게 익습니다.", "phase": "preparation", "heat_level": null, "step_index": 4, "action_type": "slice", "description": "시금치, 당근, 양파, 노란파프리카, 빨간파프리카를 길쭉하게 썰어 준비해 주세요.", "tools_needed": ["칼", "도마"], "timer_seconds": null, "ingredients_needed": ["시금치", "당근", "양파", "노란파프리카", "빨간파프리카"]}, {"tip": "고기에 간이 고루 베이도록 골고루 버무려 주세요.", "phase": "preparation", "heat_level": null, "step_index": 5, "action_type": "season", "description": "돼지고기와 표고버섯에 밑간을 해주세요.", "tools_needed": ["볼"], "timer_seconds": null, "ingredients_needed": ["돼지고기", "생 표고버섯", "간장", "맛술", "설탕", "다진마늘", "참기름", "후추"]}, {"tip": "양념이 고루 배도록 30초 이상 버무려 주세요.", "phase": "preparation", "heat_level": null, "step_index": 6, "action_type": "mix", "description": "볼에 고기와 표고버섯에 양념을 넣고 골고루 주물주물 해주세요.", "tools_needed": ["볼", "주걱"], "timer_seconds": null, "ingredients_needed": ["돼지고기", "생 표고버섯", "간장", "맛술", "설탕", "다진마늘", "참기름", "후추"]}, {"tip": "데친 시금치는 물기를 꽉 짜서 남은 물기가 흐트러지지 않게 해 주세요.", "phase": "cooking", "heat_level": "High", "step_index": 7, "action_type": "boil", "description": "시금치를 끓는 물에 데쳐 건져 찬물에 헹구고 물기를 꼭 짜 주세요.", "tools_needed": ["냄비", "체"], "timer_seconds": 60, "ingredients_needed": ["시금치"]}, {"tip": "소금은 기호에 맞춰 조절해 주세요.", "phase": "cooking", "heat_level": null, "step_index": 8, "action_type": "mix", "description": "물기 짠 시금치를 소금과 참기름으로 살짝 무쳐 주세요.", "tools_needed": ["볼"], "timer_seconds": null, "ingredients_needed": ["시금치", "소금", "참기름"]}, {"tip": "양념은 미리 맛을 보고 필요 시 간을 맞춰 주세요.", "phase": "cooking", "heat_level": null, "step_index": 9, "action_type": "mix", "description": "잡채양념 재료를 큰 볼에 넣고 골고루 섞어 양념을 완성해 주세요.", "tools_needed": ["볼"], "timer_seconds": null, "ingredients_needed": ["간장", "물", "후추", "올리고당", "설탕", "굴소스", "식용유", "잡채양념"]}, {"tip": "야채의 숨이 죽으면 불을 끄고 접시에 옮겨 한김 식혀 주세요.", "phase": "cooking", "heat_level": "High", "step_index": 10, "action_type": "fry", "description": "달궈진 팬에 기름을 살짝 두르고 센불에서 양파, 당근, 파프리카, 목이버섯을 볶아 주세요.", "tools_needed": ["궁중팬", "팬"], "timer_seconds": null, "ingredients_needed": ["양파", "당근", "노란파프리카", "빨간파프리카", "목이버섯"]}, {"tip": "볶은 고기도 접시에 펼쳐 한김 식혀 주세요.", "phase": "cooking", "heat_level": "High", "step_index": 11, "action_type": "fry", "description": "같은 팬에 밑간 해 놓은 돼지고기와 표고버섯도 달달달 볶아 주세요.", "tools_needed": ["팬"], "timer_seconds": null, "ingredients_needed": ["돼지고기", "생 표고버섯"]}, {"tip": "당면이 양념과 잘 어우러지도록 고루 볶아 주세요.", "phase": "cooking", "heat_level": "High", "step_index": 12, "action_type": "mix", "description": "고기 볶았던 팬에 잡채양념을 넣고 끓이다가 끓어오르면 바로 불린 당면을 넣고 볶듯이 끓여 주세요.", "tools_needed": ["팬"], "timer_seconds": 180, "ingredients_needed": ["잡채양념", "당면"]}, {"tip": "가위로 자를 때는 한 입 크기로 고르게 잘라 주세요.", "phase": "finishing", "heat_level": null, "step_index": 13, "action_type": "slice", "description": "당면이 익으면 가위로 먹기 좋게 잘라 주세요.", "tools_needed": ["가위"], "timer_seconds": 60, "ingredients_needed": ["당면"]}, {"tip": "뜨거우니 안전장갑을 착용하고 조리해 주세요.", "phase": "finishing", "heat_level": null, "step_index": 14, "action_type": "mix", "description": "당면까지 다 볶으면 미리 준비해놓은 야채와 고기를 위에 부어 참기름을 뿌려 골고루 무쳐 주세요.", "tools_needed": ["팬", "주걱"], "timer_seconds": 60, "ingredients_needed": ["당면", "야채", "고기", "참기름"]}, {"tip": "", "phase": "finishing", "heat_level": null, "step_index": 15, "action_type": "season", "description": "참깨를 솔솔 뿌려 맛과 향을 더해 완성해 주세요.", "tools_needed": [], "timer_seconds": null, "ingredients_needed": ["참깨"]}], "ingredients": {"sub": [{"name": "진간장", "unit": "큰술", "usage": "양념용", "amount": 2}, {"name": "맛술", "unit": "큰술", "usage": "양념용", "amount": 1}, {"name": "설탕", "unit": "큰술", "usage": "양념용", "amount": 1}, {"name": "참기름", "unit": "큰술", "usage": "양념용", "amount": 1}, {"name": "다진마늘", "unit": "큰술", "usage": "양념용", "amount": 1}, {"name": "후추", "unit": "작은술", "usage": "양념용", "amount": 0.5}, {"name": "진간장", "unit": "컵", "usage": "양념용", "amount": 0.333}, {"name": "설탕", "unit": "큰술", "usage": "양념용", "amount": 2}, {"name": "올리고당", "unit": "큰술", "usage": "양념용", "amount": 2}, {"name": "식용유", "unit": "큰술", "usage": "조리용", "amount": 3}, {"name": "후추", "unit": "작은술", "usage": "양념용", "amount": 0.5}, {"name": "굴소스", "unit": "작은술", "usage": "양념용", "amount": 1}, {"name": "물", "unit": "컵", "usage": "양념용", "amount": 1}, {"name": "소금", "unit": "작은술", "usage": "양념용", "amount": 0.5}, {"name": "참기름", "unit": "작은술", "usage": "양념용", "amount": 0.5}], "main": [{"name": "당면", "unit": "g", "notes": "", "amount": 300}, {"name": "돼지고기", "unit": "g", "notes": "", "amount": 300}, {"name": "말린 목이버섯", "unit": "개", "notes": "", "amount": 3}, {"name": "시금치", "unit": "단", "notes": "", "amount": 0.5}, {"name": "당근", "unit": "개", "notes": "", "amount": 0.5}, {"name": "양파", "unit": "개", "notes": "", "amount": 1}, {"name": "노란파프리카", "unit": "개", "notes": "", "amount": 0.5}, {"name": "빨간파프리카", "unit": "개", "notes": "", "amount": 0.5}, {"name": "생 표고버섯", "unit"