INSERT INTO cleaned_recipes (id, recipe_id, cleaned_at, planning_version, planning_result, title, opening_remark, closing_remark, created_at, updated_at) VALUES (187, '6993115', 2025-11-23 02:23:59.255554, '1.0', '{"meta": {"title": "생굴무침 양념 레시피 굴무생채 물기 없이 쫄깃한 굴무침만들기", "servings": 4, "difficulty": "Easy", "description": "요리하는러라의 레시피로, 굴과 무를 매콤한 양념에 버무려 냉장 숙성시키는 굴무침의 한 접시.", "time_estimate": 60}, "tools": ["볼", "가위", "숟가락", "체", "칼", "도마", "냉장고", "밀폐용기"], "process": [{"tip": "꽉 문지르며 씻어 불순물을 제거해 주세요.", "phase": "preparation", "heat_level": null, "step_index": 1, "action_type": "wash", "description": "굴의 봉지 끝을 조심스럽게 잘라 충전수를 제거한 뒤 굴을 볼에 담아 찬물을 자박하게 붓고 굵은소금 반 스푼을 넣어 깨끗이 씻어주세요.", "tools_needed": ["볼", "가위", "숟가락", "체"], "timer_seconds": null, "ingredients_needed": ["굴"]}, {"tip": "물기가 남지 않도록 충분히 헹궈 주세요.", "phase": "preparation", "heat_level": null, "step_index": 2, "action_type": "wash", "description": "굴을 숟가락으로 살살 저어 헹군 뒤 체에 받쳐 물기를 제거하고 다른 용기에 옮겨 담아 주세요.", "tools_needed": ["숟가락", "체"], "timer_seconds": null, "ingredients_needed": ["굴"]}, {"tip": "깨끗하게 씻어 식감을 살려주세요.", "phase": "preparation", "heat_level": null, "step_index": 3, "action_type": "wash", "description": "물이 맑아질 때까지 반복하며 굴의 이물질과 핏물을 깨끗이 제거한 후 손질이 끝나면 준비를 완료합니다.", "tools_needed": ["볼", "체"], "timer_seconds": null, "ingredients_needed": ["굴"]}, {"tip": "밑간이 잘 들도록 고르게 섞어 주세요.", "phase": "preparation", "heat_level": null, "step_index": 4, "action_type": "mix", "description": "세척한 굴에 맛술 2숟가락과 고운소금 0.5숟가락을 넣고 고르게 섞은 뒤 체에 밭쳐 냉장실에 40분간 재워 두세요. 굴에서 나오는 수분이 굴에 닿지 않도록 채반 아래에는 오목한 그릇을 받쳐주세요.", "tools_needed": ["볼", "체", "냉장고"], "timer_seconds": 2400, "ingredients_needed": ["굴", "맛술", "고운소금"]}, {"tip": "무가 부드럽게 절일수록 맛이 잘 배어납니다.", "phase": "preparation", "heat_level": null, "step_index": 5, "action_type": "slice", "description": "무 한 토막을 얇게 나박나박 썰어 볼에 담고 고운 소금 0.3숟가락을 넣어 고루 버무려 30분간 절여주세요.", "tools_needed": ["칼", "도마", "볼"], "timer_seconds": 1800, "ingredients_needed": ["무", "고운소금"]}, {"tip": "수분을 잘 빼 주어 양념이 잘 베이도록 합니다.", "phase": "preparation", "heat_level": null, "step_index": 6, "action_type": "drain", "description": "절인 굴과 무에서 나온 물은 버려주고 굴과 무는 헹구지 말아주세요.", "tools_needed": ["볼", "체"], "timer_seconds": null, "ingredients_needed": ["굴", "무"]}, {"tip": "간은 취향에 따라 추가로 맞춰 주세요.", "phase": "preparation", "heat_level": null, "step_index": 7, "action_type": "mix", "description": "물기 쭉 뺀 생굴과 무를 볼에 넣고 고춧가루 5숟가락, 설탕 0.5숟가락, 다진마늘 2숟가락, 다진생강 0.2숟가락, 매실청 2숟가락, 액젓 1.5숟가락을 넣고 숟가락으로 살살 버무려 주세요. 간을 보고 필요하면 액젓을 추가해 맛을 맞춰 주세요.", "tools_needed": ["볼", "숟가락"], "timer_seconds": null, "ingredients_needed": ["생굴", "무", "고춧가루", "설탕", "다진마늘", "다진생강", "매실청", "액젓"]}, {"tip": "숙성 시간이 길수록 맛이 더 깊어집니다.", "phase": "finishing", "heat_level": null, "step_index": 8, "action_type": "mix", "description": "밀폐용기에 담아 냉장고에서 약 1시간 정도 숙성시켜 주세요. 숙성되는 동안 양념이 고르게 배어 굴이 쫄깃하고 풍미가 깊어집니다.", "tools_needed": ["밀폐용기", "냉장고"], "timer_seconds": 3600, "ingredients_needed": ["굴", "무", "고춧가루", "설탕", "다진마늘", "다진생강", "매실청", "액젓"]}, {"tip": "보관 시 밀폐용기에 담아 냉장 보관해 주세요.", "phase": "finishing", "heat_level": null, "step_index": 9, "action_type": "mix", "description": "먹기 직전에 마지막으로 가볍게 버무려 맛을 확인한 뒤 필요 시 추가로 양념을 더해 주세요. 이 레시피로 더 많이 만들어 이틀 정도 즐길 수 있습니다.", "tools_needed": ["볼"], "timer_seconds": null, "ingredients_needed": ["굴", "무"]}], "ingredients": {"sub": [{"name": "고운소금", "unit": "숟가락", "usage": "밑간용", "amount": 0.8}, {"name": "맛술", "unit": "숟가락", "usage": "밑간용", "amount": 2}, {"name": "고춧가루", "unit": "숟가락", "usage": "양념용", "amount": 5}, {"name": "설탕", "unit": "숟가락", "usage": "양념용", "amount": 0.5}, {"name": "다진마늘", "unit": "숟가락", "usage": "양념용", "amount": 2}, {"name": "다진생강", "unit": "숟가락", "usage": "양념용", "amount": 0.2}, {"name": "매실청", "unit": "숟가락", "usage": "양념용", "amount": 2}, {"name": "액젓", "unit": "숟가락", "usage": "양념용", "amount": 2}, {"name": "통깨", "unit": "약간", "usage": "토핑용", "amount": 0}], "main": [{"name": "굴", "unit": "g", "notes": "", "amount": 500}, {"name": "무", "unit": "g", "notes": "", "amount": 200}]}}'::jsonb, '생굴무침 양념 레시피 굴무생채 물