INSERT INTO cleaned_recipes (id, recipe_id, cleaned_at, planning_version, planning_result, title, opening_remark, closing_remark, created_at, updated_at) VALUES (190, '7032089', 2025-11-23 02:29:33.934302, '1.0', '{"meta": {"title": "알배기배추 겉절이 김치 만드는법", "servings": 2, "difficulty": "Medium", "description": "저자 Tina소울푸드의 레시피로, 알배기배추 겉절이 김치를 매콤하고 아삭하게 버무려 맛있게 즐길 수 있습니다.", "time_estimate": 90}, "tools": ["칼", "도마", "믹서기", "믹싱볼", "볼", "큰 그릇", "체", "냄비", "주걱"], "process": [{"tip": "", "phase": "preparation", "heat_level": null, "step_index": 1, "action_type": "cut", "description": "알배기 배추의 밑동을 잘라 내고 잎을 분리해 주세요.", "tools_needed": ["칼", "도마"], "timer_seconds": null, "ingredients_needed": ["알배기배추 작은것"]}, {"tip": "", "phase": "preparation", "heat_level": null, "step_index": 2, "action_type": "wash", "description": "알배기 배추를 물에 담가 한 번 씻고 체에 받쳐 물기를 빼 주세요.", "tools_needed": ["볼", "체"], "timer_seconds": null, "ingredients_needed": ["알배기배추 작은것"]}, {"tip": "소금물을 완전히 녹여 소금물이 균일해야 배추가 고르게 절여집니다.", "phase": "preparation", "heat_level": null, "step_index": 3, "action_type": "mix", "description": "물 2리터에 굵은 천일염 반컵을 녹여 소금물을 만들어 주세요.", "tools_needed": ["큰 볼", "숟가락"], "timer_seconds": null, "ingredients_needed": ["물", "천일염"]}, {"tip": "배추를 절이는 동안 중간에 뒤집어 고루 절여 주세요.", "phase": "preparation", "heat_level": null, "step_index": 4, "action_type": "mix", "description": "배추에 소금물을 부어 주세요. 위에 굵은 소금을 약간 더 뿌려 주세요. 배추를 1시간 정도 절이면서 중간에 한두 번 뒤집어 고루 절여 주세요.", "tools_needed": ["큰 볼"], "timer_seconds": 3600, "ingredients_needed": ["알배기배추 작은것", "천일염", "물"]}, {"tip": "", "phase": "preparation", "heat_level": null, "step_index": 5, "action_type": "mix", "description": "찹쌀가루나 밀가루로 풀을 쑤어 주거나 밥이나 죽을 이용해도 좋아요. 저는 냉동실에 보관했던 죽이 있어서 죽을 한번 끓여서 식혀 줬어요.", "tools_needed": ["볼", "냄비"], "timer_seconds": null, "ingredients_needed": ["찹쌀가루 또는 밀가루", "밥", "죽"]}, {"tip": "", "phase": "preparation", "heat_level": null, "step_index": 6, "action_type": "wash", "description": "배추는 물에 가볍게 헹궈 주세요.", "tools_needed": ["수세미", "볼"], "timer_seconds": null, "ingredients_needed": ["알배기배추 작은것"]}, {"tip": "", "phase": "preparation", "heat_level": null, "step_index": 7, "action_type": "drain", "description": "배추를 바로 건져 체에 받쳐 물기를 빼주세요.", "tools_needed": ["체", "볼"], "timer_seconds": null, "ingredients_needed": ["알배기배추 작은것"]}, {"tip": "", "phase": "preparation", "heat_level": null, "step_index": 8, "action_type": "blend", "description": "믹서에 고추가루를 제외한 다른 김치 양념을 넣고 갈아 주세요.", "tools_needed": ["믹서기", "볼"], "timer_seconds": null, "ingredients_needed": ["마늘", "생강", "까나리액젓", "꽃게액젓", "새우젓", "배즙음료", "설탕", "찹쌀가루 또는 밀가루", "물", "천일염"]}, {"tip": "", "phase": "preparation", "heat_level": null, "step_index": 9, "action_type": "mix", "description": "갈아 놓은 김치 양념에 식혀 놓은 풀과 고추가루를 5-6스푼을 넣어 섞어 주세요. 고추가루를 미리 불려 주면 색이 더 고와져요.", "tools_needed": ["볼", "숟가락", "주걱"], "timer_seconds": null, "ingredients_needed": ["풀", "고추가루"]}, {"tip": "", "phase": "preparation", "heat_level": null, "step_index": 10, "action_type": "cut", "description": "대파를 송송 썰어 주세요.", "tools_needed": ["칼", "도마"], "timer_seconds": null, "ingredients_needed": ["대파"]}, {"tip": "", "phase": "preparation", "heat_level": null, "step_index": 11, "action_type": "slice", "description": "양파 반개를 채썰어 주세요.", "tools_needed": ["칼", "도마"], "timer_seconds": null, "ingredients_needed": ["양파"]}, {"tip": "", "phase": "preparation", "heat_level": null, "step_index": 12, "action_type": "mix", "description": "배추를 큰 용기에 담고 채썰어 놓은 양파와 대파를 넣어 주세요.", "tools_needed": ["큰 용기", "주걱"], "timer_seconds": null, "ingredients_needed": ["알배기배추 작은것", "양파", "대파"]}, {"tip": "", "phase": "preparation", "heat_level": null, "step_index": 13, "action_type": "mix", "description": "양념을 넣고 잘 버무려 주세요.", "tools_needed": ["주걱", "볼"], "timer_seconds": null, "ingredients_needed": ["양념"]}, {"tip": "", "phase": "finishing", "heat_level": null, "step_index": 14, "action_type": "stir", "description": "날씨가 더우니 실온에 한나절 정도 두었다가 냉장고에 보관해 주세요.", "tools_needed": [], "timer_seconds": null, "ingredients_needed": []}], "ingre