INSERT INTO cleaned_recipes (id, recipe_id, cleaned_at, planning_version, planning_result, title, opening_remark, closing_remark, created_at, updated_at) VALUES (191, '7037475', 2025-11-23 02:32:13.560748, '1.0', '{"meta": {"title": "실패할일 없는 김장김치양념 /절임배추20kg/ 김장김치 양념비율 황금레시피 /김장담그기", "servings": 6, "difficulty": "Medium", "description": "대규모 김장김치를 위한 황금 양념 레시피로, 절임배추와 해산물 양념을 활용해 깊은 풍미의 김치양념장을 만들고 숙성하는 과정을 담은 레시피(작성자: 김진옥요리가좋다)", "time_estimate": 120}, "tools": ["박스", "저장용 용기", "냄비", "거품기", "도마", "칼", "믹서기", "큰 그릇", "주걱", "김치통", "밀봉용 비닐", "체"], "process": [{"tip": "배추가 골고루 절여지도록 박스 아래위 위치를 바꿔 주세요", "phase": "preparation", "heat_level": null, "step_index": 1, "action_type": "mix", "description": "절임배추가 도착하면 박스 채 아래위 방향으로 뒤집어 한 시간에서 몇 시간 서늘한 곳에 보관해 절임 상태가 고르게 되도록 해주세요.", "tools_needed": ["박스", "저장용 용기"], "timer_seconds": 3600, "ingredients_needed": ["절임배추"]}, {"tip": "거품이 올라오지 않도록 천천히 저어 주세요", "phase": "cooking", "heat_level": "Medium", "step_index": 2, "action_type": "boil", "description": "냄비에 멸치다시마육수 1300ml와 찹쌀가루 90g을 넣고 거품기로 풀어준 후 중불에서 3~5분간 끓여주고 완전히 식혀주세요.", "tools_needed": ["냄비", "거품기"], "timer_seconds": 240, "ingredients_needed": ["멸치다시마육수", "찹쌀가루"]}, {"tip": "", "phase": "preparation", "heat_level": null, "step_index": 3, "action_type": "mix", "description": "끓인 찹쌀풀을 완전히 식히도록 식혀주세요.", "tools_needed": ["그릇"], "timer_seconds": null, "ingredients_needed": ["찹쌀풀 식힌"]}, {"tip": "", "phase": "preparation", "heat_level": null, "step_index": 4, "action_type": "wash", "description": "홍갓과 쪽파를 깨끗이 씻어 준비해 주세요.", "tools_needed": ["물", "도마"], "timer_seconds": null, "ingredients_needed": ["홍갓", "쪽파"]}, {"tip": "", "phase": "preparation", "heat_level": null, "step_index": 5, "action_type": "cut", "description": "홍갓과 쪽파를 각각 2cm 길이로 썰어 준비해 주세요.", "tools_needed": ["칼", "도마"], "timer_seconds": null, "ingredients_needed": ["홍갓", "쪽파"]}, {"tip": "", "phase": "preparation", "heat_level": null, "step_index": 6, "action_type": "cut", "description": "무를 씻은 뒤 큰 사이즈의 한 개를 반으로 갈라 얇게 채썰어 주세요.", "tools_needed": ["칼", "도마"], "timer_seconds": null, "ingredients_needed": ["무"]}, {"tip": "", "phase": "preparation", "heat_level": null, "step_index": 7, "action_type": "blend", "description": "배와 사과를 반으로 자르고, 양파 반개와 대파 흰부분 3개, 무 500g을 토막내어 믹서기에 넣고 곱게 갈아 주세요.", "tools_needed": ["믹서기"], "timer_seconds": null, "ingredients_needed": ["배", "사과", "양파", "대파 흰부분", "무(500g)"]}, {"tip": "", "phase": "preparation", "heat_level": null, "step_index": 8, "action_type": "blend", "description": "생새우 180g, 새우젓 200g, 멸치다시마육수 1300g를 함께 넣고 곱게 갈아 주세요.", "tools_needed": ["믹서기"], "timer_seconds": null, "ingredients_needed": ["생새우", "새우젓", "멸치다시마육수"]}, {"tip": "소금은 맛을 보며 기호에 맞게 조절하세요", "phase": "cooking", "heat_level": "Medium", "step_index": 9, "action_type": "mix", "description": "큰 그릇에 식혀 놓은 찹쌀풀과 믹서기로 간 재료를 함께 넣고 다진마늘 400g, 다진생강 100g, 소금 50g, 매실청 60ml, 멸치액젓 700ml, 고춧가루 1100g를 넣어 고루 섞어 주세요. 그리고 준비한 무채와 홍갓, 쪽파를 넣고 함께 버무려 김치양념장을 완성합니다.", "tools_needed": ["큰 그릇", "주걱", "믹서기"], "timer_seconds": null, "ingredients_needed": ["찹쌀풀 식힌", "믹서기에 간 재료", "다진마늘", "다진생강", "소금", "매실청", "멸치액젓", "고춧가루", "무채", "홍갓", "쪽파"]}, {"tip": "물기를 너무 꽉 짜지 않도록 살짝 짜 주세요", "phase": "preparation", "heat_level": null, "step_index": 10, "action_type": "drain", "description": "절임배추의 물기를 체에 받쳐 1시간 정도 빼 주세요.", "tools_needed": ["체"], "timer_seconds": 3600, "ingredients_needed": ["절임배추"]}, {"tip": "", "phase": "cooking", "heat_level": null, "step_index": 11, "action_type": "mix", "description": "물기를 뺀 절임배추에 준비한 양념장을 골고루 버무려 흰줄기 부분 위주로 섞어 주세요.", "tools_needed": ["큰 그릇", "주걱"], "timer_seconds": null, "ingredients_needed": ["절임배추", "양념장"]}, {"tip": "", "phase": "finishing", "heat_level": null, "step_index": 12, "action_type": "layer", "description": "버무린 김치를 김치통에 차곡차곡 담고, 절임배추의 푸르고 억센 겉잎 몇 장을 덮어 맨 위에 올려 밀봉해 주세요. 원하시면 김치통에 김치를 담은 뒤 밀봉하거나 김장비닐로 밀봉해 보관하셔도 좋습니다.", "tools_needed": ["김치통", "밀봉용 비닐"], "timer_seconds": null, "ingredients_needed": ["김치", "겉잎"]}], "ingredients": {"sub": [], "main": [{"name": "절임배추", "unit": "킬로그램", 