INSERT INTO cleaned_recipes (id, recipe_id, cleaned_at, planning_version, planning_result, title, opening_remark, closing_remark, created_at, updated_at) VALUES (194, '7038306', 2025-11-23 02:37:01.407706, '1.0', '{"meta": {"title": "초간단 숙주무침 레시피", "servings": 4, "difficulty": "Easy", "description": "작성자 뿡씨스터즈의 간단한 숙주무침으로, 숙주를 데쳐 대파와 연두, 참기름으로 버무려 고소하고 아삭한 맛이 돋보이는 요리입니다.", "time_estimate": 5}, "tools": ["볼", "냄비", "믹싱볼", "칼", "도마", "접시"], "process": [{"tip": "씻은 숙주는 물기를 살짝 제거해 주세요", "phase": "preparation", "heat_level": null, "step_index": 1, "action_type": "wash", "description": "숙주를 볼에 담아 깨끗이 씻어 주세요.", "tools_needed": ["볼"], "timer_seconds": null, "ingredients_needed": ["숙주"]}, {"tip": "데친 뒤 즉시 건져 찬물에 헹구지 않아도 됩니다.", "phase": "cooking", "heat_level": "High", "step_index": 2, "action_type": "boil", "description": "냄비에 물이 끓어 오르면 숙주를 넣고 약 1분 데쳐 주세요.", "tools_needed": ["냄비"], "timer_seconds": 60, "ingredients_needed": ["숙주"]}, {"tip": "물기를 살짝 남겨 두면 버무림이 잘 됩니다.", "phase": "cooking", "heat_level": null, "step_index": 3, "action_type": "mix", "description": "데친 숙주를 건져 믹싱볼에 담아 주세요.", "tools_needed": ["믹싱볼"], "timer_seconds": null, "ingredients_needed": ["숙주"]}, {"tip": "대파의 향이 살아 있도록 얇게 써 주세요.", "phase": "cooking", "heat_level": null, "step_index": 4, "action_type": "slice", "description": "대파를 송송 썰어 주세요.", "tools_needed": ["칼", "도마"], "timer_seconds": null, "ingredients_needed": ["대파"]}, {"tip": "연두의 향이 배이도록 잘 섞어 주세요.", "phase": "cooking", "heat_level": null, "step_index": 5, "action_type": "mix", "description": "데친 숙주에 연두를 넣고 고루 버무려 주세요.", "tools_needed": ["믹싱볼"], "timer_seconds": null, "ingredients_needed": ["연두"]}, {"tip": "오일이 골고루 섞이도록 천천히 버무려 주세요.", "phase": "cooking", "heat_level": null, "step_index": 6, "action_type": "mix", "description": "참기름을 넣고 다시 버무려 주세요.", "tools_needed": ["믹싱볼"], "timer_seconds": null, "ingredients_needed": ["참기름"]}, {"tip": "양념이 고르게 배도록 여러 번 버무려 주세요.", "phase": "cooking", "heat_level": null, "step_index": 7, "action_type": "mix", "descripti