INSERT INTO cleaned_recipes (id, recipe_id, cleaned_at, planning_version, planning_result, title, opening_remark, closing_remark, created_at, updated_at) VALUES (195, '7040324', 2025-11-23 02:38:50.012518, '1.0', '{"meta": {"title": "풀 없이 갓김치 담그는 법 홍갓김치 담그기 양념 만들기", "servings": 6, "difficulty": "Easy", "description": "소금물에 절인 홍갓을 매콤한 양념으로 버무려 아삭하게 담근 홍갓김치의 기본 양념 만들기 레시피입니다.", "time_estimate": 90}, "tools": ["믹싱볼", "도마", "조리용나이프", "숟가락", "대야", "밀폐용기", "접시"], "process": [{"tip": "흐르는 물에 잔여 물질이 남지 않도록 꼼꼼히 씻어 주세요", "phase": "preparation", "heat_level": null, "step_index": 1, "action_type": "wash", "description": "홍갓의 잎과 뿌리 부분의 흙과 더러움을 흐르는 물로 깨끗이 씻어 주세요. 큰 잎과 작은 잎을 구분해 준비합니다.", "tools_needed": ["도마", "수세미"], "timer_seconds": 60, "ingredients_needed": ["홍갓"]}, {"tip": "칼집은 일정하게 내어 골고루 절임이 되도록 해 주세요", "phase": "preparation", "heat_level": null, "step_index": 2, "action_type": "slice", "description": "줄기가 두꺼운 부분은 뿌리 쪽에 열십자 칼집을 내어 소금에 잘 절여지게 준비합니다.", "tools_needed": ["칼", "도마"], "timer_seconds": 60, "ingredients_needed": ["홍갓"]}, {"tip": "소금이 완전히 녹아 균일한 소금물을 만들도록 해 주세요", "phase": "preparation", "heat_level": null, "step_index": 3, "action_type": "mix", "description": "큰 그릇에 물 1.2리터와 굵은소금을 넣고 잘 녹여 소금물을 만듭니다.", "tools_needed": ["믹싱볼", "숟가락"], "timer_seconds": 60, "ingredients_needed": ["물", "굵은소금"]}, {"tip": "줄기 부분이 물에 잠기도록 완전히 잠기지 않으면 절임이 골고루 되지 않습니다", "phase": "preparation", "heat_level": null, "step_index": 4, "action_type": "soak", "description": "만들어 놓은 소금물에 홍갓을 넣고 30분에서 40분 정도 절여 주세요. 두꺼운 줄기가 물에 잠기도록 살짝 기울여 주세요.", "tools_needed": ["그릇", "손"], "timer_seconds": 2100, "ingredients_needed": ["홍갓", "굵은소금", "물"]}, {"tip": "물기가 남아 있지 않도록 잘 짜 주세요", "phase": "preparation", "heat_level": null, "step_index": 5, "action_type": "wash", "description": "절임이 끝난 홍갓을 물에 한 번 헹궈 남은 소금기를 제거하고 물기를 꼭 짭니다.", "tools_needed": ["수세미", "대야"], "timer_seconds": 60, "ingredients_needed": ["홍갓", "물"]}, {"tip": "양념이 고르게 섞이도록 잘 저어 주세요", "phase": "preparation", "heat_level": null, "step_index": 6, "action