INSERT INTO cleaned_recipes (id, recipe_id, cleaned_at, planning_version, planning_result, title, opening_remark, closing_remark, created_at, updated_at) VALUES (207, '7059616', 2025-11-23 02:58:53.090270, '1.0', '{"meta": {"title": "돼지보쌈삶는법, 보쌈 삶는법 레시피 보쌈용고기 어떤부위로", "servings": 4, "difficulty": "Easy", "description": "띠안이 공유한 보쌈용 고기를 잡내를 제거하고 부드럽게 삶아 썰어 먹는 전형적인 보쌈 삶기 레시피입니다.", "time_estimate": 60}, "tools": ["프라이팬", "냄비", "도마", "칼", "국자", "주걱", "접시"], "process": [{"tip": "겉면이 골고루 갈색이 날 때까지 앞뒤로 고르게 구워주세요", "phase": "cooking", "heat_level": "High", "step_index": 1, "action_type": "fry", "description": "돼지고기 앞다릿살을 프라이팬에 올려 기름을 두르고 겉면이 노릇하게 익도록 구워주세요.", "tools_needed": ["프라이팬"], "timer_seconds": 300, "ingredients_needed": ["돼지고기 앞다릿살"]}, {"tip": "양파의 알갱이가 흐트러지지 않도록 얇게 썰어 넣어주세요", "phase": "cooking", "heat_level": "Medium", "step_index": 2, "action_type": "slice", "description": "양파를 반으로 잘라 먹기 좋게 썰어 프라이팬에 넣어주세요.", "tools_needed": ["도마", "칼"], "timer_seconds": null, "ingredients_needed": ["양파"]}, {"tip": "대파의 흰 부분까지 고르게 잘라 넣어 향을 더해주세요", "phase": "cooking", "heat_level": "Medium", "step_index": 3, "action_type": "slice", "description": "대파를 반으로 잘라 넣어주세요.", "tools_needed": ["도마", "칼"], "timer_seconds": null, "ingredients_needed": ["대파"]}, {"tip": "향을 살리기 위해 마늘은 다져 넣고 재료를 골고루 섞어 주세요", "phase": "cooking", "heat_level": "Medium", "step_index": 4, "action_type": "mix", "description": "통후추, 다진마늘, 된장, 월계수잎을 모두 넣어 잘 섞어 주세요.", "tools_needed": ["냄비", "주걱"], "timer_seconds": null, "ingredients_needed": ["통후추", "다진마늘", "된장", "월계수잎"]}, {"tip": "간은 조금씩 보며 조절해 주세요", "phase": "cooking", "heat_level": "Medium", "step_index": 5, "action_type": "mix", "description": "쇠고기다시다와 소금을 약간 넣어 간을 살짝 맞춰 주세요.", "tools_needed": ["냄비", "주걱"], "timer_seconds": null, "ingredients_needed": ["쇠고기다시다", "소금"]}, {"tip": "고기가 아주 부드러워질 때까지 중간에 저어 주지 말고 뚜껑을 살짝 열고 끓여 주세요", "phase": "cooking", "heat_level": "Medium", "step_index": 6, "action_type": "simmer", "description": "중불로 약 40분간 푹 끓여 부드럽게 익혀 주세요.", "tools_needed": ["냄비"], "timer_seconds": 2400, "ingredients_needed": []}, {"tip": "식힘 과정에서 육질이 더욱 부드럽고 냄새가 덜 나요", "phase": "finishing", "heat_level": null, "step_index": 7, "action_type": "slice", "description": "익은 돼지고기를 꺼내 한김이 살짝 식을 때까지 두었다가 얇게 썰어 접시에 담아 마무리해 주세요.", "tools_needed": ["칼", "도마", "접시"], "timer_seconds": null, "ingredients_needed": ["돼지고기 앞다릿살"]}], "ingredients": {"sub": [], "main": [{"name": "돼지고기 앞다릿살", "unit": "그램", "notes": "", "amount": 1200}, {"name": "대파", "unit": "개", "notes": "", "amount": 1}, {"name": "양파", "unit": "개", "notes": "", "amount": 1}, {"name": "통후추", "unit": "큰술", "notes": "", "amount": 0.5}, {"name": "다진마늘", "unit": "큰술", "notes": "", "amount": 1}, {"name": "된장", "unit": "큰술", "notes": "", "amount": 1}, {"name": "쇠고기다시다", "unit": "큰술", "notes": "", "amount": 0.3}, {"name": "월계수잎", "unit": "장", "notes": "", "amount": 5}, {"name": "소금", "unit": "큰술", "notes": "", "amount": 0.3}]}}'::jsonb, '돼지보쌈삶는법, 보쌈 삶는법 레시피 보쌈용고기 어떤부위로', '안녕하세요! 지금부터 돼지보쌈삶는법, 보쌈 삶는법 레시피 보쌈용고기 어떤부위로 만들기를 시작하겠습니다. 띠안이 공유한 보쌈용 고기를 잡내를 제거하고 부드럽게 삶아 썰어 먹는 전형적인 보쌈 삶기 레시피입니다.', '돼지보쌈삶는법, 보쌈 삶는법 레시피 보쌈용고기 어떤부위로 만들기가 완료되었습니다. 맛있게 드세요!', 2025-11-23 02:58:53.090270, 2025-11-23 02:58:53.090270);
INSERT INTO cleaned_recipes (id, recipe_id, cleaned_at, planning_version, planning_result, title, opening_remark, closing_remark, created_at, updated_at) VALUES (208, '913370', 2025-11-23 03:00:31.858789, '1.0', '{"meta": {"title": "만드는 법은 간단하고 맛은 일품인 총각김치", "servings": 6, "difficulty": "Easy", "description": "알타리무와 무청을 주 재료로 매콤하고 새콤한 맛의 총각김치를 실온 숙성으로 만드는 반찬", "time_estimate": 60}, "tools": ["칼", "수세미", "볼", "용기", "냄비", "숟가락", "주걱", "도마", "김치통"], "process": [{"tip": "", "phase": "preparation", "heat_level": null, "step_index": 1, "action_type": "wash", "description": "알타리무의 흙과 이물질을 제거하기 위해 칼로 다듬고 흐르는 물에 깨끗이 두 번 정도 씻어주세요.", "tools_needed": ["칼", "수세미", "볼"], "timer_seconds": null, "ingredients_needed": ["알타리무"]}, {"tip": "", "phase": "preparation", "heat_level": null, "step_index": 2, "action_type": "soak", "description": "알타리무에 굵은소금 3컵과 물 3리터를 부어 2시간 정도 절여주세요. 무를 썰지 않고 절이므로 시간이 필요합니다. 필요에 따라 알타리무를 반으로 나누어 1시간 정도 절일 수 있습니다.", "tools_needed": ["용기"], "timer_seconds": 7200, "ingredients_needed": ["알타리무", "굵은소금", "물"]}, {"tip": "", "phase": "cooking", "heat_level": "Medium", "step_index": 3, "action_type": "boil", "description": "무가 절여지는 동안 냄비에 찹쌀가루 3큰술과 물 2컵을 넣고 덩어리 없이 풀어주며 끓인 뒤, 보글보글 끓으면 1분 정도 더 저어 걸쭉한 찹쌀풀을 만듭니다. 밀가루로 대체할 경우에도 비슷한 농도가 됩니다.", "tools_needed": ["냄비", "숟가락"], "timer_seconds": 120, "ingredients_needed": ["찹쌀가루", "물"]}, {"tip": "", "phase": "cooking", "heat_level": "Medium", "step_index": 4, "action_type": "mix", "description": "고춧가루 3컵, 멸치액젓 1컵, 새우젓 4큰술, 다진마늘 6큰술, 갈은 양파 1컵, 설탕 4.5큰술을 준비하고 위에서 만든 찹쌀풀과 함께 양념장을 만드세요. 양파를 갈아 넣으면 시원한 맛이 더해집니다.", "tools_needed": ["볼", "주걱"], "timer_seconds": 60, "ingredients_needed": ["고춧가루", "멸치액젓", "새우젓", "다진마늘", "갈은 양파", "설탕", "찹쌀풀"]}, {"tip": "", "phase": "preparation", "heat_level": null, "step_index": 5, "action_type": "slice", "description": "쪽파를 깨끗이 다듬어 손가락 길이로 썰어 준비합니다.", "tools_needed": ["칼", "도마"], "timer_seconds": null, "ingredients_needed": ["쪽파"]}, {"tip": "", "phase": "cooking", "heat_level": "Medium", "step_index": 6, "action_type": "mix", "description": "2시간 절여진 알타리무를 흐르는 물에 두세 번 헹궈 물기를 빼고, 쪽파와 양념장을 넣고 밑에서 위로 살살 버무려 무가 부서지지 않도록 조심스럽게 버무려주세요.", "tools_needed": ["볼", "주걱"], "timer_seconds": null, "ingredients_needed": ["알타리무", "쪽파", "양념장"]}, {"tip": "", "phase": "preparation", "heat_level": null, "step_index": 7, "action_type": "wrap", "description": "무에 무청을 돌돌 말아 감고 떨어지지 않도록 고정합니다.", "tools_needed": ["손"], "timer_seconds": null, "ingredients_needed": ["무청", "무"]}, {"tip": "", "phase": "finishing", "heat_level": null, "step_index": 8, "action_type": "layer", "description": "김치통에 알타리무와 무청, 양념장을 차곡차곡 담아 실온에서 2일 정도 숙성시킨 후 냉장보관합니다. 실온 숙성 기간은 맛의 숙성도에 따라 달라집니다.", "tools_needed": ["김치통"], "timer_seconds": null, "ingredients_needed": ["알타리무", "무청", "양념장"]}], "ingredients": {"sub": [], "main": [{"name": "알타리무", "unit": "단", "notes": "", "amount": 3}, {"name": "쪽파", "unit": "단", "notes": "", "amount": 0.5}, {"name": "물", "unit": "리터", "notes": "", "amount": 3}, {"name": "굵은소금", "unit": "컵", "notes": "", "amount": 3}, {"name": "찹쌀가루", "unit": "큰술", "notes": "", "amount": 3}, {"name": "물", "unit": "컵", "notes": "", "amount": 2}, {"name": "고춧가루", "unit": "컵", "notes": "", "amount": 3}, {"name": "멸치액젓", "unit": "컵", "notes": "", "amount": 1}, {"name": "새우젓", "unit": "큰술", "notes": "", "amount": 4}, {"name": "다진마늘", "unit": "큰술", "notes": "", "amount": 6}, {"name": "갈은 양파", "unit": "컵", "notes": "", "amount": 1}, {"name": "설탕", "unit": "큰술", "notes": "", "amount": 4.5}]}}'::jsonb, '만드는 법은 간단하고 맛은 일품인 총각김치', '안녕하세요! 지금부터 만드는 법은 간단하고 맛은 일품인 총각김치 만들기를 시작하겠습니다. 알타리무와 무청을 주 재료로 매콤하고 새콤한 맛의 총각김치를 실온 숙성으로 만드는 반찬', '만드는 법은 간단하고 맛은 일품인 총각김치 만들기가 완료되었습니다. 맛있게 드세요!', 2025-11-23 03:00:31.858789, 2025-11-23 03:00:31.858789);
